[45037] = { ["id"] = 45037, ["name"] = "The Locket of Eldre'Thalas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 45037 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "<Carefully prying open the locket, you find a portrait of Queen Azshara made entirely of precious stones.> <Highborne possessions like this are rare - to find one so pristine in the hands of the Legion is deeply troubling.> <You know the Kirin Tor in Dalaran may be able to tell you more.>", ["objectivesText"] = "Find someone who can tell you more about the Locket of Eldre'Thalas. You suspect that the Kirin Tor in Dalaran are a good place to start.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 142373 }, ["questType"] = "standard", ["flags"] = {  },
