[49578] = { ["id"] = 49578, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 49578 }, ["series"] = { 49584 }, ["description"] = "I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun. It's a foreboding desert, full of canyons, with a great pyramid in the center. If my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map. And let's hope it's still in one piece.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
