[49579] = { ["id"] = 49579, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 49579 }, ["description"] = "This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire. Well, maybe not the main city itself, but close to it. Actually... <Samuel checks a map he has laid out.> Ah, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of. Here are you notes for the shrine and the location for it should be marked on your map.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Zandalar. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
