[49580] = { ["id"] = 49580, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 49580 }, ["description"] = "The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls. Luckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct... <Samuel looks quickly back and forth between the journal and his map and finally stops his finger on the map.> It should be right there. Take note of its location and here are the notes for that shrine. Good luck, <name>.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
