[49945] = { ["id"] = 49945, ["name"] = "First Impressions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10565, ["storyline"] = { 49945 }, ["series"] = { 49875, 49878, 49879, 49880, 49881, 49882, 49947, 49948 }, ["description"] = "This was all I had to offer you, young scribe. But your journey is not yet at the end. Go to your trainer and and inform them of your success here. <Kronah grabs an odd-looking jar.> I don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you? <As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.> Fine, be that way. It's an acquired taste any ways. Takes thousands of years to train the palette.", ["objectivesText"] = "Return to Zooey Inksprocket in Tiragarde Sound.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["flags"] = {  },
},
[49947] = { ["id"] = 49947, ["name"] = "Blood Bonded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 49947 }, ["series"] = { 49875, 49878, 49879, 49880, 49881, 49882, 49945, 49948 }, ["description"] = "Looks like you're all done here, <name>. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that. But between you and me, this was the easy part. Just wait till you meet the grandmaster. I'll let your current trainer fill you in on that part. Good luck, <name>!", ["objectivesText"] = "Return to Zooey Inksprocket in Tiragarde Sound.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[49948] = { ["id"] = 49948, ["name"] = "The Final Verse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 49948 }, ["series"] = { 49875, 49878, 49879, 49880, 49881, 49882, 49945, 49947 }, ["description"] = "Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn. Dere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill. Miju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know.", ["objectivesText"] = "Seek out Miju in (Zone) to begin your final trial.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[50326] = { ["id"] = 50326, ["name"] = "Ain't No Place Like Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9439, ["storyline"] = { 50326 }, ["description"] = "Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base. How about I help you out with that?", ["objectivesText"] = "Talk to Wistel Silversnitch", ["rewardItems"] = { 150733 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard", ["flags"] = {  },
},
[57308] = { ["id"] = 57308, ["name"] = "The Battle of Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 57308 }, ["description"] = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar. With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley. Vanquish him, and then return to me.", ["objectivesText"] = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Dun Baldar.", ["rewardGold"] = 702000, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["flags"] = {  },
},
[57319] = { ["id"] = 57319, ["name"] = "The Battle for Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 57319 }, ["description"] = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike! You will find Vanndar in Dun Baldar, in the north of Alterac Valley. Destroy him, <name>, and then return to me.", ["objectivesText"] = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in Frostwolf Village.", ["rewardGold"] = 702000, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["flags"] = {  },
},
