[70707] = { ["id"] = 70707, ["name"] = "The Next Waygate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 70707 }, ["series"] = { 70702 }, ["description"] = "I've been keepin' this here vessel from yer nightborne friend safe. What do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?", ["objectivesText"] = "Choose the next waygate location to pursue.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
