[71025] = { ["id"] = 71025, ["name"] = "Against Overwhelming Odds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {  }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges. If you gather some friends, I know a place you can show the other side who is truly superior. And to make it interesting, if you are successful I have a prize for you.", ["objectivesText"] = "Slay 25 Level 70 Alliance anywhere within the Dragon Isles.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2112, ["db2PoiUiMapID"] = 2112, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "pvp",
},
[76168] = { ["id"] = 76168, ["name"] = "A Place of Refuge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 76168 }, ["description"] = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. <name>, I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.", ["objectivesText"] = "Meet Baine and Tomul at Toghusuq Village.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[76169] = { ["id"] = 76169, ["name"] = "Glow in the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76169 }, ["description"] = "Codswallop! Peevish has run off again. He is assigned to this post but is never here! I heard him screaming from the nearby cave. He must have tried to hide in there. Take my torch and go to the Coldshadow Cave. Find Peevish along with the bottles of Dauntless Draught he stole. He can desert his post if he wants, but I won't let him take the drinks!", ["objectivesText"] = "Locate \"Peevish\" Paeton Berncort and recover 8 bottles of Dauntless Draught . Progress: Have you found \"Peevish\" Paeton Berncort and the bottles of Dauntless Draught he took with him?", ["rewardItems"] = { 206203, 217342, 217344, 219198, 224552, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 212419, ["x"] = 0.644, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 212419, ["x"] = 0.644, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[76247] = { ["id"] = 76247, ["name"] = "Keep the Home Fires Burning", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76247 }, ["description"] = "The keyflame braziers, located across the countryside keep the darkness at bay and our people safe. Many have gone dark as the Radiant Remnants needed to maintain them have become harder to find. We've worked hard to ensure our brazier is always lit, but we could always use your help. Please gather remnants from our supplies and use them to help empower our family keyflame.", ["objectivesText"] = "5 Hillhelm Remnant Supplies gathered and used to empower the Hillhelm Keyflame. Progress: Have you empowered our keyflame?", ["rewardItems"] = { 209854 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questType"] = "standard", ["flags"] = {  },
},
