[76588] = { ["id"] = 76588, ["name"] = "Defender of the Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76588 }, ["description"] = "The Expedition forces face formidable adversaries. Drawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts. Please help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.", ["objectivesText"] = "Eliminate two rare creatures within the areas controlled by the keyflames. Progress: Have you eliminated the threats?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 206350, 228741, 233290, 233299 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questType"] = "standard", ["flags"] = {  },
},
[76600] = { ["id"] = 76600, ["name"] = "Right Between the Gyro-Optics", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76600 }, ["description"] = "My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why! The lights go out, and they all start trying to kill us! You want to help me sort this out? I'm a crack shot with a rifle. You mark the target, and I'll start shooting!", ["objectivesText"] = "With Auebry's help, eliminate 8 Dark-Crazed Harvesters .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 207084, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 212398, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[76733] = { ["id"] = 76733, ["name"] = "Tater Trawl", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76733 }, ["description"] = "Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely. If you light the harvest torches, you might uncover some potatoes hiding in the shadows. Using those lights, gather as many potatoes as you can. Every bit helps in these trying times.", ["objectivesText"] = "Light 5 Harvest Torches and gather 15 Firelight Spuds . Progress: Have you found any spuds?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 210745 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[76997] = { ["id"] = 76997, ["name"] = "Lost in Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76997 }, ["description"] = "Greetings, <name>. I find myself in a dire situation. Some fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented. I found safety in this house, but most of the recruits fled, confused into the darkness. Will you help me locate them? I have a spare Patrol Torch . The mere sight of it should rally them to your side.", ["objectivesText"] = "Find and rally 3 Demoralized Recruits using the Patrol Torch . Progress: Have you found the recruits?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211872, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 208186, ["x"] = 0.646, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 208186, ["x"] = 0.646, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[77485] = { ["id"] = 77485, ["name"] = "Technoscrying: Back to Eadweard!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 75729, 75867, 75868, 76448, 76557, 76564, 76576, 77415, 77425, 77434, 77483, 77484, 77485 }, ["description"] = "Thanks for all your help! Let's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.", ["objectivesText"] = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2025, ["db2PoiUiMapID"] = 2025, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 12, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
