[78226] = { ["id"] = 78226, ["name"] = "A Most Intriguing Invitation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "We've received an invitation. Or rather, you have, <name>. It's a request to meet with the Vizier. That name rattles even the most wealthy and powerful figures in the City of Threads. Gaining this individual as an ally could seal our victory against Ansurek's horrid little shadow for good. You're to meet them in the Burrows. Use the pheromone dispenser here in my lair to mask yourself enough to enter safely.", ["objectivesText"] = "Meet the 'Vizier' in the Burrows of Azj-Kahet 's City of Threads.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2216, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2QuestHubAreaPoiID"] = 7940, ["questType"] = "standard", ["flags"] = {  },
},
[78228] = { ["id"] = 78228, ["name"] = "Into a Skittering City", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however... Nevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive. Perhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.", ["objectivesText"] = "Tell the Vizier of the Weaver's plan, and apply Pheromones for access to the Umbral Bazaar. Progress: For being so young, I find Master Anduin is practically bursting with the grand experiences of a much more traveled sort. Impressive. At least from the perspective of a humble Kaheti.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["mapID"] = 2216, ["db2PoiUiMapID"] = 2216, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78231] = { ["id"] = 78231, ["name"] = "Like a Spider on the Wall", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "Inviting Alleria was a risk... but even at this moment, I feel it was worth taking. I know it was. I will speak with her on my own. In the meantime, I'd like you to venture into the city above. The pheromones Nizrek gifted you will allow access into the Umbral Bazaar. Observe the merchants, listen to the conversations, purchase their goods. This city is as vibrant as Stormwind. And its people are as worthy of freeing from abuse as our own. Experience for yourself how similar we all are.", ["objectivesText"] = "Explore the Umbral Bazaar. Progress: Enjoy yourself? And no trouble with the pheromones, I hope.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217386, ["x"] = 0.605, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78232] = { ["id"] = 78232, ["name"] = "Rewriting the Rewritten", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "We called you here today because it is \"Ascendance Day\". Queen Ansurek has deigned declare it a day to revel in our newfound, void-infused evolution--our \"Ascendance\". Please note my satirical nuance. While the streets are alive with festivity and joyous citizens, the Shadecasters planted through the Bazaar will be drowning the air with Ansurek's vile propaganda. Take this invention of mine. Use it to overwrite them with more... illuminating information for the public.", ["objectivesText"] = "Overwrite 3 Shadecasters. Progress: Anduin has me worried. I've always known him to lean towards diplomacy, but does he have the conviction to draw his sword? If he does not, he may never be able to end this war.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225970 }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 211375, ["x"] = 0.549, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78233] = { ["id"] = 78233, ["name"] = "The Weaver's Gift", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "A little weave-rat tells me that an intriguing series of events are playing out to the north. It seems there has been a remarkably coincidental waterfall of failures marring the military efforts there. I want to know who is responsible. Look into it for me, and see if your curiously binary eyes can pluck out any potential allies. Some of your little friends are among the escapees drawing the ire of one \"Zev'kall.\" Do go catch up. Tell them the Weaver bids them... greetings.", ["objectivesText"] = "Find the friends the Weaver has revealed to you as a gift.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78234] = { ["id"] = 78234, ["name"] = "Force Your Way", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Even with the general gone, it's not going to be easy getting out of here. This place is infested. I know I'm hiding it well, but I'm not exactly feeling my best. I'm not sure I'll be much help in this state. You're going to have to clear a path for us.", ["objectivesText"] = "Kill 8 Kaheti forces in Rak-Zakaz. Progress: Say what you will, but you do meet the most interesting company while imprisoned.", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78236] = { ["id"] = 78236, ["name"] = "Scrappy Straggler", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "If someone got left behind, we need to do something about that. I hate to say it, but these people need someone to protect them here. I have to stay. Find this straggler. And while you're at it, take a peek behind enemy lines. See if you can find anything useful.", ["objectivesText"] = "Rescue the straggler in Rak-Zakaz. Progress: The others all made it to safety, right?", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78237] = { ["id"] = 78237, ["name"] = "Let Fly!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Hm. This Anub'azal gave the orders that led to the prisoners' escape. Zev'kall here didn't seem very pleased with that. So how about this--you sneak into Siegehold, and make best friends with Anub'azal . Easy. I've noticed a lot of cargo being ferried over, I'm sure no one would notice if we just swapped out the contents of a particular crate. In the meantime, I'll share our discoveries with the Weaver. I'd love to come with you, but I'd rather not tempt more Flynn stabbings today.", ["objectivesText"] = "Stow away into a box to be carried into Siegehold.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78244] = { ["id"] = 78244, ["name"] = "Kaheti Hospitality", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "That stage in the distance is where Ansurek will give her Ascendance Day speech. You, Alleria, and I shall make our way up one of the nearby towers and observe. If we are to turn her own citizens against her, then we must also gain as much first hand experience with her tactics as we can manage. I've already told Alleria as much, but we cannot make our presence known. If we do run into any trouble, the Vizier has arranged for a set of getaway fliers at the edge of the Burrows where we first met.", ["objectivesText"] = "Speak to Anduin when you're ready to observe the Ascendance Day speech, and exit the city quietly after. Progress: The Vizier has made special accommodations for us to reach the tower we'll be observing from. Sticking to the plan will mean we all get out safely.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 225561, 225562, 225563 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217386, ["x"] = 0.552, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217386, ["x"] = 0.552, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78248] = { ["id"] = 78248, ["name"] = "What We Still Have", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "I went into the city prepared--prepared to end this war even if I was ended with it. But I am alive. As are you. As is Anduin. We have new allies and a new way forward. I realize at this moment that my vision may have been obscured by my guilt. Part of me feels those words are Anduin's, not mine. Perhaps he's rubbing off on me. Let us return to your Weaver's Lair. I wish to see yours and Anduin's efforts to save these people as well as our own through.", ["objectivesText"] = "Return to the Weaver's Lair. Progress: I do believe my suggestion was to stay quiet while in the city, was it not?", ["rewardGold"] = 151900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217385, ["x"] = 0.606, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78249] = { ["id"] = 78249, ["name"] = "Specific Personages", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Zev'kall has recently placed his own loyal lackeys in key positions around Siegehold. Killing them will force replacements, which will cause chaos and re-training. All of which will make Zev'kall struggle. Get rid of all three.", ["objectivesText"] = "Kill Zev'kall's minions for General Anub'azal . Progress: All three must be removed from office.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225549, 225550, 225551, 225552 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78250] = { ["id"] = 78250, ["name"] = "General Admission", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "It isn't enough to inconvenience Zev'kall. He should be humiliated. I already have some information, but I need more. He stores military logs in a room that is too tiny for me to access. See what information he's hiding. I'm sure there's potential blackmail material in there somewhere.", ["objectivesText"] = "Find some useful blackmail material for the General. Progress: There should be something I can use.", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["rewardItems"] = { 217165 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78251] = { ["id"] = 78251, ["name"] = "Dalaran's Most Distressed", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "I don't trust this big bug at all. He let me lay there ages without saying anything! But if he wants to give us access to Siegehold, let's use it. I saw some other people dragged away into other parts of the base. I don't think they're eating them. It looks more like they're transporting them somewhere. Let's gather them up, make a prisoner convoy, and roll on out. Find me outside!", ["objectivesText"] = "Free prisoners for the fake prisoner convoy.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211399, ["x"] = 0.452, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78254] = { ["id"] = 78254, ["name"] = "Stolen Influence", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "These logs of Zev'kall's... he is wasting numerous nerubian lives. Throwing them away like some rabid mantid. We must act. As I said, Zev'kall doesn't produce his own pheromone marks anymore due to this 'Ascension' process. He's been forced to use mine. His alchemist is trying to concoct some for him... but once they do, what of me? Take those false pheromones and sneak them out of Siegehold. Expose Zev'kall, use them... you're creative, aren't you? Just make it messy.", ["objectivesText"] = "Steal the pheromones and prepare to sneak them out of Siegehold. Progress: What did the General ask you to do?", ["rewardGold"] = 607600, ["rewardXP"] = 13245, ["rewardItems"] = { 212528 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78255] = { ["id"] = 78255, ["name"] = "Just Act Casual", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "It's time to get outta here with the prisoners and those pheromones. I've found some convincing chains, since we have such a big group. Long as everybody stays in character, our chances look good. We've only got General Anub'azal's marker scent goop for you and I, so we'll be the drones with permission. You do all the talkin', while I mind the cart. I hope this works. Lead us through the gate, <name>!", ["objectivesText"] = "Help the convoy to exit Siegehold by speaking to the gatekeeper. Progress: We just need to make it out of the entrance. I'll figure it out from there.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225513, 225520, 225523, 225537 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215845, ["x"] = 0.518, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78256] = { ["id"] = 78256, ["name"] = "The General's Consensus", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "We got lucky here. That General Anub'azal is so interested in sabotaging Zev'kall that it's an \"enemy of our enemy is our friend\" situation for today. I feel like this is gonna be a theme: spiders tryin' to use us against each other. Ah, well. You're gonna want to take those pheromones somewhere useful, huh? You do that. I'll take these folks safely out of harm's way.", ["objectivesText"] = "Take Zev'kall's pheromones to someone that has a use for them. Progress: What do you have for me?", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["rewardItems"] = { 217042 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215845, ["x"] = 0.518, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78289] = { ["id"] = 78289, ["name"] = "To Rambleshire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["series"] = { 78291 }, ["description"] = "There's word of troubles in the village of Rambleshire, at the base of Thunderhead Peak. Can't abide the place myself. Always wet and rumbling. But Rooktender Lufsela thought it worth a look, however, seeing as how the birds fancy the moss that the village produces. She's still green though, and might just need a hand.", ["objectivesText"] = "Meet Lufsela in Rambleshire.", ["rewardGold"] = 77400, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214352, ["x"] = 0.328, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78290] = { ["id"] = 78290, ["name"] = "Sleepy Sheep", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "The energized moss that these flocks produce is a favorite treat for the storm rooks. But with the storm gone, the rams are lethargic, vulnerable, and no longer producing. We may not be able to conjure a storm, but we could offer the mosswools a motivating zap. See if you can find a lodestone that will hold a charge. Then bring it here to Shraubendre so she can get it loaded up.", ["objectivesText"] = "Use an Energized Lodestone to rouse 8 Lethargic Mosswools near Rambleshire. Progress: The lodestone should hold just enough of a charge to give the mosswools the motivation they need to return to their corrals. It won't hurt them.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 210489, 211459 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78291] = { ["id"] = 78291, ["name"] = "Power Predators", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["series"] = { 78289 }, ["description"] = "Thunderhead Peak normally boasts a perpetual storm from which the local mosswools draw energy. Without it, the poor dears look to be listless and near dead on their feet. That makes them easy pickings for predators. To get moss production back on track, we'll need to get to the bottom of the missing storm. But first we need to beat back these predators before they turn the mosswools to gravel.", ["objectivesText"] = "Cull 10 predators around Rambleshire. Progress: Please do what you can for the poor mosswools.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78292] = { ["id"] = 78292, ["name"] = "Lost Lord of the Storm", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "Listen well, stranger. Once a year, the great ram Durzan , Lord of the Southern Storm, crosses the isle to meet his brother Belzt on Thunderhead Peak. The clash of their horns heralds the storm and brings prosperity for another year. But something is wrong. Durzan has not come and the skies have cleared. The Stormrider may not believe, but I sense you have seen wilder things. Ask around if you still have doubts. Just please help us find Durzan .", ["objectivesText"] = "Find Durzan near Rambleshire. Progress: Pray Durzan is still with us. If the brothers don't meet at the summit, the storm and our livelihoods will be lost.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78293] = { ["id"] = 78293, ["name"] = "Their Moss, Our Gain", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "You say nerubians had him? Not sure what they wanted with old Durzan, but he looks weakened by the ordeal. We can't have that if he's to challenge his brother Belzt on the mountain. The moss harvested from our flocks gives the storm rooks a kick, so Durzan might benefit from it as well. Collect a bushel's worth and make an offering. And if the mosswools get ornery, be sure to put them in their place.", ["objectivesText"] = "Harvest moss from Rambleshire Mosswools and feed it to Durzan. Progress: That moss captures and contains the power of the storm. It ought to give Durzan the boost he needs to get back up on that mountain.", ["rewardGold"] = 232300, ["rewardXP"] = 7135, ["rewardItems"] = { 211858 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78294] = { ["id"] = 78294, ["name"] = "Thunderhead Butt", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "Durzan looks hale and hearty again. That moss packs a real punch. I have a sense that he's ready to go. I just wish we had more time. I have so many questions. But the greatest of those questions will be answered when he reaches the peak. We shouldn't send him up there alone. But I think he trusts you to take him.", ["objectivesText"] = "Accompany Durzan to Belzt on Thunderhead Peak. Progress: We'll be watching from here. I truly hope Belzt is up there waiting.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78348] = { ["id"] = 78348, ["name"] = "Friends in Low Places", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "When we crashed, the nerubians were upon us in an instant. We would have lost nearly everyone we brought with us, had someone not intervened. I do not know who--or what--stepped in on our behalf. But if there is even a shred of hope that we have allies in this place then we must seize upon it and refuse to let go.", ["objectivesText"] = "Search the Breathing Pit for your mysterious protector.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["rewardItems"] = { 109076 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78350] = { ["id"] = 78350, ["name"] = "Heroes Never Die", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["series"] = { 83552 }, ["description"] = "Damn it all! We were too hasty, and now my people are paying the price. We were fools to think the nerubians wouldn't be prepared for an incursion. Arathi soldiers are made of stern stuff, but even they will struggle to walk off an airship crash. I will keep everyone here safe. Please, go into the field and rescue as many people as you can.", ["objectivesText"] = "Aid twelve Wounded Aeroknights . Progress: Make haste, <class>. Time is of the essence.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225521, 225524, 225530, 225540 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78352] = { ["id"] = 78352, ["name"] = "For Naught, So Vial", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Truthfully, I don't care what the nerubians are plotting. They are not the first upstart people seeking power, and they certainly won't be the last. The problem is how they're going about it. I fear that tampering with this Black Blood will threaten far more than the delicate ecosystems of Khaz Algar. We must make sure that they never return to this pit again. Their equipment is still strewn throughout the pit. Destroy as much of it as you can manage.", ["objectivesText"] = "Destroy 8 pieces of nerubian extracting equipment throughout the Breathing Pit. Progress: The nerubians fled when those aberrations began appearing en masse, but I imagine they will try to come back for their ill-advised treasures. We need to make sure they have nothing to come back for.", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78353] = { ["id"] = 78353, ["name"] = "Fear the Old Blood", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "This is not exactly the place for a long talk, so I will be brief. These roots you see are part of something much greater than you know, and it is my job to protect them. If it isn't obvious to you already, this place is teeming with writhing Black Blood. If we do not act, it will spread deeper and further still. You want allies? Fine. Help me cleanse this place and protect these roots, and I will at least hear you out.", ["objectivesText"] = "Work to cleanse the Breathing Pit.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225545, 225546 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78354] = { ["id"] = 78354, ["name"] = "A Guiding Thread", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "<The words on the parchment appear burned, not written. A venomous tang singes your nose.> Blind and alone, you stumble in the dark. I offer you a thread to cling to. Follow it, should you wish to find your allies.", ["objectivesText"] = "Follow Spindle . Progress: State your business, lest I get peckish.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225514, 225516, 225529, 225533 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 216213, ["x"] = 0.4888, ["y"] = 0.5104 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.4888, ["y"] = 0.5104 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78383] = { ["id"] = 78383, ["name"] = "Strategic Edge", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "To add insult to injury, they disarmed me. I'm not leaving without those blades! While we're looking, keep an eye out for any evidence of what's going on here. Anything that could give us an advantage against the nerubians. Something strange happened that provided us the opening to escape. I have a feeling that could be something we can exploit.", ["objectivesText"] = "Find Flynn's Blades and 3 nerubian intel from Kaheti forces in Rak-Zakaz. Progress: There must be something around here of value to the Weaver...", ["rewardGold"] = 286500, ["rewardXP"] = 10595, ["rewardItems"] = { 211870, 221031, 225363 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78384] = { ["id"] = 78384, ["name"] = "Chasing the Light", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "Anduin survived that swarm. I do not doubt that for a moment. Even so, the nerubians are everywhere and he is just one man. Wherever he goes, wherever he is taken, I will find him. Find me any sign that he yet lives. That is all I need to follow him to Azeroth's end.", ["objectivesText"] = "Search for clues of Anduin's survival. Progress: You've returned. I trust you have news.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 211774, 211775, 211783 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211752, ["x"] = 0.302667, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211752, ["x"] = 0.302667, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.302667, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78392] = { ["id"] = 78392, ["name"] = "The Tangled Web", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "Make no mistake--I have no intention of sending you off to skitter about in the dark like a freshly-hatched beetle. It wouldn't do to have my little morsel snatched up by a starving cave borer. You must educate yourself, my dear. Your allies have found themselves ensconced in a torrid tapestry. Only by familiarizing yourself with its erstwhile architects can you hope to reclaim them. Luckily for you, I have made some of my personal resources available to you.", ["objectivesText"] = "Peruse the Weaver's archives. Progress: Haven't you finished yet? Really, the archives' design is quite elegant. Just tap and listen. Even a spindly thing like you can figure it out, I am sure.", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78393] = { ["id"] = 78393, ["name"] = "A Seeming Respite", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "You have endured quite the evening since your ill-fated little ship ride, haven't you? Worry not, little morsel. You will find that my friends here are most accommodating, even to someone with your predilections--as strange as they may be. Please, take a moment to explore. Avail yourself of my many amenities. With luck, you will find some sorely-needed rest. ...Oh, but do take care not to move about too quickly. Sudden movements, I'm sure you understand.", ["objectivesText"] = "Explore the Lair of the Weaver. Progress: There is no need to be afraid! I am almost certain my companions will not eat you.", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78457] = { ["id"] = 78457, ["name"] = "Stones of Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "I am Merrix , Councilward of Dornogal. I appreciate your aid--especially in light of the fraught nature of your arrival. You must forgive Stormward Baelgrim. Being suspicious is part of his directive. A formal discussion of our situation is warranted. If you wish to strike back at the nerubians, as we do, meet us at the Foundation Hall. Baelgrim and I need to review the data so far. In the meantime, you are my guest. Take my ring. It will allow you to access Dornogal's amenities.", ["objectivesText"] = "Meet with various earthen citizens in Dornogal. Progress: The attack seems concentrated on the Coreway. The rest of the city is secure, but we should ready ourselves for anything.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216697 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217854, ["x"] = 0.295, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78459] = { ["id"] = 78459, ["name"] = "State of the Union", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "I hate to admit it, but we have been caught unprepared by the nerubians. Our processes focused on sustaining Dornogal and our declining population. Stormward Baelgrim's stalwart pride has kept him and the Stormriders capable fighters, but they are already stretched thin, and they are not builders. The Coreway's damage surpasses our ability to fix it. But... that was not always so. I suppose if you wish to understand, you must learn more about us.", ["objectivesText"] = "Learn from Merrix about the Council of Dornogal. Progress: So much has been lost.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2QuestHubAreaPoiID"] = 7898, ["questType"] = "standard", ["flags"] = {  },
},
[78460] = { ["id"] = 78460, ["name"] = "Hypocenter", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "I have failed my people. The Coreway is impassible. Dornogal's lifeline to the Ringing Deeps has been severed as has the path beyond. The nerubians will get their comeuppance. It is my edict as it is my will. I will ascertain if the Councilward yet functions and bring him to the Archive. Speaker Brinthe should be there, titans willing. But Oathsworn citizens are still in peril. If you wish to ally with us, clear the debris here and help our survivors. I will meet you at the Archive.", ["objectivesText"] = "Clear debris and rescue earthen on the way to the Archive. Progress: The Archive looks intact, fortunately. We must keep it that way at all costs.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 217610 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217853, ["x"] = 0.296, ["y"] = 0.595333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78461] = { ["id"] = 78461, ["name"] = "The Fourth Seat", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "With me da' and Anduin weakened and Alleria nowhere to be found, it's up to us, <name>, to clear the way for Thrall an' Jaina's army if we hope tae strike back at the nerubians an' Xal'atath. But we cannae get to the nerubians without the Coreway. An' we cannae repair the Coreway without the earthen's help. If Merrix thinks this Adelgonn an' her \"Unbound\" are the only ones that can fix the Coreway, then we need tae find her. Time tae sharpen me smile an' put on me diplomat hat. Are ye with me, <name>?", ["objectivesText"] = "Find Adelgonn in Freywold Village in the Isle of Dorn . Progress: If you are with Baelgrim, then the Council and Oathsworn must have accepted you onto our land.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217864, ["x"] = 0.405, ["y"] = 0.259 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.259 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2QuestHubAreaPoiID"] = 7898, ["questType"] = "standard", ["flags"] = {  },
},
[78462] = { ["id"] = 78462, ["name"] = "Echoes of Compassion", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "The last thing I expected today was to see Baelgrim--much less receive his help. But I guess since the Coreway was damaged, he has no choice. I... do not know how to compute this. It is only logical to accept it. < Adelgonn begins crushing the fungarian flesh roughly in her stone hands. It becomes a masticated pulp disturbingly quickly.> Here. Mix this with mud and apply it to the injured.", ["objectivesText"] = "Heal 5 Earthen denizens in Freywold Village. Progress: We've fought off animals and elementals before, but nerubians? My people are artisans and miners--not warriors.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 219796 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78463] = { ["id"] = 78463, ["name"] = "Building Blocks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The quarry is overrun with fungarians, all of the mining tunnels are collapsed, and we do not have time to clear them out and rebuild! However, I did spy a good amount of ore on the ground on the way here. It would be a start at repairing the Coreway but... < Baelgrim sighs and grimly looks at the injured Unbound earthen.> I am needed here. With Adelgonn's people. My people. Will you gather the ore in my stead?", ["objectivesText"] = "Collect 20 Glittering Ore in The Orecreg. Progress: Collect as much ore as you can. The Coreway is still my priority, but these injured need immediate help.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211962 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217881, ["x"] = 0.418, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217881, ["x"] = 0.418, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78464] = { ["id"] = 78464, ["name"] = "Delve into the Earth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The nerubian attack, your meteoric fall... And now Baelgrim is here? Baelgrim needs more hands for his Coreway, but I couldn't help even if I wanted to. My people are dying as we speak. Some were abducted by the nerubians during the attack. You're not the first outlander I've met. A small fellow, like Moira, arrived here earlier and wasted no time following the nerubians. He took the path west to a nearby cave. I would be in your debt if you found my people.", ["objectivesText"] = "Complete the Earthcrawl Mines delve near Freywold Village. Progress: The mines were always dangerous even when the Stonebound worked them. Be careful.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 219783, 219784, 219785, 219786, 219787, 219788, 219789, 219790, 219792 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78465] = { ["id"] = 78465, ["name"] = "Golgrin's Reach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Now that we have the opals, we can meet Brinthe in Golgrin's Reach. She said there's a project she's workin' on there she wants me tae help with. I wonder what it is?", ["objectivesText"] = "Meet Dagran at Golgrin's Reach in the Isle of Dorn .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78467] = { ["id"] = 78467, ["name"] = "Charge for a Charge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I am pleased Dagran has brought you here. I need help with a dangerous task. I used Dagran's opals to repair the titan console we recently recovered from this site. The Oathsworn have long wanted to learn more about the titans and restore records unreachable in the Archive--or from before its construction. This console may hold some answers if we can bring it back online. Take this device I have made. It will lead you to titan power cells we can use to power it on now that it is restored.", ["objectivesText"] = "Collect 3 Power Cells in Golgrin's Reach. Progress: Without power, we will not be able to bring the console online.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 11566, 65918, 65944, 65968, 65991, 66007, 131617, 174292, 175474, 175475, 175476, 175477, 177053, 178156, 179942, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 194347, 194348, 194349, 194380, 198048, 198059, 200453, 204075, 204673, 204732, 204735, 204736, 204744, 204745, 204760, 204762, 204765, 204766, 204768, 204770, 204773, 204774, 204776, 204780, 204782, 204783, 204787, 204789, 204896, 204898, 204901, 215177, 215179, 215180, 237812, 239607 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78468] = { ["id"] = 78468, ["name"] = "The Archive", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The memory gem you recovered is what its name suggests. It contains an earthen's memories, directives, and a hard coding of our Edicts. This building, the Archive, is the nexus of our civilization. Here, memories are cycled, catalogued, and stored at the end of an earthen's scheduled rotation. With the codex I have invented, we can access one or two memories from a memory gem. Take it, and read the memory gem you found.", ["objectivesText"] = "Use the Prismatic Codex to view the Memory Gem. Then, return the Memory Gem to the Archival Repository in The Archive. Progress: The operating instructions are simple: insert the gem into the device, and a memory will play.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 204076, 221751, 224784, 229354, 237812, 239118, 244865, 248651 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217857, ["x"] = 0.295, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217857, ["x"] = 0.295, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78469] = { ["id"] = 78469, ["name"] = "Prairie Fever", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "I was supposed to see Kodun earlier, but I'm as petrified as unliving stone. The attack on the village was... paralyzing. < Hreka takes a deep breath and focuses on the shape of another jar.> Could you do me a favor and deliver those jars to Kodun ? He's a stone's throw away in the village pottery shop. I must finish this piece before the clay dries.", ["objectivesText"] = "Examine and then deliver Hreka 's pottery jars to Kodun in Freywold Village. Progress: Are you one of the newcomers from the beach crash?", ["rewardGold"] = 306800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78470] = { ["id"] = 78470, ["name"] = "The Proscenium", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The nerubians are attackin' the earthen again. We must follow that swarm! I fear we are outnumbered, but if the earthen can come together and stand with us... We may just have a chance.", ["objectivesText"] = "Journey to the Proscenium in the Isle of Dorn .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217878, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217898, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78471] = { ["id"] = 78471, ["name"] = "Convergence", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "We know the nerubians are in league with Xal'atath. An' we have a fair idea why they attacked us--and Dalaran. They seem bent on destroying the earthen--even kickin' 'em when they're down. But why? Is it because the Coreway is the key an' destroyin' it was nae enough? Maybe what we're doin' here, repairin' the Coreway, is just what they dunnae want us to do. We should go back to Dornogal an try to piece this together.", ["objectivesText"] = "Return to Foundation Hall in Dornogal.", ["rewardGold"] = 29700, ["rewardXP"] = 1190, ["rewardItems"] = { 219750, 219751, 219752, 219753 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217898, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217905, ["x"] = 0.402, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.506667 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78529] = { ["id"] = 78529, ["name"] = "Violent Impact", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "<Your vision swims as you slowly regain consciousness. Distant shouts and screams echo in your ringing ears. The last thing you remember is Dalaran, the great, floating city of magic, plummeting to the earth--then nothing but darkness. Mixed in with sounds of shouting and battle, you hear a strange, insectoid chittering. The nerubians were waiting for you. You must rejoin the fight, but first you need to free yourself from the crushing weight of the rubble piled atop you.>", ["objectivesText"] = "Climb out of the rubble and find your surviving leaders.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 }, { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78530] = { ["id"] = 78530, ["name"] = "Slay the Saboteurs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 83548 }, ["description"] = "The nerubians are everywhere, <name>. There are too many for all of them to be solely crash survivors. I've seen others burrowing up from the ground. This Queensguard Zirix was laying in wait here to overwhelm us. Let them know we are not easy prey. Cut them down!", ["objectivesText"] = "Kill 12 nerubians. Progress: We need to thin their numbers if we are to survive this.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78531] = { ["id"] = 78531, ["name"] = "Urgent Recovery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "We survived mostly unharmed. Not everyone was so lucky. Many who were in Dalaran when it went down are unaccounted for. They will need our help. Search the battlefield for survivors. Help them in any way you can. We need everyone up and fighting!", ["objectivesText"] = "Aid 7 survivors of the Dalaran crash. Progress: We must save everyone we can.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78532] = { ["id"] = 78532, ["name"] = "Erratic Artifacts", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 80334 }, ["description"] = "Dalaran housed many precious and powerful relics. Many of them were damaged in the crash and are now malfunctioning. They must be destroyed! Take this scroll. I have stored a shattering spell within it. Read the words aloud and its magic will be unleashed. Report what you have done to Jaina when you are through. She will understand.", ["objectivesText"] = "Destroy 5 Damaged Arcane Relics. Progress: It pains me, but we have to destroy the malfunctioning relics!", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 211535 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223166, ["x"] = 0.308, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78533] = { ["id"] = 78533, ["name"] = "Secure the Beach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "Queensguard Zirix emerged from the ground and surprised Magni. He's near the farthest edge of the wreckage fighting off his swarm. Moira and I were trying to help, but we couldn't draw them away. Come with me. Magni needs our help!", ["objectivesText"] = "Find Magni and defeat Queensguard Zirix.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 219754 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212450, ["x"] = 0.295, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211859, ["x"] = 0.304, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78534] = { ["id"] = 78534, ["name"] = "To Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "You have brought death and destruction to our shores the likes of which has not been seen in millennia. But you have nerubian blood on your hands and a thraegar at your side. This is enough to earn my trust--for now. My Stormriders and I must return to our capital, Dornogal, and investigate what is likely an ongoing attack there. Fly with us. Our slipstream will allow you to soar through the skies with ease. I will send other Stormriders to collect your allies once it is safe for them to land.", ["objectivesText"] = "Meet Baelgrim in Dornogal by following the Stormrider's Slipstream. Most services in Dornogal will be unavailable during this quest. Progress: We need answers.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 225239 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211859, ["x"] = 0.304, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216628, ["x"] = 0.335, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78535] = { ["id"] = 78535, ["name"] = "They Come from Below", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "I do not yet know why you have come here, outlander. But you seem... efficient in killing nerubians. As are we, the Stormriders, vanguards of this isle. The nerubians are an ancient enemy. I would not be surprised if this Zirix knows and fears me, the Stormward. Even so, we could use your skill to help us protect Dornogal. I have a stormrook for you to ride. Mount up and help us rid our city of these insects!", ["objectivesText"] = "Mount the stormrook Lokren and slay nerubians in Dornogal. Most services in Dornogal will be unavailable during this quest.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216628, ["x"] = 0.335, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78536] = { ["id"] = 78536, ["name"] = "Impossible Odds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "By the titans... The Coreway appears completely destroyed! It will take years, perhaps centuries, to remove the rubble and repair the damage the nerubians did to its inner structure, much less traverse to the world's core. More than that with the Stonebound gone... I must take a moment to decide what to do. Your friends have safely arrived. Speak to them, and stay out of my way. If we need you, I will let you know.", ["objectivesText"] = "Speak to Thrall. Progress: The Council must be appraised. There will be much to do...", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 219746, 219747, 219748, 219749 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78538] = { ["id"] = 78538, ["name"] = "Group Effort", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "The Unbound have arrived with the equipment and resources needed to begin repairing the Coreway. This is a momentous occasion. One for the Archive! I would not say this to Adelgonn, but I see the titans' hands in it... And now it is time for me to exercise my directive! I have devised a plan for how to organize our workers most efficiently--and have also allocated supplies to welcome them. Take these orders to Adelgonn's workers so that they can begin in earnest. We will meet you there shortly.", ["objectivesText"] = "Distribute Merrix 's orders to 10 Unbound Workers around the Coreway. Progress: We must begin work at once.", ["rewardGold"] = 297900, ["rewardXP"] = 9515, ["rewardItems"] = { 213271 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217904, ["x"] = 0.4, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 212746, ["x"] = 0.36, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78539] = { ["id"] = 78539, ["name"] = "Lasting Repairs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "With my Stormriders... inactive, Dornogal is undefended, save a handful of lay peacekeepers. If the nerubians attack us here again, Dornogal will fall--and all of us with it. It is imperative we draw them away from the city and take out their commander. We can and will make our own web and capture Zirix in it. I have a plan.", ["objectivesText"] = "Discuss the plan to attack the nerubians with Baelgrim . Progress: We cannot remain on the defense.", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78540] = { ["id"] = 78540, ["name"] = "To the Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "Your archer friend is right. We must eliminate Zirix and his forces if the Coreway is to remain safe. Let us head to the Cinderbrew Meadery at once.", ["objectivesText"] = "Meet Baelgrim at the Cinderbrew Meadery.", ["rewardGold"] = 30000, ["rewardXP"] = 1190, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78541] = { ["id"] = 78541, ["name"] = "Lay the Trap", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "With all these cinderbrew kegs here, this meadery would burn hotter than the Forgegrounds if they were all ignited. I surmise that's why Wenbrandt's kegs are made out of stout and strong ironwood--they do not break or catch fire easily. Luckily, we can start a reaction from the inside if we lead fuses into each of them. Those ropes the workers left around should work in a pinch.", ["objectivesText"] = "Connect 4 Rope Fuses to Sizzling Kegs. Progress: We need to get the cinderbrew kegs prepared.", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78542] = { ["id"] = 78542, ["name"] = "Evacuation Area", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "Look, you can blow up my life's work if it is our only choice, but I will not put my workers in danger. This was the path we all chose, but I won't have them sacrifice themselves to fire or nerubians for it. Tell them that I said they need to get out of here immediately. And if a single one of them gets so much as chipped, the Council will have a lot to answer for!", ["objectivesText"] = "Evacuate 8 Unbound Meadworkers. Progress: If my workers cannot be kept safe, I am putting a stop to this plan.", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212750, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212750, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78543] = { ["id"] = 78543, ["name"] = "Poking the Spider Nest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "The meadery is evacuated and the explosives are primed. It is time to bait the nerubians into our trap. Your compatriot is by the nerubian burrow north of here. She told me her directive is to keep watch over it in case the nerubians make a move before we are ready. So far they have not made a move and may now need... coaxing. Take a keg of cinderbrew to the burrow. Tossing it in should stir their \"nest.\" Rendezvous with us back at the Meadyard--quickly--after.", ["objectivesText"] = "Throw a Keg of Cinderbrew Mead into the nerubian burrow and then return to the Meadyard.", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212756, ["x"] = 0.748, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78544] = { ["id"] = 78544, ["name"] = "Bring the Thunder", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "The nerubians will strike out in anger and pride--which is exactly what we want. They will swarm the meadery soon, seeking to punish us for attacking their burrow. We will hold them here on the ground while you take to the skies. When Zirix appears to command his army, we will light the fuses. Wenbrandt scrounged together some supplies we can use to corral the nerubians. Set them up quickly, and then we will get you on a stormrook. Go!", ["objectivesText"] = "Hold off the nerubians at the Cinderbrew Meadery until Queensguard Zirix appears.", ["rewardGold"] = 607600, ["rewardXP"] = 11895, ["rewardItems"] = { 219755, 219756, 219757, 219758 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212756, ["x"] = 0.748, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217849, ["x"] = 0.75, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78545] = { ["id"] = 78545, ["name"] = "Return to the Coreway", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We dealt a heavy blow to the nerubians. But Baelgrim... < Adelgonn pauses to compose herself.> He was infuriatingly rigid and we argued ceaselessly, but in the end... he was a defender of our people--all of them. Baelgrim sacrificed himself to vouchsafe the Isle of Dorn from the nerubians. Everyone needs to know that--and we can't let the nerubians force our hand like that again. Go back to Merrix in Dornogal. Tell him we will come soon. We just... need a moment here.", ["objectivesText"] = "Return to Merrix in Dornogal. Progress: How fares your sortie at the meadery?", ["rewardGold"] = 303800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217849, ["x"] = 0.75, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78546] = { ["id"] = 78546, ["name"] = "Recompense", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We heard the echo of the explosion from here. I presume you have found victory, but your solitary arrival suggests not all is well. What happened?", ["objectivesText"] = "Speak to Adelgonn to inform Merrix of Baelgrim's fate. Progress: Tell me what happened.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219760, 219761, 219762, 219763 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78555] = { ["id"] = 78555, ["name"] = "Underground and Overwhelmed", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 80434, 83550 }, ["description"] = "I've been away too long. The Machine Speakers are clearly not faring well here. Does the High Speaker know about this? Nerubian sabotage and gross negligence are a devastating combination. We need to get Ironhaul Station up and running as soon as possible. It's a vital link between the Ringing Deeps and the city up above. Please, $p, help our injured workers, collect any salvageable cargo, and restore safety to Ironhaul Station.", ["objectivesText"] = "Help Machine Speakers secure Ironhaul Station. Progress: Dead nerubian skitterlings, unexploded bombs, injured workers... what a mess.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 216720 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78557] = { ["id"] = 78557, ["name"] = "Getting Off Track", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Speaker Brinthe acknowledged. Outlanders, there is work to do. One of our larger mine carts has derailed. It's blocking the station's main junction. My workers' productivity is impaired, and their functioning is suboptimal. The titans put us here to work, but my workers aren't all working. Could you go and get us back on track? Be careful. I can see you're made of flesh and bone. I don't want you to be crushed.", ["objectivesText"] = "Investigate the derailed mine cart in Ironhaul Station. Progress: As long as we stay loyal, hit our deadlines, and meet our quotas, everything will be fine. The gears keep grinding, and we keep working. Praise the Machine.", ["rewardGold"] = 303800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218290, ["x"] = 0.4, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218290, ["x"] = 0.4, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78562] = { ["id"] = 78562, ["name"] = "Discarded and Broken", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["description"] = "You there! You're here to help, aren't you? The humming melody of the machines is changing, and I... I admit I am not ready. For so many years I served faithfully, and then... Well the important thing is that I'm ready to get to work again. But you see, my tools have all been broken and scattered about. If you could keep an eye out for them and bring them back to me, I would be in your debt.", ["objectivesText"] = "Collect Machinist Kittrin 's lost tools. Progress: A machinist is nothing without the tools of office.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 210732, 210733, 210734 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78563] = { ["id"] = 78563, ["name"] = "The Weight of a World", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["series"] = { 78564 }, ["description"] = "My tools didn't randomly end up where you found them. They were placed there. By me. I had reached a point so low that I saw no alternative. The machines, the great work of my people, were never going to sing again. So why should I bother to keep them repaired? But now I see, and now, I understand! The last tool I need, I dropped it into the water, and it was eaten by a giant creature. I think that one might need a bit more force to return it to me.", ["objectivesText"] = "Collect Machinist Kittrin 's Calibrated Weight. Progress: Once I have all my tools back, I know that things will be right again.", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 210740 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78564] = { ["id"] = 78564, ["name"] = "Reforged Purpose", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["series"] = { 78563 }, ["description"] = "That's all of them! Now, it's time to do my duty and recast these tools. Reforge them, and myself, into what I was meant to be: a proud machinist of the Ringing Deeps .", ["objectivesText"] = "Help Machinist Kittrin reforge and rededicate the tools. Progress: I'm ready to do my part once again. I just need to reforge these old tools.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 223572 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78570] = { ["id"] = 78570, ["name"] = "Frayed Legacy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["series"] = { 78571 }, ["description"] = "Keep true, <race>t. We of the Woldguard uphold an ancient promise to Freya to tend to these lands. Our edict is older than those wielded by the demagogues in Dornogal. Older than Dornogal itself. However, not all lands have been tended equally. The leader of our order was to care for the basin nearby but we've not heard from them in many cycles. I have sent a novice to investigate. Aid them and my order will be in your favor.", ["objectivesText"] = "Meet Igris at the Boskroot Basin on the Isle of Dorn .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212708, ["x"] = 0.416, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78571] = { ["id"] = 78571, ["name"] = "Mycomayhem", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["series"] = { 78570 }, ["description"] = "Freydrin was the leader of my order. I was sent here to assist them. I was too late. There is a darkness that haunts these woods, <race>s. These woods were Freydrin's home. It was her charge to tend to them, so given by the Keeper herself. And now she is gone and her woods run amok. Bring me the spores of these mayhemic menaces. Perhaps there is a way to cleanse this land yet.", ["objectivesText"] = "Collect 30 Boskroot Spores from fungarians in Boskroot Basin. Progress: Do you have them all?", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 210845 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78572] = { ["id"] = 78572, ["name"] = "Wold Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "Freydrin must have had some way of fending off the fungarians. Although there are few left in the countryside who still follow the Edicts, Freydrin was long a true believer. She would never have allowed these woods to reach this state while she held faith. We should take a look at her home in the woods. Perhaps there is something that may prove useful inside.", ["objectivesText"] = "Search Freydrin's home for help against the fungarians in Boskroot Basin. Progress: Looking through the Woldkeeper's things unnerves me. So many untold stories.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 154874, 154875, 154894, 216858 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78573] = { ["id"] = 78573, ["name"] = "Keeper's Aid", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "Magical staff? Wards? What were you doing, Freydrin? <Igris ruminates briefly, her brow crinkling and eyes aglow. After a moment, she turns to you with a smile carved into her face.> I've got it! The life energy in this staff should overcome any mycotic corruptions in the wildlife here. Then you return them to the natural cycle and the land will heal on its own in time. And if you see any wards, take them down. Take her memory gem just in case. It may yield more information yet.", ["objectivesText"] = "Use Freydrin's Shilelagh to purify Boskroot Basin. Progress: There is much latent magic buried within this staff. It may be our only hope to bring these fungarians to heel.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215158 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78574] = { ["id"] = 78574, ["name"] = "Boss of the Bosk", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "There is one final thing I must ask of you. There is a great monster that roams these woods. I am certain you've sensed it. It must be felled. Rotbark was Freydrin's final means to control this basin, but even this was too great for any individual earthen. Ours is not to control, but to tend to its needs. Use the staff once more and bring an end to Rotbark's reign.", ["objectivesText"] = "Defeat Rotbark the Unfelled in Boskroot Basin. Progress: If we are to restore this place, we must do so a different way. We must carve a new path.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 215142, 219766, 219767, 219768, 219769 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
