[78607] = { ["id"] = 78607, ["name"] = "To Mereldar", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "We must get to Mereldar and let General Steelstrike know what the Order of Night tried here. Thank the Sacred Flame we stopped them before they could do any worse.", ["objectivesText"] = "Travel to Mereldar and meet with General Steelstrike.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214364, ["x"] = 0.434, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78613] = { ["id"] = 78613, ["name"] = "The Bastion of Hallowfall", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "I have to admit, I did not think that the first visitors we'd have in Mereldar would have been outsiders. I thought the Empire... Well, nevermind. You have been more than helpful to my people, and that deserves recognition. Mereldar is the bastion of the Arathi in Hallowfall . Take some time, rest.", ["objectivesText"] = "Explore Mereldar. Progress: This city has much to see.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 216687, 217708 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220124, ["x"] = 0.419333, ["y"] = 0.555333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78614] = { ["id"] = 78614, ["name"] = "Mereldar's Light", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying. Faerin sent word that she was going to the orphanage, and asked you to meet her there. She often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.", ["objectivesText"] = "Play with 3 Arathi Orphans . Progress: It's great to see how happy these kids are, after what they have gone through.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220124, ["x"] = 0.419333, ["y"] = 0.555333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78615] = { ["id"] = 78615, ["name"] = "The Bell Tolls", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Those bells mean Mereldar is under attack! Let's get to the gates and find out what is going on.", ["objectivesText"] = "Go to the main gates of Mereldar in Hallowfall .", ["rewardGold"] = 29500, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220124, ["x"] = 0.419333, ["y"] = 0.555333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.419333, ["y"] = 0.555333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
