[78624] = { ["id"] = 78624, ["name"] = "A Candle in the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Beledar has turned to Shadow, we must retreat back to Mereldar! <Vaelisia looks towards Aelric Leid .> I-- No. We need to destroy Aelric first. Take him down, then we retreat.", ["objectivesText"] = "Kill Aelric Leid in the Veneration Grounds in Hallowfall .", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 220133 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
