[78626] = { ["id"] = 78626, ["name"] = "Spar Day", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Your skills in combat are impressive, <name>. We are rotating our next round of reserves into active duty, and they need to sharpen their skills. While Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.", ["objectivesText"] = "Duel 8 Arathi Recruits in Mereldar. Progress: The tricks they learn from you today will help them survive a difficult encounter later.", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
