[78630] = { ["id"] = 78630, ["name"] = "The Rise of the Reckoning", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "The Reckoning is ready! Let's make these spiders pay. Blood for blood.", ["objectivesText"] = "Board The Reckoning and slay 150 nerubian forces. Progress: We will make the nerubians regret ever thinking they could push into our home!", ["rewardGold"] = 929400, ["rewardXP"] = 15285, ["rewardItems"] = { 220128, 220129, 220131, 220132 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.383667, ["y"] = 0.692333 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
