[78631] = { ["id"] = 78631, ["name"] = "Speaking to the Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78837, 78838 }, ["description"] = "I've heard about a problem nearby, and I think I know what's wrong. We used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in. We haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it. Someone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.", ["objectivesText"] = "Reassure Gundargaz' defenders on the way to the Lost Mines.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78634] = { ["id"] = 78634, ["name"] = "Leave No Stone Behind", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Many earthen fell when the kobolds took this mine. Worse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen? We will not fail them again, <name>. Gather the identification plaques of those we lost, so we may commemorate them properly.", ["objectivesText"] = "Recover Identification Plaques from fallen earthen in the Lost Mines. Progress: Have you found them?", ["rewardGold"] = 306800, ["rewardXP"] = 9920, ["rewardItems"] = { 210873, 217694, 217695, 217696, 217699 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78635] = { ["id"] = 78635, ["name"] = "Death and Waxes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom! We steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead! Also means we not have to wait out here in dark until get eaten. Hurry!", ["objectivesText"] = "Recover Flickerflame Candles from around the Lost Mines. Progress: Did you take candle?", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 210878, 219361, 219363, 219368, 219375 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78636] = { ["id"] = 78636, ["name"] = "Retaking the Mines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Now that we have the keys, it is time to take the fight to the Candle King. Get that gate open. Once we're inside, we'll move on to the next step.", ["objectivesText"] = "Unlock the gate to the Lost Mines.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 218307, 219014 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215671, ["x"] = 0.580667, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78637] = { ["id"] = 78637, ["name"] = "Cracking Cogchewer", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. Need his keys to get in the mines... and get me out of this thing!", ["objectivesText"] = "Kill Cogchewer in the Lost Mines and recover his keys. Progress: Did you find keys?", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 211865 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78638] = { ["id"] = 78638, ["name"] = "Engineering Destruction", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Some of the kobolds are retrofitting equipment left behind when the mines fell. Please, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy. There was a storage depot on the western edge of the lowest level of the mine. Start there.", ["objectivesText"] = "Destroy mining rigs in the Lost Mines. Progress: Are any still operable, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78639] = { ["id"] = 78639, ["name"] = "Ko-boldening", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Bullies everywhere! Innocent kobolds kept down by Candle King's thugs all across Warrens. Give bullies taste of own medicine! Once bullies beaten, innocent have chance to run. Be free!", ["objectivesText"] = "Free oppressed kobolds in the Warrens by defeating their captors. Progress: Now they will see what it feels like!", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 219365, 219367, 219374, 219378 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78640] = { ["id"] = 78640, ["name"] = "Manifesto Destiny", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Before take mines, my people live in great city. Stoneheads call it the Warrens. Candle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King. What better way than pamphlets? Everyone love pamphlet! We draw real good! Brinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets! < Skitter looks at you expectantly, making small flapping motions as she waits.>", ["objectivesText"] = "Scout out and distribute pamphlets across the Warrens from the air. Progress: Never flown before. Is fun?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215672, ["x"] = 0.581333, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.581333, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78641] = { ["id"] = 78641, ["name"] = "Tackling Torchsnarl", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully. We show everyone. Bullies can be beaten!", ["objectivesText"] = "Defeat Torchsnarl in the Warrens. Progress: Torchsnarl is big one. Don't know why hiding behind flunkies. Still, can't miss him!", ["rewardGold"] = 561800, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78642] = { ["id"] = 78642, ["name"] = "New Candle, New Hope", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "We weaken Candle King's grasp. Still need symbol, rally my people. King has ancient relic: symbol of hope. Called Candle Crown . Heart of my people. Candle King threw away! Found new prize: Darkflame Candle. That crown? Still in hoard. Candle King should come out now. See what we did here! While he looks, we sneak in! Use old tunnels! Take what's ours! We smart.", ["objectivesText"] = "Recover the Candle Crown from the Darkflame Cleft. Progress: We take hope from darkness, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 19840, ["rewardItems"] = { 210882, 212575, 217171, 219459, 220737, 258264 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78656] = { ["id"] = 78656, ["name"] = "Hose It Down", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78656 }, ["description"] = "With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline. We need your help to clean up this gooey blight! I have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.", ["objectivesText"] = "Activate Baeny the Barrel and use the hose to wash away 40 Contaminating Goo. Progress: Have you cleaned up the shoreline?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211942 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
