[78658] = { ["id"] = 78658, ["name"] = "The Hallowed Path", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "$p, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall . She's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence. Adelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.", ["objectivesText"] = "Meet with the denizens of Hallowfall . Progress: Who are you?", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213983, ["x"] = 0.449, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214, 2215 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78659] = { ["id"] = 78659, ["name"] = "Where the Light Touches", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["series"] = { 83551 }, ["description"] = "Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships. General Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed. If you're willing, ride with me or meet me there.", ["objectivesText"] = "Meet with Faerin's ally near the Aegis Wall.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78665] = { ["id"] = 78665, ["name"] = "Tunnel Trouble", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "It's good to have new allies here. Together, we have much better chances of protecting this tower. The nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall. If you can handle that, we will survey the field from the top of the wall and meet you there.", ["objectivesText"] = "Destroy 6 Nerubian Burrows . Progress: Were you able to stop the nerubians from coming under the ground?", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.710667, ["y"] = 0.587333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78666] = { ["id"] = 78666, ["name"] = "The Only Good Spider", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, if we don't stem the tide of nerubians climbing up to us, nothing else will matter. Their numbers are just too great. We need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint. Do what you can to thin their numbers.", ["objectivesText"] = "Kill 12 Nerubian attackers. Progress: <name>, every nerubian you kill here could mean a life saved in Hallowfall , and aids the chances of our own success.", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.710667, ["y"] = 0.587333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78667] = { ["id"] = 78667, ["name"] = "Rekindled Memories", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "Good people died here today, $p--a lot of them. Every Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope. With the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.", ["objectivesText"] = "Recover 6 Arathi tinderboxes from fallen soldiers and burn their bodies. Progress: Have you recovered their tinderboxes? Every life deserves to be remembered in the Sacred Flame.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 213191, 220119, 220125, 220126, 220127 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78668] = { ["id"] = 78668, ["name"] = "Rally on the Dawnbreaker", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent. The nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies. If we lose our armada, our hopes fade dramatically. Meet us there when you can.", ["objectivesText"] = "Meet Faerin at Tenir's Ascent aboard the Dawnbreaker.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224945, ["x"] = 0.575, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78669] = { ["id"] = 78669, ["name"] = "For Their Eyes Only", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "We've fought the nerubians since we arrived, $p. Their attacks have not risen to this level in a long time. These airship docks are clearly a target, but do they have any others? Is there a larger goal? The nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.", ["objectivesText"] = "Gather 3 nerubian Shadecasters to learn their plans. Progress: Have you found any of those shadecasters yet, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 216658, 216659, 216660 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224946, ["x"] = 0.574, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78670] = { ["id"] = 78670, ["name"] = "Siege Weapon Sabotage", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, if we're going to hold the nerubians back, we have to deal with their siege weapons. Around Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work. Gather some barrels, and take them down to the nerubian siege weapons.", ["objectivesText"] = "Destroy 4 siege weapons below Tenir's Ascent. Progress: Were you able to destroy their siege weapons, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 213630, 220118 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224945, ["x"] = 0.575, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78671] = { ["id"] = 78671, ["name"] = "The Light of the Dawntower", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "$p, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall . Kyron is there as well. It's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light. Meet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.", ["objectivesText"] = "Assist the Lamplighters in lighting the dawntower.", ["rewardGold"] = 147500, ["rewardXP"] = 5095, ["rewardItems"] = { 220107, 220111, 220113, 220114 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645667, ["y"] = 0.576333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78672] = { ["id"] = 78672, ["name"] = "A Lamplighter's Duty", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Darkness has fallen. We can't rest yet. < Faerin gives you a weary smile, but there is a light in her eyes.> The light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. My patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.", ["objectivesText"] = "Take the Lamplighter Skiff to Lorel's Crossing.", ["rewardGold"] = 607600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78685] = { ["id"] = 78685, ["name"] = "The Tunnel's End", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "So we're hearing more rumors about Taelloch. The town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there. That tells me we should investigate. And of course, if people are hurting, then we should help them.", ["objectivesText"] = "Investigate the rumors about Taelloch. Progress: We have to find out what happened here.", ["rewardGold"] = 210675, ["rewardXP"] = 7440, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218715, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213612, ["x"] = 0.583, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78686] = { ["id"] = 78686, ["name"] = "Lights Out", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid. The dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall , it's probably because of the rising tide of kobyss. Lamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?", ["objectivesText"] = "Meet Taenar and Aemyra near Velhan's Claim.", ["rewardGold"] = 29700, ["rewardXP"] = 1275, ["rewardItems"] = { 38666, 223432, 237812, 246936, 249400, 251257, 251821, 254267, 254579, 260854, 260855, 260856, 260857 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214019, ["x"] = 0.492, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78687] = { ["id"] = 78687, ["name"] = "Crash Recovery", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "A lot of things went wrong when the Indomitable crashed, $p. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades. It seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form. Take back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.", ["objectivesText"] = "Retrieve 4 Recovered Tinderboxes from the Indomitable's stalwarts. Progress: Did you find those tinderboxes, <name>?", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["rewardItems"] = { 212317 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78688] = { ["id"] = 78688, ["name"] = "Cage, Match", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice. Those sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims. Let's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.", ["objectivesText"] = "Burn 10 kobyss cages with Aemyra's Holy Flame. Progress: Have you dealt with those cages yet? The citizens of Velhan's Claim won't be safe until you do.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 211945 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78689] = { ["id"] = 78689, ["name"] = "If It Leads, It Bleeds", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Everything rises and falls on leadership, $p. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand. Without leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map. Deal with them, and we'll be much more able to help Velhan's Claim.", ["objectivesText"] = "Defeat the kobyss leaders besieging Velhan's Claim. Progress: Did you find their leaders? They look strong, but I'm sure you're up to the task.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78690] = { ["id"] = 78690, ["name"] = "Situational Awareness", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim. $p, will you please check in with the families here? Let them know we're here to help. See if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.", ["objectivesText"] = "Speak with 10 citizens of Velhan's Claim. Progress: It's so important to reassure the citizens of Velhan's Claim, <name>, that they'll get through this. Hope is everything in dark times.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78691] = { ["id"] = 78691, ["name"] = "The One That Got Away", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "$p, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". When they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away. I have not handled myself bravely, $p. The story of the Indomitable says I was a hero; those lies were my report. If there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, $p--help me save Maximillian.", ["objectivesText"] = "Rescue Maximillian at the crash of the Indomitable. Progress: Stay focused, <name>--we have to find my son.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 34863 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.471333, ["y"] = 0.133333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78692] = { ["id"] = 78692, ["name"] = "Teach a Man to Fish", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "$p, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. And there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. Get these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!", ["objectivesText"] = "Distribute 8 spears to the residents of Velhan's Claim. Progress: Have you handed out those spears yet? The people need them to remind them what they're capable of.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78693] = { ["id"] = 78693, ["name"] = "Spears for Fears", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them. This is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human. Head out there and gather some spears for the people, $p, and they won't have to be so afraid.", ["objectivesText"] = "Gather 8 Kobyss Spears for the people of Velhan's Claim. Progress: Kobyss giving you trouble? Soon, the people of Velhan's Claim will be the ones giving them trouble.", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["rewardItems"] = { 211948 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78694] = { ["id"] = 78694, ["name"] = "Reclaiming Velhan's Claim", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "The problem I see, $p, is the kobyss. There's just so many of them. Everyone here was serving in the Empire's military when we arrived in Hallowfall . They may be rusty now, but they've all trained before, and know how to be dangerous. But we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.", ["objectivesText"] = "Kill 12 Kobyss warriors around Velhan's Claim. Progress: How's it going out there, <name>? You sending those creatures of darkness back to the deeps?", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78695] = { ["id"] = 78695, ["name"] = "Lamp Lit", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "The kobyss normally live deep underwater, $p. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them. As Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.", ["objectivesText"] = "Place 8 torches around the perimeter of Velhan's Claim, then observe the re-lighting of the dawntower. Progress: Did you get those torches set, <name>? The people will be able to quickly light them whenever Beledar fades.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225944 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78696] = { ["id"] = 78696, ["name"] = "We Don't Go to Taelloch", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him. We shouldn't dally. We need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!", ["objectivesText"] = "Clear the entrance to Taelloch of encroaching beasts.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 219359, 219364, 219369, 219373 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213612, ["x"] = 0.583, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213634, ["x"] = 0.602, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78697] = { ["id"] = 78697, ["name"] = "Ghost of a Company Town", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby! We should go further into town and see if anyone has any idea where she might be. Or maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!", ["objectivesText"] = "Use the Investigate ability to find clues about what happened in Taelloch.", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213634, ["x"] = 0.602, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216479, ["x"] = 0.64, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78700] = { ["id"] = 78700, ["name"] = "Controlled Demolition", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "I know we've fought skardyn before, champion, but this... this is worse. I knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. If we must venture out there, I'm taking down some of those abominations along the way.", ["objectivesText"] = "Kill 18 skardyn in Taelloch Progress: There's more to be done. We can't let this corruption spread.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 219380, 219383 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216479, ["x"] = 0.64, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78701] = { ["id"] = 78701, ["name"] = "The Truth in Chalk", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean.... I'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines. And I know the foreman is the key. She has to be.", ["objectivesText"] = "Search for messages in Taelloch Mine. Progress: There's more to learn here. I'm sure of it.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78703] = { ["id"] = 78703, ["name"] = "Buried in Stone", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.", ["objectivesText"] = "Investigate the cave at the back of the Taelloch Mine Progress: We're missing something... There must be something in that cave!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78704] = { ["id"] = 78704, ["name"] = "Find the Foreman", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "Dagran was right. I suppose I shouldn't be surprised by that any longer. All the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers. We've come this far. Let's see what's inside.", ["objectivesText"] = "Find the foreman. Progress: There must be answers deeper within the cave.", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["rewardItems"] = { 219362, 219366, 219371, 219376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78705] = { ["id"] = 78705, ["name"] = "What She Saw", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "What is that? That thing the skardyn dropped before we... before it died. I think I've seen something like that before.", ["objectivesText"] = "Investigate the gem left by the skardyn. Progress: I think I know what that gem is...", ["rewardGold"] = 578600, ["rewardXP"] = 12400, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219453, ["x"] = 0.671333, ["y"] = 0.643333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.671333, ["y"] = 0.643333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78706] = { ["id"] = 78706, ["name"] = "The High Speaker's Secret", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We got what we came for. We need to return to Gundargaz. Brinthe has to know what happened here. We'll go on ahead, $p. Meet us in Gundargaz.", ["objectivesText"] = "Return to Brinthe in Gundargaz.", ["rewardGold"] = 28900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219452, ["x"] = 0.671333, ["y"] = 0.643333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.671333, ["y"] = 0.643333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78713] = { ["id"] = 78713, ["name"] = "The War Within", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81966 }, ["description"] = "There is a vision being seen across Azeroth. A \"Radiant Song.\" We believe it's a warning, but we are unsure of its meaning. Meet me in Silithus. We must ask Azeroth's Speaker what this vision means.", ["objectivesText"] = "Go to Silithus to talk with Thrall about the visions spreading across Azeroth.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 135539, 227669 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 221949, ["x"] = 0.495333, ["y"] = 0.773333 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213620, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.773333 }, ["mapCandidates"] = { ["npc"] = { 81, 85 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 81, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 5967 }, ["questType"] = "standard", ["flags"] = {  },
},
[78714] = { ["id"] = 78714, ["name"] = "A Poor Reception", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help. That's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us. He should be in the Chamber of the Heart. Let's go.", ["objectivesText"] = "Go to the Heart Chamber to ask Magni for help deciphering the Radiant Song.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 213620, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["db2PoiUiMapID"] = 2321, ["db2PoiMapID"] = 2698, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78715] = { ["id"] = 78715, ["name"] = "Azeroth's Voice", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can. But I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what. First, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?", ["objectivesText"] = "Help Magni perform his ritual. Progress: I understand Magni's concerns, but we have no other choice. The future of our world is at stake. We must try everything we can to understand what Azeroth is trying to warn us of.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 2321, ["db2PoiMapID"] = 2698, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78716] = { ["id"] = 78716, ["name"] = "Painful Lessons", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran . Follow us when you can.", ["objectivesText"] = "Take the portal to Dalaran .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78717] = { ["id"] = 78717, ["name"] = "A Mysterious Warning", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin. I saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us. That's what we need to protect.", ["objectivesText"] = "Discuss the next steps, then follow up with Khadgar. Progress: Khaz Algar...", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 629, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78718] = { ["id"] = 78718, ["name"] = "Strengthen the Wards", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst. Here, take this wand. It's been attuned with Dalaran 's defense magics. Just wave it near strategic parts of the city to strengthen our magical defenses.", ["objectivesText"] = "Strengthen Dalaran 's defenses. Progress: We will be hard pressed to save Khaz Algar if our own defenses aren't strong enough to withstand attack.", ["rewardGold"] = 216900, ["rewardXP"] = 7135, ["rewardItems"] = { 220483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 629, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78719] = { ["id"] = 78719, ["name"] = "Citizens of Dalaran", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Our citizens must be prepared for Dalaran 's departure. Can you ask around the city and see if anyone requires aid? I'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.", ["objectivesText"] = "Help the citizens of Dalaran prepare for the teleportation. Progress: Dalaran is always ready to defend the world, but that doesn't mean we can do so on a whim. Preparations are key to a smooth transportation.", ["rewardGold"] = 232300, ["rewardXP"] = 7135, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 629, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78721] = { ["id"] = 78721, ["name"] = "Meet the Team", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. They're calling themselves the Algari Expedition this time around. I'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?", ["objectivesText"] = "Check in on the Algari Expedition. Progress: A league and an expedition walk into a tavern... Nope, nothing's coming to me.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 629, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78722] = { ["id"] = 78722, ["name"] = "To Khaz Algar!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out. Let me know when you're ready to depart.", ["objectivesText"] = "Tell Khadgar you're ready to depart.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 2305, ["db2PoiUiMapID"] = 2305, ["db2PoiMapID"] = 2731, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78738] = { ["id"] = 78738, ["name"] = "Absent Speaker", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "It is a dark day for the Ringing Deeps , $p. I always knew there was something about the High Speaker that wasn't quite right. Now we have proof. And we need justice. If he has plans for the Awakening Machine, then we've got to stop him.", ["objectivesText"] = "Meet Speaker Brinthe in the Earthenworks.", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213569, ["x"] = 0.45, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78741] = { ["id"] = 78741, ["name"] = "Sympathetic Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "I have to stop the High Speaker from making more skardyn. Machine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!", ["objectivesText"] = "Look for Machine Speaker Foremen in the Earthenworks with Speaker Brinthe .", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213569, ["x"] = 0.45, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219428, ["x"] = 0.469, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78742] = { ["id"] = 78742, ["name"] = "Battle of the Earthenworks", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "$p! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker. I'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. What do you say, $p? Up for a scrap?", ["objectivesText"] = "Defeat enemy Machine Speakers, constructs, and help frightened workers in the Earthenworks! Progress: I'll admit: the ability to acquire an army at the drop of a hat has gotten me fairly far in life.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 219360, 219370, 219372, 219377 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.464667, ["y"] = 0.188667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78743] = { ["id"] = 78743, ["name"] = "Before I Depart", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 78744 }, ["description"] = "I can feel my energy reserves depleting. I will soon not be able to execute my duties. That is why I have Urtago here to take over. Before my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there. Maybe it is good you are here. You may have the strength to help us. Please, help Urtago rid the site of kobolds.", ["objectivesText"] = "Meet Urtago at the Mourning Rise memorial site.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["rewardItems"] = { 219413 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213184, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78744] = { ["id"] = 78744, ["name"] = "Honor Their Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 78743 }, ["description"] = "Take these gifts and place them by the past caretakers. Each is a gift honoring their memory. I'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix. Please do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.", ["objectivesText"] = "Eliminate the kobold infestation and place gifts near the shut-down, past caretakers. Progress: The kobolds cannot be left to desecrate Mourning Rise. The Unbound that rest here are here because they do not want to be disturbed or moved. While they do not wish to be revived, taking their armor and possessions is an insult to earthen culture. We must do something.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78745] = { ["id"] = 78745, ["name"] = "You No Take Plunder!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. Abominable. Find where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later. This vandalism will not go unchecked!", ["objectivesText"] = "Recover earthen belongings from piles of plunder. Progress: Were you able to find their plunder?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211428 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78746] = { ["id"] = 78746, ["name"] = "Laws Apply to All", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here. Still, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.", ["objectivesText"] = "Slay kobold invaders in Mourning Rise. Progress: So many of them still infest Mourning Rise.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78747] = { ["id"] = 78747, ["name"] = "The Great Collapse", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back. Remember the stuff that Korgran asked about? Explosive sticks --his recipe. I have brought enough to shake a mountain! More than enough for the kobolds. Help me show these kobolds that we will fight for what is ours so they will never come back!", ["objectivesText"] = "Use the Explosive sticks to destroy Kobold tunnels . Progress: Is it done? Were the tunnels dealt with?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211435 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78748] = { ["id"] = 78748, ["name"] = "Cutting the Wick", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Knowing kobolds, they will have several workmasters, or leaders, running this raid. Find and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.", ["objectivesText"] = "Find and slay the kobold workmasters. Progress: Were you able to slay all three of them? Their deaths will strike a significant blow to this kobold operation.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78749] = { ["id"] = 78749, ["name"] = "Who Runs This Fine Establishment?", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind. If that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down. I will meet you at this cave.", ["objectivesText"] = "Slay Grand-Heister Bokk .", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78754] = { ["id"] = 78754, ["name"] = "Lost Delivery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "<You find a small yet heavy leather-bound package on the road with an attached label.> Gundargaz Courier Express EXPEDITED To: Harvester Farnee Durgaz Cabin OPEN WITH CARE: Contains volatile elemental minerals.", ["objectivesText"] = "Deliver the Abandoned Package to Harvester Farnee at Durgaz Cabin.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214640, ["x"] = 0.67, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78755] = { ["id"] = 78755, ["name"] = "Playing in the Mud", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger! Problem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach! Bring me wet, elementally charged silt to use as our restorative substrate!", ["objectivesText"] = "Gather 20 handfuls of Elementally Charged Silt . Progress: By combining living sand and water, we can create an elemental silt that mimics the underclay's healing properties. Or at least something that comes close to it! Isn't elemental fusion fascinating?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211483, 211484, 211485 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78756] = { ["id"] = 78756, ["name"] = "Lots and Lots of Fire Honey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. Unfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. Head on down to the wold's edge and bring us some honey. You're going to need a lot.", ["objectivesText"] = "Find a lot of Fire Honey. Progress: Mind yourself in my forest. Cinderbees are dangerous, but we rely on them for the honey they produce for our mead.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211489 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214922, ["x"] = 0.67, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214922, ["x"] = 0.67, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78757] = { ["id"] = 78757, ["name"] = "Honey and Clay the Pain Away", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. The bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond. The good news is that we have all we need to tend to him. We just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! Ready?", ["objectivesText"] = "Help Harmot prepare Shalehoof's salve. Progress: Much like us earthen, healing something made from rock and stone is no easy task. But the unique properties of the clay you've brought, combined with the fusing properties of the honey makes for an excellent restorative!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78758] = { ["id"] = 78758, ["name"] = "Pulse Within the Earth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. Though, if the nerubians burrowing up didn't wake him up, I'm not sure what will. Take these earth shards and plant them on the waterfalls and hills around the lake. Once we've got them set up, I'll be able to get a reading on the giant's health.", ["objectivesText"] = "Place 4 Tremor Stones around the pond. Progress: Once you've got the shards set up, I can drop the final one here to get a proper read.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78759] = { ["id"] = 78759, ["name"] = "To Wake a Giant", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "By the Coreway, this stuff packs a punch! Combining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain! Which is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide! It should be enough to wake him up and alleviate any soreness. Hopefully, anyways.", ["objectivesText"] = "Apply elemental salve to the mountain giant for Harmot . Progress: This will either wake the giant and patch him up good as new or... Well, let's not talk about the other possibility. Have some faith in the process!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 228380, 253166 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78760] = { ["id"] = 78760, ["name"] = "Dark Iron from Above", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["series"] = { 78761 }, ["description"] = "We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening. Now, we just need to deal with the leader of their forces before they can coordinate a more unified resistance. Are you ready to do this, <name>?", ["objectivesText"] = "Defeat Supervisor Varric and his forces within the Earthenworks.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213796, ["x"] = 0.452, ["y"] = 0.097333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.464667, ["y"] = 0.188667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78761] = { ["id"] = 78761, ["name"] = "Into the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["series"] = { 78760 }, ["description"] = "No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him. Remember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!", ["objectivesText"] = "Confront the High Speaker inside the Hall of Awakening.", ["rewardGold"] = 929400, ["rewardXP"] = 14880, ["rewardItems"] = { 219018, 253020 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213796, ["x"] = 0.452, ["y"] = 0.097333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.097333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78827] = { ["id"] = 78827, ["name"] = "Go Take Candle!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "Ksk, ksk! You there! Yes, you! <You hear the sound of jostling behind the vent and a new, even scratchier voice emerges.> We, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me. Bring us, me, bring me candles ! Yes! No ask question, just go get candles . We are, er, I am professional, yes. Professionals do not ask questions. Only get candles .", ["objectivesText"] = "Steal candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 58902, 58903, 58904, 58905, 156935, 226155, 226156, 228711, 248797 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78837] = { ["id"] = 78837, ["name"] = "Pomp and Dire Circumstance", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78631, 78838 }, ["description"] = "I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will. The High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.", ["objectivesText"] = "Meet Speaker Brinthe in Gundargaz. Progress: That is... never pleasant.", ["rewardGold"] = 76700, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78838] = { ["id"] = 78838, ["name"] = "Cogs in the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78631, 78837 }, ["description"] = "Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed. As the number of Machine Speakers decreases, we're in a race against time. Lately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens. Let me show you around the area. There are some earthen I would like you to meet.", ["objectivesText"] = "Accompany Brinthe as they talk to earthen in Gundargaz. Progress: This is not how I remember my home.", ["rewardGold"] = 306800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78839] = { ["id"] = 78839, ["name"] = "Kobold Shoulder", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz. See if you can reduce the swarm, <name>, before hostilities escalate further.", ["objectivesText"] = "Kill invading kobolds in the Lost Mines. Progress: This should never have happened.", ["rewardGold"] = 306800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78860] = { ["id"] = 78860, ["name"] = "More Candles!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "I, er, we...no, no, I! I have new deal for you, oh shadowy one. More candles ! In return, you get... er... <Frantic shuffling reveals a new voice.> You get more candles ! Then you give to us! To me! candles ! candles ! candles ! <The excitedly whispered chanting continues for some time.>", ["objectivesText"] = "Steal more candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ? More candles ?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78874] = { ["id"] = 78874, ["name"] = "Conjured Help", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78874, 78879, 78900, 78918 }, ["description"] = "If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment. It's starting to become a problem, actually. Say... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?", ["objectivesText"] = "Summon food for Innkeeper Brax in the Gundargaz Inn. Progress: You don't want to try a nibble of cobalt?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78877] = { ["id"] = 78877, ["name"] = "Bless These Homes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 2, 5 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78877, 78879, 78900, 78918 }, ["description"] = "Divine presence acknowledged. Every day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. A sacred task. These are dark times we live in--perhaps you could add your own beatitudes to our little rituals?", ["objectivesText"] = "Bless the incense around Gundargaz. Progress: You do us an honor, bringing your faith into these caverns. Let it bless these machines and those who work with them, just as they bless us in turn.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78879] = { ["id"] = 78879, ["name"] = "Evoking the Forge", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well... There's no one to fix it anymore. If you can figure out a way of getting it running hot again, Gundargaz would be in your debt!", ["objectivesText"] = "Find a way to stoke the forge outside of Gundargaz. Progress: I'm going to miss Itsak. He made the best end-of-shift rock roasts...", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213841, ["x"] = 0.453, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213841, ["x"] = 0.453, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78895] = { ["id"] = 78895, ["name"] = "A Shadow Over Gundargaz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 9, 12 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78879, 78895, 78900, 78918 }, ["description"] = "You look dangerous. <Toki spits on the ground.> That's good. We need dangerous. Something is stalking Gundargaz. Something mean. Something... recent. Just before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock. Fingers, mostly. If you could sniff out what's stalking my town, I'd be in your debt.", ["objectivesText"] = "Track down whatever is hunting the earthen in Gundargaz. Progress: Life didn't always used to be this exciting.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 219919, 219923 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78897] = { ["id"] = 78897, ["name"] = "Boom or Blight", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "This place is infested with cave borers. They pose a threat to the great roots that stretch through this place. Yes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. By my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?", ["objectivesText"] = "Cull 10 worms of the Wormlands. Progress: How fares the blight?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78898] = { ["id"] = 78898, ["name"] = "Intention vs Instinct", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention. A wormcaller of the nerubians must be present. Find them and recover the tool they use to call these worms here. With it we can lead them away in time.", ["objectivesText"] = "Collect a Singing Stone from Wormcaller Iz'tikrine. Progress: I can sense more worms coming. As if they are drawn to this place.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 211412 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78900] = { ["id"] = 78900, ["name"] = "On Cold, Dark Wings", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "You came down the Coreway, right? From up top? <Toki chuckles.> They have it easy, those city earthen. Down here, death comes for you from all around. From below. From above. You look like you've killed a fair few beasts in your time. Care to add another to the list?", ["objectivesText"] = "Track down the Ringing Death in Gundargaz. Progress: Keep quiet, that's my advice.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78901] = { ["id"] = 78901, ["name"] = "Heeeelllp!!!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Hey! You! Get me down! Away from these worms! Please! I'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! Just get me down! Also, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.", ["objectivesText"] = "Rescue Skedgit Cinderbangs .", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78902] = { ["id"] = 78902, ["name"] = "Delegated Dig", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp. This is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. I'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a <class> would know how to use it. Tell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!", ["objectivesText"] = "Acquire 25 Chunks of Sivstone. Progress: You get the goods?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 211415 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78915] = { ["id"] = 78915, ["name"] = "Squashing the Threat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78915 }, ["description"] = "I need your help! The massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites. Mom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs. Can you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?", ["objectivesText"] = "Remove 8 Shadow-Sour Squash and slay 10 Shadow-Sour Mites . Progress: Have you removed all the Squash?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78918] = { ["id"] = 78918, ["name"] = "Brax's Brass Knuckles", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "I have a proposition for you. We get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. Usually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts. Mind fetching my knuckles and administering some love taps?", ["objectivesText"] = "Kill creatures around Gundargaz to find Brax's Brass Knuckles . Progress: Now which beasts did I punch with those knuckles last...", ["rewardGold"] = 140450, ["rewardXP"] = 4960, ["rewardItems"] = { 211493, 219379, 225709, 225710, 225715, 225716, 225718 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[78929] = { ["id"] = 78929, ["name"] = "Tricks of the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper! And that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. They eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!", ["objectivesText"] = "Rescue 5 Arathi captives .", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214377, ["x"] = 0.5516, ["y"] = 0.3632 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78932] = { ["id"] = 78932, ["name"] = "Fickle Fiendish Fish", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Judging by the glint in your eye, you wish to join Faerin in this madness? To push into the kobyss waters? In the darkness? You are a fool with a death wish. Take as many of those damnable fish out as you can, before they drag you into the depths for their dinner.", ["objectivesText"] = "Kill 13 kobyss invaders. Progress: We can't abandon the villagers here!", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214377, ["x"] = 0.5516, ["y"] = 0.3632 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78933] = { ["id"] = 78933, ["name"] = "The Sweet Eclipse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78933 }, ["description"] = "I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor! To balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness. Please assist me in harvesting the following ingredients: Frog-Kissed Caviar , Darkroot Persimmon and Ethereal Sugar .", ["objectivesText"] = "Collect 8 Darkroot Persimmon , 30 Frog-Kissed Caviar , and 1 Ethereal Sugar . Progress: Have you found all of the ingredients?", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 211478, 211479, 212491, 219808, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78934] = { ["id"] = 78934, ["name"] = "Blades of the Arathi", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing. With the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow. Light a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength. We will catch up with you. May the Flame guide you, my friend.", ["objectivesText"] = "Light a torch with the Sacred Flame, then rally 6 groups of Arathi in Sina's Yearning.", ["rewardGold"] = 280900, ["rewardXP"] = 10190, ["rewardItems"] = { 220507, 220508 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 221100, ["x"] = 0.552, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78936] = { ["id"] = 78936, ["name"] = "Something's Fishy", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "So you outsiders and Faerin managed to both survive and save the villagers at the beach? <Steelstrike breathes a quick prayer in relief.> We're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. We have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.", ["objectivesText"] = "Slay Deepsludger , The Abominable Wavecrasher , and Tidelord Teethwretch in Sina's Yearning. Progress: When we first encountered the kobyss, there were those among us who tried to establish peace with them. But it quickly became apparent that they only see us as food.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78937] = { ["id"] = 78937, ["name"] = "Shadow upon Shadow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "< Faerin 's wide eyes dart around in surprise.> What just happened? Did you see that shadow? And the oil well... it's gone dark? I've never seen anything like this before. Could it be the nearby dawntower? Hurry!", ["objectivesText"] = "Investigate the nearby dawntower.", ["rewardGold"] = 28090, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 221100, ["x"] = 0.552, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214405, ["x"] = 0.561333, ["y"] = 0.419333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78938] = { ["id"] = 78938, ["name"] = "Champion of the Waterlords", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 51, ["mapID"] = 32, ["storyline"] = { 78938 }, ["description"] = "I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing. Prove your conviction! Slay Ragnaros, once and for all!", ["objectivesText"] = "Defeat Remembered Ragnaros during a Radiant Echoes event. Progress: Ragnaros yet remains, mortal. His foul heat emanates from nearby.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 32, ["npcID"] = 214399, ["x"] = 0.435, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 32, ["npcID"] = 214399, ["x"] = 0.435, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 32, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "standard",
},
[78939] = { ["id"] = 78939, ["name"] = "The Darkened Flame", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what. We should investigate.", ["objectivesText"] = "Investigate the darkened dawntower. Progress: My own people... how could they? <Faerin shakes her head in disbelief.>", ["rewardGold"] = 154900, ["rewardXP"] = 5095, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214405, ["x"] = 0.561333, ["y"] = 0.419333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.419333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78941] = { ["id"] = 78941, ["name"] = "A Tide Needing Turned", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment? Something is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands. Report to the Arathi general. I'll head to the battlefield directly.", ["objectivesText"] = "Meet with General Steelstrike in Hallowfall .", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78942] = { ["id"] = 78942, ["name"] = "The Might of Khaz Algar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight. The Algari Offensive stands at your back, <name>. Spare no enemy.", ["objectivesText"] = "Fight back against the nerubians.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214274, ["x"] = 0.645, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78943] = { ["id"] = 78943, ["name"] = "Steel and Flames", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Our forces may be able to hold their own, but seeing you in the fray may help their spirits. Take this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.", ["objectivesText"] = "Rally 20 Algari Offensive troops.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 217309, 223438, 223443, 223454, 223461 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214275, ["x"] = 0.685, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78948] = { ["id"] = 78948, ["name"] = "A Light in the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Something is very wrong. As the battle continues, each side has become more aggressive. Alleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.", ["objectivesText"] = "Speak with Anduin and chase down Xal'atath.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 220161, 223472, 237812, 257143, 265106, 265631 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214273, ["x"] = 0.645, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220688, ["x"] = 0.36, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78950] = { ["id"] = 78950, ["name"] = "Cutting Off the Legs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical. Take them out. Hopefully that will allow us some breathing room. Speak with Anduin after you are done. He and the Arathi girl went after Alleria.", ["objectivesText"] = "Slay the nerubian lieutenants. Progress: Speak with Anduin within the Sanguine Grasps.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214276, ["x"] = 0.685, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214273, ["x"] = 0.645, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78951] = { ["id"] = 78951, ["name"] = "Ever Deeper Shadow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. It pains me, but... my light alone is not enough to banish these shadows. And so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. We must stop them before this darkness spreads.", ["objectivesText"] = "Slay 10 Order of Night cultists in the cave beneath the Cliffside Beacon. Progress: These were once my people. My allies. My mentors. I once tried to reason with them. Tried to make them see the Light... see that the Light is still within us all. <Faerin's face flickers between sadness and anger.> They wouldn't listen. And they're killing innocents. I can't hesitate. Not anymore.", ["rewardGold"] = 295000, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214413, ["x"] = 0.558, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78952] = { ["id"] = 78952, ["name"] = "The Final Resistance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "<Faerin speaks in a hushed, furious whisper.> Good work. But before we can leave, there's something else. Down this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself. It will be dangerous, but we must stop them. Are you with me?", ["objectivesText"] = "Destroy the Shadow Rift .", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214413, ["x"] = 0.558, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 221733, ["x"] = 0.554, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78954] = { ["id"] = 78954, ["name"] = "Restore the Flame", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Do you feel it? Hope, returning? Thank you for your help, <name>. The dawntower's flame remains dark. But this time, I think we'll be able to restore it. Let's meet at the tower.", ["objectivesText"] = "Help Faerin restore the Holy Flame at the Cliffside Beacon. Progress: I only hope that together, we can kindle a little more light in our little world.", ["rewardGold"] = 73700, ["rewardXP"] = 2550, ["rewardItems"] = { 220108, 220109, 220110, 220112 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 221733, ["x"] = 0.554, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78972] = { ["id"] = 78972, ["name"] = "Harvest Havoc", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78972 }, ["description"] = "Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. We have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!", ["objectivesText"] = "Control Harvestbot Remy to load 4 Cabbage and 4 Carrots into carts. In addition slay 12 Invasive Beetles. Progress: Have you completed the chores?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
