[78996] = { ["id"] = 78996, ["name"] = "Weapons and Warriors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough. I know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment. We will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use. I will go with the farmers and train them as best I can.", ["objectivesText"] = "Collect 3 weapon crates and recruit 5 warriors from Freywold Village and Dhar Durgaz.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214444, ["x"] = 0.426, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78997] = { ["id"] = 78997, ["name"] = "Pilfered Pearls", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing. The gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.", ["objectivesText"] = "Retrieve 8 Pilfered Pearls from gorlocs at the Glimmering Shore. Progress: We need to return these pearls to the farmers.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212176 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 }, { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78998] = { ["id"] = 78998, ["name"] = "Frontline Farmers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. I need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.", ["objectivesText"] = "Distribute 3 weapon crates to the pearl farmers at Glimmering Shore.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[78999] = { ["id"] = 78999, ["name"] = "Heart of a Hero", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily. It will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created. Elementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them. This should end the gorloc threat to the farmers once and for all.", ["objectivesText"] = "Defeat the three gorloc shaman leaders.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 219764, 219765, 253021 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215420, ["x"] = 0.504, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
