[79029] = { ["id"] = 79029, ["name"] = "It's Sabotage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "We're back, and we're ready. You and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out. We don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve. The Darkfuse lackeys will clear out when the coin stops flowing.", ["objectivesText"] = "Wreak havoc, gain access to the manufacturing bay, and restart the facility.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 29978, 29979, 29980, 39811, 39873, 39875, 39877, 53225, 53253, 53255, 57451, 57452, 57453, 131384, 131454, 140255, 220118, 223440, 223442, 223451, 223467, 237812 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220928, ["x"] = 0.539, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
