[79089] = { ["id"] = 79089, ["name"] = "Consecrated Cleanup", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Our Veneration Grounds have been desecrated. Its beauty marred. It's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.", ["objectivesText"] = "Restore the Veneration Grounds in Hallowfall . Progress: I wish you could have seen this place before the Kobyss arrived.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79105] = { ["id"] = 79105, ["name"] = "Breach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. Rescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.", ["objectivesText"] = "Send civilians to the landing for safety.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 38669, 38715, 39019, 39048, 39080, 60854, 63775, 63780, 143488, 143747, 165871, 166792, 211279, 229371, 232049, 232371, 237812, 246812, 246813, 246814, 246815, 246936, 248575, 248576, 249400, 249783, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15177 } }, ["mapID"] = 2305, ["db2PoiUiMapID"] = 2305, ["db2PoiMapID"] = 2731, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
