[79106] = { ["id"] = 79106, ["name"] = "Rupture", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "Follow me. We'll work together to find any others in need of rescuing.", ["objectivesText"] = "Save Dalaran . Progress: The nerubians are capturing anyone they can and stringing them up in webs. Make sure to free whoever you find before moving on.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15177 } }, ["mapID"] = 2307, ["db2PoiUiMapID"] = 2307, ["db2PoiMapID"] = 2731, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79107] = { ["id"] = 79107, ["name"] = "After the Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. Many were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly. The surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.", ["objectivesText"] = "Check on the Stormriders.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 147475, 237812 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79108] = { ["id"] = 79108, ["name"] = "Seeds of Evil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "<class>, some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better. My idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait. Clearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.", ["objectivesText"] = "Collect Corrupted Shadowleaf Seeds . Progress: Did you cull those plants?", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 212153, 221849 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79109] = { ["id"] = 79109, ["name"] = "Follow Miral", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble. Can you find out what is bothering her for me?", ["objectivesText"] = "Discover what is bothering Miral Murder-Mittens . Progress: <Miral looks at you as if expecting something. You are being judged.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 221849 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215041, ["x"] = 0.606, ["y"] = 0.257 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79110] = { ["id"] = 79110, ["name"] = "Save Tomothy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>", ["objectivesText"] = "Save Tomothy Hillhelm from The Grasping Darkness .", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 221849 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215041, ["x"] = 0.606, ["y"] = 0.257 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
