[79114] = { ["id"] = 79114, ["name"] = "Beautification Project", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "A fine enough job, for one of your... ilk. If you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply. Rak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows. Find a way to clear them. I don't care how.", ["objectivesText"] = "Clear the Stagshell Hollow of Overgrown Plants. Progress: It would be unwise to return to me with an unfinished job.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79116] = { ["id"] = 79116, ["name"] = "Spider Optics", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["db2Objectives"] = { { ["text"] = "Rescue Spiderlings", ["amount"] = 6, ["type"] = 0, ["objectID"] = 223682, ["orderIndex"] = 1 }, { ["text"] = "Protect Egg Sacs", ["amount"] = 5, ["type"] = 0, ["objectID"] = 223683, ["orderIndex"] = 2 } }, ["objectivesText"] = "Rescue Spiderlings Protect Egg Sacs", ["mapID"] = 2255, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "world", ["flags"] = {  },
