[79117] = { ["id"] = 79117, ["name"] = "Bright Young Niffen", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "You need swarmhands, huh? Last time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo. We've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! Maybe if you lighten their workload, they'll take you up on your offer.", ["objectivesText"] = "Find 6 Niffen Arachnologists outside Mmarl to join Rak-Ush. Progress: Have you found anyone yet?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79118] = { ["id"] = 79118, ["name"] = "Rak-Ush Under New Management", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Well, you got your swarmhands. What are you still doing here? Go on then, you don't need my permission! Make sure the nerubians treat them fairly, now.", ["objectivesText"] = "Return to Vix'aron in Rak-Ush.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79119] = { ["id"] = 79119, ["name"] = "It's Rough to Be a Bug!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead. Since this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose. Go. We are to restore the stagshell hollows and fill them with swarmbeasts.", ["objectivesText"] = "Clean up the barn in Rak-Ush. Progress: We need this barn in an operational state!", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79120] = { ["id"] = 79120, ["name"] = "Beetle in a Haystack", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "There are still feral stagshells on the outskirts of Rak-Ush. This scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location. Once they are stunned, one of the rats will take them back to their hollow. Capture them and bring them back. We will be waiting.", ["objectivesText"] = "Capture and return six Feral Stagshells to Rak-Ush. Progress: We still require more stagshells.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 213392 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79121] = { ["id"] = 79121, ["name"] = "Bug Test", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things. Loathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I. They can enlighten you on your duties, if this was not explanation enough.", ["objectivesText"] = "Speak to Aromash and care for the stagshells in Rak-Ush. Progress: Do not return to me until you have finished your lessons with the niffen.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79122] = { ["id"] = 79122, ["name"] = "Scarab Scouting", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. The truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.", ["objectivesText"] = "Use a Rak-Ush Stagshell to find 5 Kaheti truffles. Progress: We need an abundance of truffles to ensure we are properly prepared.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 228439, 228440, 228441, 228442 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79123] = { ["id"] = 79123, ["name"] = "Permanent Hire", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Rak-Ush is beginning to look like a functioning swarmery. The role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. Saffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.", ["objectivesText"] = "Speak with Saffrin in Rak-Ush. Progress: You have not spoken to Saffrin yet, have you? Otherwise you would not be here.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["rewardItems"] = { 225935 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217250, ["x"] = 0.748, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79124] = { ["id"] = 79124, ["name"] = "Conduit of the Southern Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 81914 }, ["description"] = "I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter. But... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them. To summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.", ["objectivesText"] = "Find the Conduit of the Southern Storm . Progress: Have you found the conduit?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 218455 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.522667, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79125] = { ["id"] = 79125, ["name"] = "The Kalimdor Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 79125 }, ["series"] = { 78040, 78047, 79126, 79127, 79128 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Stormwind.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 214031, ["x"] = 0.618, ["y"] = 0.7505 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.7505 }, ["mapCandidates"] = { ["npc"] = { 84, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79126] = { ["id"] = 79126, ["name"] = "The Kalimdor Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 85, ["storyline"] = { 79126 }, ["series"] = { 78040, 78047, 79125, 79127, 79128 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Orgrimmar.", ["rewardGold"] = 10500, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 213769, ["x"] = 0.5255, ["y"] = 0.795 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5255, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 85, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
