[79129] = { ["id"] = 79129, ["name"] = "Rook Rally", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79475, 79476 }, ["description"] = "Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. Thrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts. An earthen trusting their feelings and instincts. That's... a challenge. You will help me, right? I'm not a fighter, and it looks dangerous up there. If anything happens to me, make sure Shraubendre makes it out safe. Please.", ["objectivesText"] = "Safeguard the summoning ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 223427, 223447, 223453, 223465 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214919, ["x"] = 0.3565, ["y"] = 0.5845 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79139] = { ["id"] = 79139, ["name"] = "Alone in the Dark", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now? But the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that. The nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.", ["objectivesText"] = "Investigate the Eye of Ansurek. Progress: <The spider looks at you expectantly.>", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216213, ["x"] = 0.4888, ["y"] = 0.5104 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79140] = { ["id"] = 79140, ["name"] = "Goldbricking", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. We've got a lot of work to do. Get down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.", ["objectivesText"] = "Spar with undisciplined earthen trainees. Progress: Don't go easy on them. They're made of stone after all.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215187, ["x"] = 0.452, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215187, ["x"] = 0.452, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79145] = { ["id"] = 79145, ["name"] = "Metal and Stone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it. Earthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.", ["objectivesText"] = "Equip earthen trainees for battle. Progress: Check in with Vindicator Jaelaana. She is in charge of distributing the weapons though she can be rather stingy. Be sure she doesn't send too many off for hand-to-hand training.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223871, 223872, 223873, 223874, 223875, 223876, 223877 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223205, ["x"] = 0.453, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223205, ["x"] = 0.453, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79146] = { ["id"] = 79146, ["name"] = "Ground Pounders", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "The rooks and their chosen riders will need time to bond. Perhaps you should use this time to check in on our other trainees. The Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines. Adelgonn , Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.", ["objectivesText"] = "Meet with Adelgonn , Geya'rah, and Turalyon.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214919, ["x"] = 0.3565, ["y"] = 0.5845 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215277, ["x"] = 0.451, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.3565, ["y"] = 0.5845 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79147] = { ["id"] = 79147, ["name"] = "Flight Training 101", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79477, 81912, 81913, 81915 }, ["description"] = "Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No? Right then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. After that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.", ["objectivesText"] = "Help Kurdran train recruits in aerial maneuvering. Progress: Let's set a good example for these new riders. Lead them through the course as quick as ye can.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.4685, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79148] = { ["id"] = 79148, ["name"] = "The Nibelgaz Refinery", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79679 }, ["description"] = "Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. I am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers. Here, take this healing clay . It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.", ["objectivesText"] = "Rescue 6 Refinery Workers and look for Munderut.", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 218356 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79149] = { ["id"] = 79149, ["name"] = "Rampage in the Refinery", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs. Duty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!", ["objectivesText"] = "Kill 10 Rampaging Elementals . Progress: Well? Did you destroy them? I need my crew back to work immediately!", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215234, ["x"] = 0.493, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215234, ["x"] = 0.493, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.493, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79150] = { ["id"] = 79150, ["name"] = "Thespians at the Proscenium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 79150 }, ["description"] = "When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way. My old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea. I think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.", ["objectivesText"] = "Help Architect Brokfor clean up the Proscenium. Progress: Have you helped Brokfor straighten up?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79151] = { ["id"] = 79151, ["name"] = "An Orphan's Request", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Wow, you look really strong! Would you be able to help me? My parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. Could you go get it for me?", ["objectivesText"] = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall . Progress: I will make the kobyss regret ever setting foot in these lands.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 216604 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215237, ["x"] = 0.416, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79152] = { ["id"] = 79152, ["name"] = "Gutting the Pool", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated. Kill any stupid fish-faces you see.", ["objectivesText"] = "Kill 10 kobyss in The Hungering Pool in Hallowfall . Progress: Yes, make them bleed. Make them pay!", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79153] = { ["id"] = 79153, ["name"] = "Vae Victis", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Ah it's time. Kill their leader. Salt his bones, take his head, and laugh as his tribe crumbles! Sharpscale's last moments are upon him, and he doesn't even realize it yet. Stupid fish-face.", ["objectivesText"] = "Kill Sharpscale the Devourer and retrieve its head in the Hungering Pool in Hallowfall . Progress: His skull would make a good cup I think? Perhaps a mantle ornament?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 217175 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.50519, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79154] = { ["id"] = 79154, ["name"] = "A Final Goodbye", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Well, parents avenged, fish killed, more fish killed, biggest fish killed. Pretty good day. I guess I should go burn stuff.", ["objectivesText"] = "Help Alyza say goodbye in the Hungering Pool in Hallowfall .", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["rewardItems"] = { 225949 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219368, ["x"] = 0.418, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.50519, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79156] = { ["id"] = 79156, ["name"] = "The Edicts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders. I'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.", ["objectivesText"] = "Report to Merrix and Adelgonn. Progress: This is a critical moment for all earthen.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 79869, 87399 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 }, { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79157] = { ["id"] = 79157, ["name"] = "Titanic Failsafe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "So, the titans sent their ancient machines against their disobedient children. Would our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart? No, today we are all Unbound, and we will fight for our freedom. For Azeroth!", ["objectivesText"] = "Defeat the colossal titan construct . Progress: None on this isle will be safe until that titan construct is dealt with. Go!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 223428, 223446, 223457, 223468 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79158] = { ["id"] = 79158, ["name"] = "Seeds of Salvation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79158 }, ["description"] = "These once obedient harvestbots have run amok and are wreaking havoc in our fields. The success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters! Would you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?", ["objectivesText"] = "Recover Harvest Seeds and plant 8 seeds in Seed-Ready Soil . Progress: Have you planted the seeds?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211947 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79159] = { ["id"] = 79159, ["name"] = "Dereliction of Duty", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "A moment, if you have one. One of my lieutenants, Shinda Creedpike , did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren. I am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? Take all the time you need.", ["objectivesText"] = "Find Shinda Creedpike at Mereldar in Hallowfall . Progress: Dawnsurge must have sent you. It seems like my respite is over.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215306, ["x"] = 0.414, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79160] = { ["id"] = 79160, ["name"] = "Fishing is Good for the Soul", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time. Perhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!", ["objectivesText"] = "Meet Shinda at the fishing hole. Progress: Maybe I can find peace in the act of fishing.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 228362, 228363, 228364, 228365, 228366, 228367 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79162] = { ["id"] = 79162, ["name"] = "Burnout", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.", ["objectivesText"] = "Return to Endiri Dawnsurge in Mereldar.", ["rewardGold"] = 151900, ["rewardXP"] = 5095, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215306, ["x"] = 0.414, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79165] = { ["id"] = 79165, ["name"] = "A Moment to Rest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "Good, you're both here. I have a favor to ask. Faerin's wandered off. I think it might help if you and your... disheveled friend here find her. She'll be in Light's Redoubt.", ["objectivesText"] = "Find Faerin near Light's Redoubt.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215341, ["x"] = 0.43, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218541, ["x"] = 0.422, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79166] = { ["id"] = 79166, ["name"] = "Lost Pieces", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "There was a time when I would have known what words to say to help her. But now... they are as lost to me as everything else. <Anduin sighs.> There must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. I'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings ... could you try to look?", ["objectivesText"] = "Collect 8 Lost Personal Effects from enemies in the Harrowing Depths. Progress: There's no time to mourn. Not when there's fighting to be done. If you have time to mourn, you have time to train. To make sure we don't lose anyone else.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211959 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218541, ["x"] = 0.422, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215331, ["x"] = 0.422, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79168] = { ["id"] = 79168, ["name"] = "Light's Gambit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "It's fine! We can catch you up on the rest of the rules later! Resolving combat is the most fun, anyway! You and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance! <Faerin laughs.>", ["objectivesText"] = "Grab the castle piece to start a game of Light's Gambit with Faerin and Anduin.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223432 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218267, ["x"] = 0.431, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217909, ["x"] = 0.432, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.431, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79173] = { ["id"] = 79173, ["name"] = "Supply the Effort", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79173 }, ["description"] = "When shadow fell upon our town, many necessary supplies were taken in the cover of darkness. With the light returning, it is time to rebuild, but first, we must retrieve what was lost. Search the surrounding areas, recover any supplies that might be useful.", ["objectivesText"] = "Recover various stolen items from the surrounding area to satisfy our needs. Progress: Have you recovered the stolen items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211964, 211966, 211967, 211968, 211969, 211970, 211971, 211972, 211973, 211974, 211975, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79174] = { ["id"] = 79174, ["name"] = "Infested Infestation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it! They already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. Go to Pillar-nest Vosh and take some of those spore-afflicted beasts out!", ["objectivesText"] = "Kill 12 spore-afflicted beasts at Pillar-nest Vosh.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79175] = { ["id"] = 79175, ["name"] = "I Think I'm a Drone Now", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth. And now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.", ["objectivesText"] = "Allow Anub'azal to mark you with his pheromones. Progress: Don't waste my time. Are you ready to accept my mark? Step into the pheromone cloud with your <race> friend, and rub it on.", ["rewardGold"] = 77400, ["rewardXP"] = 2650, ["rewardItems"] = { 225515, 225526, 225535, 225538 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79176] = { ["id"] = 79176, ["name"] = "Opals and Runes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79544, 79545 }, ["description"] = "You have certainly made my disaster of a day far less stressful, <name>. For that, you have the thanks of the entire Forgegrounds and those who keep it running. < Vokgret winks as she gives you a knowing smile.> Bevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps. Here is her liquid opal. Give it to her with my compliments.", ["objectivesText"] = "Trade the Vial of Liquid Opal for the Speakeasy Passrune from Bevrusi. Progress: Everyone in the city is in need of something, and there is always someone with the means to acquire it.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 217414, 218085 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217091, ["x"] = 0.452, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217097, ["x"] = 0.605, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79193] = { ["id"] = 79193, ["name"] = "Spinning Spore Spines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that. Did you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some? I will make my way back to the refinery. I am eager to get back and meet this Orsenth.", ["objectivesText"] = "Collect 150 Spore Spines for Munderut . Progress: Why, what is this now? You're a stranger to these depths, are you not? What are you doing here? <You remind him of all you've spoken of.> Well, what are you waiting for? Go and get me those spines!", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 212529 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79194] = { ["id"] = 79194, ["name"] = "To the Source", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79944 }, ["description"] = "Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz , supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. I will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.", ["objectivesText"] = "Meet Keldaz outside of the northeastern mine.", ["rewardGold"] = 77400, ["rewardXP"] = 2480, ["rewardItems"] = { 25913, 25914, 25915, 36878, 36879, 36880, 36881, 36882, 36883, 52595, 52621, 52633, 66908, 66909, 66910, 131282, 142054, 155392, 155393, 155394, 155395, 155448, 159975, 193666, 193671, 198606, 211279, 237812, 245616 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217474, ["x"] = 0.49, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79196] = { ["id"] = 79196, ["name"] = "Renowned with The Severed Threads", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79196 }, ["description"] = "The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal. Come to the Weaver's Lair. I have a parcel waiting for you.", ["objectivesText"] = "Speak with Lady Vinazian in the Weaver's Lair.", ["rewardItems"] = { 225247 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2596, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
},
[79197] = { ["id"] = 79197, ["name"] = "Surface Bound", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["series"] = { 79333, 84365, 84367 }, ["description"] = "<name>, the moment is upon us. We must make haste to the city of Dornogal, where our allies await. Only together do we stand a chance against Harbinger's machinations.", ["objectivesText"] = "Meet with Moira Thaurissan and your allies in Dornogal in the Isle of Dorn .", ["rewardGold"] = 153400, ["rewardXP"] = 5300, ["rewardItems"] = { 206350 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 219252, ["x"] = 0.556, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79200] = { ["id"] = 79200, ["name"] = "Who am I?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn , and this is Foreman Uzjax. Many things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it. Like many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. Embrace it.", ["objectivesText"] = "Complete the first stage in the Awakening Protocol.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79201] = { ["id"] = 79201, ["name"] = "The Analysis Interface", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.", ["objectivesText"] = "Complete the Analyzing Sequence in the Analysis Interface.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79202] = { ["id"] = 79202, ["name"] = "Rock Beats Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "Welcome to the Procedural Forum. Foreman Uzjax informs me that this chamber once served as our assignment testing facility. With his guidance, we've repurposed this chamber. Earthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.", ["objectivesText"] = "Spar with 6 newly Awakened Earthen. Progress: Whether they were once Storm Riders or Peacekeepers or craftsman and laborers, martial prowess takes time to hone and refine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79203] = { ["id"] = 79203, ["name"] = "Authorization: Negated", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "The Bulwark of Authorization! That's what this chamber was once called. I had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. A golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers. Dawn seems to think you've got what it takes to deal with it. Up to the challenge?", ["objectivesText"] = "Defeat the Phalanx of Authorization within the Bulwark of Authorization.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79204] = { ["id"] = 79204, ["name"] = "Whoever You Want to Be", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "After an awakening protocol like that, I can see why Dawn says you're special. The world is not prepared for an earthen like you. <Kuldas claps you on the back with a gravely chuckle.> Dawn and the Foreman are waiting for you in the Awakening Vestibule. Go on, then! Complete your Awakening Protocol and get out of here!", ["objectivesText"] = "Speak with Dawn to complete your Awakening Protocol.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 224166 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79205] = { ["id"] = 79205, ["name"] = "Not Waste, Not Want", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Everything have use, friend. Even things stoneheads throw away and think worthless. Kobolds know better. Go and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!", ["objectivesText"] = "Collect potentially useful scrap from around the Warrens. Progress: You will be surprised. Kobold crafting is amazing!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 29931, 29938, 29943, 29945, 212177, 217015 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79206] = { ["id"] = 79206, ["name"] = "Broken Memories", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79206 }, ["description"] = "Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe .", ["objectivesText"] = "Bring the Faded Memory Gem to Brinthe. Provided item:", ["rewardGold"] = 230100, ["rewardXP"] = 7440, ["rewardItems"] = { 212178 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
