[79213] = { ["id"] = 79213, ["name"] = "The Anachronism", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Insert the batteries into the cylindrical holes on the console. Then, titans willing, we will see what it holds.", ["objectivesText"] = "Activate the Excavated Console and use the device to defeat the Sargassum Guardian in Golgrin's Reach. Progress: To obtain the power necessary, find an elemental of sufficient size to charge the artifact. If I am right, the titan artifact will do the rest.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212602 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
