[79216] = { ["id"] = 79216, ["name"] = "Web of Manipulation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79216 }, ["description"] = "This town has been under siege, overrun by spiders! Even when we clear them out, they always return. Something is behind these attacks! A small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!", ["objectivesText"] = "Explore the nearby ledge and deal with any threats within. Progress: Have you solved our spider problem?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79217] = { ["id"] = 79217, ["name"] = "Back to Base", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours. His mind will be a big help to us here.", ["objectivesText"] = "Meet Brinthe back in Gundargaz.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
