[79218] = { ["id"] = 79218, ["name"] = "Renowned with the Hallowfall Arathi", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79218 }, ["description"] = "Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded. Find me in Mereldar.", ["objectivesText"] = "Speak with Auralia Steelstrike in Mereldar.", ["rewardItems"] = { 225246 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2611, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
