[79219] = { ["id"] = 79219, ["name"] = "Renowned with the Council of Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79219 }, ["description"] = "The Council continues to be in your debt, friend. If you visit me in Dornogal, I will give you supplies to reduce that debt.", ["objectivesText"] = "Speak with Auditor Balwurz in Dornogal.", ["rewardItems"] = { 225239 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223728, ["x"] = 0.393, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.393, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2612, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
