[79220] = { ["id"] = 79220, ["name"] = "Renowned with the Assembly of the Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79220 }, ["description"] = "Good work deserves good reward, yes? Assembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies. Come see Waxmonger Squick in Gundargaz.", ["objectivesText"] = "Speak with Waxmonger Squick in Gundargaz.", ["rewardItems"] = { 225245 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221390, ["x"] = 0.452, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2613, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
