[79221] = { ["id"] = 79221, ["name"] = "The Unusual Bug", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79221 }, ["description"] = "Nerubians in Rak-Ush may find this strange little spider of interest.", ["objectivesText"] = "Deliver this Unusual Bug to Widow Arak'nai in Rak-Ush. Provided item:", ["rewardGold"] = 28600, ["rewardXP"] = 1470, ["rewardItems"] = { 212331 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["startItems"] = { 212331 }, ["questType"] = "standard", ["flags"] = {  },
