[79222] = { ["id"] = 79222, ["name"] = "Shadow-Hardened Mainspring", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79222 }, ["description"] = "<Maybe it was the effects of prolonged darkness or tinkering by Ezgi Irongear, but the strength of this spring would be of interest to Speaker Kuldas in Gundargaz.>", ["objectivesText"] = "Deliver this item to Kuldas in Gundargaz. Provided item:", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["rewardItems"] = { 212330 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["startItems"] = { 212330 }, ["questType"] = "standard", ["flags"] = {  },
