[79224] = { ["id"] = 79224, ["name"] = "Gathering Intel", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79227, 79230 }, ["description"] = "The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy. My own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster. Unfortunately, she is... well. You'll see.", ["objectivesText"] = "Speak with Widow Arak'nai at the Weaver's Lair in Azj-Kahet .", ["rewardGold"] = 29700, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79225] = { ["id"] = 79225, ["name"] = "The Lost Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79225 }, ["description"] = "<A tinderbox of a Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.> An expedition scout might possess knowledge about this item.>", ["objectivesText"] = "Deliver the Expedition Tinderbox to Keyrra Flamestonge at the Shadowgrove Vineyards. Provided item:", ["rewardGold"] = 289300, ["rewardXP"] = 11765, ["rewardItems"] = { 209924, 209938, 212333 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["startItems"] = { 212333 }, ["questType"] = "standard", ["flags"] = {  },
},
[79227] = { ["id"] = 79227, ["name"] = "A Spider's-Eye View", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79224, 79230 }, ["description"] = "I have eyes in every crevice of the city save for one that has... eluded me. The Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded. A more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.", ["objectivesText"] = "Place shadecasters to rendezvous with the Weaver's scouts in the Umbral Bazaar, the Eastern Span, and the Twitching Gorge.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215626, ["x"] = 0.695333, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79230] = { ["id"] = 79230, ["name"] = "Creeping Through Corridors", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79224, 79227 }, ["description"] = "I've identified three sites of interest to investigate. A stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there. There's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them. Stay sharp, stay quiet.", ["objectivesText"] = "Investigate the western stockpile, central warehouse, and royal stores of the Transformatory, using anger pheromones to distract guards and avoid detection. Progress: Don't let your guard down. Not here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215626, ["x"] = 0.695333, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.695333, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79232] = { ["id"] = 79232, ["name"] = "Those Who Fell", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79232, 81673 }, ["description"] = "Since the Day of Shadows these lands have been a dangerous place. The kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves. The memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. Search for the Tinderboxes of these missing expedition members and return them to me.", ["objectivesText"] = "Locate the remains of Oskaer Daleclash, Dalian Ironlink, and Idona Seerstone, and recover their tinderboxes. Progress: Have you located the tinderboxes?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219451, 219453, 219499, 219503, 220157 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5670, ["name"] = "Zone 3 Neck 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79233] = { ["id"] = 79233, ["name"] = "Lab Access", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer. Of course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery. The nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.", ["objectivesText"] = "Collect 6 Loyalist Secretions from nerubian loyalists in the Transformatory area. Progress: If you saw me? No you didn't.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 215457 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215637, ["x"] = 0.695, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215659, ["x"] = 0.5712, ["y"] = 0.9244 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79234] = { ["id"] = 79234, ["name"] = "A Small Bag of Seeds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79234 }, ["description"] = "<This small bag of seeds seems forgotten, perhaps Aliya Hillhelm could make use of them.>", ["objectivesText"] = "Deliver this small bag of seeds to Aliya Hillhelm at the Hillhelm Stead. Provided item:", ["rewardGold"] = 300800, ["rewardXP"] = 11765, ["rewardItems"] = { 212339, 217344, 220756 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["startItems"] = { 212339 }, ["questType"] = "standard", ["flags"] = {  },
},
[79237] = { ["id"] = 79237, ["name"] = "Making of a Monster", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "We've got a new objective: Figure out what Ansurek's plans are for this... thing. We'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it. I scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck. Meet you in there.", ["objectivesText"] = "Access the Laboratory of the Grand Splicer via roof hatch, then investigate clues as to the purpose of the First Ascended. Progress: I don't like this. There's something we're still missing here.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 223431 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79239] = { ["id"] = 79239, ["name"] = "The Queen's Chains", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "Ansurek... that worm, that witless, gutless little-- < Y'tekhi growls under their breath, struggling to maintain their composure.> If this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do. When the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.", ["objectivesText"] = "Destroy Neferess's shackles.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215659, ["x"] = 0.5712, ["y"] = 0.9244 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215661, ["x"] = 0.784, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.5712, ["y"] = 0.9244 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79240] = { ["id"] = 79240, ["name"] = "Rogue Agent", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "We lost Y'tekhi . We can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse. <Lilian snorts.> I guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.", ["objectivesText"] = "Subdue Y'tekhi . Progress: Hard to think of how this could have gone any worse.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215661, ["x"] = 0.784, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79241] = { ["id"] = 79241, ["name"] = "Go Loud", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79243, 79244 }, ["description"] = "So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up. They're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least. I've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.", ["objectivesText"] = "Plant 6 Commandeered Nerubian Charges at specified points across the convoy, then remotely detonate them. Progress: They know we're here. May as well make the most of it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.3955 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79243] = { ["id"] = 79243, ["name"] = "Manufactured Mutiny", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79241, 79244 }, ["description"] = "We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count. There's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in. Hit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.", ["objectivesText"] = "Slay Siege Marshal Tekhzok and Royal Quartermaster Ze'erik . Progress: Those aggression pheromones came in handy... let's make sure not to waste them.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.3955 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79244] = { ["id"] = 79244, ["name"] = "News From Below", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79241, 79243 }, ["description"] = "I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly. Y'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim. Alleria is going to want a status report. Good luck.", ["objectivesText"] = "Inform Widow Arak'nai about what was found in the Transformatory. Then, return to Alleria at Dornogal on the Isle of Dorn. Progress: Nothing to do but keep going.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardItems"] = { 223437, 223445, 223455, 223466 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79256] = { ["id"] = 79256, ["name"] = "A Hint of Fear", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker. He said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either. I'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.", ["objectivesText"] = "Meet Moira Thaurissan outside Camp Murroch.", ["rewardGold"] = 29500, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215781, ["x"] = 0.529, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79257] = { ["id"] = 79257, ["name"] = "Grotto Grievances", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["db2Objectives"] = { { ["text"] = "Living Grotto contained", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["objectivesText"] = "Living Grotto contained", ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79258] = { ["id"] = 79258, ["name"] = "Mineral Water Woes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder. Fortunately, I am a hero! And as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it. That mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.", ["objectivesText"] = "Acquire the proper-temperature mineral water from the Living Grotto springs.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215788, ["x"] = 0.526, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79259] = { ["id"] = 79259, ["name"] = "Put On a Good Face", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it. If we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. Those Lashrooms look like they're a good place to start. It all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.", ["objectivesText"] = "Collect Lashroom Dust from Lashrooms in the Living Grotto. Progress: Have you gathered up that dust? It's the only way you're going to get near that hammer, especially with that creature wandering around.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 212490 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215781, ["x"] = 0.529, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215788, ["x"] = 0.526, ["y"] = 0.681 }, { ["mapID"] = 2214, ["npcID"] = 215822, ["x"] = 0.519, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79260] = { ["id"] = 79260, ["name"] = "Epicenter", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79261, 79263 }, ["description"] = "There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps , didn't it? Look at the size of that crater! With the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it! But if it does turn aggressive, don't worry, I'll be right behind you. We'll get that hammer out of here safely!", ["objectivesText"] = "Approach the Verdant Hulk .", ["rewardGold"] = 561800, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215822, ["x"] = 0.519, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79261] = { ["id"] = 79261, ["name"] = "Boiling Mad", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79260, 79263 }, ["description"] = "That gravel-brained ingrate! He took Fearbreaker and ran off to the north! It's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power! We need to track him down before he hurts himself or someone else with that hammer!", ["objectivesText"] = "Track Berrund and Fearbreaker through the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.6595 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79262] = { ["id"] = 79262, ["name"] = "Clean Up House", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things. If this was a thriving mining operation, it ain't anymore. We need to help the earthen get it under control again, and that means thinning out these beasts.", ["objectivesText"] = "Slay agitated creatures in the Rumbling Wastes. Progress: I want to get Fearbreaker back, but we need to clear out some of these agitated beasts first.", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 119001 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215837, ["x"] = 0.551, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79263] = { ["id"] = 79263, ["name"] = "Fault Lines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79260, 79261 }, ["description"] = "Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero. But ye can't go about doing the wrong thing for the right reasons. I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. He's likely tae need saving himself now. Let's find him in this blasted place.", ["objectivesText"] = "Find Berrund the Gleaming within the Rumbling Wastes. Progress: You found me?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215836, ["x"] = 0.551, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79264] = { ["id"] = 79264, ["name"] = "These Strong Hands", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79265 }, ["description"] = "< Berrund the Gleaming coughs dustily.> I knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be. But it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... <He coughs again.> It's clearly not mine. It never was. I'm... I'm... sorry.", ["objectivesText"] = "Witness Moira Thaurissan .", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215836, ["x"] = 0.551, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217598, ["x"] = 0.557333, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79265] = { ["id"] = 79265, ["name"] = "Fearbreaker", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79264 }, ["description"] = "The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker . We're going to finish that job before I take the hammer back to Magni. What kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.", ["objectivesText"] = "Slay skardyn and save earthen in the Rumbling Wastes with Moira Thaurissan .", ["rewardGold"] = 561800, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217598, ["x"] = 0.557333, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216085, ["x"] = 0.604, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.557333, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79266] = { ["id"] = 79266, ["name"] = "The Bronzebeard Legacy", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it. Now it's time tae bring it back tae Magni. Let's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.", ["objectivesText"] = "Meet Moira Thaurissan in Gundargaz.", ["rewardGold"] = 28900, ["rewardXP"] = 1240, ["rewardItems"] = { 224449 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216085, ["x"] = 0.604, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217827, ["x"] = 0.451, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79267] = { ["id"] = 79267, ["name"] = "Wax On, Pot Off", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy. Take that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any. It should certainly make any candles made with that wax quite feisty, once they're lit.", ["objectivesText"] = "Sabotage the pots of wax in the Warrens. Progress: Try not to breathe too many of the fumes.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79282] = { ["id"] = 79282, ["name"] = "The Grand Debut", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 79282 }, ["description"] = "The Proscenium is looking amazing! Are you ready to get on stage? Give us a hand as part of the crew, and we'll give you a chance to act. Will you accept this directive?", ["objectivesText"] = "Complete one Theater Troupe event in The Proscenium. Progress: I haven't seen you on stage yet, <name>. You won't win any fans by standing around!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79297] = { ["id"] = 79297, ["name"] = "Nightwatch", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Xal'atath is using the Order of Night to serve her whims. I overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike . I'll be there as soon as I can. We need to convince her of the severity of this threat.", ["objectivesText"] = "Collect 8 Order of Night Propaganda . Progress: Anything I can help you with, <name>?", ["rewardGold"] = 289300, ["rewardXP"] = 10190, ["rewardItems"] = { 217988, 217990, 217993, 217995 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218182, ["x"] = 0.426, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79300] = { ["id"] = 79300, ["name"] = "The Notebook", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["series"] = { 79304 }, ["description"] = "$p, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report! I'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it. I thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?", ["objectivesText"] = "Help Sophietta look for her notebook.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216001, ["x"] = 0.526, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79301] = { ["id"] = 79301, ["name"] = "Height Club", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain. He's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher. But if I can't turn in my report, he'll be the next captain. Take it back from him!", ["objectivesText"] = "Confront Edwyn about the notebook. Progress: Did you get it back? I'd love to see the look on Edwyn's face...", ["rewardGold"] = 280900, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79302] = { ["id"] = 79302, ["name"] = "Gone with the Wind", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "I can't believe Edwyn threw my report out into the wind. Can you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. This report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in. Bring me whatever pages you find!", ["objectivesText"] = "Recover 10 pages from Sophietta's report. Progress: I hope you found all the pages, <name>!", ["rewardGold"] = 303800, ["rewardXP"] = 10190, ["rewardItems"] = { 225180 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225926, ["x"] = 0.534, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79303] = { ["id"] = 79303, ["name"] = "A Principled Principal", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch ! He's probably in the classroom. I sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.", ["objectivesText"] = "Get Sophietta's report to Headmaster Fynch .", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225945, 228457 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225926, ["x"] = 0.534, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226074, ["x"] = 0.528, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79304] = { ["id"] = 79304, ["name"] = "Care Package", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["series"] = { 79300 }, ["description"] = "My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew. She's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls ! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?", ["objectivesText"] = "Take the care package to Sophietta Lynflayme at Lightspark Sky Academy. Progress: What's this? Are these for me?", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["rewardItems"] = { 19150, 19151, 19152, 19153, 19154, 19155, 20228, 20229, 20230, 20231, 20233, 20236, 228409 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217609, ["x"] = 0.692, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216001, ["x"] = 0.526, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79309] = { ["id"] = 79309, ["name"] = "Status Report", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens. One such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.", ["objectivesText"] = "Locate the missing Arathi Army scouting party.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216061, ["x"] = 0.704, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79310] = { ["id"] = 79310, ["name"] = "Seek the Lost", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer. I am afraid. I won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror. Tell Captain Trueflame her scouts died in darkness, one and all.", ["objectivesText"] = "Look for a member of Wayshelm's party. Progress: < Scout Wayshelm gazes into the flames of his campfire.>", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 213519 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79311] = { ["id"] = 79311, ["name"] = "Stem the Flow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night. It is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. I've lost my nerve. But you, outsider, can still make this right.", ["objectivesText"] = "Slay 12 Bloatrot Stingers or Fungal Infestors . Progress: <Scout Maevest's compass gleams in the firelight. Wayshelm has bound it with twine and now wears it around his neck.>", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79312] = { ["id"] = 79312, ["name"] = "Mow the Masses", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back. Only later did I find the tiny bite marks on my ankles. Be warned, there's something in the water. I took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.", ["objectivesText"] = "Cut down 8 Foulnectar Fronds .", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79313] = { ["id"] = 79313, ["name"] = "What Grows in the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. But your courage shines with splendor, <name>. At your side, my way is lit. No more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.", ["objectivesText"] = "Slay Fallowbarb .", ["rewardGold"] = 561800, ["rewardXP"] = 12740, ["rewardItems"] = { 226140 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216061, ["x"] = 0.704, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79324] = { ["id"] = 79324, ["name"] = "To the Waterworks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility. Meet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.", ["objectivesText"] = "Meet up with Dagran and ZZ-01-47 at the Waterworks.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["rewardItems"] = { 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79325] = { ["id"] = 79325, ["name"] = "Shadowvein Extraction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "I sent Zee-Zee ahead to the Shadowvein extraction site. From what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you. I don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.", ["objectivesText"] = "Meet up with ZZ-01-47 at the Shadowvein Extraction Site.", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216140, ["x"] = 0.535, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79327] = { ["id"] = 79327, ["name"] = "The Glittering Shard", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "<Glistening with an inner light, this shard of crystal feels warm to the touch.. Orsenth may be interested in examining this piece of ore.>", ["objectivesText"] = "Bring the glistening clay to Orsenth near Nibelgaz Mine. Provided item:", ["rewardGold"] = 144600, ["rewardXP"] = 4960, ["rewardItems"] = { 212595 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219042, ["x"] = 0.49, ["y"] = 0.148 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 6, ["flags"] = 1 } }, ["startItems"] = { 212595 }, ["questType"] = "standard", ["flags"] = {  },
},
[79328] = { ["id"] = 79328, ["name"] = "Embassies and Envoys", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 83271, 83286, 83315 }, ["description"] = "I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians. With your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.", ["objectivesText"] = "Set up your faction's embassy in Dornogal.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223546, 223547, 223548, 223549, 223564, 223569, 223584, 223588 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216167, ["x"] = 0.36, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79329] = { ["id"] = 79329, ["name"] = "Glowing Harvest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 79329 }, ["rewardItems"] = { 212755 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2Objectives"] = { { ["text"] = "Remnants Satchels collected", ["amount"] = 12, ["type"] = 1, ["objectID"] = 212755, ["orderIndex"] = 0 } }, ["objectivesText"] = "Remnants Satchels collected", ["mapID"] = 2215, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["db2WidgetSetID"] = 1054, ["questType"] = "standard",
},
[79333] = { ["id"] = 79333, ["name"] = "The Fleet Arrives", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["series"] = { 79197, 84365, 84367 }, ["description"] = "From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. Jaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen. An' I have to say we've done well on our own, haven't we? <Moira smiles at you proudly.> But it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!", ["objectivesText"] = "Scout the harbor for ships arriving from the Horde and Alliance fleet.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216167, ["x"] = 0.36, ["y"] = 0.814 }, { ["mapID"] = 2339, ["npcID"] = 216168, ["x"] = 0.358, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79335] = { ["id"] = 79335, ["name"] = "One More Tradition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Before I shut down, I must craft an item that is meaningful to me. As a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after. I wish to forge a new lantern to guide my way through these final moments. The lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills. Gather the materials, and I will forge the lantern.", ["objectivesText"] = "Gather 5 ore and 5 Charged Cores near Fallside Outpost. Progress: Have you gotten the materials I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 213001, 213002 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213184, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79336] = { ["id"] = 79336, ["name"] = "The Forging of Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am. < Korgran lets out a deep sigh.> These hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge. Please, add the right material to the forge as I call them out.", ["objectivesText"] = "Help Korgran forge his lantern. Progress: Oh, I almost forget. I did ask you to help with forging the lantern, didn't I?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 219413 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79337] = { ["id"] = 79337, ["name"] = "The Last Journey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 79338 }, ["description"] = "This lantern is perfect. Enough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony. < Korgran forces a smile.> It is nothing fancy, I promise. As I said, it is more symbolic than anything else. My head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago !", ["objectivesText"] = "Wait for Korgran and then regroup with Urtago outside at Fallside Outpost.", ["rewardGold"] = 216900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79338] = { ["id"] = 79338, ["name"] = "The Lost Earthen", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 79337 }, ["description"] = "This is horrible! I knew I should have been keeping a closer eye on him. Confusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is. I am such a boulder head! <name>, please, I think I saw him go east into the trees. Meet me there up the road!", ["objectivesText"] = "Help Urtago find Korgran. Progress: Were you able to find any sign of Korgran?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216677 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216878, ["x"] = 0.61, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 11, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79339] = { ["id"] = 79339, ["name"] = "A Change of Tradition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before... I may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. As Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets. <name>, meet me at the shore to the southeast of here.", ["objectivesText"] = "Meet Urtago and Korgran by the shore.", ["rewardGold"] = 30300, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216878, ["x"] = 0.61, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 12, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79340] = { ["id"] = 79340, ["name"] = "Tools of Declaration", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. Figuratively, of course. To do that, Korgran will need a horn. He would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me. I saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.", ["objectivesText"] = "Collect 4 Pristine Horns near Restless Estuary. Progress: Remember, the horns must be in pristine condition.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213171 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79341] = { ["id"] = 79341, ["name"] = "Cleansing Ashes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. It is a symbolic process of purification. For it, we need to gather ashenfold , a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities. We are then ready to embrace our final moments. < Urtago looks at Korgran with a hand on her chest. Her face falls.>", ["objectivesText"] = "Collect 6 ashenfold flowers near Restless Estuary. Progress: Do you have the flowers, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213157 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79342] = { ["id"] = 79342, ["name"] = "As He Departs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "It is time for the ceremony, <name>. Please place the bowl of ashenfolds by Korgran and then hand him the horn. Once the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend. Korgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time. My core is mud, but it is a great honor to stand here with him... and with you.", ["objectivesText"] = "Help Urtago and Korgran perform the ceremony. Progress: It is a bittersweet moment.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 217041 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79343] = { ["id"] = 79343, ["name"] = "Everyday I'm Snufflin'", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79343 }, ["description"] = "Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.", ["objectivesText"] = "Bring the Odd Glob of Wax to Gnawbles in Gundargaz. Progress: You snuffle something good?", ["rewardGold"] = 232300, ["rewardXP"] = 7440, ["rewardItems"] = { 228228 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5710, ["name"] = "Everyday I'm Snufflin'", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
