[79344] = { ["id"] = 79344, ["name"] = "Urban Odyssey", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "Did ye hear, <name>? A lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in. The more support we gather, the better.", ["objectivesText"] = "Ask around Dornogal for pledges of support in the coming conflict. Progress: I am glad to see you return, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79346] = { ["id"] = 79346, ["name"] = "Chew On That", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79346 }, ["description"] = "Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves. I've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time! If you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.", ["objectivesText"] = "Collect 20 Duskstem from the tallest plants that grow in the darkness. Progress: Have you collected enough?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 215447, 228741 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79349] = { ["id"] = 79349, ["name"] = "Entrepreneur, Inc.", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding. You should meet my business partner, Ripsnoodle . He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you. You can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.", ["objectivesText"] = "Find Ripsnoodle in Mmarl.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["rewardItems"] = { 226172 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216308, ["x"] = 0.782, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79354] = { ["id"] = 79354, ["name"] = "The Machine Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "Ah, $p! The <race> of the hour... We were just discussing you. <Moira nods towards Speaker Brinthe.> There is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more. Care to stick around?", ["objectivesText"] = "Watch the conversation between Moira and Speaker Brinthe in Gundargaz.", ["rewardGold"] = 144600, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79355] = { ["id"] = 79355, ["name"] = "Prisoner Preservation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "The beasts took our people! Dragged them away when we were gettin' our first rest since our escape! We only just escaped those nerubians. We can't afford ta lose more people. Search Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.", ["objectivesText"] = "Find 4 Expedition Members. Progress: Survivin' ain't easy, but we gotta keep pushin' on.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79356] = { ["id"] = 79356, ["name"] = "Antifungal Firestarter", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. Maybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts. Take these antifungal firebombs and torch as many fungal spore pods as you can!", ["objectivesText"] = "Burn 8 Fungal Spore Pods. Progress: Too many strange tings occur this far underground. Watch yourself.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 212334 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79357] = { ["id"] = 79357, ["name"] = "Removing the Cap", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave. We can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom. Get to Pillar-nest Vosh and kill that fungarian leader!", ["objectivesText"] = "Kill Agaricus Festerbloom .", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 213420 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79367] = { ["id"] = 79367, ["name"] = "A Nebb in Need", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "You! You no spider. Please, must help before spiders come again. Nebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light. Can't leave post. You take candles, yes? Light up barricade. Keep spiders away.", ["objectivesText"] = "Collect the Bundle of Candles and place candles along the barricade. Progress: Keep away dark. Keep away spiders.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 217116 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79368] = { ["id"] = 79368, ["name"] = "Hair of the Spider", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Light good, but more to do. Spiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now. Nebb might know a way, yes, turn venom into cure. Use bite to cure bite. Bring venom. Hurry now!", ["objectivesText"] = "Collect 12 Undercrawler Venom . Progress: You have venom?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 213178 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79369] = { ["id"] = 79369, ["name"] = "Protecting the Harvest", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw . Can no waste time. Kobolds starve if spiders gobble grubs and eggs. Save them, gather eggs. As many as can carry before spiders snatch all.", ["objectivesText"] = "Collect 20 Grub Eggs . Progress: Bring eggs, we save harvest.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 213209 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79370] = { ["id"] = 79370, ["name"] = "A Poultice for Poison", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Little venom, little wax... < Nebb reaches into his pouch and gives you a handful of thick, pungent wax.> Yes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw . He feel right better.", ["objectivesText"] = "Use Nebb's Poultice on Snubjaw . Progress: Poultice fix him right up.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 213539 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79371] = { ["id"] = 79371, ["name"] = "A Royal Cure", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Poultice no work! Wax right, venom wrong? Yes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave. Now you must follow. Collect royal venom. Please, Snubjaw have little time.", ["objectivesText"] = "Collect Queen Rickiticka's Venom to make a new poultice for Snubjaw . Progress: Queen venom must work.", ["rewardGold"] = 607600, ["rewardXP"] = 12400, ["rewardItems"] = { 213218, 217159 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79372] = { ["id"] = 79372, ["name"] = "A Clutch of Hope", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "<The broodmother lies dead, coiled around a single egg. She gave her life to keep it from the spiders. You should take it to Nebb . He and the other Grubtenders would know what to do with it.>", ["objectivesText"] = "Bring the egg to Nebb . Progress: What this, another egg?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 215164 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 213425 }, ["questType"] = "standard", ["flags"] = {  },
