[79579] = { ["id"] = 79579, ["name"] = "That Airspace is Mine(d)!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79574, 79579, 79580 }, ["description"] = "Our advantage is air superiority. The nerubians are threatening that with their mines. Your mount is more maneuverable than our skiffs. Get in the air and take those mines out. I will deploy what resources I can to provide you some blessings to improve your capabilities.", ["objectivesText"] = "Fly through 5 nerubian mines while under the effects of Holy Lance. Progress: Our priests are powerful with the Light but lack the air speed you and your resources can achieve.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.451 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5559, ["name"] = "The Second Front", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79580] = { ["id"] = 79580, ["name"] = "Offensive Counter", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79574, 79579, 79580 }, ["description"] = "I will not yield this ground. Get out there and kill anything with more than two legs!", ["objectivesText"] = "Slay 12 nerubians.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.451 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5559, ["name"] = "The Second Front", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79625] = { ["id"] = 79625, ["name"] = "Not Quite Dead", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "I am General Anub'azal . I loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! I have decided to use you and your kind against Zev'kall. And yes, you will get something out of it. Search that rubbish pile there. You will see.", ["objectivesText"] = "Examine the spoils pile in Siegehold. Progress: Go on, check the pile of rubbish.", ["rewardGold"] = 77400, ["rewardXP"] = 2650, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79627] = { ["id"] = 79627, ["name"] = "Wine and Die", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2255, ["storyline"] = { 79627 }, ["description"] = "I can see it now, morsel. The pattern of our newest weave is laid bare before my mind. Meesk is well-guarded. He believes himself to be safe. That is where his weakness lies. Go to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward. I trust you, <name>. And if you lay our threads out properly, I can guarantee you quite the show.", ["objectivesText"] = "Find a way to charm Meesk the Venomtongue .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 213538 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227428, ["x"] = 0.534, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 216298, ["x"] = 0.628, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79630] = { ["id"] = 79630, ["name"] = "Searching the Web", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "Oh, thank the hollows! You look like someone that can help. <The nerubian dabs at her many eyes with a silken handkerchief.> It's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony... But when we were to retire for the evening, he disappeared. <She sniffles dramatically.> Please, could you find him and bring him home to me?", ["objectivesText"] = "Locate Arax'ne 's husband, Klaskin in the Umbral Bazaar. Progress: Please, I need help!", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217356, ["x"] = 0.64, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217355, ["x"] = 0.478, ["y"] = 0.134 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79631] = { ["id"] = 79631, ["name"] = "Klaskin's Great Escape", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "Silken threads, I'm saved! It's incredibly important that I make it back home without my wife seeing me. I took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne . Will you help me avoid the guards and get back home?", ["objectivesText"] = "Return Klaskin to Arax'ne in the Umbral Bazaar. Progress: Please hurry!", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217355, ["x"] = 0.478, ["y"] = 0.134 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217356, ["x"] = 0.64, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.134 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79633] = { ["id"] = 79633, ["name"] = "The Weaver's Legacy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79633 }, ["description"] = "Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this. Ah, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.", ["objectivesText"] = "Bring Meesk the Venomtongue to meet the Weaver.", ["rewardGold"] = 140450, ["rewardXP"] = 5885, ["rewardItems"] = { 226103 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 216298, ["x"] = 0.628, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79641] = { ["id"] = 79641, ["name"] = "Wipe Away Their Smiles", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces. Come! My brother and I will cleanse our lands from this filth. Try to keep up!", ["objectivesText"] = "Collect kobyss teeth from slain kobyss. Progress: Let's see them smile now!", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 219211 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79642] = { ["id"] = 79642, ["name"] = "Stave Them Off", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Without their magical weapons, the kobyss casters won't be able to use their foul necromancy. Steal their staves so we might toss them into the Sacred Flame and be done with them.", ["objectivesText"] = "Collect 5 Darkwater staves. Progress: Did you find any Darkwater Staves?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217426, ["x"] = 0.303333, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.303333, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79643] = { ["id"] = 79643, ["name"] = "Dreaded Dreadfang", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "My brother and I have dealt heavy blows to the kobyss, <name>, but you could have done more. The most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came. Let's take the head of Dreadfang!", ["objectivesText"] = "Kill Dreadfang the Merciless . Progress: Ready to kill some kobyss?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79644] = { ["id"] = 79644, ["name"] = "Go to the Priory", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "I... I do not have the words. Theleon... I will take h-his body. They will know what to do at the priory. Oh, brother... It was not supposed to end like this...", ["objectivesText"] = "Meet Sister Etna Blayze at the Priory of the Sacred Flame.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["rewardItems"] = { 2815, 2899, 2902, 3056, 226134, 226137, 226138, 226139, 237014 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79645] = { ["id"] = 79645, ["name"] = "Sweet-Sting Infestation", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre. But first, you. I've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains. Be fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.", ["objectivesText"] = "Collect 10 vials of Wasp Venom. Progress: Did you kill those things?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 218113 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79646] = { ["id"] = 79646, ["name"] = "Memorial Wine", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Oh, Theleon. He always did follow his big brother into anything. While we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?", ["objectivesText"] = "Make Memorial Wine with Brother Abealard. Progress: Did you help Brother Abealard?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79647] = { ["id"] = 79647, ["name"] = "Burning Reflections", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well. It is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.", ["objectivesText"] = "Help Sybaestan mourn his brother. Progress: The ritual helps ease the hearts of many.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79648] = { ["id"] = 79648, ["name"] = "Missing Somebody", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Theleon was a good one, but now we must commit his body to the Flames. Sybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?", ["objectivesText"] = "Collect Theleon's remains. Progress: You're strong and you have the distance Sybaestan lacks right now.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79649] = { ["id"] = 79649, ["name"] = "Sacred Flame Inquisition", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something. Go ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.", ["objectivesText"] = "Interrogate the local clergy. Progress: Did you find anything out?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79650] = { ["id"] = 79650, ["name"] = "Priory of the Sacred Flame: A Brother's Grief", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. She and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can. Tell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.", ["objectivesText"] = "Confront Prioress Haelsey Murrpray inside the Priory of the Sacred Flame. Progress: We must confront the prioress.", ["rewardGold"] = 1239200, ["rewardXP"] = 20380, ["rewardItems"] = { 226134, 226137, 226138, 226139 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
