[79679] = { ["id"] = 79679, ["name"] = "Muddled Mind in the Mine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79148 }, ["description"] = "The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. He might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.", ["objectivesText"] = "Look for Munderut in Nibelgaz Mine.", ["rewardGold"] = 144600, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79680] = { ["id"] = 79680, ["name"] = "Pipe Patching", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach. < Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.> Stoneheads not have \"approved replacements,\" but we not have time wait. Take glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.", ["objectivesText"] = "Fly near the leaks in steam pipes above Gundargaz to seal them with kobold-provided glue. Progress: Try not glue self to pipe, yes?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79681] = { ["id"] = 79681, ["name"] = "Plumber Power", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz. Tunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone. Check with crew boss if have problems. He help go over maps.", ["objectivesText"] = "Use the Tunnel Access to plot the steam pipe routes through Gundargaz. Progress: Get lost?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79682] = { ["id"] = 79682, ["name"] = "Critical Pressure!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Pressure still too high! Something else wrong, not just old pipes. Open main release before something burst. Not have time for manuals. Consequences for deal with later!", ["objectivesText"] = "Open the main release valve and deal with whatever happens. Progress: Find problem?", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79683] = { ["id"] = 79683, ["name"] = "Home Is Where the Candle Is", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Exciting to have new place call home, <name>. Not quite settled, though. We not know Gundargaz. Gundargaz not know us. Time to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy! Start with help three kobolds. Fourman Grimes want get to work right away. She very task oriented. Granny Scribbles tell you lot about kobold culture. And Janky want set up new business in town, sell candle to Gundargaz.", ["objectivesText"] = "Assist Fourman Grimes, Janky, and Granny Scribbles.", ["rewardGold"] = 147500, ["rewardXP"] = 4960, ["rewardItems"] = { 223625 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213152, ["x"] = 0.456667, ["y"] = 0.337333 }, { ["mapID"] = 2214, ["npcID"] = 222803, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213152, ["x"] = 0.456667, ["y"] = 0.337333 }, { ["mapID"] = 2214, ["npcID"] = 222803, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.456667, ["y"] = 0.337333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[79686] = { ["id"] = 79686, ["name"] = "Concerning Fungarians", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79686 }, ["description"] = "<Abandoned in the dim candlelit chamber, the parchment, wrinkled and worn, bears the traces of hastily scribbled research notes.> Log Entry: 235-18-7 Date: Fabrication Quarter Cycle Observation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.", ["objectivesText"] = "Collect the remaining research notes and return them to their owner in the Freywold Village. Progress: Did you find something interesting?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216882, 216888, 216889 }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218729, ["x"] = 0.414, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5653, ["name"] = "Concerning Fungarians", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 213557 }, ["questType"] = "standard", ["flags"] = {  },
},
[79691] = { ["id"] = 79691, ["name"] = "Monsters in the Dark", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "The local quarry was an active source of clay and ore for us until the fungarians took over some time ago. We were worried about the fungarians encroaching upon the village, but there's something more. Multiple sightings of a creature much larger than our native wildlife have been reported at night. Combined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned. We would be in your debt if you searched the tunnels.", ["objectivesText"] = "Slay the Ashen Stonestalker in Gemvein Tunnels. Progress: You do us a great service by making our lands safe.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79692] = { ["id"] = 79692, ["name"] = "Buried, Not Forgotten", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen. She hasn't returned. The fungarians prevent us from searching the area. It would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.", ["objectivesText"] = "Find Modhina and her belongings in Gemvein Tunnels. Progress: Be careful. I fear more sinister things lurk in these tunnels.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215464, 217107, 217108 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79701] = { ["id"] = 79701, ["name"] = "The Cavalry is Here", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "< Baelgrim quakes with fury.> These cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight! Let's grind every last one of the bugs back into the ground.", ["objectivesText"] = "Repel the nerubian attack at the Proscenium.", ["rewardGold"] = 295000, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217766, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217766, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.506667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79703] = { ["id"] = 79703, ["name"] = "Hope, An Anomaly", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "< Hreka looks through the things you retrieved, one by one.> So you risked your life to find our friend. Modhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery. What can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment. What can I do now, but make a pot? Will you help me?", ["objectivesText"] = "Make a piece of pottery with Hreka . Progress: A lifetime spent making pottery. Is this my titan given fate? Then why do I still wonder?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219920, 253035 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79710] = { ["id"] = 79710, ["name"] = "A Fin of Every Kind", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "Oh! My! LEGS! You're perfect! Yes! You're a perfect, little, unassuming biped for my work. Alchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them. They seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! Here's a sack. Fill it up! Fill it up with their innards! As much as you can carry!", ["objectivesText"] = "Fill up the Kobyss Innards Sack. Progress: Is that really as much as you can carry?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 214504, 222921, 224102, 224103, 224232 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79711] = { ["id"] = 79711, ["name"] = "That's Pretty Gross", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "<You dislodge a familiar-looking appendage from the silt. It doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian .>", ["objectivesText"] = "Bring the Familiar-Looking Appendage back to Al'kubian . Progress: Ooooh! What is this?", ["rewardGold"] = 151900, ["rewardXP"] = 5300, ["rewardItems"] = { 214504 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 214504 }, ["questType"] = "standard", ["flags"] = {  },
},
[79713] = { ["id"] = 79713, ["name"] = "Moonlight Gutter Swim", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "An Ascended's leg... A kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story. Let us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal. Dive into the lake's depths. Slay the largest of these creatures or their pets. And of course, bring me their innards.", ["objectivesText"] = "Collect Liverseeker's Intestines and Leg Chewer's Stomach . Progress: Any profits I gain from my work goes directly to scientific and alchemical research. As in, I use the profits for myself, and I am an alchemical scientist.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 222924, 222926 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79714] = { ["id"] = 79714, ["name"] = "Rescuing the Food", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern. My conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts. It's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.", ["objectivesText"] = "Rescue 5 Captive Kaheti.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 223287 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79715] = { ["id"] = 79715, ["name"] = "Grand, Gutsy Solutions", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "I require one final piece of data. These beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus. My final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified. And, you know, perhaps it will slow them down as well.", ["objectivesText"] = "Collect the Brain of Grand Gluttony. Progress: Have you got it? Is it leaking?", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 222944, 222980 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79716] = { ["id"] = 79716, ["name"] = "The History Beneath Us", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "The titan console is a huge find. And look at these ruins! There has tae be more here! But goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come. Elementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage! Can ye go out there an' get some relics back from the elementals? We need tae preserve what we can!", ["objectivesText"] = "Collect 20 Shattered Relic Fragments from elementals in Golgrin's Reach. Progress: Have ye found anythin' yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 225886 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79717] = { ["id"] = 79717, ["name"] = "Means of Ingress", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79717 }, ["description"] = "Ah, look at you! Just the sort of rogue element I need. My name is Ar'syn , and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind. But gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building. < Ar'syn looks at you meaningfully.>", ["objectivesText"] = "Survey three potential entryways into the Royal Preservatory. Progress: Well, what do you think? I think you'll find that even the Preservatory itself is quite the work of art in its own right... Though that does mean it will prove rather vexing to infiltrate.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79718] = { ["id"] = 79718, ["name"] = "Skeins Street Irregulars", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79718 }, ["description"] = "I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins. You, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit? Oh, don't give me that look. You were going to do it anyway.", ["objectivesText"] = "Slay Sureki agents around the Royal Preservatory. Progress: You needn't worry about any moral quandaries here. The craven Sureki would do the same to you thrice over.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79721] = { ["id"] = 79721, ["name"] = "Fire in the Hole", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "Who are you? But of course, another outlander! I'm Wenbrandt , tamer of cinderbees and creator of cinderbrew. < Wenbrandt squares himself up as if you should be impressed.> I had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain... I refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable. This burrow here is a perfect test subject.", ["objectivesText"] = "Use cinderbrew to repel the nerubian attack in the Proscenium. Progress: Go drop a few on the nerubians. Let's see what happens.", ["rewardGold"] = 295000, ["rewardXP"] = 9515, ["rewardItems"] = { 65346, 65349, 65352 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212295, ["x"] = 0.565, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212295, ["x"] = 0.565, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79722] = { ["id"] = 79722, ["name"] = "Gutter Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["rewardXP"] = 11765, ["rewardItems"] = { 222921, 224102, 224103, 224232, 257353, 258188 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2Objectives"] = { { ["text"] = "Salien Gutters scavenged", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["objectivesText"] = "Salien Gutters scavenged", ["mapID"] = 2255, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 16, ["flags"] = 0 } }, ["questType"] = "world", ["flags"] = {  },
},
[79723] = { ["id"] = 79723, ["name"] = "Repatriation by Subtraction", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79723 }, ["description"] = "Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from. Well, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller. But that is where we come in, <name>. Those relics that the Sureki forces stole? It's time to steal them back.", ["objectivesText"] = "Loot six Pillaged Trophies from the Royal Repository. Progress: Well, <name>? I'm sure the place is filled with a queen's ransom.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 215159 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79724] = { ["id"] = 79724, ["name"] = "A Titanic Expedition!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\" Apparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff! Tuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work. Care to join us?", ["objectivesText"] = "Meet Rannan at The Three Shields.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217763, ["x"] = 0.588, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217657, ["x"] = 0.778, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79725] = { ["id"] = 79725, ["name"] = "Not a Heating Pack", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. I think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning? Imagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah! The gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?", ["objectivesText"] = "Rannan wants you to kill 12 gorlocs. Progress: Did you get them? I thought I saw one sneak by a moment ago...", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217657, ["x"] = 0.778, ["y"] = 0.302 }, { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79726] = { ["id"] = 79726, ["name"] = "\"Cataloguing\"", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "As ya know, we are here to collect some titan shinies, artifacts, whatever! And Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans. That'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home. My wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!", ["objectivesText"] = "Recover 7 titan artifacts . Progress: You get some good shinies yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215233 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217656, ["x"] = 0.778, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217656, ["x"] = 0.778, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79727] = { ["id"] = 79727, ["name"] = "Because It's Shiny", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach. None of them seemed interested in us, but then I saw one huge gorloc. It killed off some smaller gorlocs then took off. It had something glowing in its claw though! It had to be an artifact. And it looked like it was working! We've got to get it back. By \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.", ["objectivesText"] = "Retrieve the artifact from the huge gorloc. Progress: Were you able to get the artifact?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215234 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217659, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217659, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79728] = { ["id"] = 79728, ["name"] = "It's Probably Nothing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "You found a buzz orb! ...Er, that's what the niffen call it. I just kind of went with it. It's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern! <name>, you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. Nothing to worry about, I'm sure.", ["objectivesText"] = "Interact with the titan orb. Progress: Yes, yes! It will be very exciting to hear what you have discovered.", ["rewardGold"] = 286500, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79729] = { ["id"] = 79729, ["name"] = "Educate Yourself", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79729 }, ["description"] = "The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters. With luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.", ["objectivesText"] = "Tamper with the shadecasters in front of each of the four Founding Relics.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79730] = { ["id"] = 79730, ["name"] = "Dogged Pursuit", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79730 }, ["description"] = "But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again! That shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall. I'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?", ["objectivesText"] = "Defeat Royal Broker Rez'kal . Progress: Be careful, <name>. What Rez'kal lacks in acuity he makes up for in scarab-headed stubbornness.", ["rewardGold"] = 619600, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79944] = { ["id"] = 79944, ["name"] = "Raging Rifts", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79194 }, ["description"] = "The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. I could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more. I need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.", ["objectivesText"] = "Destroy 4 rifts and find their source within the cave. Progress: Destroy what rifts you come across, but above all, find their source! I suspect you will find it deep inside the nearby cave. The miners you rescued spoke of breaking through to a crystal-filled room, and of the elementals pouring forth from within.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 226672 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79954] = { ["id"] = 79954, ["name"] = "Spiders!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "Why, hello there, little $pr. You seem like you might be able to assist me. You see, my dear mate Ami'thax fell onto a sharp dagger. Her body was taken to Pillar-nest Xesh, just below where we stand. Xesh is used to dispose of all sorts of bodies that we never speak of again. Unfortunately I have need to speak of Ami'thax, because she had the key to my new High Hollows burrow on her when she died. Dreadful timing, really. Would you go and fetch it? Do beware of the spiders, I need my key.", ["objectivesText"] = "Find Ag'thax 's missing key in Pillar-nest Xesh. Progress: Don't let the spiders eat you before you escape with my key.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 146671, 181501, 181502, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181656, 181658, 181671, 181672, 181673, 181674, 181679, 181681, 184305, 184772, 184773, 184774, 184775, 184776, 216688 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217255, ["x"] = 0.774667, ["y"] = 0.685333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217255, ["x"] = 0.774667, ["y"] = 0.685333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.774667, ["y"] = 0.685333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79955] = { ["id"] = 79955, ["name"] = "...And Now I'm Arachnophobic", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "Who is there? Someone? Did I imagine you? I am Albert . I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts. My eyes. My insides. It hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. I wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?", ["objectivesText"] = "Locate Albert 's friends in the walls.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["mapID"] = 2216, ["db2PoiUiMapID"] = 2216, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[79956] = { ["id"] = 79956, ["name"] = "Legs in the Ceiling", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach. The horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!", ["objectivesText"] = "Pull on the spider thread if the spiders are not already attacking, and kill whatever comes.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["mapID"] = 2216, ["db2PoiUiMapID"] = 2216, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
