[80000] = { ["id"] = 80000, ["name"] = "Beebiter", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Mites kill fire bees. No good! Janky hate mites. Bite you when not even stealing wax. Not even make wax! Give bees chance. Kill biggest, bite-iest mite before eats more bees.", ["objectivesText"] = "Slay Beebiter . Progress: How feel about being on fire? Good?", ["rewardGold"] = 590000, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
