[80022] = { ["id"] = 80022, ["name"] = "Calling the Stormriders", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it. With our backs turned and our focus on the Coreway, we are prime targets. I need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without. Meet me outside of the Stormperch. I will call upon my troops there.", ["objectivesText"] = "Meet Baelgrim outside the Stormperch, then speak with him to follow him into The Rookery. This challenge may be completed solo or with up to 3 party members. Progress: Baelgrim is right. We need to defend the Unbound while they work on the Coreway.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 212747, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 212746, ["x"] = 0.36, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80049] = { ["id"] = 80049, ["name"] = "The Flame Still Burns", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "That was too close. This attack took a toll on all of us. We have many injured, and many shaken. Can you check in with people? See how they are doing?", ["objectivesText"] = "Check in with Arathi Survivors in the Veneration Grounds in Hallowfall . Progress: How's it looking out there?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.383667, ["y"] = 0.692333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80058] = { ["id"] = 80058, ["name"] = "Kobold Kleanup", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby. We help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home. You help, too. Grab broom, get going!", ["objectivesText"] = "Clean up Gundargaz. Progress: How go?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216568, ["x"] = 0.457, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[80079] = { ["id"] = 80079, ["name"] = "A Wrench in the Works", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "Looks like the High Speaker is addressing his workers. It seems something has finally shaken them from their complacency, and their time away from the Awakening Machine is affecting them. <Moira pauses to brush a bit of dust off her robe.> Perhaps this would be a good opportunity for everyone to hear what they have to say? We should convince a few of these Machine Speakers to speak up.", ["objectivesText"] = "Encourage members of the crowd to air their grievances. Progress: Recalcitrant lot, aren't they?", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218714, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218714, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[80082] = { ["id"] = 80082, ["name"] = "Back to Gundargaz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well. Our new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower. Shall we bring them home, <name>?", ["objectivesText"] = "Return to Gundargaz.", ["rewardGold"] = 28900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218715, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80096] = { ["id"] = 80096, ["name"] = "The Shovel in the Stone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness. Only problem is that it very stuck. In very big rock. No idea how even get there, really. Come! We try you hand at fate!", ["objectivesText"] = "Recover the legendary kobold shovel Excavator . Progress: Pull with knees, not with back.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 216915 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
