[80144] = { ["id"] = 80144, ["name"] = "The Holey Grail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Holey Grail , one of very best relics, lost for long time, <name>. Very old, very powerful. Would mean a lot if could find. Set you grand quest for to search for Holey Grail ! Try start with Fishcan . He old as dirt, might know something. Seek him by pools to north-east.", ["objectivesText"] = "Find the Holey Grail . Progress: Got Grail?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228771 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
