[80145] = { ["id"] = 80145, ["name"] = "The Motherlode", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "<Zee-Zee's internals begin to hum softly as their projector reaches the appropriate operating temperature.>", ["objectivesText"] = "Activate the remaining crushers in the Shadowvein cave. Progress: <Zee-Zee looks up at you.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 29813, 29814, 29815, 143559, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
