[80175] = { ["id"] = 80175, ["name"] = "The Last Mage", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash. He's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. We all know it's a lost cause, but he still hasn't given up. Maybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?", ["objectivesText"] = "Find Wenren Althal in Beledar's Bounty.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80176] = { ["id"] = 80176, ["name"] = "Arcane Trickles", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "I've almost got it! I'm making a new kind of teleportation spell to get us back home to the Empire. These crabs might just be the key. They're practically radiating arcane teleportation magic! I need more samples to study. Take this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!", ["objectivesText"] = "Obtain 5 Arcane-Suffused Organs from Shore Crawlers near Mereldar. Progress: Have you found the crabs? They'll be near water. That focus should let you see the trails of arcane dust they leave behind.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 217269 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80177] = { ["id"] = 80177, ["name"] = "Arcane Experiments", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula-- I can do this, my new friend! I just need another hand. Help me test this?", ["objectivesText"] = "Help Wenren with his experiments.", ["rewardGold"] = 280900, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80178] = { ["id"] = 80178, ["name"] = "A Murder Most Foul", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "<Somebody didn't want Wenren to finish his spell. Find out who.>", ["objectivesText"] = "Investigate Wenren's murder. Progress: <The body is still warm.>", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 221190 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80179] = { ["id"] = 80179, ["name"] = "Finding Justice", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "<The pieces fit together to form a simple, but dark picture. The Order of Night did not want Wenren to create a portal back to the Empire. No doubt reinforcements and supplies would hinder their mission. So, someone stabbed him, burned his research, and smashed his tools. But with this arcane focus in hand, you can see a faint trail of arcane residue. Did some arcane dust get on the perpetrator? Follow the trail and find out.>", ["objectivesText"] = "Track down Wenren's killer.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 225946 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80184] = { ["id"] = 80184, ["name"] = "Preserving in Battle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80184 }, ["description"] = "There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.", ["objectivesText"] = "Obtain Honor in Random Battlegrounds. Progress: You haven't finished quite yet.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
},
[80185] = { ["id"] = 80185, ["name"] = "Preserving Solo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80185 }, ["description"] = "Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.", ["objectivesText"] = "Complete 12 rounds of Solo Shuffle. Progress: Finish off what you set to do then return.", ["rewardItems"] = { 2899, 244848 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
