[80187] = { ["id"] = 80187, ["name"] = "Preserving in Skirmishes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80187 }, ["description"] = "Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me. Let us see what you can prove, then return to me.", ["objectivesText"] = "Obtain Honor from Arena Skirmishes. Progress: Practice makes perfect. Finish off the tasks then return.", ["rewardItems"] = { 2899, 244848 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
},
[80188] = { ["id"] = 80188, ["name"] = "Preserving in Arenas", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80188 }, ["description"] = "Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.", ["objectivesText"] = "Obtain Honor in Rated Arenas while in a Party. Progress: You have not finished what you set off to do yet.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
