[80189] = { ["id"] = 80189, ["name"] = "Preserving Teamwork", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80189 }, ["description"] = "The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.", ["objectivesText"] = "Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds. Progress: Finish off what you set to do then come back.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
},
[80202] = { ["id"] = 80202, ["name"] = "Hot Pollenate-o", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Important to make sure not take too much. Make sure hive healthy so can come back. Bees eat pollen, yes? So fire bees eat fire pollen? Yes. Bring fire pollen to bees. Grow strong. Bee productive. Check edge of hive for flowers bees not get to yet. When catch fire, you got good one.", ["objectivesText"] = "Gather pollen from Pollen Rich Cinderblooms and return it to nearby bees before it goes out. Progress: Just a little bit on fire. You tough, you be okay.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80203] = { ["id"] = 80203, ["name"] = "Social Clues", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "<The nerubian keeps her voice low, a careful eye on the guards behind you.> The Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course. But he's missing. A rather large inconvenience. I need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you. I so rarely get to work alongside a friend. We will have fun together, fellow spy.", ["objectivesText"] = "Help Orator Tx'itk ask around to find the Magistrate. Progress: I have a few old friends who recently Ascended. Surely, one of them has heard something they would be willing to share. For old time's sake. And if not, maybe jealousy in seeing my fashionable new pet will inspire them to offer up what they know.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 219357, ["x"] = 0.715, ["y"] = 0.4445 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221092, ["x"] = 0.664, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.4445 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80204] = { ["id"] = 80204, ["name"] = "Espionage and Ventriloquism", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "The Puppetmaster is our best lead for finding the Magistrate. But is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show. We should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful. You'll have to keep playing your rather undignified role in this charade. But it will pay off for us.", ["objectivesText"] = "Investigate the Puppetmaster's Workshop. Progress: < Orator Tx'itk lowers her voice.> Something isn't right here. Play along just a while longer. Let's see what else we can find.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["rewardItems"] = { 219443 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221092, ["x"] = 0.664, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80205] = { ["id"] = 80205, ["name"] = "Pulling Strings", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose. It's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this. We're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp. Hopefully he's not part of the show yet.", ["objectivesText"] = "Confront the Puppetmaster to rescue High Elevator Etak'kaht .", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221088, ["x"] = 0.715, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.417333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80206] = { ["id"] = 80206, ["name"] = "Marionette Mercy", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate. I don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off. Even such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere! Find it. And perhaps we test it before we go use it on the Magistrate. Just in case.", ["objectivesText"] = "Find the Puppetmaster's Antiparalytic Serum . Progress: I would worry we're taking too long, but considering how dramatic that Puppetmaster is, I can't imagine he'll start the show without us. We should be prepared for something... rather unpleasant at that theater.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 219385 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.417333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80207] = { ["id"] = 80207, ["name"] = "How Scandalous!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Did you see anything? I was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again. But it was not that... Some peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers! The peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?", ["objectivesText"] = "Investigate the disturbance near the Forgegrounds in Dornogal .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219393, ["x"] = 0.625, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80208] = { ["id"] = 80208, ["name"] = "Digging into Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["rewardXP"] = 11765, ["rewardItems"] = { 223802 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2Objectives"] = { { ["text"] = "Subdue Moles or Kill Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Subdue Moles", ["amount"] = 10, ["type"] = 0, ["objectID"] = 219424, ["orderIndex"] = 2 } }, ["objectivesText"] = "Subdue Moles or Kill Players Subdue Moles", ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3302 }, ["questType"] = "pvp", ["flags"] = {  },
},
[80209] = { ["id"] = 80209, ["name"] = "An Oddball in Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["series"] = { 80456 }, ["description"] = "We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident. I have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me? I have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.", ["objectivesText"] = "Interview Concerned Dornogal Citizens to locate the Arathi Lamplighter.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222224, ["x"] = 0.544, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 222268, ["x"] = 0.664667, ["y"] = 0.178667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80210] = { ["id"] = 80210, ["name"] = "Found Around the Unbound", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village. My superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city. <Leif quickly hides a smile.> It is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.", ["objectivesText"] = "Meet Peacekeeper Leif outside Freywold Village.", ["rewardGold"] = 28600, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222268, ["x"] = 0.664667, ["y"] = 0.178667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.178667 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80211] = { ["id"] = 80211, ["name"] = "The Pillage of Freywold Village", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but... Soon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night. The locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now? Given the villagers' hostility, the Lamplighter and I shall remain here for the moment.", ["objectivesText"] = "Search for clues as to where the Arathi went. Progress: I am attempting to convince the villagers that the Lamplighter is not involved in these disappearances. Did you find anything useful?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80212] = { ["id"] = 80212, ["name"] = "The Abductors' Obstructors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them. The next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them. Go on ahead <name>. I must first speak with Kaerter about why the Arathi are doing this.", ["objectivesText"] = "Meet Peacekeeper Leif at Rambleshire.", ["rewardGold"] = 28600, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222353, ["x"] = 0.575, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80213] = { ["id"] = 80213, ["name"] = "Holy Fire in Rambleshire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. You and I are gonna find out. Here, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. Just throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. Just don't throw one at me! Got it?", ["objectivesText"] = "Use Flashfire Thuribles to reveal Order of Night forces in Rambleshire, eliminate them, and search them for clues. Progress: Alright, I'll admit it, the little Pebble is pretty useful. He knows more about the earthen and the surface than I ever will. Anyway, did you find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 224104, 224118 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222352, ["x"] = 0.575, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222356, ["x"] = 0.62, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80214] = { ["id"] = 80214, ["name"] = "A Time to Kill at the Lumber Mill", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. But the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here. And now we gotta deal with the Order AND whoever their new friends are. <Kaerter swears and shakes his head.> C'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.", ["objectivesText"] = "Meet Lamplighter Kaerter outside of Skolzgal Mill.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222356, ["x"] = 0.62, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80215] = { ["id"] = 80215, ["name"] = "Ungirthin' the Earthen", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first. I saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do! Oh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.", ["objectivesText"] = "Free 8 Abducted Lumberjacks.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 }, { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80216] = { ["id"] = 80216, ["name"] = "Concealed in the Weald", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see. We cannot allow such a large enemy force to operate unimpeded this close to Rambleshire. The nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people. We must eliminate as many of them as we can. Preferably all of them.", ["objectivesText"] = "Eliminate Shadowsilk forces at the Skolzgal Mill. Progress: The more enemies we eliminate, the safer we will all be.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222358, ["x"] = 0.67, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80217] = { ["id"] = 80217, ["name"] = "A Lamplight for the Shipwright", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "Where is Kaerter now? Did he go off on his own again? <Leif sighs.> We've rescued the earthen and eliminated many hostile forces, but our task is not yet complete. Shortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright. The shipwright is the leader here. Losing her will cripple their efforts to utilize the mill. Head up the hill and find her before she can escape.", ["objectivesText"] = "Confront the Arathi shipwright.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80218] = { ["id"] = 80218, ["name"] = "Up to No Good Down in Silkwood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. The nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage. While slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel. Get going <name>. I'll be right behind you.", ["objectivesText"] = "Collect Silkwood Explosive Barrels, then destroy the nerubian tunnel at Silkwood Grotto. Progress: Did you take out the tunnel?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222364, ["x"] = 0.66, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222365, ["x"] = 0.655, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
