[80312] = { ["id"] = 80312, ["name"] = "Gasping Plea", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "<A gasping, pathetic-looking fish taken from the corpse of a kobyss flops weakly in your hand. Its beady eye twitches, and you suddenly hear a breathless voice in the recesses of your mind.> The water. Take me to the water. Away from these kobyss wretches. Away from the sky.", ["objectivesText"] = "Put the strange fish in safe waters near the kobyss camp at Sunless Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["rewardItems"] = { 217352, 222964 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 217352 }, ["questType"] = "standard", ["flags"] = {  },
},
[80313] = { ["id"] = 80313, ["name"] = "Tidal Charms", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "<When the fish speaks, its lips do not move. You hear its voice in your head.> No doubt you have found that your senses cannot be trusted when dealing with the kobyss. A tremendous power, is it not? It is only fair that you show them the power they wield is not theirs alone. I will show you how to craft a tool to lure and destroy them. You will find their kind carry shards taken from the deep. Bring them to me.", ["objectivesText"] = "Collect 12 Sunless Shards from the kobyss at Sunless Strand. Progress: Bring the materials. Only then can we continue.", ["rewardGold"] = 295000, ["rewardXP"] = 10190, ["rewardItems"] = { 217352, 217709, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80314] = { ["id"] = 80314, ["name"] = "Voices from the Deep", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "To deceive the senses of these kobyss is one matter. To know what will captivate them is another. They champ and drool at the thought of devouring your kind. But it is the voices of the deep that transfix them and lower their guard. It's then that you will strike. Search their shrines to gain an insight for what these wretches hold sacred. See how they have twisted the bellowing truths that lie below.", ["objectivesText"] = "Study three ritual sites for insights on the kobyss. Progress: What have you learned?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 217352, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80315] = { ["id"] = 80315, ["name"] = "Alluring Offer", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "It is done. Take this tidal charm, cloak your form in the darkness of the sea, and unmake the kobyss. Their strongest warriors gather and scheme against your kind upon that central island. With the lure, they will not see you for what you are. Use that advantage to become their end. But understand, as the kobyss fail to, this is a power you borrow. It belongs to the sea.", ["objectivesText"] = "Lure and assassinate Gillcarver and his Kobyss Tidemarshals on the island off the Sunless Strand. Progress: Isolate them. Destroy them.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 217352, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80316] = { ["id"] = 80316, ["name"] = "Return to the Sea", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "I remain weakened by my time so near the searing Light of the surface. I ask that you take me to deeper waters, away from these kobyss, where I can return to my kind.", ["objectivesText"] = "Take the Peculiar Fish to deeper waters.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 217352, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80321] = { ["id"] = 80321, ["name"] = "Departure", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "Best if we split up here. I'll guide everyone to safety and see about getting them evacuated. In the meantime, you should search for Khadgar. I'm sure he could use your aid as well. You'll find another exit further ahead that should lead back to the surface.", ["objectivesText"] = "Find Khadgar back on the surface.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 42786, 42799, 42811, 42828, 224453, 224454, 224455, 224456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15177 } }, ["mapID"] = 2305, ["db2PoiUiMapID"] = 2305, ["db2PoiMapID"] = 2731, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
