[80334] = { ["id"] = 80334, ["name"] = "Shattered Spires", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 78532 }, ["description"] = "With nothing to contain their arcane power, Dalaran's spires are crumbling. If we let their energies continue to bleed out unchecked, that power could destabilize and destroy what is left of our forces. Find Aethas! He will know what to do.", ["objectivesText"] = "Find Aethas at the Tranquil Strand.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223166, ["x"] = 0.308, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 4, ["flags"] = 1 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 8, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
