[80378] = { ["id"] = 80378, ["name"] = "A Light of the Dark", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "The image of a purple candle, burning with glorious power springs unbidden to your mind as you contemplate the decaying filth before you, followed by a faint whisper echoing through your mind: \"One candle to rule them all, and in its brightness bind them.\" Bring Janky the candlesmith in Gundargaz enough Coagulated Black Blood to forge a most unfortunate candle.", ["objectivesText"] = "Collect Coagulated Black Blood and bring it to Janky the kobold candlesmith in Gundargaz. Progress: < Janky shivers as you approach.> Ah!", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 217390, 217391, 220161, 221776, 223472, 237812, 257143, 265106, 265631 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216598, ["x"] = 0.455, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80382] = { ["id"] = 80382, ["name"] = "Eggs in One Basket", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80382 }, ["description"] = "<This work order remains unfilled. Aliya Hillhelm would be quite happy if you helped complete the order.>", ["objectivesText"] = "Collect 10 Hillhelm Eggs to place in this basket. Progress: Inform Aliya that the work order is complete.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 206350, 217396 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
