[80392] = { ["id"] = 80392, ["name"] = "The Caretaker of Brunwin's Terrace", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Greetings, outlander. You must be the problem solver I've heard about! I'm Caretaker Batzvara . I tend to earthen who have gone into stasis, like our friend here. I often patrol Brunwin's Terrace to honor my fellow earthen with an offering of cinderbrew. Recently, however, I've drawn the attention of a local species of moles. They have a nose for sweets, and greedy claws for all else. You look like you can defend yourself. Will you accompany me to pay respect to those who have gone into stasis?", ["objectivesText"] = "Offer cinderbrew to 6 inert earthen and kill 10 Sweetsnufflers .", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219784, ["x"] = 0.491, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224362, ["x"] = 0.494, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.491, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
