[80397] = { ["id"] = 80397, ["name"] = "Sweets Seekers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 80397 }, ["description"] = "Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it! As I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.", ["objectivesText"] = "Kill 12 sweetsnufflers .", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80399] = { ["id"] = 80399, ["name"] = "Rations and Revelations", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "We found these prisoners fleeing a nearby nerubian military base. The circumstances of their escape are... unclear, even to them. As if someone else created the opening they needed to escape. They need rest, but we need to find out what happened in there. Food first. Maybe once they've regained some of their strength, they'll remember something.", ["objectivesText"] = "Hand out 3 Arathi Rations . Progress: We managed to throw together a simple stew of sorts. It's not the tastiest, but it has to be better than whatever they had to eat in spider prison.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 217614 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80401] = { ["id"] = 80401, ["name"] = "A Perfect Sponge", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Welcome, stalwart colleague, to Shimmermist Falls! It's always damp here--a thriving paradise for green, living things. Unfortunately, it's also the perfect climate for moss to grow on my inert earthen charges. We'll need to gather a few supplies for removing the moss. First, we need a sponge to wash their surfaces. It needs to be soft enough to not damage them but strong enough to hold up to an earthen's rough stone skin. The caps from the lashrooms down below are perfect!", ["objectivesText"] = "Collect one perfect lashroom cap . Progress: These lashroom caps make for perfect sponges!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 218131 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80402] = { ["id"] = 80402, ["name"] = "Buckets and Blooms", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Down among the creeping lashrooms grows an orange flower. When mixed with water, its blooms make a caustic solvent that is perfect for removing moss from earthen skin. I also left a bucket next to this earthen the last time I was here, which I use to make the solvent. Something seems to have made off with it. Could I delegate the task of gathering these to you? I'll wait here. The moles from the terrace have given me enough excitement for one day.", ["objectivesText"] = "Collect 8 caustic blooms and find the missing bucket . Progress: The acidity from the plants is strong enough to remove the moss but gentle enough not to harm the earthen. Plus it has a pleasing smell to it. Almost like sulfur.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 218187, 218355 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80404] = { ["id"] = 80404, ["name"] = "Mossy Earthen", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Excellent work gathering everything together. I've mixed the solvent for you. Now all that's left is to gently clean off our mossy friends down there.", ["objectivesText"] = "Tend to 4 mossy earthen. Progress: Let's get these folks cleaned up.", ["rewardGold"] = 232300, ["rewardXP"] = 7440, ["rewardItems"] = { 218353 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80405] = { ["id"] = 80405, ["name"] = "Too Much Drip", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "This is Ausgazur . His hand is usually full of a selection of his favorite gems. We don't really know what it's like when we go into stasis, but he wanted to spend his last moments contemplating the natural beauty of Azeroth and her bounty. I am afraid someone or something has made off with the jewels he usually holds. Let's look around. See if you can find any clues where they may have gone off to.", ["objectivesText"] = "Examine Ausgazur for clues. Progress: Ausgazur will never forgive me if his gems go missing. This is very upsetting. Who would steal from an earthen in stasis?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 219216 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80406] = { ["id"] = 80406, ["name"] = "Seeking Ausgazur's Gems", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "So it was kobolds who made off with Ausgazur's gems. I did not realize the Waterworks was under attack. Our timing is lucky for the defenders down below! We must get those jewels back! I'll stay here and guard the remaining gems, but I implore you to complete a critical task: go down into the Waterworks and retrieve the rest.", ["objectivesText"] = "Recover 4 of Ausgazur's gems. Progress: We need to find the rest of Ausgazur's gems! Critical priority!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 219015 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80407] = { ["id"] = 80407, ["name"] = "Glintwick the Gem Grabber", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "The kobold mentioned Glintwick, did he? It sounds like she's the driving force behind these gem thieves. I'll bet my beard she's got Ausgazur's last gem! Look for her in the Waterworks and see if she has the final gem. She may also be behind the attack that's happening, so taking her out will help the defenders.", ["objectivesText"] = "Kill Glintwick. Progress: Glintwick will not get away with this thievery!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 219213, 228658 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
