[80500] = { ["id"] = 80500, ["name"] = "The Bronzebeard Family", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "<Moira takes a deep, centering breath.> We need to let Brann and my son Dagran know what happened. They're at Dalaran 's visitor center. Could ye go get them for me? Father needs his family right now.", ["objectivesText"] = "Head to Brann and Dagran in the Dalaran Visitor Center to inform them of what has happened to Magni. Progress: My son always has been the scholarly sort. Takes after his father in that way... We're all quite proud of him.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 629, ["db2PoiUiMapID"] = 629, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
