[80502] = { ["id"] = 80502, ["name"] = "Don't Cry for Me, Azj-Kahet", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "<You find a crumpled page of journal paper wrapped around a small key.> I always suspected Arax'ne was a traditionalist, but I didn't think she'd go this far. I don't know where I'm going, but I just have to get away from her. To whoever finds this, it means the worst has come to pass. This key unlocks a chest that contains all my worldly possessions. They are yours. All I ask is that you avenge me by slaying Arax'ne .", ["objectivesText"] = "Avenge Klaskin and kill Arax'ne in the Umbral Bazaar. Progress: The key glints silver in the light of Azj-Kahet .", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 226173, 226174, 226175, 226176 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 220690, ["x"] = 0.638, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 218084 }, ["questType"] = "standard", ["flags"] = {  },
