[80508] = { ["id"] = 80508, ["name"] = "Dread in the Den", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You kobold friend, yes? Need help. Bad things happening in the Chittering Den. Glumtooth Gang setting up camp. Cronies of Candle King, want war with earthen. Can't stop them alone. Meet me at camp.", ["objectivesText"] = "Meet Scrit at her camp in the Chittering Den.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
