[80509] = { ["id"] = 80509, ["name"] = "A Suit of Slime", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80510, 80511 }, ["description"] = "Glumtooth Gang no let you into camp looking like that. Need disguise. Make you look like bug, then we walk right in. First, need wax. Plenty here. Take from slime beasts or scrape off hoppers. Then we stick wax on you. Stick bug bits to wax. Perfect disguise.", ["objectivesText"] = "Collect 20 Sticky Wax from Waxy Runoffs and Wax-addled Hoppers . Progress: With right disguise, no one know you not bug.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220218 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80510] = { ["id"] = 80510, ["name"] = "Healing the Headwaters", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80509, 80511 }, ["description"] = "Glumtooth Gang so wasteful! They leave much scrap in the water. Bad for water. Bad for scrap. Go clean it up.", ["objectivesText"] = "Remove 6 Waxy Scrap.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
