[80511] = { ["id"] = 80511, ["name"] = "Casing the Camp", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80509, 80510 }, ["description"] = "Now we take you to camp. You see what Boss Whiskerlash do. Put on bug disguise when we close to camp. Let me do talking.", ["objectivesText"] = "Investigate the Glumtooth Gang camp. Progress: Can no let this camp stand. Too much to lose for kobold and earthen.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
