[80512] = { ["id"] = 80512, ["name"] = "Beat the Best", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "If Glumtooth Gang succeed, this earthen first captive of many. We need free him. He prize. Every kobold here want fight him. Must earn our place. You beat up strong bugs, they think me strong trainer. Then they let you into ring. May best bug win.", ["objectivesText"] = "Defeat the bug-trainers. Progress: Beat other three contenders and we can rescue the earthen.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
