[80513] = { ["id"] = 80513, ["name"] = "Snouty Sabotage", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both. Some fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape. While you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.", ["objectivesText"] = "Place Cinder-Flash Candles and loosen bug leashes. Progress: Boss Whiskerlash regret day he help turn kobolds to war.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80514] = { ["id"] = 80514, ["name"] = "Break out Berrund!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You work good. Now they let you into ring to \"fight\" earthen. You go to ring when ready. Cinder-flash candles could go off any moment. I head back to camp. Wait for you and earthen there. You good one. No get killed.", ["objectivesText"] = "Escort Berrund from the camp.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220220, ["x"] = 0.675, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
