[80515] = { ["id"] = 80515, ["name"] = "Put the Shine On", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "Hate to admit, but loud earthen right. Boss Whiskerlash have strongest bugs. But everything have weakness. Spiders afraid of light, and our friend very shiny. If we make him shinier, no spider want to fight. Glumtooth Gang been capturing candleflies. Free them and rub off some glow dust. We make big earthen big shiny!", ["objectivesText"] = "Free Candleflies and collect their luminescence. Progress: This better not go to his head.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220485 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
