[80516] = { ["id"] = 80516, ["name"] = "Bump off the Boss", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "That kobold knows her stuff. Scrit says Boss Whiskerlash has his own cadre of spiders in a cave nearby. Don't worry, I'll lead the charge. Come on, we've got a boss to take down.", ["objectivesText"] = "Slay Boss Whiskerlash .", ["rewardGold"] = 578600, ["rewardXP"] = 12400, ["rewardItems"] = { 228654, 228655, 228656, 228657, 258265 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220220, ["x"] = 0.675, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
