[80558] = { ["id"] = 80558, ["name"] = "Nothing Ventured", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "These niffen have been down here a long time--long enough to build a village and set up trade with the nerubians. Some of them are even able to trade in that big nerubian city! The goblins, though? They're from the Venture Company. No wonder General Anub'azal was skeptical of me, if he's used to dealing with them. What are they doing all the way down here? Let's try to learn what led them to this place.", ["objectivesText"] = "Learn what you can from the goblins in Mmarl. Progress: Take a good look around for loose-lipped goblins.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80563] = { ["id"] = 80563, ["name"] = "Tool of Attunement", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80564, 80565, 82143 }, ["description"] = "The nerubians must have some means of cleansing themselves after Black Blood exposure. If they did not, they would not have been so successful in their harvesting operation. If necessary, I can pick up on the harmony of this world with ease to restore my mind to this reality. But for your sake and Hannan's, we should probably obtain whatever it is they use. Although we can spare the trouble... if you don't mind the threat of forever splitting your consciousness between two realities.", ["objectivesText"] = "Find a Tuning Crystal . Progress: The nerubians must have something on them to cleanse their minds after such direct proximity to the Black Blood.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 218188 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80564] = { ["id"] = 80564, ["name"] = "Field Research", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80563, 80565, 82143 }, ["description"] = "The nerubians are harvesting Black Blood nearby. If allowed to persist, the corruption caused by excavating the veins may spread. It will continue until it consumes everything. I have no intention of sitting and waiting for it to taint the roots. I am trying to learn and understand their methods... so that I may strike at the heart of the operation. You're welcome to join me. If, of course, you would also prefer your world not to drown in oozing pools of Black Blood.", ["objectivesText"] = "Investigate the Black Blood harvesting site. Progress: These disgusting pustules, the veins of corruption... this is only the beginning of the damage this horrific operation could cause.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80565] = { ["id"] = 80565, ["name"] = "Resounding Repercussions", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80563, 80564, 82143 }, ["description"] = "I did not mean for... < Orweyna 's eyes narrow.> Fetch him, <name>. You were exposed to the Black Blood, too. But Hannan took most of it. He has entered the Unseeming, his mind shifted to a realm beyond our eyes through exposure to the Black Blood. You may need to join him, however far in he ventured, to retrieve him. I will activate the nerubian cleansing instrument for when you return. Do not lose yourself in that altered state.", ["objectivesText"] = "Retrieve Hannan from the Abandoned Harvest Site inside the cave. Progress: Is this real? Am I imagining the monsters?", ["rewardGold"] = 28090, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220603, ["x"] = 0.598, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220608, ["x"] = 0.618, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80566] = { ["id"] = 80566, ["name"] = "Enemies Abound", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80567, 80568 }, ["description"] = "< Hannan is barely responsive and less corporeal than he should be, lost deeper in the Unseeming than you.> Some of the canisters exploded... Then the spiders appeared. Kill the--kill the spiders!", ["objectivesText"] = "Find and kill the spiders.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220608, ["x"] = 0.618, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 223285, ["x"] = 0.598, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80567] = { ["id"] = 80567, ["name"] = "Song of Restoring", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80566, 80568 }, ["description"] = "< Orweyna looks relieved at the sight of Hannan , but does not seem dissuaded from her task.> I cannot say I am surprised at what you found in that cave. Nerubians stuck in the Unseeming, trapped in a realm of monsters and madness... I would pity them, but they sought this out. You, however, need to shift back before the influence of the Black Blood becomes too strong on your mind.", ["objectivesText"] = "Use the Harmonizing Instrument . Progress: It is a relief that the tuning crystal we found worked on this strange instrument. For once we should be grateful for the ingenuity of the nerubians. If this device had not worked, we may have been stuck in the Unseeming forever. Like the nerubians in the cave.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223285, ["x"] = 0.598, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 223286, ["x"] = 0.598, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80569] = { ["id"] = 80569, ["name"] = "Harmonious Approach", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["description"] = "I know I cannot stop Orweyna from going down there and drawing attention to our presence. But... perhaps we could stop word of our presence from spreading. Find whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.", ["objectivesText"] = "Kill Harvest Warden Izk'tilak . Progress: I'm not going to leave her down here alone. But we have to be cautious. We must deal with anyone who sees us.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["mapID"] = 2256, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80570] = { ["id"] = 80570, ["name"] = "Staunch the Flow", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80571, 80572 }, ["description"] = "Do they even understand what they are doing? < Orweyna bares her teeth, practically growling.> Destroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage. We cannot stop them all, not today. But a bit of destruction may temper my rage.", ["objectivesText"] = "Destroy 8 Extractors.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["mapID"] = 2256, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80571] = { ["id"] = 80571, ["name"] = "Decipher the Cacophony", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80570, 80572 }, ["description"] = "This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder... < Orweyna seems shaken, but not deterred.> I can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is. <name>. Bring me something from the Unseeming.", ["objectivesText"] = "Collect 10 Discordant Essence from Discordant enemies in the Unseeming. Progress: What have the nerubians done to this place?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 217391, 221776 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["mapID"] = 2256, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80572] = { ["id"] = 80572, ["name"] = "Discordant Measures", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80570, 80571 }, ["description"] = "I cannot stand to look at this any longer. I must act. <name>. You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed. We will kill what we can and search for some sliver of hope that we can still restore this land.", ["objectivesText"] = "Acquire 50 stacks of Unseeming Shift and collect 3 samples from elite enemies lost in the Unseeming. In addition to destroying extractors, you can also acquire Unseeming Shift by standing in pools of Black Blood. However, be careful as you will gain stacks quickly by doing so. Progress: Hannan's concerns are not unfounded. But I cannot simply witness this corruption and make no attempt to root it out.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 225696, 225697, 225698 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["mapID"] = 2256, ["db2PoiUiMapID"] = 2256, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80573] = { ["id"] = 80573, ["name"] = "Dropping Eaves: Spoils of War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 80573, 81470, 81471, 81472, 81473, 81475, 81476, 81477, 81478, 81479, 81480, 81481, 81482, 81483, 81484, 81487, 81488, 81489, 81490, 81491, 81492, 81493, 81494, 81495, 81496, 81497, 81498, 81499, 81500, 81501, 81502, 81503, 81504, 81505, 81506, 81555 }, ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 218456, 219016, 219017 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2Objectives"] = { { ["text"] = "Have a drink and eavesdrop", ["amount"] = 1, ["type"] = 0, ["objectID"] = 228735, ["orderIndex"] = 0 }, { ["text"] = "Sureki War Chest looted", ["amount"] = 1, ["type"] = 0, ["objectID"] = 220889, ["orderIndex"] = 1 } }, ["objectivesText"] = "Have a drink and eavesdrop Sureki War Chest looted", ["mapID"] = 2213, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5573, ["name"] = "The Severed Threads", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3555 }, ["questType"] = "standard", ["flags"] = {  },
},
[80576] = { ["id"] = 80576, ["name"] = "Listener Lost", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["description"] = "Blast it all! Brennok and I were on our way to Shadowvein Point to conduct a recitation ceremony. We were attacked by scorpids. Now the hauler has a scorpid stinger lodged in its gears, and Brennok wandered off. He said he was going to stretch his legs while I fixed the hauler, but that was a while ago. I need to get the bot moving again, can you look for him?", ["objectivesText"] = "Find Brennok .", ["rewardGold"] = 29500, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80577] = { ["id"] = 80577, ["name"] = "Readying the Recitation", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80676, 81613 }, ["description"] = "Once a year, Brennok and I take the long road through The Ringing Deeps . We stop at each outpost, and Brennok tells the residents a story from their past. One they entrusted to him to remember, even when they forget. It's my duty to ready the ceremony site. Would you come with me? I could use the help.", ["objectivesText"] = "Prepare the recitation site. Progress: Brennok usually seems more excited for a recitation.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 224008 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80578] = { ["id"] = 80578, ["name"] = "The Common Costume", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 82224 }, ["description"] = "I'll slip away after the recitation. It's easy to vanish in a crowd of earthen enjoying a keg of cinderbrew. However, I can't be recognized when I leave town. I don't want anyone to stop me. Or worse, to think I'm abandoning my oath. Better to just disappear. If you find me a spare set of Miner's Clothes , I'll be able to get away without being noticed.", ["objectivesText"] = "Find a spare set of Miner's Clothes . Progress: Did you find them yet?", ["rewardGold"] = 140450, ["rewardXP"] = 4960, ["rewardItems"] = { 221472 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.613143, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80592] = { ["id"] = 80592, ["name"] = "Forge a Pact", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80592 }, ["description"] = "Let us renew your Pact. Remember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.", ["objectivesText"] = "Choose a Severed Threads Pact.", ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest", ["questType"] = "standard",
},
[80593] = { ["id"] = 80593, ["name"] = "A Sip of Cinder", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["description"] = "Now there's one last thing we need. It wouldn't be a proper recitation ceremony without mead. However, Hearthkeeper Zirc tells me the last couple deliveries of cinderbrew haven't arrived. It seems the local flayers in the Rumbling Wastes have a taste for it and raid the shipments. Here, take a spare keg. See what you can recover from the flayers.", ["objectivesText"] = "Fill a keg with Cinderbrew Mead. Progress: Careful out there, flayers are already dangerous enough. I wouldn't want to meet one that's been guzzling cinderbrew.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 221000, 221001 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80670] = { ["id"] = 80670, ["name"] = "Eyes of the Weaver", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations. Still, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty. Lucky you, I suppose.", ["objectivesText"] = "Continue your efforts in aiding the Weaver in Azj-Kahet. Progress: Chk-chaah! You return at least. What news of the city do you bring me, hrm?", ["rewardXP"] = 17650, ["rewardItems"] = { 225571, 239125, 250769 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224734, ["x"] = 0.564, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest", ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard",
},
[80671] = { ["id"] = 80671, ["name"] = "Blade of the General", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet. Ansurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.", ["objectivesText"] = "Continue your efforts in aiding the General in Azj-Kahet. Progress: Hrmph. It is about time that you've returned. What news?", ["rewardXP"] = 17650, ["rewardItems"] = { 225572, 239122, 250767 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224729, ["x"] = 0.558, ["y"] = 0.422 }, { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest", ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard",
},
[80672] = { ["id"] = 80672, ["name"] = "Hand of the Vizier", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support. That is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?", ["objectivesText"] = "Continue your efforts in aiding the Vizier in Azj-Kahet. Progress: I fear that our task grows more arduous with each passing day. I hope you are not wasting time.", ["rewardXP"] = 17650, ["rewardItems"] = { 210796, 210799, 210802, 210805, 210808, 210930, 210933, 210936, 212664, 212667, 224828, 225573, 228950, 228952, 239124, 250768 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest", ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard",
},
[80673] = { ["id"] = 80673, ["name"] = "Runway Scare-a-way", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "'Lo there. Me and Mags are generally in charge of clearing the sky in this area during our Lamplighting route. If we don't cull the moths in the area, they start spreading up towards the skydocks and start laying eggs in the machinery of our ships. Unfortunately we're not as spry as we used to be. Could you lend a helping hand? They're pretty frail so they'll squish easily to any high velocity flight. Or you could just smack 'em the old-fashioned way.", ["objectivesText"] = "Kill 25 moths either by flying through them or killing them normally. Progress: Nasty critters...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80676] = { ["id"] = 80676, ["name"] = "Defragmenting Memory", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80577, 81613 }, ["description"] = "My oath is to be a compiler. I collect and tell the stories of our people. < Brennok sighs.> Is there wisdom in stories told by someone who never lived them? I've never had an adventure. I was afraid to overwrite the stories entrusted to me. So I started transcribing them into a book I hid here. Each time we returned to Shadowvein Point, I added more. I was going to leave and pass on the book, but scorpids ransacked it. Please, find the missing pages before they stuff them into their nests.", ["objectivesText"] = "Collect 100 Missing Pages of Brennok 's book. Progress: Thousands of stories, now they're probably lining some animal's den...", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220999 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.613143, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80677] = { ["id"] = 80677, ["name"] = "Torching Lights", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "No matter how many moths we swat, if we don't take care of the eggs they'll just continue to be a problem. Take this firearm, use it to torch some of the eggs on the top of the mire's canopy.", ["objectivesText"] = "Torch 15 moth eggs . Progress: Watch the torch trigger, it's an older piece.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219943 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[80678] = { ["id"] = 80678, ["name"] = "Time Lost", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Now that the job's done -- one thing I've always done on this route is muck around for some of the valuables that fall from the docks. As things get moved onto ships small items can fall off. Sometimes people chuck 'em for luck or in rage, and the like. But some of those items have memories in 'em. Things so precious that losing it might as well be losing part of your heart. If you could help me look I'd be grateful.", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardGold"] = 169800, ["rewardXP"] = 11765, ["rewardItems"] = { 219524, 219809, 219810, 219811, 219812, 219813, 219814, 219815, 219816 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
