[81510] = { ["id"] = 81510, ["name"] = "Ship It!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 81510 }, ["description"] = "What a haul! I was able tae give a bit of what we found tae Dagran so he could finish off one of his projects. He should be here any minute. Ah, I can't hold back. Surprise! It's a gift tae help you get around.", ["objectivesText"] = "Speak with Brann Bronzebeard Progress: Wait 'till ye see what Dagran has cooked up.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 219391 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
