[81514] = { ["id"] = 81514, ["name"] = "Bountiful Delves", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 81514 }, ["description"] = "We're going tae need lots of resources to fight off Xal'atath. Lucky for you, we've uncovered a source! Some delves we've found are \"bountiful\" on account of the baddies there hoardin' more treasure. This treasure can only be unlocked with special keys found throughout Khaz Algar. Keys and key fragments can be found all about the world. Hunt them down and dive into a bountiful delve!", ["objectivesText"] = "Complete Special Assignment World Quests, World Activities, or Weekly Quests to recover a Restored Coffer Key or Coffer Key Shards to unlock a chest within a Bountiful Delve. Progress: Did ye find the key yet?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 219391 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
