[81556] = { ["id"] = 81556, ["name"] = "Foreign Fog", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "Pleasure to meet you, adventurer. I wonder if you might be willing to help me with some research? I'm sure you've noticed the fog beasts that have recently started encroaching upon this area. People see them as a bad omen, they always seem to show up during periods of ecological imbalance. I disagree with this assertion. Still as an expert in all vapor-based magics, I've been hired to find out where they're coming from so they can be cut off at the source.", ["objectivesText"] = "Place the fog collector and collect fog samples from different areas occupied by fog beasts. Progress: Have you collected the fog samples?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81557] = { ["id"] = 81557, ["name"] = "Fog Tags", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "While I analyze these fog samples, I have another task for you. My employers have asked me to figure out where these fog beasts are coming from. I've developed these trackers. If you could, please attach them to an assortment of fog beasts. You'll have to get close, so... be careful. Hopefully they don't mind it too much!", ["objectivesText"] = "Attach trackers to fog beasts in and around Taelloch. Progress: Have you attached all the trackers?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219469 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81558] = { ["id"] = 81558, ["name"] = "Unnatural Predators", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "It would be no use tagging fog beasts to study if they all were to die, would it? Could you clear out some of the aggressive deepflayers that have flocked to feast on the fog beasts? They'll ruin my data if left unchecked, I'm sure of it.", ["objectivesText"] = "Kill Deepflayer Hunters . Progress: Have you taken out the deepflayers?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
