[81559] = { ["id"] = 81559, ["name"] = "Fog Follower", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "With the trackers attached, we should be able to find out where the fog beasts are coming from. The trackers leave a residue in the air. It's invisible to the naked eye, but I can use the mists to reveal it in places where there's a high enough concentration. Theoretically, this should lead us to the places they most frequent. Maybe a nest! That I'll then have to report to my employer... hm. Anyway. Let's see what we can find.", ["objectivesText"] = "Help Noli find the source of the fog beasts with her mist tracking ability. Progress: I know we'll be able to find them. Let's keep looking!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
