[81655] = { ["id"] = 81655, ["name"] = "Juicy Krolusk Meat", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81655, 81669, 81672 }, ["description"] = "Greetings! I am Kagfritha . I was once a site supervisor for operations in the Rumbling Wastes to the south of here, but time has taken its toll on our enterprise and we had to abandon the area. It's high time we got things back in working order down there, but while we were gone some unsavory creatures moved in. I have a plan for dealing with the worst of the bunch, but first we need some bait. If you're here to help, go hunt some of those dirt diving krolusks and bring me back their meat.", ["objectivesText"] = "Collect 4 pieces of krolusk meat. Progress: I have big plans for that krolusk meat, and for the Rumbling Wastes!", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["rewardItems"] = { 219493 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5621, ["name"] = "Revenge in the Rumbling Wastes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
