},
[81661] = { ["id"] = 81661, ["name"] = "To Mourning Rise", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Greetings, outlander. My name is Urtago , and I am Caretaker Korgran's apprentice at the Mourning Rise memorial site. The mischievous Candlelit Kobolds have overrun Mourning Rise, and we seek assistance. Would you meet me at Fallside Outpost? It is just to the north of here. I will be able to tell you more once you arrive.", ["objectivesText"] = "Meet Urtago at Fallside Outpost.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 221355, ["x"] = 0.556, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81667] = { ["id"] = 81667, ["name"] = "The Upstart", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["series"] = { 81668 }, ["description"] = "You are the Weaver's \"untethered third party?\" Excellent. You are the perfect catalyst for a coup. The City of Threads has sent an upstart here to seize control of Rak-Ahat. The arrival of Ren'khat has everything all tangled up. He postures himself as some kind of silk visionary from the city, and he challenges the authority of the Overspinner who refused to relinquish control. Bad for the Overspinner, good for us. Speak with Ren'khat and feed his ambition. Help him against the Overspinner.", ["objectivesText"] = "Offer your services to Ren'khat against Grand Overspinner Antourix. Progress: What is this? An overcrawler? Here?", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221550, ["x"] = 0.665, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81668] = { ["id"] = 81668, ["name"] = "Measure Once, Cut Thrice", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["series"] = { 81667 }, ["description"] = "I was promised an important, glamorous, enviable position of power when I left the city for Rak-Ahat. This warehouse job? Neither important nor enviable. And certainly not glamorous. Grand Overspinner Antourix has been at this for far too long. She doesn't understand my vision. All she wants are drones that do exactly what she wants, how she wants it. Take out her most loyal workers. We'll see how tough she is on her own once I take over the dyeworks.", ["objectivesText"] = "Slay Webwarper Tath'rhiz , Seam Reaper Zhir'ix , and Colormancer Nirethi . Progress: Ugh. It's impossible to work under these conditions.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221550, ["x"] = 0.665, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222133, ["x"] = 0.728, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81669] = { ["id"] = 81669, ["name"] = "Sticks and Bones", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81655, 81669, 81672 }, ["description"] = "While the krolusks like to attack from beneath, the Rumbling Waste also plays host to a predator who prefers to swoop down from above. Deepsflayers have built nests on the peaks and ridges around the Waste. Destroy their nests and show them that the Waste is no welcoming home.", ["objectivesText"] = "Burn 6 Deepsflayer Nests . Progress: Let's show those overgrown bats that the Wastes is no home for them!", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5621, ["name"] = "Revenge in the Rumbling Wastes", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81670] = { ["id"] = 81670, ["name"] = "Shattered Silk", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "none", ["categories"] = { "bonusobjective" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 81670 }, ["description"] = "Nothing will get the attention of the Head Cutter--and disrupt her operations--like destroying her equipment! Get in there and mess stuff up, really send a message.", ["objectivesText"] = "Bar fill destroy EVERYTHING kill EVERYONE", ["rewardGold"] = 1227200, ["rewardXP"] = 21190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["db2Objectives"] = { { ["text"] = "Silkworkers slain", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2QuestInfoID"] = 283, ["db2QuestInfoName"] = "Bonus Objective with Completion Toast", ["questType"] = "standard", ["flags"] = {  },
},
[81672] = { ["id"] = 81672, ["name"] = "In a Pinch", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81655, 81669, 81672 }, ["description"] = "I suppose I should come clean and tell you why I had you gather that meat. Truth is, there's a horrible beast who lives down in the Wastes. A monster who feeds on the unwary and whose pincers can snap through stone and bone like a knife through warm butter. Its name is Smaragthr , and the foul thing is the reason I have but one eye and my gems are cracked. I am no match for it, but you... you could enact my vengeance. Kill Smaragthr so the Wastes can be free!", ["objectivesText"] = "Kill Smaragthr . Progress: I will have my revenge on that vile creature!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 219510 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5621, ["name"] = "Revenge in the Rumbling Wastes", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81673] = { ["id"] = 81673, ["name"] = "Honor Your Efforts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79232, 81673 }, ["description"] = "Though my rank is humble, I bestow upon you this honor. A tinderbox, signifying your friendship with our expedition and your esteemed status in Hallowfall . Should you fall in battle, your tinderbox shall be given a place of honor among the other great heroes who died defending this land. Please accept this honor.", ["objectivesText"] = "Accept the honor of a Hallowfall Tinderbox. Progress: You should be proud of your efforts.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 219503 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5670, ["name"] = "Zone 3 Neck 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81675] = { ["id"] = 81675, ["name"] = "Water the Sheep", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["storyline"] = { 80295, 80394, 80395, 81465, 81512, 81615, 81621, 81639, 81675, 81710, 81854, 82225, 82234, 82237, 82291, 82292, 82355, 82448, 82451, 82454, 82455, 82456, 82470 }, ["rewardXP"] = 9515, ["rewardItems"] = { 219525 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["db2Objectives"] = { { ["text"] = "Mosswool Sheep watered", ["amount"] = 8, ["type"] = 0, ["objectID"] = 221413, ["orderIndex"] = 0 }, { ["text"] = "Pests punted", ["amount"] = 10, ["type"] = 0, ["objectID"] = 221425, ["orderIndex"] = 1 } }, ["objectivesText"] = "Mosswool Sheep watered Pests punted", ["mapID"] = 2248, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["questLines"] = { { ["id"] = 5589, ["name"] = "Isle of Dorn - World Quests", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "world", ["flags"] = {  },
},
[81683] = { ["id"] = 81683, ["name"] = "Spring Collection", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["series"] = { 83616 }, ["description"] = "That maggot Ren'khat wants my position, hm? He's welcome to try and take it. All the runoff from our operation flows into the spring below Rak-Ahat. Decades of mordants, catalysts, and alchemical concoctions have coalesced into something quite... potent. Don't fuss about the side effects. Just bring me a good variety of dyestuffs and I'll brew up colors that will have you growing extra pairs of legs.", ["objectivesText"] = "Collect 12 Reclaimed Catalyst , as well as 3 Luminous Strangler Sap , 3 Eyeless Petals , and 3 Cochineal Crawlers . Progress: You're still here?", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["rewardItems"] = { 224283, 224284, 224285, 224286 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221557, ["x"] = 0.756, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222135, ["x"] = 0.728, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81685] = { ["id"] = 81685, ["name"] = "Azj-Kahet's Next Top Dyemaster", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["description"] = "Ren'khat and the Overspinner are fighting pincer-and-claw. Inside the spinneret. With no witnesses. We have a unique opportunity here. If they took one another out... well, with Antourix's favorites dispatched and the whole of Rak-Ahat in disarray, the next best authority would be the caravan coordinator. Me. I don't love being in the spotlight, but it would be very beneficial to our secret-smuggling operation if those two didn't make it out of the dyeworks.", ["objectivesText"] = "Slay Ren'khat and Grand Overspinner Antourix . Progress: What a relief not to hear those two bickering anymore...", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 226166 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222132, ["x"] = 0.728, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81686] = { ["id"] = 81686, ["name"] = "Subterfuge in Silk", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81686 }, ["description"] = "I'm expecting a shipment of silk. That it hasn't arrived worries me. Most silk in Azj-Kahet , from the finest veils to the strongest warsilk, comes from Rak-Ahat. It makes the place a convenient nexus of information. One of my agents smuggles military secrets woven into the silk itself. Recently, she has reported a power struggle emerging in Rak-Ahat... and even more recently, she has reported nothing at all. Meet with her and ensure no more delays.", ["objectivesText"] = "Meet with Teth at Rak-Ahat.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207476, ["x"] = 0.568, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81687] = { ["id"] = 81687, ["name"] = "I Expect You To Dye", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["description"] = "I thought playing them against each other would give me some cover, but it's plunged all of Rak-Ahat into chaos! This could jeopardize our whole operation! You heard what Antourix said. She already augmented the dyebaths with all of those reagents you collected. I don't know what they'll do, but if she was planning on using them against Ren'khat... there's no reason you couldn't use them to take out both of their goons. Test out those dyebaths, and clear out the dyeworks!", ["objectivesText"] = "Slay 8 Dyeworks nerubians using the powers granted by Augmented Dyebaths. Progress: I wanted less squabbling interfering with my work, not more!", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222132, ["x"] = 0.728, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81688] = { ["id"] = 81688, ["name"] = "That's All", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["description"] = "It will be interesting to see how all this unfolds... but knowing the Weaver, I'm sure she has some strings to pull to make it go her way. This is the secret I was trying to pass to her when things started heating up. Why don't you deliver it to her, as a sign of a job well done? I'm sure she'll be pleased to know that she continues to have a set of eyes in Rak-Ahat.", ["objectivesText"] = "Deliver the Secret-Woven Silk to the Weaver in her lair. Provided item:", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["rewardItems"] = { 224659 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81689] = { ["id"] = 81689, ["name"] = "Orientation: Gundargaz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "Our new kobold friends have been moving into Gundargaz. They've also been gathering odds and ends from around the Ringing Deeps . You should check in with the Quartermaster! Go have a look at what they've collected. Then we can talk about what we're doing next. I heard Anduin's around here somewhere. I suspect he has some plans for Hallowfall. We need all the allies we can get against the nerubians.", ["objectivesText"] = "Meet with Waxmonger Squick in Gundargaz Progress: New allies are always appreciated.", ["rewardGold"] = 28900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
},
[81690] = { ["id"] = 81690, ["name"] = "The Light at the End of the Tunnel", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "I've never seen shadows this deep. This... vicious. It almost feels like they're reaching for us. <Faerin shudders.> We can't stay here.", ["objectivesText"] = "Escape Gloomcrag Bower with Faerin and Anduin.", ["rewardGold"] = 590000, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 221733, ["x"] = 0.554, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214405, ["x"] = 0.561333, ["y"] = 0.419333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["questType"] = "standard", ["flags"] = {  },
},
