[81692] = { ["id"] = 81692, ["name"] = "The Flame Within", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 81692, 81751, 81869, 81896 }, ["description"] = "When sparked, a tinderbox creates a flame that embodies the essence of its bearer's life journey. It is a reflection of your strength and inner spirit. In your travels, you have met many who could help us fashion a tinderbox capable of igniting a flame befitting your formidable spirit. Seek the assistance of Speaker Kuldas in Gundargaz. The earthen's knowledge will help create a more powerful tinderbox.", ["objectivesText"] = "Seek out and gain the aid of Speaker Kuldas in Gundargaz.", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214380, ["x"] = 0.432, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2214, 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5671, ["name"] = "Zone 3 Neck 2", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[81693] = { ["id"] = 81693, ["name"] = "Desperately Seeking Skorthuz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81693, 81712, 81713 }, ["description"] = "Eh? Who are you? Oh that's right, I heard that there were new folk about. Say, are you heading north? If so, keep an eye out for my friend, Skorthuz , will you? The laggard was due back an hour ago but is nowhere to be seen. I heard he was heading towards the Chittering Den for some awful reason. If you see him, tell him to hurry up and get back here or I'm drinking alone!", ["objectivesText"] = "Look for Skorthuz around the Chittering Den.", ["rewardGold"] = 73700, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220415, ["x"] = 0.603, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220446, ["x"] = 0.629, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.603, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5622, ["name"] = "Frolicking in the Fetid Grotto", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
