[81990] = { ["id"] = 81990, ["name"] = "The Light's Call", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 81990 }, ["description"] = "Attention, residents of Hallowfall ! Urgent assistance is needed to reclaim the shadowed outskirts. As darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.", ["objectivesText"] = "Report to Keyrra Flamestonge for further service.", ["rewardGold"] = 30000, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questType"] = "standard", ["flags"] = {  },
