[82195] = { ["id"] = 82195, ["name"] = "Rust and Redemption", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 82195 }, ["description"] = "As you approach, a rusty lever catches your eye, stubbornly stuck in its place. \"This thing hasn't moved in ages,\" you muse, as you feel the rough metal resist your touch. Glancing around, you note the oily sheen on the plantlike Crawlers. \"Perhaps a bit of natural lubricant would do the trick,\" you ponder, realizing that these flora foes might yield what you need to ease the lever's grip.", ["objectivesText"] = "Collect 3 Pure Crawler Extracts from Underdrip Crawlers and Crawler Sproutlings within the Ringing Deeps . Progress: The lever remains immovable, its secret locked tight without the Crawler Extract.", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 221970 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
