[82226] = { ["id"] = 82226, ["name"] = "Papers? Please!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82226 }, ["description"] = "Hey pal, what's it gonna take to get you to leave me alone? How about a trip? A POWER trip... I told Boss Sparkshot that I would man the worksite's...er, resort's! Yeah, that I would man the resort's front desk for a bit. Care to take my place? It's just your usual paper-pushing busy work. Check credentials, keep an eye out for corporate sabotage, call in the occasional air strike, etcetera, etcetera... <Garv has already fallen back asleep.>", ["objectivesText"] = "Check papers at the Overseer's Desk in Opportunity Point. Progress: You're in my shade, pal.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223184, ["x"] = 0.634, ["y"] = 0.786667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223184, ["x"] = 0.634, ["y"] = 0.786667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.786667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
