[82441] = { ["id"] = 82441, ["name"] = "For The Love of Gems", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82441, 82465, 82466, 82467 }, ["description"] = "Before Dalaran crashed, I was a preeminent expert on gems. But I lost it all--gems, books, scrolls--like everyone else. Imagine my surprise when I learned of a creature named Basalteous that possesses knowledge of gems stretching back before the Sundering. I want that knowledge. I will do anything for it. But the rock-skinned yokels here won't tell me any more about Basalteous. Can you get the earthen to talk?", ["objectivesText"] = "Gather information on Basalteous from earthen villagers. Progress: Were you able to talk to them? Do you have any information?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 228217 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223637, ["x"] = 0.43, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223637, ["x"] = 0.43, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5651, ["name"] = "Heart of Stone", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
