[82465] = { ["id"] = 82465, ["name"] = "Precious Gems", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82441, 82465, 82466, 82467 }, ["description"] = "So, all they gave us was a location and a garbled riddle... But I guess we know where to start. I can picture it now. Once I have Basalteous's knowledge, I will have nobles and merchants lining up outside my house. No, my mansion! The earthen did say southwest, right? I will find the cave and meet you there. Quickly now!", ["objectivesText"] = "Meet Natalia by Basalteous's cave.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223637, ["x"] = 0.43, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223924, ["x"] = 0.338, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5651, ["name"] = "Heart of Stone", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82466] = { ["id"] = 82466, ["name"] = "What We Do For Gems", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82441, 82465, 82466, 82467 }, ["description"] = "According to the earthen, we have to lure the spirit. Or disturb it. Or something. The four standing stones they mentioned have depleted elemental cores laying around them. There are igneous elementals outside and on the beach to the north. Are you thinking what I'm thinking? Could you get me elemental cores? Maybe just a few? We're so close, so we might as well try...", ["objectivesText"] = "Collect 4 elemental cores from the Igneous Sand elementals. Progress: Do you have the cores?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 223891 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223924, ["x"] = 0.338, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223924, ["x"] = 0.338, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5651, ["name"] = "Heart of Stone", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82467] = { ["id"] = 82467, ["name"] = "Gems Are Forever", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82441, 82465, 82466, 82467 }, ["description"] = "I am so close, I can feel it in my bones. Place the cores next to each standing stone. It is time to summon Basalteous .", ["objectivesText"] = "Lure out Basalteous by placing a core by each standing stone. Progress: This is it. I can feel it.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 228217 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223924, ["x"] = 0.338, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223924, ["x"] = 0.338, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5651, ["name"] = "Heart of Stone", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
