[82477] = { ["id"] = 82477, ["name"] = "A Helping Farmhand", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["description"] = "Greetings, $p, name's Orren. We've got a whole mess of Jawcrawlers that came up from underground attacking the crops. Something a <class> like yourself could really help out with! Hunger is never far away in Hallowfall , so saving these crops is my priority. But if you'd be willing to drive them off for me, I'll be able to focus on my long-term plan to feed people more effectively. Meet me over by the shed! And bring any food that's not too chewed up.", ["objectivesText"] = "Recover 8 Slightly Chewed Harvest Bounty from Gluttonous Jawcrawlers. Progress: This'll keep our crops safe in the future. And perhaps the leftovers can go... in a stew.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 224051 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 223920, ["x"] = 0.49, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224378, ["x"] = 0.472, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82478] = { ["id"] = 82478, ["name"] = "Regularly Scheduled Maintenance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["description"] = "I've got another problem that's a bit more... personal, $p. My girlfriend, Aemyra, is a Lamplighter. I thought she'd be back from her last mission, to Velhan's Claim, by now. Could you go make sure she's okay, and deliver this message? I'm worried to the point of distraction. Maybe you could also pick some of her favorite flowers, up that hill? I'd go myself, but if I can get ELIZA working right, it would do so much to feed people in Hallowfall . And give me more time to spend with Aemyra, too!", ["objectivesText"] = "Take Orren's Message , 6 Crimson Charmer and 6 Amber Bloom to Aemyra at Velhan's Claim. Progress: These are from Orren? I think they go well together, even though they're so different.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 224098, 224099, 224193 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224378, ["x"] = 0.472, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82479] = { ["id"] = 82479, ["name"] = "The Sword is Mightier", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["series"] = { 82480 }, ["description"] = "I had told Orren I'd be back by now, but Velhan's Claim has larger problems than I expected. The people here need my help against the kobyss. $p, I've always been better with a sword than a pen. Strong feelings and being far apart makes it even harder. I'm more at home protecting the vulnerable than being vulnerable. Perhaps I could tell you what I want to get across and you could write it for me?", ["objectivesText"] = "Help Aemyra choose the right words for her message to Orren. Progress: Did you find Aemyra? Is she alright?", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224379, ["x"] = 0.465, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82480] = { ["id"] = 82480, ["name"] = "Job Killing Robot Or...", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["series"] = { 82479 }, ["description"] = "I shouldn't have set ELIZA to simply gather as much food as she could. She was working, but when a wagon came by, full of food for Mereldar, she started chasing it! And she wouldn't let me access her decision sprockets or tensor springs! I kept trying, but ELIZA wouldn't stop. Eventually, she outran me. $p, I need you to stop her before someone gets killed.", ["objectivesText"] = "Stop ELIZA . Progress: Were you able to stop ELIZA ?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 225947 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224379, ["x"] = 0.465, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224380, ["x"] = 0.483, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82481] = { ["id"] = 82481, ["name"] = "Enforcer Extermination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["db2Objectives"] = { { ["text"] = "Pale Weavelashers slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 224009, ["orderIndex"] = 0 } }, ["objectivesText"] = "Pale Weavelashers slain", ["mapID"] = 2255, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 38, ["flags"] = 0 } }, ["questType"] = "world", ["flags"] = {  },
