[82482] = { ["id"] = 82482, ["name"] = "Worldsoul: Snuffling", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I've wanted to be able to explore beyond Hallowfall's caves for so long now. Of course, I hardly have time, but when I do... there's such surprises everywhere! Treasures, friends in need, foes great and small... All so wonderful. I'll just have to live vicariously through you. Deeds need doing! Go out and seek the surprises in every nook and cranny. I'm certain you will find things that need doing!", ["objectivesText"] = "Find Disturbed Earth piles to Snuffle and discover Worldsoul Motes by skyriding all around Khaz Algar. Progress: Oh, what have you found?! Tell me everything.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82483] = { ["id"] = 82483, ["name"] = "Worldsoul: Spreading the Light", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Darkness continues to spread through Hallowfall. We need your help to keep the fires burning! The shadows are deep and dark. My people are strong, but we always need more hope. More sparks for the flame. You are the brightest spark of all.", ["objectivesText"] = "Complete Spreading the Light objectives and slay Rare creatures in Khaz Algar.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82485] = { ["id"] = 82485, ["name"] = "Worldsoul: Cinderbrew Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim. I can't help but imagine it's how Beledar would taste... The earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands. But... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", ["objectivesText"] = "Complete the Cinderbrew Meadery dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 48, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82486] = { ["id"] = 82486, ["name"] = "Worldsoul: The Rookery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, <name>.", ["objectivesText"] = "Complete the Rookery dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 47, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82487] = { ["id"] = 82487, ["name"] = "Worldsoul: The Stonevault", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. I can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. Eirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", ["objectivesText"] = "Complete the Stonevault dungeon on Normal difficulty or higher. Progress: To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 46, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82488] = { ["id"] = 82488, ["name"] = "Worldsoul: Darkflame Cleft", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... <Faerin clasps her hand to her chest with a grin.> So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!", ["objectivesText"] = "Complete the Darkflame Cleft dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 44, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82489] = { ["id"] = 82489, ["name"] = "Worldsoul: The Dawnbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. It is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", ["objectivesText"] = "Complete The Dawnbreaker dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82490] = { ["id"] = 82490, ["name"] = "Worldsoul: Priory of the Sacred Flame", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- <Faerin pauses, momentarily lost for words.> There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, <name>. Stop them.", ["objectivesText"] = "Complete the Priory of the Sacred Flame dungeon at Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 17, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82491] = { ["id"] = 82491, ["name"] = "Worldsoul: Ara-Kara, City of Echoes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. There's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. We need to find out what's going on. Bring together your strongest companions and investigate!", ["objectivesText"] = "Complete the Ara-Kara, City of Echoes dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 19, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82492] = { ["id"] = 82492, ["name"] = "Worldsoul: City of Threads", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. We must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", ["objectivesText"] = "Complete the City of Threads dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 20, ["flags"] = 0 } }, ["questType"] = "standard",
},
