[82498] = { ["id"] = 82498, ["name"] = "Worldsoul: Darkflame Cleft", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... <Faerin clasps her hand to her chest with a grin.> So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!", ["objectivesText"] = "Complete the Darkflame Cleft dungeon on Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 25, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82499] = { ["id"] = 82499, ["name"] = "Worldsoul: Priory of the Sacred Flame", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- <Faerin pauses, momentarily lost for words.> There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, <name>. Stop them.", ["objectivesText"] = "Complete the Priory of the Sacred Flame dungeon at Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 26, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82500] = { ["id"] = 82500, ["name"] = "Worldsoul: The Rookery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, <name>.", ["objectivesText"] = "Complete the Rookery dungeon on Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 27, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82501] = { ["id"] = 82501, ["name"] = "Worldsoul: The Dawnbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. It is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", ["objectivesText"] = "Complete The Dawnbreaker dungeon on Mythic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 28, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82502] = { ["id"] = 82502, ["name"] = "Worldsoul: Ara-Kara, City of Echoes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. There's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. We need to find out what's going on. Bring together your strongest companions and investigate!", ["objectivesText"] = "Complete the Ara-Kara, City of Echoes dungeon on Mythic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 29, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82503] = { ["id"] = 82503, ["name"] = "Worldsoul: Cinderbrew Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim. I can't help but imagine it's how Beledar would taste... The earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands. But... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", ["objectivesText"] = "Complete the Cinderbrew Meadery dungeon on Mythic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 30, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82504] = { ["id"] = 82504, ["name"] = "Worldsoul: City of Threads", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. We must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", ["objectivesText"] = "Complete the City of Threads dungeon on Mythic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 31, ["flags"] = 0 } }, ["questType"] = "standard",
},
