[82511] = { ["id"] = 82511, ["name"] = "Worldsoul: Awakening Machine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The earthen tell me of this \"Awakening Machine\" that is part of their life cycle. It imbues them with energy, once a gift of the titans but now from the Worldsoul. <Faerin smiles faintly and nods knowingly.> They hold it in high reverence--as we do Beledar. I will fight to defend it with the same fervor as I would defend our own star! Aid me, <name>. We can't let them down.", ["objectivesText"] = "Defeat 20 cumulative waves of enemies in the Awakening Machine.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 223269, 224784, 229354, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 40, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82512] = { ["id"] = 82512, ["name"] = "Worldsoul: World Boss", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Hallowfall is not the only land beset by enemies. Great monsters wander all of Khaz Algar--savage beasts and intelligent fiends alike. They murder Arathi, earthen, and adventurers in equal measure from innocent farmers to great warriors. I know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", ["objectivesText"] = "Defeat any World Boss and 5 rare creatures in Khaz Algar. Progress: I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 41, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82516] = { ["id"] = 82516, ["name"] = "Worldsoul: Forging a Pact", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I've heard some reports of the goings on in Azj-Kahet. Nerubians have killed my people mercilessly since we arrived... it is very difficult to imagine them as allies. But... I understand feeling... different from the rest of your people. Perhaps these nerubians who have interest in us are also... different. <Faerin sighs.> No matter the cost... I can't bear to not give them a chance. Are they not also inhabitants of Khaz Algar? See what aid you can bring them, my friend.", ["objectivesText"] = "Select a Severed Threads Pact to represent in Azj-Kahet, complete objectives in their name, and slay rares in Khaz Algar. Progress: I want to believe some nerubians can be different... can be better. But please be careful.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 228949, 228950, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard",
},
