[82539] = { ["id"] = 82539, ["name"] = "Radiant Echoes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 82539 }, ["description"] = "<A missive finds its way to you.> $p, please come to Dalaran at once. Strange phenomena are appearing all across Azeroth. We believe they may be connected to the Radiant Song. I'd like you to investigate.", ["objectivesText"] = "Meet Khadgar in Dalaran .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82540] = { ["id"] = 82540, ["name"] = "Memories of Adventures Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 82540 }, ["description"] = "It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. Past events have now come to life once more. I believe they're Azeroth's memories. Memories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.", ["objectivesText"] = "Go the portrait room in Dalaran and use a glowing portal to join a Radiant Echoes event. Once it begins kill the area boss to complete the event. Progress: Radiant Echoes and Radiant Visions, all appearing at once. What could Azeroth be trying to tell us? Or perhaps it's just... instinct.", ["rewardItems"] = { 219325, 223644 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["flags"] = {  },
},
