[82629] = { ["id"] = 82629, ["name"] = "Nerub-ar Palace: For Nerubian Eyes Only", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14980, ["storyline"] = { 82629 }, ["description"] = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. Fetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", ["objectivesText"] = "Collect 3 Signets of the Thousand Scars and 3 Signets of the Skeinspiner within Nerub-ar Palace on Normal difficulty. Progress: Safe passage has its price.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 224011, 224014 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14980 } }, ["questType"] = "raid", ["flags"] = {  },
