[82659] = { ["id"] = 82659, ["name"] = "Worldsoul: Nerub-ar Palace", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", ["objectivesText"] = "Complete the Nerub-ar Palace raid on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82672] = { ["id"] = 82672, ["name"] = "Another Timely Invitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 82672 }, ["series"] = { 84254 }, ["description"] = "The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris! There are all sorts of new activities to partake in that honor and remember what has transpired over the years. Head to Tanaris and join in the festivities.", ["objectivesText"] = "Visit the celebration in Tanaris outside the Caverns of Time.", ["rewardGold"] = 26210, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 224334, ["x"] = 0.496, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 224419, ["x"] = 0.476, ["y"] = 0.779 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 71, 84, 85 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[82676] = { ["id"] = 82676, ["name"] = "Broken Masquerade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 82676 }, ["description"] = "I cannot remember how I arrived at this swamp, but it was great luck that I did. As I wandered, I spotted Lady Katrana Prestor entering a strange toothy cave. Now, what would a noblewoman be doing in such a ghoulish place? Following her closely, I found a great clutch of black dragon eggs within the lair. Such evidence is clear. Katrana is Lady Onyxia! I beg of you, aid me in defeating this vile dragon once and for all.", ["objectivesText"] = "Defeat Remembered Onyxia during a Radiant Echoes event. Progress: If only Varian were here. Surely he'd have no issue slaying her.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 224367, ["x"] = 0.454667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 224367, ["x"] = 0.454667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard",
},
[82678] = { ["id"] = 82678, ["name"] = "Archives: The First Disc", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I am pleased to report progress has been made restoring the titan Vault of Memory in the Archive. I have the mainframe up and running--but part of its internal mechanism has failed over time. Getting parts for it will be a challenge, which is why we need your help. Come with me to the Vault of Memory. We can discuss what we need with Dagran.", ["objectivesText"] = "Meet with Dagran in the Vault of Memory and assist him in finding titan disc fragments . These disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar. Progress: Did you happen to find anything?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 225741, 229354, 239118, 244865 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82679] = { ["id"] = 82679, ["name"] = "Archives: Seeking History", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "We're still processing the data in the Archive and restoring what we can. But... the discs we've recovered so far in the Archive itself are unusable. Finding more of these discs are a priority. We must reclaim our memories. Return what you find to Dagran. He is assisting me in rebuilding the Archive.", ["objectivesText"] = "Collect 100 titan disc fragments . These disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar. Progress: Have ye found anythin'?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 225741, 229354, 239118, 244865 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82680] = { ["id"] = 82680, ["name"] = "Birdman of the Three Shields", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["series"] = { 82681 }, ["description"] = "Are you here to watch the mosswools? No? That's too bad. I find the elemental creatures on our isle fascinating. I'm not the only one. An old friend of mine named Olbarig resides out on the Three Shields. He studies the wild cloudrooks there. But come to think of it, I haven't heard from him in awhile. Maybe someone should check on him. Hm. Would you mind?", ["objectivesText"] = "Find Olbarig on the Three Shields.", ["rewardGold"] = 72300, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224394, ["x"] = 0.602, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82681] = { ["id"] = 82681, ["name"] = "Cloudrook Down", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["series"] = { 82680 }, ["description"] = "You see that flock in the distance? Wild cloudrooks. They've lived on these islands peacefully for ages. But recent events have stirred other elementals from the earth and sea. One of the cloudrooks was attacked, and it was... disincorporated. Now the flock circles endlessly. Surely they will tire soon. If they get too tired... Perhaps if we cleared the hostile elementals from this island, they will return and take their rest.", ["objectivesText"] = "Cull the riled elementals from the central Shield. Progress: This is the cloudrooks' habitat. Your crash and our war with the nerubians is what caused the other elementals to come. We should set this right.", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82682] = { ["id"] = 82682, ["name"] = "Elemental Hors D'Oeuvres", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["description"] = "The cloudrooks cannot possibly circle forever, and I cannot bear more of them being lost. But maybe they'd roost if we tempted them with their favorite food? The eels that swim in these waters carry a small electrical charge not unlike the mosswool favored by their faster, stronger cousins the stormrooks. I once reasoned that cloudrooks might enjoy the eels for similar reasons. And I confess... I've been feeding them the eels ever since. Gather some up and give it a go.", ["objectivesText"] = "Gather 10 Electric Eels . Progress: The eels may not pack quite the punch of Rambleshire mosswool, but the cloudrooks seem to prefer it that way.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 232510 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82689] = { ["id"] = 82689, ["name"] = "Only Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 82689 }, ["description"] = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!", ["objectivesText"] = "Defeat Remembered Lich King during a Radiant Echoes event. Progress: We battle for the fate of Azeroth. For the light of dawn!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 224373, ["x"] = 0.595, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 224373, ["x"] = 0.595, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard",
},
[82690] = { ["id"] = 82690, ["name"] = "Lingering Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "When we faced Xal'atath's forces in Hallowfall , I sensed something dark just beneath the surface. Something that was not her, but it still troubles me. I have learned that running into every situation myself is not always the best tactic. Sometimes, a leader must stand back to see the field. So, I send you. Go to Hallowfall , and uncover what you can about this mysterious force. I don't want to be caught blind again.", ["objectivesText"] = "Return to where Alleria sensed Black Blood in Hallowfall .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7898, ["questType"] = "standard", ["flags"] = {  },
},
[82691] = { ["id"] = 82691, ["name"] = "No Breathing Room", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "We all followed Orweyna to these surface caves because we believed in what we were doing. But this... We did not bargain for so many injuries, so much dogged searching. For now, we just need a little breathing room. Slay the creatures out there that are harming us, and we can get the space to address the real issue.", ["objectivesText"] = "Slay Seeping creatures. Progress: Our people are fierce and strong. We are accustomed to being outnumbered. But this is too much.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 56667, 56668, 56669, 131322 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224397, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224397, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82692] = { ["id"] = 82692, ["name"] = "Price of a Mission", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I don't know what prompted you to come here, but we could use your help. We came to investigate signs of the Black Blood in this area, but the creatures overwhelmed us. Several of us are still out in the field. You are hale and hearty. Go find my people so they can return. And, if you have the strength, take a closer look at the strange flowers that grow from the blood that seeps beneath the ground. They may hold a clue as to how we can fight against its corruption.", ["objectivesText"] = "Find the pinned-down haranir and examine Strange Flowers . Progress: Have you found my people?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82693] = { ["id"] = 82693, ["name"] = "Standing in the Way", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "Some of these creatures are stronger than others. When we were able to act together and fresh to the fight, these creatures were no threat. Now our injuries and separation leave us vulnerable. My people are resilient, but we are not immortal. There is one beast larger than all the others. That beast is making it difficult for the haranir to return and recover. Slay it, so they can be safe.", ["objectivesText"] = "Defeat the Bloodcrust Behemoth . Progress: Once we are together again I know we will be able to regroup and continue.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82694] = { ["id"] = 82694, ["name"] = "Together, Alone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I am not blind. I know that they are tired and weary. But we are so close to figuring out what we can do about the Black Blood. The importance of what we uncover goes beyond Hallowfall , or the nerubian kingdom. There is so much more work if we are to find a solution. For now, let us withdraw and recover. Somewhere away from these creatures.", ["objectivesText"] = "Meet Hannan in Hallowfall to hear the plan.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82695] = { ["id"] = 82695, ["name"] = "The Voice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "Here is where I must focus. I can hear the voice of my goddess, and she must be near. I will enter a meditation to ask what I must do. How can I continue this mission alone? How can I go on without the others? Stay close. I don't know what may lurk or threaten while I am concentrating.", ["objectivesText"] = "Defend Orweyna as she meditates. Progress: < Orweyna is unresponsive as she focuses entirely on her meditation.>", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 38718, 38751, 39022, 39051, 39089, 211279, 237812 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82696] = { ["id"] = 82696, ["name"] = "Ringing in the Deeps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "My vision was clear to me. I need to continue this work. I need to find out how we can stop the Black Blood from spreading, before it's too late for your people, and for mine. Meet me in the Ringing Deeps . I will be in a form that allows me to hide and to listen without anyone noticing.", ["objectivesText"] = "Meet Orweyna at Camp Murroch in the Ringing Deeps .", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224856, ["x"] = 0.558667, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2214, 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82697] = { ["id"] = 82697, ["name"] = "Good Help These Days", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["series"] = { 82699 }, ["description"] = "Seeing you here is a welcome surprise! There's something big happening over at Opportunity Point, but it's hard to know what without getting closer to the people working there. I know Haxle's involved. We'll need his paperwork if we want to be able to ask around without trouble. He's headed down to Opportunity Point. Go, follow him, and see if he's got anything on him we can use. Don't worry about the mess-- I know you're discreet when you need to be. And... also not, when you need to be.", ["objectivesText"] = "Find Haxle Drillbit and shake him down for access to the operation. Progress: Got that work order? We can open up way more doors with it than without it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225913 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224857, ["x"] = 0.570667, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.570667, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82698] = { ["id"] = 82698, ["name"] = "Haywired and Hostile", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I saw many machines nearby, and all of them seem to make dreadful noises. I cannot hear the one that I heard in the vision, though, at least not clearly. Destroy the excess ones. They are only in the way. While you are quieting the scene, I will hunt and scout.", ["objectivesText"] = "Destroy the haywire excavators . Progress: You're not who I expected to see here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82699] = { ["id"] = 82699, ["name"] = "Hey, What's Going On?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["series"] = { 82697 }, ["description"] = "Time to do some networking. There's a bunch of goblins outside of Opportunity Point, over there in the Abyssal Excavation. I heard some of them grumbling as they started their shift. Let's see what some friendly words shake loose. While you're out there, check out the used fuel drums . They wouldn't let me look inside the full drums, but they just drop the used ones around the work site.", ["objectivesText"] = "Search for clues by questioning goblins and uncovering evidence in the Abyssal Excavation. Progress: We've got to stop meeting like this. Assuming we've met before, which, maybe we have.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82700] = { ["id"] = 82700, ["name"] = "Built to Blast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "We've got an intel problem, but we've also got a clank problem. If you look over there, there's a big, haywire mech that's just going crazy. There's no way anyone's going to uncover anything while that's out in the field. We should do something about that.", ["objectivesText"] = "Destroy the Haywire MEK IV .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.87 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82701] = { ["id"] = 82701, ["name"] = "Bat Versus World", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "When I scouted, I heard and saw things that I don't understand. Perhaps if I describe it to you and the goblins, you will know what it means.", ["objectivesText"] = "Experience Orweyna 's scouting mission.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82702] = { ["id"] = 82702, ["name"] = "Found Friends", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "So Gallywix has chosen to show his ugly face here, and it looks like he's got himself organized. We should report this to Alleria. See how she wants to handle it.", ["objectivesText"] = "Report to Alleria in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82706] = { ["id"] = 82706, ["name"] = "Delves: Worldwide Research", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "It's been all quiet recently. I've nae heard of any issues. This seems like a good opportunity for exploration, eh? I'm at yer disposal! We can go wherever it is ye want tae go!", ["objectivesText"] = "Complete 3 Delves in The War Within. Progress: Dangerous exploration? Survivin' by the skin of our teeth? Makes this ol' <race> feel alive!", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354, 239118, 244865 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 51, ["flags"] = 0 } }, ["questType"] = "standard",
},
[82739] = { ["id"] = 82739, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1584, ["storyline"] = { 82739 }, ["description"] = "The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths .", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[82740] = { ["id"] = 82740, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1584, ["storyline"] = { 82740 }, ["description"] = "The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths .", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon", ["flags"] = {  },
