[82747] = { ["id"] = 82747, ["name"] = "Crossroads Plaza", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82747 }, ["description"] = "Hello, outlander. Do you want to know about news from outside the city? The Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts. My friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.", ["objectivesText"] = "Meet Bondaz in Crossroads Plaza.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 224544, ["x"] = 0.465, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
},
[82748] = { ["id"] = 82748, ["name"] = "Deephaul Ravine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82748 }, ["description"] = "We've received reports of troubles in the earthen depths. Explore the Deephaul Ravine and the resources available, then report to Ruffious .", ["objectivesText"] = "Complete the Deephaul Ravine battleground.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
},
[82768] = { ["id"] = 82768, ["name"] = "Cloud Fishing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["description"] = "Now that we have the eels, we can try to lure the cloudrooks back to land. Head over to the neighboring island. Get as close as you can and make an offering to the rooks. With luck, they'll cease their circling and come down for a nourishing meal.", ["objectivesText"] = "Offer 7 Electric Eels to Wild Cloudrooks. Progress: Nothing better than electric eels to sate a tired and hungry cloudrook.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 109076, 224119, 228370, 228371, 228372, 228373 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82771] = { ["id"] = 82771, ["name"] = "Heritage of the Earthen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 84, 85 }, ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82771 }, ["description"] = "The time has come to give back to the Archives. All earthen wanderers are invited to share their experiences for the preservation of what has come before and the betterment of those who will come after. This knowledge and experience of the wider world of Azeroth is a priceless treasure, and the practice of sharing it is key to our earthen heritage.", ["objectivesText"] = "Upload experiences to the Archives in Dornogal. Progress: Have you uploaded your experiences yet?", ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 224790, ["x"] = 0.292667, ["y"] = 0.595333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.292667, ["y"] = 0.595333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82773] = { ["id"] = 82773, ["name"] = "A Functional Favor", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82774 }, ["description"] = "I am seeking my mentor, Foreman Arbauch. He is... missing. Under other circumstances, I would send for a search party from Gundargaz, but there is no time. I suspect he passed through here, but the only lead I have is DelGizmo. He wants the local fog beasts removed. Reluctance. But if he has seen Arbauch, I must learn what he knows. The lurkers to the south carry powerful Galvanic Glands . They have enough charge to disperse even the thickest fog. Retrieve some. Compensation assured.", ["objectivesText"] = "Collect 6 Galvanic Glands . Progress: Haste is appreciated. I must find Arbauch.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 224271 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82774] = { ["id"] = 82774, ["name"] = "Antifogmatic", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82773 }, ["description"] = "Machine speakers have no love for fog beasts. Where there is fog, rust is sure to follow. Still, I'd prefer not to harm them. Arbauch always said it was bad luck. Take this device. The glands you collected should provide enough power to disperse the fog without hurting the fog beasts within. Caution. Fog beasts are skittish, but other creatures may also lurk.", ["objectivesText"] = "Disperse the fog around Camp Murroch. Progress: Is it done? We have little time to waste.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 224438 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82775] = { ["id"] = 82775, ["name"] = "Quickchange Artist", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 82775 }, ["description"] = "You seem to have the programming of a great actor within you, $p! I know it because I have that fire myself--no matter what the rest of these so-called \"actors\" say. I'm very impressed with how fast you change costumes. I am a master of the quickchange artist's ways myself, you know. You're very close to figuring it out. You just need a few pointers from an expert--like me!", ["objectivesText"] = "Receive tips from Wendeline in the Proscenium.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215748, ["x"] = 0.568, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215748, ["x"] = 0.568, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82778] = { ["id"] = 82778, ["name"] = "Hallowfall Fishing Derby", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82778, 83529, 83530, 83531, 83532 }, ["description"] = "Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", ["objectivesText"] = "Catch these Trophy Fish before the Derby Dasher buff expires: Nibbling Minnow, Arathor Hammerfish, Queen's Lureback.", ["rewardItems"] = { 33820, 44050, 168417, 191356, 202207, 212310, 217375, 219002, 219003, 219004, 219005, 219006, 220134, 220135, 220136, 220137, 220138, 220139, 220141, 220142, 220143, 220144, 220145, 220146, 220147, 220148, 220149, 220150, 220151, 220152, 220153, 221790, 222533, 222745, 222842, 223286, 223979, 224717, 224727, 224752, 225592, 225758, 225763, 225770, 225771, 225892, 226376, 226378, 226379, 226392, 228421, 228422, 228423, 228954 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5637, ["name"] = "Hallowfall Fishing Derby", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82781] = { ["id"] = 82781, ["name"] = "Attention-Getter", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82781 }, ["description"] = "My, $p, it seems you have drawn the attention of a particular audience member. This fan letter was mistakenly included in my fan mail. I'm not surprised. Sorting my copious fan mail must be a difficult chore... Here, take it. It belongs to you, of course. I'm sure this is very new for you. I have a few pieces of wisdom for greeting eager fans, if you would like to hear it...", ["objectivesText"] = "Receive tips from Elma in the Proscenium.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217248, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217248, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82782] = { ["id"] = 82782, ["name"] = "Authenticity in Dress", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 82782 }, ["description"] = "You've done very well as an actor on stage, $p. But as an actor in a troupe, there are other directives we must carry out. One directive is to preserve our costumes for use in future plays. Many costumes we use more than once. I think we can trust you with using and preserving the troupes' costumes, don't you think? It would mean you could practice with us more frequently...", ["objectivesText"] = "Speak with Rabaan in the Proscenium.", ["rewardGold"] = 30300, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215745, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215745, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82783] = { ["id"] = 82783, ["name"] = "Chromie's Codex", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 82783 }, ["description"] = "Hello there! I could really use your help. You see, my codex has gotten a bit jumbled in all my travels lately, and I have to give a time tour back to the gates of Ahn'Qiraj in an hour. I need you to jump in with me to sort out any... inconsistencies. Then it should be right as rain and all the visitors here will have a fun, not-super-dangerous tour!", ["objectivesText"] = "Complete the Codex of Chromie event. Progress: Whew, that was pretty dicey there for a moment. I thought you might not have made it!", ["rewardItems"] = { 232877, 233014 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226368, ["x"] = 0.626, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226368, ["x"] = 0.626, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard",
},
[82784] = { ["id"] = 82784, ["name"] = "Resonant Performance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 82784 }, ["description"] = "$p, I have learned a lot from watching you perform. You change your nature so easily. In one play, I have seen you change from enemy to friend, from anger to sorrow... It's like watching mercury flow. With you on our stage, I feel we complete our plays to the letter of our directives with the highest satisfaction for our audience. If you have a moment, I would like to thank you for your support.", ["objectivesText"] = "Speak with Burkhalt in the Proscenium.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215744, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215744, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82785] = { ["id"] = 82785, ["name"] = "Ghosts in the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82786, 82814, 82969, 82990 }, ["description"] = "There's a substation directly below us? Perhaps that is where Arbauch went to hide it... Disregard, we must investigate. With luck, Arbauch may still be here. The entrance should be to the north, near the pool of water from the burst pipe. Please, come with me. He may need our help. I will explain everything once he is located.", ["objectivesText"] = "Find Foreman Arbauch.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82786] = { ["id"] = 82786, ["name"] = "Duty of Care", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82814, 82969, 82990 }, ["description"] = "The golem is unstable. I doubt it can travel far. We will track it, but haste failed me once already. Arbauch showed true devotion to the machines--we will follow his example. Repairs must come first. Machine systems are delicate. We must activate the backup before the failure can cascade. Exterminate any pests you find as well. Even the smallest creature can ruin delicate machinery. I am damaged. I will send my cogwalker with you to relay instructions.", ["objectivesText"] = "Activate the backup systems along the Cataract River. Progress: Our primary duty is to mend.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224618, ["x"] = 0.467, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
