[82792] = { ["id"] = 82792, ["name"] = "All Ore Nothing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["series"] = { 82796 }, ["description"] = "Outlander. Your aid is requested. The earthen here have said you would be of help. Our fellow earthen at the Opalcreg have not reported their quota for the past day. There must be something causing a disruption. Would you pay Foreman Alvegar a visit?", ["objectivesText"] = "Go to the Opalcreg and seek out Alvegar .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218535, ["x"] = 0.41, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82796] = { ["id"] = 82796, ["name"] = "Third Mine Blind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["series"] = { 82792 }, ["description"] = "I got cut off from the rest of the crew. We did not expect to be attacked by nerubians. Though I can't imagine the rest quitting. Our duty is too important to give up just yet. Barging right into the mine could cause the nerubians to frenzy and hurt the others. So, I found a third way to get in earlier. Though undetected will still be tough. Follow me.", ["objectivesText"] = "Meet Alvegar at the third entrance of the Opalcreg.", ["rewardGold"] = 144600, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.467333, ["y"] = 0.619333 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82797] = { ["id"] = 82797, ["name"] = "Hit Rock Bottom", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "A long way down to be sure, but I am certain that you can make it. If you doubt yourself, I made some parachutes to help you stick the landing. Once you get to the bottom of the cave, look for Cenderragg . She's the most senior of the group and probably has the best idea on how to rescue the team.", ["objectivesText"] = "Get to the bottom of the mine and find Cenderragg .", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.467333, ["y"] = 0.619333 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82798] = { ["id"] = 82798, ["name"] = "An Opal of Mine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "I'll be direct with you. We have a goal here and those opals are the center of it. No one will leave until we get the job done, the opals are too important. If you could gather enough ore, we could convince them to leave. But be careful, those nerubians are dangerous.", ["objectivesText"] = "Help Cenderragg collect 8 Opal Ore from the Opalcreg. Progress: Why did the nerubians have to show up? We were almost complete.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 224808 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82799] = { ["id"] = 82799, ["name"] = "Web Beats Rock", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "So, Foreman Alvegar sent you? That explains it. The situation is not great. This place is crawling with nerubians and they're showing us no mercy. They forced us to mine and took our hard-earned opals. When you disobey, they web you up. I was barely able to escape them when they came. The others... Well, that's where you come in. With you here distracting them, I can go rally the webbed earthen.", ["objectivesText"] = "Rescue 6 earthen workers in the Opalcreg.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82800] = { ["id"] = 82800, ["name"] = "A Sedimental Moment", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "Some have started to evacuate, but there's a stubborn few that just won't let go. Could you say something? Maybe an outsider's perspective will get them moving.", ["objectivesText"] = "Help Cenderrag inspire the earthen workers in the Opalcreg. Progress: Why must these few be so stubborn?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82801] = { ["id"] = 82801, ["name"] = "Beetlejeweled", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "To make sure no other earthen gets harmed we're going to have to eliminate their leader. You know the saying, rid yourself of the foreman and the whole line collapses. Either way, to get to safety we're going to have to go through them.", ["objectivesText"] = "Defeat Kix'arak outside of the Opalcreg Mine.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 228374, 228375, 228376, 228377 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218535, ["x"] = 0.41, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
