[82810] = { ["id"] = 82810, ["name"] = "Time Found", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Yer back! If you're up for it, there's more things in the muck to be found. Might have to dig a bit deeper this time.", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardXP"] = 11765, ["rewardItems"] = { 224179, 224184, 224186, 224187, 224188, 224189, 224266, 224267, 224268 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
