[82813] = { ["id"] = 82813, ["name"] = "Time Borrowed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Ah, now there's my good friend! Me and Mags are still here, looking for memories. Got a moment to spare for help?", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardGold"] = 202200, ["rewardXP"] = 11765, ["rewardItems"] = { 139506, 139770, 224187, 224238, 224239, 224250, 224254, 224257, 224272, 224273, 224274, 237812 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
