[82814] = { ["id"] = 82814, ["name"] = "Decommissioning Darkness", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82786, 82969, 82990 }, ["description"] = "Decommissioning a machine is a rare necessity. It must be done with care and regret. We put much of ourselves into our work. To destroy it is to destroy a part of ourselves. In doing so, we admit our failure to protect the Titans' work. But where stone rebels against stone, we must stand firm. Imperative: Destroy it. Recover Arbauch's memory gem .", ["objectivesText"] = "Destroy the Corrupted Golem and recover Foreman Arbauch's memory gem . Progress: Regret. This should have been my burden.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 224555 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224618, ["x"] = 0.467, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
