[82817] = { ["id"] = 82817, ["name"] = "Disturbance Detected: Blackrock Depths", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 82817 }, ["description"] = "The Timewalkers claim that they detected a time-displaced object in Blackrock Depths . While that fight may have ended in our defeat, the Dark Iron clan knows what's at stake should history change. We could lose the current dwarven alliance and all the good it has brought. Recover the object and protect our current peace.", ["objectivesText"] = "Recover the Timewarped Ironforge Blueprints from Emperor Thaurissan in Blackrock Depths . Progress: It brings me no pleasure, asking you tae fight against us. I feel for the bronze dragons and all the work they do tae protect the timeline.", ["rewardItems"] = { 224278, 232471, 232877 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard",
},
