[82836] = { ["id"] = 82836, ["name"] = "Zero Out Xerosh", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, the nerubians all seem to be taking orders from that siegelord south of here. If we can defeat her, that may turn the tide of this attack. Without a leader organizing the attack, the Arathi may be able to drive back the nerubians, especially if Faerin is able to light this dawntower she spoke of. But the longer we delay, the greater damage to the Arathi airships. Go quickly!", ["objectivesText"] = "Defeat Siegelord Xerosh . Progress: Were you able to defeat the siegelord?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645667, ["y"] = 0.576333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
