[82843] = { ["id"] = 82843, ["name"] = "Something Earthy", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82843, 82844, 82847, 82848 }, ["series"] = { 84392 }, ["description"] = "Ah, another one of you lot, eh? Well, if you want to eat, you need to help. Pick me a fresh taro, will you?", ["objectivesText"] = "Harvest a nearby taro plant for the chef Progress: Have you brought the taro?", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 224396 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.699, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5645, ["name"] = "The Mysterious Chef", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
