[82844] = { ["id"] = 82844, ["name"] = "Something Not Ruined", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82843, 82844, 82847, 82848 }, ["description"] = "Alright, I'll come with you. Show you how to do this properly. If I'm up, we might as well stock up on taro. Can't rely on adventurers to do delicate work, I suppose.", ["objectivesText"] = "Harvest 6 taro with the chef. Properly, this time. Progress: Is that all of them?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 224397 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.699, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5645, ["name"] = "The Mysterious Chef", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
