[82894] = { ["id"] = 82894, ["name"] = "The Price of Hope", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82894 }, ["description"] = "<name>, good to see you. I am about to make a trip to the local infirmary. Would you care to join me?", ["objectivesText"] = "Meet General Steelstrike in the Mereldar Infirmary. Progress: We lose so many, we need to save those we can.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 211878, 212239, 216687 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218289, ["x"] = 0.427, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
