[82895] = { ["id"] = 82895, ["name"] = "The Weight of Duty", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "I am now the caretaker of Mourning Rise. At last, I feel the weight of this new responsibility on my shoulders. It is a great honor, but one I must prepare myself for. Please, help me complete one final task, and then I will be ready. Meet me back at Fallside Outpost.", ["objectivesText"] = "Meet Urtago at Fallside Outpost to help her take on her new role. Progress: One more task, and then I shall truly be the caretaker.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219403, 223572, 224550, 253034 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224930, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224948, ["x"] = 0.572, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 16, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82916] = { ["id"] = 82916, ["name"] = "When Fungi Bloom", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82916 }, ["description"] = "Greetings! Perhaps you can help me with some busy work? I have so many orders that I have miscalculated several units of Mycobloom . To be honest, a bit more than several. Will you be kind and gather the rest for me?", ["objectivesText"] = "Gather 20 Mycobloom for Akdan in Dornogal . Progress: I don't mean to rush, but I need the mycoblooms as soon as possible. Please.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210796, 224817 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[82946] = { ["id"] = 82946, ["name"] = "Rollin' Down in the Deeps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82946, 83333 }, ["description"] = "Got a big task for you, yes? Fetch things, all waxy. Bring 'em quick, yeah? Much to trade for good finds. Get snufflin', friend!", ["objectivesText"] = "Collect 10 Odd Globs of Wax. Progress: You done snufflin' yet? Got those waxy bits?", ["rewardItems"] = { 212493, 227792, 228228 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5711, ["name"] = "Ringing Deeps - Weekly Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard",
},
[82952] = { ["id"] = 82952, ["name"] = "An Opportunity to Relax", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82952 }, ["description"] = "Hey, you! Yeah, you'll do. You wanna make some coin? We's tryin' to drum up business at our exclusive resort. Maybe ye heard of it? Opportunity Point Spa and Resort! Boss sent me up to Gundargaz to pass out this stack of flyers , but my trike blew a gasket and I'll be stuck here for a bit repairing her. How's about you head up there and pass them out for me? Look for the tired and weary types.", ["objectivesText"] = "Pass out 6 flyers to tired workers in and around Gundargaz. Progress: I shoulda listened to my mechanic. He told me there was no way my trike was gonna make it all the way up here, but my boss has been on me to get more clients. Did you pass out those flyers yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 224417 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224966, ["x"] = 0.517, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224966, ["x"] = 0.517, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.517, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82953] = { ["id"] = 82953, ["name"] = "A Cordial Invitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82953 }, ["description"] = "It is clear to me now that my time as the Vizier is drawing to a close. The nature of my service to Azj-Kahet must change. To that end, I have one final task to ask of you, <name>. You have done a great deal of work in the City of Threads since your arrival. No doubt your reputation now precedes you. Seek out our allies within the city and ask them to congregate in the Umbral Bazaar. I have a message prepared for them all.", ["objectivesText"] = "Spread word of the Vizier's announcement within the City of Threads. Progress: Move expeditiously, friend. We do not have much time.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 225024, ["x"] = 0.543333, ["y"] = 0.322667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82954] = { ["id"] = 82954, ["name"] = "Knives in the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82954 }, ["description"] = "No doubt you recall the assassin that sought to end me when last we met on this spot. If it weren't for your intervention, I would not be here now. Make no mistake, if my role in all of this has been compromised, that assassin will not be the last. If I am to make my last great stand, then I will need your help in ensuring my safety until the final hour. Scour the city for more of those skulking threats, and do what you must to ensure they will not interrupt my speech.", ["objectivesText"] = "Slay 4 Sureki Assassins in the City of Threads. Progress: Take care that you are thorough, friend. I would really rather not get stabbed today.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 225024, ["x"] = 0.543333, ["y"] = 0.322667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82955] = { ["id"] = 82955, ["name"] = "The Vizier's Resolve", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82955 }, ["description"] = "The stage is set, and the players are gathered. It is time for me to step out of the shadows. Thank you for standing with me thus far, <name>. Whatever comes next, I am grateful to have met you.", ["objectivesText"] = "Witness the Vizier's speech in the Umbral Bazaar.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 226100 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 225024, ["x"] = 0.543333, ["y"] = 0.322667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 225332, ["x"] = 0.715, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.543333, ["y"] = 0.322667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[82956] = { ["id"] = 82956, ["name"] = "To Opportunity Point", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82956 }, ["description"] = "Glad that's out of the way. Now my boss can stop breathing down my neck! I got some repairs to do on my ride, but you should go to Opportunity Point and check it out! I'll even give you a free drink voucher to our fine establishment. Go talk to Griz Finglebur and he'll get you sorted.", ["objectivesText"] = "Get a drink at Opportunity Point. Provided item:", ["rewardGold"] = 73700, ["rewardXP"] = 2480, ["rewardItems"] = { 224551 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224966, ["x"] = 0.517, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225067, ["x"] = 0.613, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.517, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
