[83031] = { ["id"] = 83031, ["name"] = "The Hardest Part", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "<Aethas sighs heavily, his voice tinged with sorrow.> Dalaran... once a symbol of unity and arcane mastery, now reduced to rubble and ash. Again. So much loss and so much pain. Friends and comrades gone in an instant, their voices silenced by Xal'atath. <He takes a deep breath, steeling himself against the overwhelming grief.> But now is the time for action--not grief. We must regroup with the remaining Kirin Tor. However, the right words do not come easily.", ["objectivesText"] = "Help Aethas Sunreaver send a message to the surviving mages of Kirin Tor in the Tranquil Strand. Progress: What does one say in times like these?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
