[83057] = { ["id"] = 83057, ["name"] = "Setting Boundaries", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["storyline"] = { 82340, 83057 }, ["description"] = "Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe. Whenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this. But hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.", ["objectivesText"] = "Kill the Ascended nerubian who is torturing Vi'azl. Progress: Nobody deserves this torturous treatment.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["mapID"] = 2216, ["db2PoiUiMapID"] = 2216, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5612, ["name"] = "Mr. Sunflower's Therapy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
