[83081] = { ["id"] = 83081, ["name"] = "Not Enough Minerals", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either. Peacekeeper Hektare will nae let me fight, but maybe she will let you. I'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal. Oh, but... Brinthe really needed those opals...", ["objectivesText"] = "Collect 6 Earthen Fire Opals from the Opalcreg in the Isle of Dorn . Progress: I'm sure I can make a poultice for this earthen. Oh, 'tis a shame I cannae get any opals.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83082] = { ["id"] = 83082, ["name"] = "The Opalfront", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I'm a city guard, not a soldier! But these people need our help! There are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us. That one was too small. But you look like a fighter. Help us!", ["objectivesText"] = "Kill nerubian forces at the Opalcreg in the Isle of Dorn . Progress: We will do what we can to help the miners escape.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225454, ["x"] = 0.448, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225454, ["x"] = 0.448, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83083] = { ["id"] = 83083, ["name"] = "A Place Forgotten", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "There is... a place behind Dornogal that I cannot go. And I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city. This, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will. The site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there. We will see.", ["objectivesText"] = "Meet with Speaker Brinthe and Dagran behind Dornogal in the Isle of Dorn .", ["rewardGold"] = 30300, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226841, ["x"] = 0.448, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83084] = { ["id"] = 83084, ["name"] = "The Old Orders", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Long ago, there were once plans to build a tunnel through the mountain into Dornogal. Before excavation could begin, the surrounding area was suddenly abandoned. There is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region. Every part of my cognitive matrix is pressing for me to leave. But we must persist. The device's signal indicates something lies within the nearby tower.", ["objectivesText"] = "Investigate the abandoned tower behind Dornogal. Progress: I'm not sure what's afflicting Brinthe, but it's clear she's in pain. I offered to escort her back to the city but she refused. I will stay with her an' make sure she does nae take a turn for the worse and try an' figure this device out more too.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 225887, 226015 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226841, ["x"] = 0.448, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83085] = { ["id"] = 83085, ["name"] = "DEPRECATED", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 83085 }, ["rewardGold"] = 134000, ["rewardXP"] = 200, ["rewardItems"] = { 94219, 128823, 128868, 209353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[83087] = { ["id"] = 83087, ["name"] = "The Old Guard", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Dornic... Galan... I've heard those names at the Proscenium! But who was speakin'? They were nae happy with Galan. All those earthen bodies... Repurposed... like reprogrammed? Tae protect what? Let's chase the other signal. Looks like it leads up ahead intae the hills. I'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.", ["objectivesText"] = "Follow the signal and witness a second memory Progress: I'll stay here with Brinthe. I dunnae want anythin' to happen tae her.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 225887, 228369 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83088] = { ["id"] = 83088, ["name"] = "Caustic Collectables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now... It's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. I think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him. That's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!", ["objectivesText"] = "Collect 6 Stinging Residue from Acidic Salvage in The Vatworks. Progress: Have you found enough residue from the oozing salvage? Make sure to get the really nasty stuff. You know, the stuff that sticks to you but also melts your skin?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226223 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83089] = { ["id"] = 83089, ["name"] = "Giving Goblins Goggles", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help. Our whole crew only listens to him! Which means no one's wearing proper protective equipment. Take these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.", ["objectivesText"] = "Talk to 5 Slimedivers in The Vatworks. Progress: Everyone's working along this river here. You can't miss them! Unless they haven't found the river. But that only happens half the time, so I'm sure it's fine.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83091] = { ["id"] = 83091, ["name"] = "Shield Your Eyes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "Causticaria ? Is he crazy? No one has ever been able to process that monster! We have to stop Enkle before he gets himself hurt! Causticaria lurks down this canal. Grab your goggles and follow me!", ["objectivesText"] = "Defeat Causticaria in The Vatworks. Progress: Has Causticaria gotten even bigger? The stench is burning my nose hairs from here!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232772, 232777, 232780, 232785 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228095, ["x"] = 0.386, ["y"] = 0.846667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83092] = { ["id"] = 83092, ["name"] = "An Igneous End", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "When the magma transport pipe failed, our workers rushed down to begin repairs. The elementals caught us unawares, rising up and attacking with great gouts of lava. Fortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood. Smash their stony prisons and free my workers!", ["objectivesText"] = "Free Entombed Earthen from their stone shells near Hallowfall Gate. Progress: Don't worry about hurting them, just get them free.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83096] = { ["id"] = 83096, ["name"] = "Welcome to Undermine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "There ya are! I'm Grimla. Welcome to Undermine . If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me. I've got a coupon you can use at the Incontinental Hotel. We'll start there. Let's take a ride in \" Gramps ,\" my hot rod! Hop in when you're ready.", ["objectivesText"] = "Go to the Incontinental Hotel with Grimla and learn more about Undermine . Progress: Did you hear anything good while you were gettin' yourself settled?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83097] = { ["id"] = 83097, ["name"] = "Cinder and Storm", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83097 }, ["description"] = "The wild creatures here have stunning properties. I wonder what might happen if I combine them? Be on the lookout for Bottled Storm and Burning Cinderbee Setae . I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.", ["objectivesText"] = "Gather 5 Bottled Storm and 5 Burning Cinderbee Setae , and deliver them to Ginnad in Dornogal . Progress: Who knows what could happen if we combine these materials!", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 218338, 218339, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83098] = { ["id"] = 83098, ["name"] = "Snap and Crackle", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83098 }, ["description"] = "Do you have a moment? I'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide , I'd be more than happy to compensate you.", ["objectivesText"] = "Gather 5 Honed Bone Shards and 2 Thunderous Hide , and deliver them to Ginnad in Dornogal . Progress: Together, these materials will make a real statement.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 212670, 218337, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83099] = { ["id"] = 83099, ["name"] = "Mergers and Acquisitions", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15103, ["mapID"] = 2248, ["storyline"] = { 83099 }, ["description"] = "When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" But now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits. Please help fix this, <name>.", ["objectivesText"] = "Defeat Goldie Baronbottom and help Wenbrandt reclaim the Cinderbrew Meadery . Progress: Thinking about those goblins in my meadery... Oh, it makes my head feel molten. And that makes me think of my cinderbrew!", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardItems"] = { 221054, 221060, 221198 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226409, ["x"] = 0.756, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226409, ["x"] = 0.756, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 15103 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83100] = { ["id"] = 83100, ["name"] = "Cracking the Shell", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83100 }, ["description"] = "Welcome! You wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin . If you find some, bring it to me. I'll see to it you get paid.", ["objectivesText"] = "Gather 20 Gloom Chitin and deliver it to Ginnad in Dornogal . Progress: Manage to lay your hands on some yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 212667, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83101] = { ["id"] = 83101, ["name"] = "Reaching for Resources", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2Objectives"] = { { ["text"] = "Climbing Gear acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 225504, ["orderIndex"] = 0 }, { ["text"] = "Find a handhold on the cliff", ["amount"] = 1, ["type"] = 0, ["objectID"] = 225506, ["orderIndex"] = 1 }, { ["text"] = "Ancient Celestite collected", ["amount"] = 7, ["type"] = 0, ["objectID"] = 225516, ["orderIndex"] = 2 } }, ["objectivesText"] = "Climbing Gear acquired Find a handhold on the cliff Ancient Celestite collected", ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 20, ["flags"] = 0 } }, ["questType"] = "world", ["flags"] = {  },
