[83102] = { ["id"] = 83102, ["name"] = "Bismuth is Business", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83102 }, ["description"] = "Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth . And we don't have nearly enough! Wherever you go, keep an eye out for Bismuth . Bring me as much as you can. Compensation is assured.", ["objectivesText"] = "Gather 20 Bismuth and deliver it to Tarib in Dornogal . Progress: Bismuth is business, and business is booming!", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210930, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83103] = { ["id"] = 83103, ["name"] = "Acquiring Aqirite", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 83103 }, ["description"] = "You there! Have you heard of Aqirite ? Valuable, versatile, very often surrounded by nerubians. I need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.", ["objectivesText"] = "Gather 10 Aqirite and deliver it to Tarib in Dornogal . Progress: Well, have you got it yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210933, 212308, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83104] = { ["id"] = 83104, ["name"] = "Identifying Ironclaw", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 83104 }, ["description"] = "I sent a team to mine some Ironclaw Ore , they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground! I'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.", ["objectivesText"] = "Gather 10 Ironclaw Ore and deliver it to Tarib in Dornogal . Progress: Trust me, you can't miss it.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210936, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83105] = { ["id"] = 83105, ["name"] = "Rush-order Requisition", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83105 }, ["description"] = "Good to see you, I've got work. The blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it. Looks like you'll need to track down Aqirite and Ironclaw Ore .", ["objectivesText"] = "Gather 5 Aqirite and 5 Ironclaw Ore , and deliver them to Tarib in Dornogal . Progress: Do you have them? The smiths have been chewing my ear off.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210933, 210936, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83106] = { ["id"] = 83106, ["name"] = "Null Pebble Excavation", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83106 }, ["description"] = "Ever seen a Null Stone ? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple. While you're at it, pick up any Bismuth you find. You can never have enough Bismuth .", ["objectivesText"] = "Gather 10 Bismuth and 2 Null Stone , and deliver them to Tarib in Dornogal . Progress: Any luck with those Null Stones ?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210930, 210939, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 }, ["questType"] = "profession", ["flags"] = {  },
},
[83108] = { ["id"] = 83108, ["name"] = "Daily Diagnostics", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83108 }, ["description"] = "It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine. Describing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines! Solution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.", ["objectivesText"] = "Take diagnostic readings of 4 machines within the Stonevault. Progress: There are numerous consoles that assist with the running of the great machines within the Stonevault. Work does not cease, even in the face of this madness. Please, get me those readings as soon as you can!", ["rewardGold"] = 1123600, ["rewardXP"] = 19840, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225533, ["x"] = 0.451, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225533, ["x"] = 0.451, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "dungeon", ["flags"] = {  },
},
[83109] = { ["id"] = 83109, ["name"] = "The Grimla Express", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. I'm not sure who runs it now, if anyone does.", ["objectivesText"] = "Head to Tailgate Park in Grimla's hot rod.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
