[83114] = { ["id"] = 83114, ["name"] = "Red Tape", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "First it was just Black Blood, now ethereals? I don't know how all this squares, but we need help if we wanna find out. Orweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.", ["objectivesText"] = "Find Alleria at Slam Central Station. Progress: We shoulda known. These guys see an outsider unescorted and try to pull a fast one. See if you can change their minds.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229236, ["x"] = 0.424667, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225570, ["x"] = 0.18, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[83115] = { ["id"] = 83115, ["name"] = "In the Mix", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him. Steamwheedle's headquarters is probably a good place to start lookin' for him. We'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.", ["objectivesText"] = "Speak to Marin Noggenfogger at the Vatworks. Progress: You see how many Darkfuse they've got here?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 133814, 204985, 205188, 237812 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225570, ["x"] = 0.18, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.18, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83116] = { ["id"] = 83116, ["name"] = "Potion Commotion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday. A day when I'm under no forms of duress or coercion whatsoever! N-None at all. <Cautiously, he glances at the Darkfuse guards, then whispers to you.> I'll tell you whatever I can if you get rid of them. <He nods subtly towards his alchemy station.>", ["objectivesText"] = "Collect some Semi-Deluxe Noggenfogger Elixirs , then use them to distract 8 Stationed Labguards. Progress: I'll keep an eye on Noggenfogger. You get it done.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226157 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225624, ["x"] = 0.275, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83117] = { ["id"] = 83117, ["name"] = "Chasing a Lead", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends. We knew they was working with Gallywix, we just didn't know how deep they were in with him. Let's go check out those kaja'mite supply lines. No time to lose.", ["objectivesText"] = "Meet Gazlowe outside the Heaps.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225635, ["x"] = 0.46, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83118] = { ["id"] = 83118, ["name"] = "Check the Schedule", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that. Up ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up. Grab as many as you can find. We'll check out Venture's headquarters in the meantime.", ["objectivesText"] = "Gather 3 Employee Schedules . Progress: They should have schedules posted all over the place. Hopefully this isn't a wild flamingo chase.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226380 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225635, ["x"] = 0.46, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225639, ["x"] = 0.532, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83119] = { ["id"] = 83119, ["name"] = "It's Worth a Shot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet. Maybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work. Venture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you. See if you can get 'em to quit. If they start a fight, do what you gotta do.", ["objectivesText"] = "Attempt to convince 10 Underpaid Workers to quit Venture Co.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226358 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225637, ["x"] = 0.46, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225638, ["x"] = 0.535, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83120] = { ["id"] = 83120, ["name"] = "Stealing the Keys", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here. Lead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. Should be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?", ["objectivesText"] = "Slay Lead Foreman Krome . Progress: You clear the way for Renzik to get the punch card yet?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 226391, 232355, 232400, 232402, 232404 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225638, ["x"] = 0.535, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225639, ["x"] = 0.532, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83121] = { ["id"] = 83121, ["name"] = "Asset Management", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward. We need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.", ["objectivesText"] = "Slay 6 Venture Supervisors in the Lucky Break Mines. Progress: It won't stop the kaja'mite supply for good, but at least it'll slow them down.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228132, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228132, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83122] = { ["id"] = 83122, ["name"] = "Crashing the Market", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation. Blow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.", ["objectivesText"] = "Destroy 5 Kaja'mite Stockpiles in the Lucky Break Mines. Progress: We need to keep that kaja'mite out of circulation.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83123] = { ["id"] = 83123, ["name"] = "A Miner Mistake", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "<On the corpse of the Venture Co. employee, you find a crumpled piece of paper stuffed into an envelope. It appears to be a paystub from a kaja'mite depot in the Venture Co. area of Undermine . Below the full address of the employer, there is a header stamped in red ink.> GALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT <A note from Gallywix is poorly taped to the back of the paystub.>", ["objectivesText"] = "Read the Crumpled Paystub , then bring it back to Gazlowe. Progress: What do you got there?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232464 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["startItems"] = { 226854 }, ["questType"] = "standard", ["flags"] = {  },
},
[83124] = { ["id"] = 83124, ["name"] = "B.I.R.D. Watching", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does. I don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers. You wanna do us the honors, <name>? I'll talk you through it.", ["objectivesText"] = "Control the Hotwired B.I.R.D. to spy on Darkfuse activities on the Kaja'Coast. Progress: They'll never suspect nothin'.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83125] = { ["id"] = 83125, ["name"] = "Price Hike", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse. These stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.", ["objectivesText"] = "Slay Overseer Dritz , then meet up with Gazlowe in Undermine .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232883 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225667, ["x"] = 0.292, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862, 2346 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83126] = { ["id"] = 83126, ["name"] = "Ethereal Invasion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming. Now they're searching every building and killing anyone who stands in their way. I don't know what they're looking for, but we can't allow them to continue this slaughter. Let's teach them a lesson.", ["objectivesText"] = "Kill 12 ethereals in the Vatworks. Progress: We cannot let this chaos continue.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.294667, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83127] = { ["id"] = 83127, ["name"] = "Racing the Clock", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "We were out of time before, but now we're REALLY out of time. The ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart. C'mon!", ["objectivesText"] = "Meet Gazlowe outside Gallywix's secret warehouse in the Heaps.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229261, ["x"] = 0.27, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225719, ["x"] = 0.555, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83128] = { ["id"] = 83128, ["name"] = "Get Our People Out", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe. They left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.", ["objectivesText"] = "Save any hostages Gallywix is keeping in the warehouse and slay 10 Ethereal Heartseekers .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232354, 232401, 232403, 232405 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225719, ["x"] = 0.555, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225730, ["x"] = 0.585, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
