[83129] = { ["id"] = 83129, ["name"] = "Nowhere Left to Hide", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one. Gallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.", ["objectivesText"] = "Destroy the Makeshift Barricade, then follow Gazlowe into the Hoardroom to confront Gallywix.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225730, ["x"] = 0.585, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 234048, ["x"] = 0.615, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83130] = { ["id"] = 83130, ["name"] = "Sour Victory", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "That's it. It's over. We're done. Gallywix lost, but the ethereals got the Dark Heart. Alleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.", ["objectivesText"] = "Meet Gazlowe at the Scrapshop in Bilgewater Flats.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234048, ["x"] = 0.615, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225756, ["x"] = 0.388, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83137] = { ["id"] = 83137, ["name"] = "When Opportunity Explodes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "There ya are, <name>! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps . There were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.", ["objectivesText"] = "Investigate the blasted hole in Opportunity Point.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 230936 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 225571, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227531, ["x"] = 0.63, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83138] = { ["id"] = 83138, ["name"] = "End of the Day", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands. Which means we can leave. Nothin' left for us to do here. Finish up whatever business you've got in Undermine . I need to get out of this damn place.", ["objectivesText"] = "Speak to Renzik.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225756, ["x"] = 0.388, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225757, ["x"] = 0.398, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83139] = { ["id"] = 83139, ["name"] = "Mixed Messages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.", ["objectivesText"] = "Pay the toll at the tollbooth, then gather information from the northern goblin camp. Progress: See what these goblins know about the area!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227531, ["x"] = 0.63, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83140] = { ["id"] = 83140, ["name"] = "Hostile Work Environment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out. I'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.", ["objectivesText"] = "Kill Darkfuse to keep the heat off Gazlowe and Renzik. Progress: Give us some time!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 }, { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83141] = { ["id"] = 83141, ["name"] = "Miner Investigations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood. We must get a closer look. Together we will gain insight into their operation.", ["objectivesText"] = "Examine suspicious canisters and crates with Orwenya.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232741, 232747, 232752, 232756 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227691, ["x"] = 0.644, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227688, ["x"] = 0.719333, ["y"] = 0.783333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83142] = { ["id"] = 83142, ["name"] = "Order of Magnitude", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "<This document requires anyone with information about who opened the western wall to bring the information to their supervisor. It details the reward: a promotion to working inside Undermine. It also includes a promise of the favor and \"appreciation\" of Gallywix. Gazlowe will want to know about this.>", ["objectivesText"] = "Give the Bounty from Gallywix to Gazlowe. Progress: What'd you find?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224772 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 }, { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["startItems"] = { 224772 }, ["questType"] = "standard", ["flags"] = {  },
},
[83143] = { ["id"] = 83143, ["name"] = "Good Honest Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "You're new here, right? I can tell by your questions. But don't worry, Zirdo 's your best pal! I'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!", ["objectivesText"] = "Follow Zirdo on his \"tour.\" Progress: I lack words.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228017, ["x"] = 0.725, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225596, ["x"] = 0.718, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83144] = { ["id"] = 83144, ["name"] = "Bloodletting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "The land aches underfoot. These pipes carry Black Blood north in a massive volume! I've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet. I'll go after the structures. Point out weak spots as you find them and I will focus our assault!", ["objectivesText"] = "Kill Black Blood creatures and signal Orweyna to attack weak points in the pipeline. Progress: The horrors these goblins have brought forth are truly a blight on this land.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232417, 232418 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225596, ["x"] = 0.718, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228034, ["x"] = 0.695, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83145] = { ["id"] = 83145, ["name"] = "Paranoia Prevention", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. Let's start with any Bilgewater goblins we can find.", ["objectivesText"] = "Investigate Gutterville's spy problem. Progress: This seems like it's more about keeping people quiet than actually learning anything.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 232491, ["x"] = 0.722, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.719667, ["y"] = 0.816333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83146] = { ["id"] = 83146, ["name"] = "Pamsy's Prized Pump", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope. You show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station. So, my crew and the pumps? They're all at the same station. But we should hurry.", ["objectivesText"] = "Go to the pump station and meet Pamsy .", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 232491, ["x"] = 0.722, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228214, ["x"] = 0.705, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83147] = { ["id"] = 83147, ["name"] = "Bloody Business", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers. Kill the manifestations of this rot, before they grow stronger.", ["objectivesText"] = "Kill blood horrors for Orweyna . Progress: I cannot ignore this blight on the land.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228894, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228894, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83148] = { ["id"] = 83148, ["name"] = "X-Treme Chill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station? Stay with me! Pamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? We put the whole operation on ice, and it'd take ages to fix!", ["objectivesText"] = "Kill Chillgut Slimes to collect Chillburst Canisters . Progress: Get enough to freeze this station solid!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224846 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83149] = { ["id"] = 83149, ["name"] = "Avenge Them", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him. Gozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.", ["objectivesText"] = "Kill the Darkfuse that killed Pamsy's engineers. Progress: These engineers deserved better.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 231089 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.703333, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83150] = { ["id"] = 83150, ["name"] = "Expanding the Plan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up. Since you gathered all the canisters, I think you should get the honor of freezing the pipe solid. Pamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!", ["objectivesText"] = "Ride the rocketboard and shoot the pipeline with ice. Progress: Hop onto the rocketboard and shoot away!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232425, 232435, 232441, 232442, 232444, 232445, 232446, 232447, 235660, 238249, 238250 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228887, ["x"] = 0.703, ["y"] = 0.891 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83151] = { ["id"] = 83151, ["name"] = "Down Undermine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "We've done what we could here. It's time to get a look at Undermine. Pamsy 's got a contact, a Venture goblin named Grimla. We can start there when we arrive. Let's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.", ["objectivesText"] = "Talk with Gazlowe, then go to Undermine using the rocket drill.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225661, ["x"] = 0.32, ["y"] = 0.521 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.703333, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2214, 2346 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83152] = { ["id"] = 83152, ["name"] = "Magmanagement", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed. We can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps. If you are capable, clear them out so we can get that magma flowing again.", ["objectivesText"] = "Kill Risen Magma and Slag Bubbles near Hallowfall Gate. Progress: Is it done?", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83153] = { ["id"] = 83153, ["name"] = "Sampling Steam", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause. In order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground. Fresh samples. Very fresh. You're going to have to stand in them as they erupt in order to gather what I need.", ["objectivesText"] = "Stand in gas vents near Hallowfall Gate as they erupt to gather samples. Progress: Do you have the samples?", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 219455, 219456, 219457, 219458, 219459, 219460, 219461, 219462, 219463, 219464, 219465, 219466, 219467 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225583, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225583, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83154] = { ["id"] = 83154, ["name"] = "Knicknack's Knickknacks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83154 }, ["description"] = "Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind! Here, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!", ["objectivesText"] = "Retrieve Knicknack 's treasures from Darkflame Cleft. Progress: Treasures all very important. Very valuable. You no take for you! Bring back to me!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224773, 224774, 224775, 224778 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225555, ["x"] = 0.450667, ["y"] = 0.302667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225555, ["x"] = 0.450667, ["y"] = 0.302667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.450667, ["y"] = 0.302667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "dungeon", ["flags"] = {  },
},
[83155] = { ["id"] = 83155, ["name"] = "Tired of Tripping", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself. See these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes! Listen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?", ["objectivesText"] = "\"Remove\" 15 Hardhead moles. Progress: You deal with 'em yet? I'm not hauling another shredder out of the mud.", ["rewardGold"] = 289300, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83159] = { ["id"] = 83159, ["name"] = "A Little Off the Top", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages. Now if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.", ["objectivesText"] = "Slay Alhainr and collect its skull. Progress: What did you do?!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 224779 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 226336, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83160] = { ["id"] = 83160, ["name"] = "Cinderbrew Reserve", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny. The inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you. I left it behind the desk in my old office, down below. Just don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.", ["objectivesText"] = "Bring the Cinderbrew Reserve to Cogwin at the Hallowfall Gate. Progress: Do you have it?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 253172 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225616, ["x"] = 0.4, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225616, ["x"] = 0.4, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83162] = { ["id"] = 83162, ["name"] = "Put it Back, Put it Back!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull. First, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better. Oh man, they're gonna get ectoplasm in the hot pools!", ["objectivesText"] = "Stomp slimes and take Alhainr's Skull away from town. Progress: Hurry up, before this whole place is wrecked!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 226336, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83163] = { ["id"] = 83163, ["name"] = "Split Venture", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "We're headed to my home turf next, Venturewood. It's next to the Heaps. The Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step. But there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right? Hop in the hot rod, I'll show you what I mean.", ["objectivesText"] = "Ride the hot rod to the Venturewood and assist friendly Venture Co. goblins. Progress: Seems like there's no respect for the little guys.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232448, 232449, 232450, 232451, 232452, 232453, 235661, 238251 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229247, ["x"] = 0.435, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83164] = { ["id"] = 83164, ["name"] = "City of Threads: Splice the Splicer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83164 }, ["description"] = "\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day. If we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good. Izo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.", ["objectivesText"] = "Enter the City of Threads and defeat Izo the Grand Splicer. Progress: Have you dealt with the Transformatory, <name>?", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 221181, 221189 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83165] = { ["id"] = 83165, ["name"] = "Badly Behaved Bot", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83165 }, ["description"] = "Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! I'm grounded while she floats there quite cheerfully. Can you believe it? Listen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.", ["objectivesText"] = "Speak with Kagfritha in Shadowvein Point.", ["rewardGold"] = 147500, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223759, ["x"] = 0.582, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83166] = { ["id"] = 83166, ["name"] = "Ara-Kara, the City of Echoes: Harvest's End", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83166 }, ["description"] = "You've seen it yourself, haven't you? The \"Black Blood,\" as we call it. We will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. Seek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.", ["objectivesText"] = "Enter the Ara-Kara, The City of Echoes and defeat Ki'katal the Harvester. Progress: Have you been to Ara-Kara yet?", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 219314, 221154 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83167] = { ["id"] = 83167, ["name"] = "Eyes from Above", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it? The last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. Go take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.", ["objectivesText"] = "Kill 8 Spy-Copters to steal their footage. Progress: There is nothing better than breaking bad machines for a good cause.", ["rewardGold"] = 289300, ["rewardXP"] = 11765, ["rewardItems"] = { 232902 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225618, ["x"] = 0.436, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225618, ["x"] = 0.436, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83168] = { ["id"] = 83168, ["name"] = "A Trail of Black Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "While you have been getting familiar with the state of Undermine , I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions. But this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.", ["objectivesText"] = "Investigate Hovel Hill for Black Blood shipments. Progress: Tracking the shipments should show us who's using 'em. Check out any labels or letters layin' around! I think I stunned all of the defenses, they'll leave us be.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232944 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225659, ["x"] = 0.356, ["y"] = 0.5384 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229233, ["x"] = 0.33, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.5384 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83169] = { ["id"] = 83169, ["name"] = "Long Way from Booty Bay", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["series"] = { 83170 }, ["description"] = "There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers. So if we want to find out where, we go right to the top-- Baron Revilgaz . Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit. The ethereal thing will have to wait.", ["objectivesText"] = "Locate Baron Revilgaz at Hovel Hill. Progress: I have a bad feeling about all this, but let's talk to Revilgaz.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229233, ["x"] = 0.33, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83170] = { ["id"] = 83170, ["name"] = "Not Again!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["series"] = { 83169 }, ["description"] = "The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied. If an outsider showed up and started making trouble, that'd be a different story.", ["objectivesText"] = "Make trouble with the Darkfuse in Hovel Hill for Revilgaz. Progress: Fairness is a loose concept in Undermine , but the Darkfuse push it too far.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2772, 24118, 24119, 24120, 25631, 25632, 25633, 29333, 29334, 29335, 29336, 32569, 34125, 37829, 44785, 44788, 46723, 46800, 46824, 52593, 52617, 52640, 52644, 52673, 53563, 53564, 53565, 62210, 62211, 62212, 62213, 65678, 65699, 65717, 116404, 131283, 131655, 131695, 140255, 142054, 156996, 181501, 181502, 181503, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181672, 181675, 181676, 181677, 181679, 181680, 181689, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 198608, 211279, 237812, 242715 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83171] = { ["id"] = 83171, ["name"] = "Eye Sores for Sore Eyes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. But the Darkfuse hate you anyway. If you torched all the posters, I would owe you one.", ["objectivesText"] = "Burn 8 Darkfuse Recruitment Posters on and around Revilgaz's house. Progress: I'm sick of seeing those recruitment posters. Burn them.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232740, 232748, 232750, 232761 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83172] = { ["id"] = 83172, ["name"] = "Black Blood Baton Pass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps. We're gonna check it out and find out where the Black Blood goes from there. He says it's guarded, so look for us out near the edge.", ["objectivesText"] = "Meet with Renzik and Gazlowe at the next Black Blood depot in the Heaps.", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229242, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83173] = { ["id"] = 83173, ["name"] = "Clearing Out the Depot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it. We can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.", ["objectivesText"] = "Clear the depot area in the Heaps. Progress: Every guards or shipment lost costs them time and money. And Gallywix hates losing both.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83174] = { ["id"] = 83174, ["name"] = "Our Good Pal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Our old pal Zirdo 's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments. We owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.", ["objectivesText"] = "Kill Zirdo .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232393, 232395, 232397, 232399 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83175] = { ["id"] = 83175, ["name"] = "Another Piece of the Puzzle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "<The ledger has longwinded ramblings about Zirdo's achievements, but also contains various deliveries of Black Blood across Undermine . Multiple entries in the ledger stick out as odd: - One thousand units for Secret Project, Deliver to Secret Project Site. - Twenty units for Developmental Ammunition, Deliver via Courier. Transfers approved by Noggenfogger of Steamwheedle.>", ["objectivesText"] = "Discuss the contents of Zirdo's Ledger with Gazlowe in the Heaps. Progress: Noggenfogger knows better than to get mixed up with Gallywix.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224797 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["startItems"] = { 224797 }, ["questType"] = "standard", ["flags"] = {  },
},
[83176] = { ["id"] = 83176, ["name"] = "Just a Hunch", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. Something's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.", ["objectivesText"] = "Check in with Renzik about Gazlowe, and then meet Gazlowe outside of the Heaps.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245310 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229236, ["x"] = 0.424667, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83177] = { ["id"] = 83177, ["name"] = "Socialized Medicine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83177 }, ["description"] = "It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady. Take this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.", ["objectivesText"] = "Dose Downtrodden Residents with Nizrek's potion . Progress: Have you aided the residents of the Burrows?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224799 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83178] = { ["id"] = 83178, ["name"] = "Rules and Consequences", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83178 }, ["description"] = "I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes. Be on guard. A veiled threat looms.", ["objectivesText"] = "Defeat the Assassin. Progress: Have you handled the interloper?", ["rewardGold"] = 295000, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83181] = { ["id"] = 83181, ["name"] = "Best Friends, Same Ends", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian. The shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships. The nerubians know this and likely assigned one of their best to protect her. If we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.", ["objectivesText"] = "Eliminate Shipwright Isaebela and Shadowspinner Azarak at Silkwood Grotto. Progress: Is it done <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 223424, 223441, 223456, 223464, 228428 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 }, { ["mapID"] = 2248, ["npcID"] = 222366, ["x"] = 0.654, ["y"] = 0.204 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 11, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83182] = { ["id"] = 83182, ["name"] = "A Bloody Inheritance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "When the kobyss killed my parents, they stole some of their most cherished things. Not me, obviously. Cherished items. While we are murdering kobyss, let's find them.", ["objectivesText"] = "Retrieve Alyza's parents' items in the Hungering Pool in Hallowfall . Progress: Stupid kobyss. I hate them.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 215446, 216524, 216525, 216526 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83194] = { ["id"] = 83194, ["name"] = "Under Fire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "I'm only standing here because of Renzik. He didn't even think about it--he just...", ["objectivesText"] = "Be there for Monte Gazlowe . Progress: We're not finished here.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 211279 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225757, ["x"] = 0.398, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225523, ["x"] = 0.398, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83195] = { ["id"] = 83195, ["name"] = "Rally the People", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time. Let's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.", ["objectivesText"] = "Pick a headline with Dirk Greasedealer and then spread the word of revolution in Tailgate Park. Progress: Now is the time to rise up. Tell 'em, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228196 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226660, ["x"] = 0.485, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225866, ["x"] = 0.51, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83196] = { ["id"] = 83196, ["name"] = "Disperse!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again. You see someone hurting a Bilgewater goblin, return the favor.", ["objectivesText"] = "Kill 20 Darkfuse at Tailgate Park. Progress: The people have to know the streets are safe. It's on us to make them so.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228196 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226660, ["x"] = 0.485, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225866, ["x"] = 0.51, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83197] = { ["id"] = 83197, ["name"] = "Who Owns the Streets?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands. I can't worry if she's got another bullet. We gotta go after her. You with me, <name>?", ["objectivesText"] = "Confront Renzik's killer, Nikki the Fixer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234551, ["x"] = 0.508667, ["y"] = 0.349333 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225868, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.508667, ["y"] = 0.349333 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83198] = { ["id"] = 83198, ["name"] = "Backyard Navy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis! It's time we introduce them to a little high seas firepower. Take this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?", ["objectivesText"] = "Destroy the Darkfuse Joyriders in the Blackwater Marina. Progress: Did my Captain send you? He knew I'd need help...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228975 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225868, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83199] = { ["id"] = 83199, ["name"] = "Been Savin' This One", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Listen <name>, Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards! Problem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?", ["objectivesText"] = "Collect Limes from the Resort Staff at the Blackwater Marina. Progress: Ngh. Did they get me with that Black Blood?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226203, 226217 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225867, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83200] = { ["id"] = 83200, ["name"] = "A Vast, Ye Swabs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Urgh. I've been locked up for so long. In my anger, I got reckless. Whatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.", ["objectivesText"] = "Brew the Noggenfogger Deluxe with Lime and feed it to Fleet Master Seahorn .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226372 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83201] = { ["id"] = 83201, ["name"] = "Expedited Delivery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there. Those flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.", ["objectivesText"] = "Hitch a ride on a Malfunctioning Cratemover.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225871, ["x"] = 0.452, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83202] = { ["id"] = 83202, ["name"] = "Punching Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix. Some of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. Just be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.", ["objectivesText"] = "Defeat the three Venture Co. loyalist lieutenants.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 194368 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225871, ["x"] = 0.452, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225874, ["x"] = 0.485, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83203] = { ["id"] = 83203, ["name"] = "Weapons Hot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before. All containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.", ["objectivesText"] = "Destroy Black Blood crates and weapons in the Heaps.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225873, ["x"] = 0.452, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 234728, ["x"] = 0.485, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83204] = { ["id"] = 83204, ["name"] = "The Thingamajig", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. No time for pre-production. We gotta build. Remember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.", ["objectivesText"] = "Recover parts for Pamsy in the Heaps. Progress: You got time to yap, then you've got time to smash!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228792, 233512, 233513, 234489 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233390, ["x"] = 0.516889, ["y"] = 0.708222 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 233390, ["x"] = 0.516889, ["y"] = 0.708222 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.516889, ["y"] = 0.708222 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83205] = { ["id"] = 83205, ["name"] = "Production Halted", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "< Orweyna rubs her palms with dirt, then cracks her knuckles.> Now, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth. Join me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.", ["objectivesText"] = "Destroy the Black Blood stockpiles in the Heaps. Progress: I would not have guessed Orweyna was that much of a natural at dodging rockets.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234728, ["x"] = 0.485, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225876, ["x"] = 0.565, ["y"] = 0.6755 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83206] = { ["id"] = 83206, ["name"] = "We Own the Streets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. They're fightin' for Undermine . We need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.", ["objectivesText"] = "Rally the people of Undermine against Gallywix.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232356, 232406, 232407, 232408, 232523 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 230268, ["x"] = 0.564, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225878, ["x"] = 0.564667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83207] = { ["id"] = 83207, ["name"] = "My Top Gal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up. He thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time. <Gazlowe looks over the thingamajig he's just finished jury-rigging.> Watch this.", ["objectivesText"] = "Defeat Nikki the Fixer .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 235516 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225878, ["x"] = 0.564667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 235238, ["x"] = 0.57, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83229] = { ["id"] = 83229, ["name"] = "Special Assignment: When the Deeps Stir", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["db2Objectives"] = { { ["text"] = "Awakened Elementals defeated", ["amount"] = 4, ["type"] = 0, ["objectID"] = 225898, ["orderIndex"] = 0 } }, ["objectivesText"] = "Awakened Elementals defeated", ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3549 }, ["questType"] = "world", ["flags"] = {  },
},
[83240] = { ["id"] = 83240, ["name"] = "The Theater Troupe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14776, ["mapID"] = 2248, ["storyline"] = { 83240 }, ["description"] = "Since you're an honorary member of the theater troupe, <name>, what do you think about playing a part in our plays? No big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are. Are you available, say, once a week?", ["objectivesText"] = "Participate in the Theater Troupe event. Progress: The show must go on! And on. And on. We've been renewed for a permanent showing. For the earthen that means... well, it means we're all employed for a long time.", ["rewardItems"] = { 217011, 217012, 217013, 226263, 235151, 239128, 250763 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard",
},
[83247] = { ["id"] = 83247, ["name"] = "Suspicious Minds", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion. However, my better half would urge me to be more welcoming... and I want to try to be better. For her. Some of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.", ["objectivesText"] = "Find 9 Salamanther Hearts in Rumshackle. Progress: Others may be satisfied with just your word that you have done what I'd ask. I am not.", ["rewardGold"] = 297900, ["rewardXP"] = 10190, ["rewardItems"] = { 225179, 228435, 228436, 228437, 228438 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.653, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83271] = { ["id"] = 83271, ["name"] = "There's Always Another Secret", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal. Dagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive. An' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.", ["objectivesText"] = "Check in on Dagran Thaurissan II and Brinthe in the Archive in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2367, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83274] = { ["id"] = 83274, ["name"] = "An Original Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 83274 }, ["description"] = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: You're not givin' up, are ya?", ["rewardItems"] = { 212446, 220305, 225582, 226194, 233014 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard",
},
[83275] = { ["id"] = 83275, ["name"] = "Gear Enchanting", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83275 }, ["description"] = "Hello, outlander! I've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid. I can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.", ["objectivesText"] = "Complete the item enchantment tutorial by enchanting any ring using the enchantment given from Ellerdin , Enchant Ring - Glimmering Haste . Progress: The enchantment and ring I gave you are fitting for each other.", ["rewardGold"] = 154900, ["rewardXP"] = 4625, ["rewardItems"] = { 223657, 223663, 223666, 223669 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226287, ["x"] = 0.518, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226287, ["x"] = 0.518, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83276] = { ["id"] = 83276, ["name"] = "Saving Private Spindle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2255, ["storyline"] = { 83276 }, ["description"] = "One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment. Meesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle 's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them. Find Spindle . Make sure she is well.", ["objectivesText"] = "Find Spindle in the High Hollows. Progress: <All of Spindle 's eyes widen with both relief and embarrassment at the sight of you.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 226019, ["x"] = 0.878, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83277] = { ["id"] = 83277, ["name"] = "Personal Pilfering", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83277 }, ["description"] = "<The little spider looks around the room, each of her eyes narrowing. You recall The Weaver telling you to retrieve evidence to blackmail Meesk. But it appears as though ransacking Meesk's storage is now personal for Spindle .>", ["objectivesText"] = "Find 3 pieces of Incriminating Evidence in Meesk's Retreat. Progress: Well, my morsel? Did you find anything of note?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225344 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 226019, ["x"] = 0.878, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.878, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83278] = { ["id"] = 83278, ["name"] = "Hillhelm Family: A Lost Shoe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83278 }, ["description"] = "<A shoe in the style worn by members of the Hillhelm family. Maybe Aliya Hillhelm can shed some light on it.>", ["objectivesText"] = "Deliver The Lost Shoe to Aliya Hillhelm at Hillhelm Stead. Provided item:", ["rewardGold"] = 289300, ["rewardXP"] = 11765, ["rewardItems"] = { 225336 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 3718 }, ["startItems"] = { 225336 }, ["questType"] = "standard", ["flags"] = {  },
},
[83279] = { ["id"] = 83279, ["name"] = "Prove One's Mettle", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "Yes, you helped us out with these pests, but it is not enough. I need more. One of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?", ["objectivesText"] = "Defeat the Coalesced Iniquity in Rumshackle. Progress: If you are truly here to help the Arathi, you would have no problem with what I am asking of you.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.653, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 2, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83282] = { ["id"] = 83282, ["name"] = "Hillhelm Family: A Clutch of Eggs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83282 }, ["description"] = "<A clutch of chicken eggs , they must have come from a nearby farm. Maybe Aliya Hillhelm can shed some light on it.>", ["objectivesText"] = "Deliver The Clutch of Eggs to Aliya Hillhelm at Hillhelm Stead. Provided item:", ["rewardGold"] = 289300, ["rewardXP"] = 11765, ["rewardItems"] = { 225339 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 3718 }, ["startItems"] = { 225339 }, ["questType"] = "standard", ["flags"] = {  },
},
[83283] = { ["id"] = 83283, ["name"] = "For Morale", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end? I've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?", ["objectivesText"] = "Retrieve 6 barrels of Imperial Brut from Rumshackle. Progress: Imagine twenty Arathi huddling under the safety of a single light for ten years. Imagine they're waiting for a chance to let their hair down with a good drink with their comrades. Now imagine how they'll feel once they hear the wine is gone. ...please hurry.", ["rewardGold"] = 297900, ["rewardXP"] = 10190, ["rewardItems"] = { 225340 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83285] = { ["id"] = 83285, ["name"] = "The Ancient Scroll", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83285 }, ["description"] = "A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223885, ["x"] = 0.626, ["y"] = 0.504 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 225348 }, ["questType"] = "standard",
},
[83286] = { ["id"] = 83286, ["name"] = "What's Hidden Beneath Dornogal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence. Dagran's query may have to wait. I have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal. Perhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.", ["objectivesText"] = "Restart the central mainframe in the Vault of Memory in Dornogal. Progress: Take your time. It has been here for millennia. I am sure it is not going anywhere.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2367, ["db2PoiUiMapID"] = 2367, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83306] = { ["id"] = 83306, ["name"] = "Where the Wild Things Camp", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83306 }, ["description"] = "Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there. Could you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.", ["objectivesText"] = "Meet Orweyna at Wildcamp Ul'ar.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83315] = { ["id"] = 83315, ["name"] = "Preparing for the Unknown", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "This will be a long process. Longer, I fear, than Dagran can stay here in the Isles. But perhaps... There are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly. Only time will tell. You have helped us enough, <name>. Go back to Moira and tell her what we have discovered.", ["objectivesText"] = "Return to Moira Thaurissan in Dornogal.", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83321] = { ["id"] = 83321, ["name"] = "Strange Bats", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83321 }, ["description"] = "Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. The spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose. You have one of those faces that make people hesitate before punching. Head out there and take a look.", ["objectivesText"] = "Investigate a possible druid sighting.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83322] = { ["id"] = 83322, ["name"] = "The Dawnbreaker: The Christening", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83322 }, ["description"] = "The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands. As someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.", ["objectivesText"] = "Help the christening ceremony in the Dawnbreaker dungeon succeed. Progress: The Dawnbreaker will cause problems for the nerubians once she is active. It is very important everything goes off without a hitch.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardItems"] = { 226141 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83324] = { ["id"] = 83324, ["name"] = "A Silken Thread", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83324 }, ["description"] = "You looking for work or something? <Linny squints her eyes at you.> If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward. The new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace. Meet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.", ["objectivesText"] = "Meet with Sum'latha at the Silken Ward.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221948, ["x"] = 0.514, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83325] = { ["id"] = 83325, ["name"] = "Bountiful Beetles", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign. However... I have my reservations about the two he left in charge. Kish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding. Seek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.", ["objectivesText"] = "Speak with Kish'nal in Rak-Ush.", ["rewardGold"] = 28900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224729, ["x"] = 0.558, ["y"] = 0.422 }, { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83326] = { ["id"] = 83326, ["name"] = "The Final Candle", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "You are good candle-taker. We have one last job for you, your waxiness! One more job! Then no more sticky business. BIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. <There's an awkward pause.> Nothing rhymes with kobolds, hm. Get us big candle!", ["objectivesText"] = "Steal the final candle for the suspicious vent in the Gundargaz Inn. Progress: Candles! Candles! Candles!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220156 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["mapID"] = 2214, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83328] = { ["id"] = 83328, ["name"] = "The Analysis Interface", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.", ["objectivesText"] = "Complete the Analyzing Sequence in the Analysis Interface.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2322, ["db2PoiUiMapID"] = 2322, ["db2PoiMapID"] = 2739, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83331] = { ["id"] = 83331, ["name"] = "Preserve and Pretend", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83331 }, ["description"] = "Chive dig for history. You help find? Got history detector from goblin. Said it finds history underground! You use. Chive dig.", ["objectivesText"] = "Help find places to dig for \"historical objects\" by using the goblin \"history detector\".", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 226255, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 226255, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83333] = { ["id"] = 83333, ["name"] = "Gearing Up for Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82946, 83333 }, ["description"] = "Greetings friend, The machine is once again in disrepair and requires restoration. I am in need of your expertise to successfully perform maintenance. A reward shall be provided for well-executed assistance.", ["objectivesText"] = "Complete 20 waves of the Awakening the Machine event. Progress: Status report?", ["rewardGold"] = 619600, ["rewardItems"] = { 225767, 226273, 239121, 250765 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 }, { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 }, { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5711, ["name"] = "Ringing Deeps - Weekly Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard",
},
[83334] = { ["id"] = 83334, ["name"] = "The Wealth of an Empire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83334 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
