[83335] = { ["id"] = 83335, ["name"] = "Wanted: The Boroughbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "<This note is nailed into the post with a small chitinous plate.> For crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar. A sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.", ["objectivesText"] = "Slay Boroughbreaker Stik'kar in the Isle of Dorn .", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 227916, 227917, 227918, 227919 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226761, ["x"] = 0.54, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83336] = { ["id"] = 83336, ["name"] = "The Earthwound", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "<Etterca grumbles as you approach.> Ground is shaking. 'Tis no good. Troubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here. Only then the earth can begin to heal. Only then can Etterca do her duties.", ["objectivesText"] = "Acquire the Broken Stoneheart from Roth the Earthwound in the Isle of Dorn . Progress: <Etterca grumbles and stares at you blankly.>", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 225674 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226750, ["x"] = 0.555, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226750, ["x"] = 0.555, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83337] = { ["id"] = 83337, ["name"] = "Stormscarred", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. Stormscar , whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. I came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar 's reign in our pastures?", ["objectivesText"] = "Slay Stormscar in the pastures near Rambleshire in the Isle of Dorn . Progress: Have you done it yet?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226792, ["x"] = 0.584, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226792, ["x"] = 0.584, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83338] = { ["id"] = 83338, ["name"] = "The Mage Slayer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom. A prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge. Seek out this fiend and put an end to its existence.", ["objectivesText"] = "Slay Mage Slayer Phytethil near Rambleshire in the Isle of Dorn .", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83339] = { ["id"] = 83339, ["name"] = "The Spirebreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran... Was equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the monster that lurks below.", ["objectivesText"] = "Slay Anub'esska on the road near Rambleshire in the Isle of Dorn . Progress: Are they safe now?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83347] = { ["id"] = 83347, ["name"] = "Emissary of War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83347 }, ["description"] = "Are you up for a real challenge? Delve into the darkest places and soar to the highest heights while upping the challenge. By pressing ourselves to the extreme we can truly test our skills.", ["objectivesText"] = "Complete 4 dungeons on Mythic difficulty. Progress: By pressing ourselves to the extreme we can truly test our skills.", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 226194, 234731, 247820, 250117 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon",
},
[83357] = { ["id"] = 83357, ["name"] = "The Very Best", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83357 }, ["description"] = "The bond between us and our machines is much like the one others have with their pets. You must be in harmony with your companions in order to accomplish great things! Show me that you can work as a team with your pets. Defeat your enemies with their assistance!", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets. Progress: You must be in harmony with your companions in order to accomplish great things!", ["rewardItems"] = { 122457 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard",
},
[83358] = { ["id"] = 83358, ["name"] = "The Arena Calls", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83358 }, ["description"] = "Have you proven your mettle in the arena? Win enough battles, and we might even find your tales worthy of storage in the Archives one day.", ["objectivesText"] = "Win 10 Arena Skirmish battles. Progress: Do not let your guard down in the arena!", ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard",
},
[83359] = { ["id"] = 83359, ["name"] = "A Shattered Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "One of your people brought me a strange tale of the cataclysm that tore Azeroth apart. In your lands, this was felt most direly due to the machinations of the wicked creature Deathwing. Travel through space and time and engage with him and other threats.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Only the titans should reshape the world.", ["rewardItems"] = { 127853, 226193, 226194, 247821, 250116 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83360] = { ["id"] = 83360, ["name"] = "A Fel Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "I have heard tales of an entire Legion of threats that lurks along the paths of space and time. Defeat them and bring me back news of their demise.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", ["rewardItems"] = { 226194 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83362] = { ["id"] = 83362, ["name"] = "A Shrouded Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "One of your people brought me tales of Pandaria! I would very much like to fly through those skies one day. Walk through mist and time and bring back news of your deeds.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I wonder what it is like to be covered in fur like a pandaren. I hear there are many floating places to visit in those lands. May they all stay afloat.", ["rewardItems"] = { 226194, 234729, 247820, 247821, 250116 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83363] = { ["id"] = 83363, ["name"] = "A Burning Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Your people have brought me tales of a Dark Portal wherein lie many enemies and challenges. I would like to hear more of these tales. Travel through time and space to this outlandish place, vanquish its foes, and bring me news of their demise.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", ["rewardItems"] = { 127853, 226193, 226194, 247820 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83364] = { ["id"] = 83364, ["name"] = "A Savage Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to a past limed with hellfire to defeat those threats once more and bring those lessons forward.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 226194, 234729, 247820, 247821 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83365] = { ["id"] = 83365, ["name"] = "A Frozen Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to the frozen past, defeat those threats once more, and bring those lessons forward.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Much has happened in the greater world while we worked in this place. I hear you had a hand in quite a bit of those tales.", ["rewardItems"] = { 127853, 226193, 226194, 247820, 247821 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard",
},
[83366] = { ["id"] = 83366, ["name"] = "The World Awaits", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83366 }, ["description"] = "Perhaps we can turn your tragedy into a mutually beneficial experience for us both. There is much you can do to be of assistance to the earthen. Lend a hand where you can.", ["objectivesText"] = "Complete 10 World Quests in Khaz Algar. Progress: My people face a wide range of difficulties these days, as do yours. We can make the best of what's befallen us both.", ["rewardItems"] = { 2815, 3056, 255881 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard",
},
[83417] = { ["id"] = 83417, ["name"] = "Out-laws", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off. I've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know? Go talk to that kid and make sure he's set for the big day. And if he's not? Fix it.", ["objectivesText"] = "Talk to Vrizek and make sure he has the Contract Fee. Progress: Everything needs to be perfect for my girl's big day. Or else.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83418] = { ["id"] = 83418, ["name"] = "The Perfect Coat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is? I got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.", ["objectivesText"] = "Acquire the fabulously feathered coat material. Progress: Tick tock!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225971 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83419] = { ["id"] = 83419, ["name"] = "The Perfect Guest List", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "The perfect weddin' has the perfect guest list! But I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly. Anyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"", ["objectivesText"] = "Get positive RSVPs from the remaining guests. Progress: You talk to all my slacker relatives yet? I have to organize the tables.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83420] = { ["id"] = 83420, ["name"] = "Catering to Perfection", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word! I need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. Ahh! I am so excited! I can't wait to see Chef Hardslice 's creations on my table at my wedding!", ["objectivesText"] = "Speak with Chef Hardslice and obtain missing ingredients. Progress: Isn't Chef Hardslice a genius?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226192 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83421] = { ["id"] = 83421, ["name"] = "The Perfect Wedding", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "I hired some goons to crash the wedding. Only the best weddings get crashed, right? But, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?", ["objectivesText"] = "Stop the wedding crashers from doing too much damage to the venue. Progress: Stop those goons from doing too much damage, or I'll take my deposit outta your hide!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232736, 232737 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83432] = { ["id"] = 83432, ["name"] = "The Rookery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83432 }, ["description"] = "My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job. We have a problem within the Rookery's walls--a skardyn outbreak. I need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it. Once you complete the mission, come back to me for your reward. And remember... this stays between us.", ["objectivesText"] = "Biergoth wants you to enter The Rookery and put an end to the skardyn threat. Progress: Back so soon? Good news, I hope?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2899, 2902, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83436] = { ["id"] = 83436, ["name"] = "Cinderbrew Meadery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83436 }, ["description"] = "Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery. He says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat. Cinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.", ["objectivesText"] = "Biergoth wants you to remove the Venture Co. from the Cinderbrew Meadery. Progress: Any news are better than no news at all. Do not keep me waiting. Unlike the mountains, my patience is like that of a landslide.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83442] = { ["id"] = 83442, ["name"] = "Tossed and Torqued", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "All my notes. My plans! <Snap is shaking with anger.> I just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000! It's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back... Maybe he didn't find it. Help me look first, then we can deal with Mite.", ["objectivesText"] = "Search Snap Vellumgrease 's apartment for the schematic in Undermine . Progress: The schematic is of a muffler-type part that sticks onto a grill. It's so amazin' that you can't miss it!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230203 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.3235, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83443] = { ["id"] = 83443, ["name"] = "Darkflame Cleft", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83443 }, ["description"] = "A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me. I need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness. How can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.", ["objectivesText"] = "Biergoth wants you to venture into Darkflame Cleft and face The Darkness. Progress: Let me know if you figure out what this darkness is all about.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83445] = { ["id"] = 83445, ["name"] = "Something Smells", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss! In fact, he's probably presenting it right now! That gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit! How good are you at pressing buttons? Will you help me present the prototype?", ["objectivesText"] = "Speak with Snap Vellumgrease at Cheap Grillz in Hovel Hill. Progress: We've got to hurry! Mite's had most of an hour to prepare. All while I was on a break, that mook!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226703, ["x"] = 0.289333, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.3235, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83446] = { ["id"] = 83446, ["name"] = "Cease and Desist", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics! But this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea! We go in, we mess up the prototype, an' we set production back months!", ["objectivesText"] = "Stop the Smellersweller 5000 production at Cheap Grillz in Hovel Hill. Progress: Mite... might actually have a good point there.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232739, 232746, 232755, 232758 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226703, ["x"] = 0.289333, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226709, ["x"] = 0.273333, ["y"] = 0.352667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.289333, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83457] = { ["id"] = 83457, ["name"] = "The Stonevault", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83457 }, ["description"] = "I have a job for you from High Speaker Brinthe herself. The skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet. Go to The Stonevault and remove the skardyn corruption. Let me know when the job is done.", ["objectivesText"] = "Biergoth wants you to end the skardyn corruption within The Stonevault. Progress: Any news I can report to High Speaker Brinthe?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83458] = { ["id"] = 83458, ["name"] = "Priory of the Sacred Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83458 }, ["description"] = "Good to see you, <name>. I have a job just for you. Sister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand. Please head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.", ["objectivesText"] = "Biergoth wants you to go to the Priory of the Sacred Flame and help Sister Etna Blayze. Progress: I am not sure if you are still here or already back.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 226134, 226137, 226138, 226139, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83459] = { ["id"] = 83459, ["name"] = "The Dawnbreaker", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83459 }, ["description"] = "I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker. By attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds. I'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.", ["objectivesText"] = "Biergoth wants you to go to The Dawnbreaker and help General Steelstrike with securing the ceremony. Progress: I know ceremonies are not your cup of cinderbrew. They are not mine either, but our job is important.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 226141, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83465] = { ["id"] = 83465, ["name"] = "Ara-Kara, City of Echoes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83465 }, ["description"] = "Tulumun, an agent of a new contact known as the Vizier, has approached us. I never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all. I will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape. Put an end to their operation. Bring back evidence of what you find.", ["objectivesText"] = "Biergoth wants you to stop the operation taking place within Ara-Kara. Progress: Move quickly. Their operation cannot be allowed to come to fruition.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 219314, 221154, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83469] = { ["id"] = 83469, ["name"] = "City of Threads", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83469 }, ["description"] = "Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place. I will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. Eliminate the Vizier's enemies, end the threat, and return to me for your payment.", ["objectivesText"] = "Biergoth wants you to eliminate all threats within the City of Threads. Progress: Make it quick. I do not wish for you to spend more time than you have to in a nerubian city.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 221181, 221189, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[83484] = { ["id"] = 83484, ["name"] = "Oh, Rats!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "Okay, scout's honor this ain't a joke. I need help because... I turned my best friend into a rat. My friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better! ...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off! Ya gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though. Can you use it an' find her?", ["objectivesText"] = "Find Alice Grillspark. Progress: The rat tilts its head, observing you closely.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 62996, 62997, 62998, 228614, 263358, 263359, 263362, 263364 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226728, ["x"] = 0.382, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226710, ["x"] = 0.332, ["y"] = 0.844 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83485] = { ["id"] = 83485, ["name"] = "Potent Potables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "<sniff> <sniff> This potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote. Please help. You're the only one who can understand me!", ["objectivesText"] = "Help Alice Grillspark.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228614 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226710, ["x"] = 0.332, ["y"] = 0.844 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83486] = { ["id"] = 83486, ["name"] = "Remote Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. If you're here to collect on a debt, you are TRESPASSING and must disregard this note . -Getry", ["objectivesText"] = "Locate Getry Sellswill at the Kaja'Coast in Zandalar. Progress: The pack has largely escaped damage. A well-worn book is visible from underneath the open flap.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 232770, 232776, 232781, 232783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["mapID"] = 862, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83487] = { ["id"] = 83487, ["name"] = "Occupational Hazard", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "<You surmise that collecting enough redberries and returning them to Humphrey should allow Alice to turn back into her usual goblin self.>", ["objectivesText"] = "Collect the redberry reagents and return to Humphrey. Progress: Any luck with that antidote, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 231369 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226728, ["x"] = 0.382, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83489] = { ["id"] = 83489, ["name"] = "Gathering All Gladiators!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83489 }, ["description"] = "Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha", ["objectivesText"] = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .", ["rewardItems"] = { 210233, 225772 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219215, ["x"] = 0.555, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["startItems"] = { 225772 }, ["questType"] = "standard", ["flags"] = {  },
},
[83492] = { ["id"] = 83492, ["name"] = "Warbands: Warbanding Together", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "<name>, some adventurers have gotten together to form a warband and could use your help. Find Blue and her group in Gadgetzan.", ["objectivesText"] = "Meet Blue and her Warband in Gadgetzan.", ["rewardGold"] = 24100, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 71, 85 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 228623 }, ["questType"] = "standard", ["flags"] = {  },
},
[83493] = { ["id"] = 83493, ["name"] = "Warbands: Rift Reader", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere! Rivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line. If we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here. If you could get us some scans of the local anomalies, it'd be a big help!", ["objectivesText"] = "Scan Transpositional Anomalies near Gadgetzan. Progress: Did you find them?", ["rewardGold"] = 319000, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2QuestSortName"] = "Nightborne", ["questType"] = "standard", ["flags"] = {  },
},
[83494] = { ["id"] = 83494, ["name"] = "Warbands: Space Ghosts by the Coast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason! They don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree! See if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?", ["objectivesText"] = "Collect Spatial Residue from the Partially Teleported creatures near Gadgetzan. Progress: Any clues?", ["rewardGold"] = 319000, ["rewardXP"] = 2765, ["rewardItems"] = { 225783 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2QuestSortName"] = "Nightborne", ["questType"] = "standard", ["flags"] = {  },
},
[83495] = { ["id"] = 83495, ["name"] = "Warbands: Twinsposition", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town. We've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all. All you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy. Rivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!", ["objectivesText"] = "Activate the Transpositional Signal Recombobulatron outside Gadgetzan and deal with the consequences. Progress: Throw the switch!", ["rewardGold"] = 683200, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2QuestSortName"] = "Nightborne", ["questType"] = "standard", ["flags"] = {  },
},
[83496] = { ["id"] = 83496, ["name"] = "Warbands: Spacetime is Money", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time! And there just happens to be a bank right here in Gadgetzan! You can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!", ["objectivesText"] = "Place the De-Recombobulatron Matrix in the Gadgetzan Bank. Progress: Did you find the bank?", ["rewardGold"] = 157900, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2QuestSortName"] = "Nightborne", ["questType"] = "standard", ["flags"] = {  },
},
[83497] = { ["id"] = 83497, ["name"] = "A Concerned Friend", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "Ah, <name>, there you are! Great Kyron was asking after you and your friend Anduin. I think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her. Check in with Kyron when you have a moment, will you?", ["objectivesText"] = "Meet Great Kyron in Mereldar.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226708, ["x"] = 0.51, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215341, ["x"] = 0.43, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83499] = { ["id"] = 83499, ["name"] = "Arcane Wasteland", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it. It is unclear if the site is hazardous or if other more corporeal dangers still lurk here. I can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?", ["objectivesText"] = "Help Aethas Sunreaver gather reagents required for a protective spell in the Tranquil Strand. Progress: The last few days have been... difficult.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225662, 225663, 225895 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83500] = { ["id"] = 83500, ["name"] = "Zekvir, Hand of the Harbinger", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 81595, 81596, 83500, 84224 }, ["description"] = "We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be! Let's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.", ["objectivesText"] = "Defeat Zekvir , the Hand of the Harbinger within his own delve.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212171, 212265, 212280, 222504, 222720, 222768, 224572, 225542, 225547, 228984 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5633, ["name"] = "Delves - Season 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83502] = { ["id"] = 83502, ["name"] = "Lessons in Defensive Magic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "The spell for the barrier is ready, but I must channel it and define its perimeter. While I channel the spell, take these wards and place them at the edges of our would-be barrier. We will empower the spell when you are finished.", ["objectivesText"] = "Help Aethas Sunreaver cast a spell to create a protective arcane dome in the Tranquil Strand.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226895, ["x"] = 0.296, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83503] = { ["id"] = 83503, ["name"] = "Return to Dornogal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "The battle is finally over and I suppose it's time we lick our wounds. Head back to Dornogal, Champion. I'll be right there as soon as Khadgar is healthy enough to withstand travel.", ["objectivesText"] = "Return to Dornogal in the Isle of Dorn and report what happened.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 223572 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220688, ["x"] = 0.36, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217864, ["x"] = 0.405, ["y"] = 0.259 }, { ["mapID"] = 2339, ["npcID"] = 225897, ["x"] = 0.254, ["y"] = 0.662667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83519] = { ["id"] = 83519, ["name"] = "But What About the Casino?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine 's crown jewel: the Gallagio. There's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. Their name: Rosebud Gallywix. I know. I know. But Rosey is a good egg. I'll introduce you to him later on. First, do me a favor. Ask the power players here at the party how they feel about the new owner.", ["objectivesText"] = "Ask about Rosebud Gallywix at the Gallagio's opening party. Progress: Don't get turned off by the Gallywix name. He had a big family, and they ain't all evil crankshafts.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.6544, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83521] = { ["id"] = 83521, ["name"] = "Little Help, Please?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["storyline"] = { 83521 }, ["description"] = "So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light. I just got that fixed. I swear it! Would you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it. Shouldn't be more than a minute. Two at most!", ["objectivesText"] = "Deal with the Venture Co. \"Policers\".", ["rewardGold"] = 117000, ["rewardXP"] = 5885, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83522] = { ["id"] = 83522, ["name"] = "Debting For A Living", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey. Now, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in. Did they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. Best we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!", ["objectivesText"] = "Speak with Kayjay and Fantastic Davey about signing the new Gallagio deed. Progress: You'll find all those in my employ are quite content. I've got the bills from various corporate training seminars to prove it.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226277, ["x"] = 0.5145, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228420, ["x"] = 0.526, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.5145, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83524] = { ["id"] = 83524, ["name"] = "Gold In Them There Trash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit. If you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me. Grab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\" Win by the final bell, and I'll let these two go. Lose, and I'll own you. It's called Slot Mining. And it will indebt you to me for life.", ["objectivesText"] = "Compete in Slot Mining at The Heaps. Progress: <Tarbonara says nothing. He simply snarls through his shiny teeth.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232766, 232767, 234188 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228420, ["x"] = 0.526, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228474, ["x"] = 0.556, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83527] = { ["id"] = 83527, ["name"] = "Winning is for Losers, Anyway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire. We're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand. But if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down. You like collecting points, don'tcha?", ["objectivesText"] = "Collect Debt Markers and free the Indenture Debtors.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228473, ["x"] = 0.558, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83528] = { ["id"] = 83528, ["name"] = "All Part of the Game", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor. With him gone... We're just two halves of a gaming genius, working for hire instead of salary. But Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in. Problem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.", ["objectivesText"] = "Collect Kayjay and Fantastic Davey's Debt Markers from Commissioner Kudd Milktooth.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228474, ["x"] = 0.556, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83529] = { ["id"] = 83529, ["name"] = "Hallowfall Fishing Derby", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82778, 83529, 83530, 83531, 83532 }, ["description"] = "Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", ["objectivesText"] = "Catch these Trophy Fish before the Derby Dasher buff expires: Bismuth Butterling, Whispering Stargazer, Regal Dottyback. Progress: Any bites, <name>?", ["rewardItems"] = { 168417, 191356, 212310, 217375, 219002, 219003, 219004, 219005, 219006, 220134, 220135, 220136, 220137, 220138, 220139, 220141, 220142, 220143, 220144, 220145, 220146, 220147, 220148, 220149, 220150, 220151, 220152, 220153, 221790, 222533, 222745, 222842, 223286, 223979, 224717, 224727, 224752, 225592, 225758, 225763, 225770, 225771, 225892, 226376, 226378, 226379, 226392, 228421, 228422, 228423, 228954 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5637, ["name"] = "Hallowfall Fishing Derby", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
