[83534] = { ["id"] = 83534, ["name"] = "Ain't No Warm Up Act", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Can't believe Revilgaz scheduled us first! No one shows up for the first band! Whatever. You the one that oldhair Marty mentioned? He already gave me the lowdown on your plan to keep the Gallagio from going to auction. Seems ridiculous. Which makes it our kinda plan. Let's make a deal. Our manager dumped us when the casino deal went south, so YOU are gonna fill in for her today. Don't worry, couldn't be worse than any other job you've done. First thing on your list: gather us a crowd.", ["objectivesText"] = "Spread the hype and gather a crowd for the Cellar Gnomes. Progress: Hope you're making up crazy lies to get these people to see us. That's what we'd do.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226899, ["x"] = 0.563, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232005, ["x"] = 0.71, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83535] = { ["id"] = 83535, ["name"] = "Plunder Party Rockin' Rumble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Here! Take this Mecha-Trianbell! I don't care that you can't play an instrument because you WILL be playing this one. While we're jamming, members of rival bands will storm the stage to stop us. Not only will the Trianbell ring out in perfect pitch, it'll also blast anyone not in our band all the way to the cheap seats.", ["objectivesText"] = "Protect the Cellar Gnomes with the Mecha-Trianbell while they play.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232769, 232774, 232778, 232784 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 232005, ["x"] = 0.71, ["y"] = 0.237 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226899, ["x"] = 0.563, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
