[83539] = { ["id"] = 83539, ["name"] = "Feeling Blue", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "I fear... that it may just be me that remains, <name>. Or that the others are too far away to receive my missive. It may be up to us to build an outpost here and see to the cleansing of the crash site. So be it. It is just as well...", ["objectivesText"] = "Build the Kirin Tor outpost in the Tranquil Strand. Progress: It's hard to describe what I feel right now.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226895, ["x"] = 0.296, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227067, ["x"] = 0.298, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.296, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83540] = { ["id"] = 83540, ["name"] = "Work the Line", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. Problem was, the crowds were too thick for me to find Gobdre anywhere. That's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us. He's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. Give it a poke and he should spill.", ["objectivesText"] = "Get Marin Noggenfogger to spill the beans on Jojo Gobdre 's whereabouts. Progress: Did you just cut the line?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 152668, 227663 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226932, ["x"] = 0.328, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 12, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83541] = { ["id"] = 83541, ["name"] = "Review Bombed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Show me you ain't just talk. I give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. Fishy much? Definitely. And not the kind I like. Go. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.", ["objectivesText"] = "Retrieve 100 Diner Review Cards . Progress: How'd they like the Junglevine-soaked Stormray? Bet they said it was bitter. I knew that batch was bitter. Ran outta salt when I was cooking it.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 227666 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83542] = { ["id"] = 83542, ["name"] = "Quick Gills for Gold Now", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Ah, crabs... I knew this would happen. The diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid. Long name, right? I was hoping that would dissuade the customers from writing it on their cards. Trouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through. Want me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.", ["objectivesText"] = "Exchange Gold Fish for Gobdre's Prized Pan . Progress: Blair and Chub Bass. The scammiest lovebirds you'll ever meet. But they did source me some terrific fish.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 227673, 227674, 237345, 237346, 237347 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83543] = { ["id"] = 83543, ["name"] = "Adventuring in Khaz Algar", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966, 83543 }, ["description"] = "We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble. Seems we got here just in time, eh? Check the scouting map on the table behind ye and lend a hand where ye can.", ["objectivesText"] = "Review the Scouting Map to choose an area within Khaz Algar to support.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 15, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83546] = { ["id"] = 83546, ["name"] = "Responsibility", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Today's the day for shiny shoes, <name>! We've got our deed signatures. We've got support from the cartels. And we've got... my kids. My wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful. Welp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!", ["objectivesText"] = "Pack up and drive to court. Progress: You look worried. You shouldn't be worried. I'm not worried.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 220158 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227018, ["x"] = 0.386, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 16, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83547] = { ["id"] = 83547, ["name"] = "Welcome to the Neighborhood", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 83547, 84832 }, ["description"] = "<A letter has been left in your mailbox. The handwriting is neat and smoothly flowing.> Welcome to Borogrove, <name>! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood. Once you've settled in, please come see me at Town Hall.", ["objectivesText"] = "Speak with Llyssabel Dawnpetal at Town Hall.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2321, ["db2PoiUiMapID"] = 2321, ["db2PoiMapID"] = 2698, ["questLines"] = { { ["id"] = 5636, ["name"] = "Housing NPC Prototype", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5689, ["name"] = "Neighborhood Prototype Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83548] = { ["id"] = 83548, ["name"] = "Isle of Dorn", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 78530 }, ["description"] = "Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix. Lend your aid to protect whomever remains.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore on the Isle of Dorn .", ["rewardGold"] = 28600, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["db2AdventureMapPoiID"] = 190, ["questType"] = "standard", ["flags"] = {  },
