[83550] = { ["id"] = 83550, ["name"] = "The Ringing Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78555, 80434 }, ["description"] = "Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away. She has asked for adventurers to join her at the bottom of the Coreway.", ["objectivesText"] = "Meet Speaker Brinthe in The Ringing Deeps .", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 19, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 191, ["questType"] = "standard", ["flags"] = {  },
