[83551] = { ["id"] = 83551, ["name"] = "Hallowfall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["series"] = { 78659 }, ["description"] = "Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall . He will need help to win over these potential allies.", ["objectivesText"] = "Speak to Faerin Lothar in Hallowfall .", ["rewardGold"] = 30600, ["rewardXP"] = 1190, ["rewardItems"] = { 224752, 225246, 225770, 225771 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 11, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2AdventureMapPoiID"] = 192, ["questType"] = "standard", ["flags"] = {  },
