[83552] = { ["id"] = 83552, ["name"] = "Azj-Kahet", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["series"] = { 78350 }, ["description"] = "An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush. Aid the survivors as they withstand the nerubian assault.", ["objectivesText"] = "Speak to Faerin Lothar aboard The Reckoning in Azj-Kahet .", ["rewardGold"] = 30600, ["rewardXP"] = 1190, ["rewardItems"] = { 226166, 226173, 226174, 226175, 226176 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2AdventureMapPoiID"] = 193, ["questType"] = "standard", ["flags"] = {  },
