[83553] = { ["id"] = 83553, ["name"] = "Magic-stealing Kobolds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn . In my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran. Dangerous items. Someone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm. Follow me.", ["objectivesText"] = "Meet with Kalecgos at Mourning Rise in the Isle of Dorn .", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227067, ["x"] = 0.298, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227063, ["x"] = 0.616, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83554] = { ["id"] = 83554, ["name"] = "Trinkets, Curios and Other Powerful Objects", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "The kobolds here could get up to untold mischief with the items they have stolen. Take what you can back from them by... whatever means you see fit. While you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same. Meet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.", ["objectivesText"] = "Reclaim stolen Kirin Tor artifacts from the kobolds in the Mourning Rise. Progress: We must search and reclaim what we can. Even the smallest curio could be meaningful to someone... or dangerous.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225920, 226162 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227063, ["x"] = 0.616, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83555] = { ["id"] = 83555, ["name"] = "Mysterious Necklace", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>", ["objectivesText"] = "Return the necklace to Kalecgos at Mourning Rise in the Isle of Dorn .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 228520, ["x"] = 0.62, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["startItems"] = { 225927 }, ["questType"] = "standard", ["flags"] = {  },
},
[83556] = { ["id"] = 83556, ["name"] = "Maybe You Shouldn't Touch That", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "This necklace... It is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me. You take another look. Maybe there's something obvious I'm missing.", ["objectivesText"] = "Investigate the Emerald Necklace in Mourning Rise.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 947, ["npcID"] = 227208, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 947, 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83558] = { ["id"] = 83558, ["name"] = "Casino Court", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "I'm all set to make our case. Just one tiny, little, minor thing to let you know about... There's a bomb under my desk here. Don't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive. Take this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger. My lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.", ["objectivesText"] = "Use the X-Plo-Dar 64k to reveal who's holding the bomb's trigger. Progress: Have you found the source yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232768, 232773, 232782, 232786 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.562667, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 17, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83563] = { ["id"] = 83563, ["name"] = "Coffee is for Closers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge. I imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions. You know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.", ["objectivesText"] = "Defeat Tarbonara Fizzlecrank, and ensure Judge Landro notarizes the new Gallagio deed. Progress: I had a feeling this would be a great case.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.562667, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 18, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83566] = { ["id"] = 83566, ["name"] = "Oh, That Casino!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You'd make a good lawyerer, you know that? Hah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer! Why don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now. Not to mention that we should actually hand them the notarized deed!", ["objectivesText"] = "Hand the Gallagio over. Progress: You teary-eyed because our adventure is over? Or because you were secretly hoping the place would go to auction, and you'd have a chance to buy it up? Bet it was the latter! Hah!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 234125 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.3975 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 19, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83569] = { ["id"] = 83569, ["name"] = "Death and Taxes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "He just... exploded... If a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this! But the more immediate pickle is this: Who owns the Gallagio now? It's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got. Take what's left of the deed to his office in Hovel Hill, and sort this out.", ["objectivesText"] = "Meet the State of Undermine 's assigned Public Defender.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.6544, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83587] = { ["id"] = 83587, ["name"] = "Our Chance to Strike", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2255, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82124 }, ["description"] = "<The child-like spider presents you with a sealed scroll. The sealed letter bears the markings of the Vizier.> The balance of power is shifting in Azj-Kahet . The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. Meet me at the Royal Apothecary when you receive this letter.", ["objectivesText"] = "Meet with the Vizier at the Royal Apothecary.", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227217, ["x"] = 0.57, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2213, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83616] = { ["id"] = 83616, ["name"] = "The Entrenched", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["series"] = { 81683 }, ["description"] = "And now the other piece to this coup. I've been operating under Grand Overspinner Antourix 's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat. Even she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart. See how quickly they turn on each other.", ["objectivesText"] = "Offer your services to Grand Overspinner Antourix against Ren'khat. Progress: An overcrawler? Here? In MY dominion?! Minions! Slay them! Wait! Wait... You might be useful...", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221557, ["x"] = 0.756, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83627] = { ["id"] = 83627, ["name"] = "The Beginning of Something Beautiful", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83627 }, ["description"] = "<This seems like it would be of interest to a nerubian alchemist. Ascension is their specialty, and this may be key to understanding more about the process.>", ["objectivesText"] = "Take the Vial of Skyrazor Blood to Shalba .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["startItems"] = { 225952 }, ["questType"] = "standard", ["flags"] = {  },
},
[83628] = { ["id"] = 83628, ["name"] = "Tense Recovery", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow. My sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them. I asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?", ["objectivesText"] = "Speak to the strangers to improve relations with the Arathi.", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227222, ["x"] = 0.236, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.236, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83629] = { ["id"] = 83629, ["name"] = "Ancient Respite", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come. Sometimes changes comes with death. Decay is natural. But the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body. Destroy these mites, so that I may rest without fear of their mouths upon my sleeping form.", ["objectivesText"] = "Kill 15 Feasting Mites for Goehi . Progress: The sound of their gnawing fills me with dread.", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83632] = { ["id"] = 83632, ["name"] = "Rings of Memory", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "I appreciate what you have done. Do not worry--I am not finished yet. If you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. These strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.", ["objectivesText"] = "Bring Goehi's Root to Wild Camp Or'lay. Progress: Did you find the ancients?", ["rewardGold"] = 303800, ["rewardXP"] = 10595, ["rewardItems"] = { 225973 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215724, ["x"] = 0.233, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83639] = { ["id"] = 83639, ["name"] = "Open Communications", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here. It is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown. I know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.", ["objectivesText"] = "Speak to Ysabel and clear up the misunderstanding. Progress: I can't leave my sister like this.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215724, ["x"] = 0.233, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227222, ["x"] = 0.236, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83641] = { ["id"] = 83641, ["name"] = "Trapped Between Life and Death", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15000, ["mapID"] = 947, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "A pocket dimension. This is old magic. Malygos used pocket dimensions on occasion when he did not wish to be disturbed. They were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing... I wonder who made this one? I suppose it doesn't matter. We need to get out. Thankfully, every pocket dimension has an exit. Though, it is normally well hidden. Let's find it.", ["objectivesText"] = "Find a way out of the pocket dimension.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 158149, 210974 }, ["starts"] = { { ["mapID"] = 947, ["npcID"] = 227208, ["x"] = 0, ["y"] = 0 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227392, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 947, ["source"] = "quest_giver", ["x"] = 0, ["y"] = 0 }, ["mapCandidates"] = { ["npc"] = { 947, 2248 }, ["zone"] = { 15000 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83643] = { ["id"] = 83643, ["name"] = "Somehow We Survived", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation. To me, this underlines the importance of the Kirin Tor. But, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts. Now that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. Perhaps now more have responded to his letter.", ["objectivesText"] = "Regroup with Kalecgos at the Tranquil Strand.", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227392, ["x"] = 0.615, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227407, ["x"] = 0.31, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83707] = { ["id"] = 83707, ["name"] = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 83707 }, ["rewardGold"] = 3098000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
