[83711] = { ["id"] = 83711, ["name"] = "Weapons of Conquest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83711 }, ["description"] = "Tales of your prowess have reached even me, hero. If you fight as well as they say you do - then I reckon you would be even better with one of my creations. Write your name in history. Return when you've proven yourself both skilled and honorable.", ["objectivesText"] = "Obtain Conquest in Rated Arenas and Battlegrounds.", ["rewardItems"] = { 232602, 232603 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219222, ["x"] = 0.552, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp", ["flags"] = {  },
