[83716] = { ["id"] = 83716, ["name"] = "Beneath the Roots", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83716 }, ["description"] = "I am glad to see you are well, <name>. I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. Would you check on them?", ["objectivesText"] = "Find the camp sheltering the Aeroknights in western Azj'kahet.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227295, ["x"] = 0.235, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
