[83719] = { ["id"] = 83719, ["name"] = "Those Are Chitin Words", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83719 }, ["description"] = "Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique! With the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!", ["objectivesText"] = "Collect enough Nerubian Chitin for Shalba 's experiment. Progress: Chitin samples will help define the strength of Siesbarg's new form.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83720] = { ["id"] = 83720, ["name"] = "Venom? More Like Get 'Em", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83720 }, ["description"] = "Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves! I'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom , specifically. I'm afraid beetles and spiders simply won't do this time around. As for where you find it, well that's up to you.", ["objectivesText"] = "Collect enough Nerubian Venom for Shalba 's experiment. Progress: Very good! This is exactly what I was looking for.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83721] = { ["id"] = 83721, ["name"] = "A Small Ocean's Worth of Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83721 }, ["description"] = "Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood . However, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available. The kind of material that Siesbarg deserves!", ["objectivesText"] = "Collect enough Nerubian Blood for Shalba 's experiment. Progress: Our experiment nears fruition, overcrawler.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83722] = { ["id"] = 83722, ["name"] = "Consolation Flies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83722 }, ["description"] = "Well... that's unfortunate. It appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension! While his physical form isn't what I intended, it appears Siesbarg 's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.", ["objectivesText"] = "Take Siesbarg off Shalba 's hands.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224150, 225952 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 228200, ["x"] = 0.443, ["y"] = 0.135 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
