},
[83739] = { ["id"] = 83739, ["name"] = "Notorious with The General", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83739 }, ["description"] = "Word of your deeds has reached many of The General's acolytes! Find me at the Weaver's Lair. We have prepared a tribute for you!", ["objectivesText"] = "Speak with Aspirant Kiipka in the Weaver's Lair.", ["rewardItems"] = { 226045 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2649, ["threshold"] = 2500 } } }, ["questType"] = "standard", ["flags"] = {  },
