[83740] = { ["id"] = 83740, ["name"] = "Notorious with The Vizier", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83740 }, ["description"] = "The Vizier has asked me to provide you with additional resources towards your efforts. Come to the Weaver's Lair. I'll be waiting for you with a parcel.", ["objectivesText"] = "Speak with Tulumun in the Weaver's Lair.", ["rewardItems"] = { 226045, 226100, 226103 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2647, ["threshold"] = 2500 } } }, ["questType"] = "standard", ["flags"] = {  },
