[83742] = { ["id"] = 83742, ["name"] = "Call to Attention", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 83742 }, ["description"] = "Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter. I am not at liberty to say more here. Seek out the General for further briefing. For Azj-Kahet.", ["objectivesText"] = "Report to General Anub'azal in Siegehold.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[83743] = { ["id"] = 83743, ["name"] = "Arcane Cold War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "A few mages have come but... I expected more to act on Aethas's call to action. But perhaps that was wishful thinking. We need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts. Meanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first! We must find these artifacts before they are used against us.", ["objectivesText"] = "Travel to Azj-Kahet and meet with Lady Jaina Proudmoore .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227409, ["x"] = 0.298, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227529, ["x"] = 0.352, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83749] = { ["id"] = 83749, ["name"] = "Delves: The Waterworks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83749 }, ["description"] = "What a trip! Can ye believe how much exists below the depths here? The Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place. What do ye say? Let's go on an adventure and help out these folks!", ["objectivesText"] = "Complete the Waterworks delve on any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 211481, 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227477, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
