[83752] = { ["id"] = 83752, ["name"] = "Threats of Zekvir", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83752 }, ["description"] = "Someone's watchin' us, <name>. They put this chest here for us to find. Let me know when you're ready. I'll trigger the trap here to see just what exactly is going on.", ["objectivesText"] = "Speak with Brann Bronzebeard to investigate the strange chest.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
