[83753] = { ["id"] = 83753, ["name"] = "Cannon Karma", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "This is gettin' serious, <name>! Those pirate goons have a cannon and are threatenin' to blow us outta the sky! But this may also be an opportunity. If youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!", ["objectivesText"] = "Bilge Rat attack disrupted and Cannon Master Jin'chu eliminated. Progress: Ya better be tellin' me dem pirates is all gone!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226133 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83755] = { ["id"] = 83755, ["name"] = "Delves: Nightfall Sanctum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83755, 83761 }, ["description"] = "Good tae see you again! I've run into a bit of a mess since we last met. Some nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more! These Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.", ["objectivesText"] = "Find evidence of Zekvir within the Nightfall Sanctum and complete the delve on any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 227523, ["x"] = 0.434, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 227528, ["x"] = 0.352, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2PoiUiMapID"] = 2215, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5650, ["name"] = "11.0 Delves - Level Up Guidance - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83758] = { ["id"] = 83758, ["name"] = "Delver's Call: Fungal Folly", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83758 }, ["description"] = "We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\" Explore the cave and eliminate any threats you find.", ["objectivesText"] = "Complete the Fungal Folly delve on any difficulty. Progress: Are you the one who grabbed the task for Fungal Folly?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
