[83759] = { ["id"] = 83759, ["name"] = "Delver's Call: Kriegval's Rest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83759 }, ["description"] = "HELP WANTED Kriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.", ["objectivesText"] = "Complete the Kriegval's Rest delve on any difficulty. Progress: Are you investigating Kriegval's Rest?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 198827, 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
