[83761] = { ["id"] = 83761, ["name"] = "Delves: The Underkeep", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83755, 83761 }, ["description"] = "Who would've thought I'd be cozying up in a nerubian's lair! There's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got. Supposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!", ["objectivesText"] = "Find information on Zekvir within the Underkeep and complete the delve at any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227544, ["x"] = 0.572, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227548, ["x"] = 0.6, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5650, ["name"] = "11.0 Delves - Level Up Guidance - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83762] = { ["id"] = 83762, ["name"] = "Critical Mass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "This is exactly what I had feared. Thalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this. I argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it. And now those notes are both the problem and the solution. Thankfully, I have read these notes, <name>. I will walk you through disarming the mana bomb.", ["objectivesText"] = "Help Lady Jaina Proudmoore disarm the mana bomb in the Breathing Pit.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227529, ["x"] = 0.352, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83763] = { ["id"] = 83763, ["name"] = "Preserve the Legacy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "The larger threat has been contained, <name>, but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet . While they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran. Leave no dark corners here in the Breathing Pit unexplored, <name>.", ["objectivesText"] = "Collect valuable items from the Breathing Pit. Progress: We must reclaim what we can of the Kirin Tor's legacy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228820, 228821, 228823 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 228963, ["x"] = 0.314, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83764] = { ["id"] = 83764, ["name"] = "Too Powerful, Too Dangerous", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are. With those vaults gone, the only course of action we can take is to destroy them. In hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran. I would trust no one else with this task, <name>. Find and destroy those artifacts.", ["objectivesText"] = "Find dangerous artifacts scattered around in the Breathing Pit and destroy them.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 228963, ["x"] = 0.314, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83766] = { ["id"] = 83766, ["name"] = "Delver's Call: Dread Pit", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83766 }, ["description"] = "Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter! Something bad is going on here. We lost a bunch of workers in this cave. We need you to deal with the threat, so we can keep business booming!", ["objectivesText"] = "Complete the Dread Pit delve on any difficulty. Progress: Glad I finally found someone to check out the Dread Pit!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216311, ["x"] = 0.568, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83767] = { ["id"] = 83767, ["name"] = "Delver's Call: The Sinkhole", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83767 }, ["description"] = "We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance. There's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!", ["objectivesText"] = "Complete the Sinkhole delve on any difficulty. Progress: Beware of what lurks within the Sinkhole.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 116271, 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214019, ["x"] = 0.492, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83768] = { ["id"] = 83768, ["name"] = "Delver's Call: The Skittering Breach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83768 }, ["description"] = "Call For Any Who Can Swing a Sword or Sling a Spell! The nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. Someone must investigate this foul place and put an end to their schemes.", ["objectivesText"] = "Complete the Skittering Breach delve on any difficulty. Progress: The Skittering Breach is a dangerous place. Be on your guard if you're going in.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83769] = { ["id"] = 83769, ["name"] = "Delver's Call: Mycomancer Cavern", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83769 }, ["description"] = "Spice Help Needed! Fungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! Will pay well.", ["objectivesText"] = "Complete the Mycomancer Cavern delve on any difficulty.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217611, ["x"] = 0.692, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83770] = { ["id"] = 83770, ["name"] = "Delver's Call: Spiral Weave", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83770 }, ["description"] = "A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on. Taking the fight to them would help put a serious dent in the nerubians' war plans.", ["objectivesText"] = "Complete the Spiral Weave delve on any difficulty Progress: You're going into the heart of a nerubian military base. Be careful.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211721, ["x"] = 0.588, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211721, ["x"] = 0.588, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83771] = { ["id"] = 83771, ["name"] = "Delver's Call: Tak-Rethan Abyss", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83771 }, ["description"] = "WEAVER'S ORDERS The Tak-Rethan Abyss continues to be a place of great unrest and trouble. Someone must keep the threats in check before they interfere with our plans.", ["objectivesText"] = "Complete the Tak-Rethan Abyss delve on any difficulty. Progress: Are you investigating those kobyss?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 116271 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83773] = { ["id"] = 83773, ["name"] = "Farewell, City of Magic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "Not all the Kirin Tor's issues can be solved in one day. But one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran. We would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.", ["objectivesText"] = "Place mementos brought by Dalaran survivors on the boats in the Tranquil Strand. Progress: One thing I am sure of is that the Kirin Tor's future is not another floating fortress in the sky. No, whatever path the Kirin Tor chooses, it will be firmly rooted here, on Azeroth, among the people it serves.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83794] = { ["id"] = 83794, ["name"] = "Soggy Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83794 }, ["description"] = "<The crate is pretty wet and smells a bit fishy, but looks to be mostly sealed tight. Alyx would appreciate the supplies returned.>", ["objectivesText"] = "Return the Soggy Celebration Crate to Alyx . Progress: Oh, I am so busy. But what can I help you with?", ["rewardItems"] = { 225996, 226200, 228694 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 226200 }, ["questType"] = "standard", ["flags"] = {  },
},
[83825] = { ["id"] = 83825, ["name"] = "Restoring A Grand Tale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83825 }, ["description"] = "It was terrible! My book was shredded, and the pages flew everywhere! I saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them? Please help me get the pages back so I can restore my book! Oh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!", ["objectivesText"] = "Return a Green Hills of Stranglethorn to Raenie Fizzlebog outside the Caverns of Time Progress: Were you able to find all the pages and repair my book?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 225252, 226241, 226242, 231907 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[83827] = { ["id"] = 83827, ["name"] = "Silence the Song", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after? Whichever it may be, these sirens' call has lured many of our forces to their doom. Our goblin allies have prepared a device to remove the control they have over our troops. Eliminate these \"sirens\" and dispel the charm that holds our troops captive.", ["objectivesText"] = "Free 7 Charmed Troops and slay Macabea The Sea Banshee . Progress: Have you eliminated the siren threat?", ["rewardGold"] = 309800, ["rewardXP"] = 8825, ["rewardItems"] = { 226261 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232753, ["x"] = 0.4545, ["y"] = 0.6755 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232753, ["x"] = 0.4545, ["y"] = 0.6755 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.4545, ["y"] = 0.6755 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83832] = { ["id"] = 83832, ["name"] = "Torn Dreams", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83832 }, ["description"] = "Hello again! I could really use your help here. A visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.", ["objectivesText"] = "Seek out Raenie Fizzlebog outside the Caverns of Time.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
