[83931] = { ["id"] = 83931, ["name"] = "Battered Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83931 }, ["description"] = "<The crate is pretty battered. It looks like at least one wolf chewed on its corner. Alyx would appreciate the supplies returned.>", ["objectivesText"] = "Return the Battered Celebration Crate to Alyx . Progress: Oh, I am so busy. But what can I help you with?", ["rewardItems"] = { 226375 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 2339, ["npcID"] = 234262, ["x"] = 0.505, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 2339 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 226375 }, ["questType"] = "standard", ["flags"] = {  },
},
[83932] = { ["id"] = 83932, ["name"] = "Historical Documents", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Imagine having the chance to accompany Sky-Captain Elaena Lancekat on such a great adventure. This is the opportunity of a lifetime! But if I'm going to write a book about this journey, I need to gather some historical information about this island. Perhaps you could collect any notes or documents that you find? Anything might be useful and tell us about the history of this place!", ["objectivesText"] = "Add 12 Notes and Documents found on the isle to the Research Journal . Progress: What did you find?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 227405, 227406 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[83933] = { ["id"] = 83933, ["name"] = "The Kaja'Coast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Alright, we got the punch card to the Kaja'Coast and a pretty good reason to believe Venture's shmoozin' up to Gallywix a lot more than we thought. Noggenfogger said we'd find answers at those mines, and that means goin' down to the Kaja'Coast for a look. Let's go. We'll meet you over at Slam Central.", ["objectivesText"] = "Meet Gazlowe and Renzik at Slam Central Station, then use the Coastside Drill to travel to the Kaja'Coast.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225639, ["x"] = 0.532, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225645, ["x"] = 0.222, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 862, 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84001] = { ["id"] = 84001, ["name"] = "Cart Blanche", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. There's a problem though... None of the carts made it to camp due to trouble on the tracks! Please repair the tracks and collect any lost ore if you can so we can get those samples to camp.", ["objectivesText"] = "Repair 2 Mine Tracks, clear 5 Crashed Mine Carts, and collect 12 Ore Samples . Progress: Are the mine carts getting through now?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226853 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232730, ["x"] = 0.485, ["y"] = 0.529 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232730, ["x"] = 0.485, ["y"] = 0.529 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.529 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84020] = { ["id"] = 84020, ["name"] = "A Mech in Need", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 84020 }, ["description"] = "This mechsuit has seen better days. Maybe a skilled Machine Speaker could assist you. I know Speaker Jurlax has been assigning machinists to mechsuit maintenance lately. He probably has some advice for you.", ["objectivesText"] = "Bring the Malfunctioning Mechsuit to Speaker Jurlax in Gundargaz.", ["rewardItems"] = { 221765, 221967, 226683 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["startItems"] = { 226683 }, ["questType"] = "standard", ["flags"] = {  },
