[84021] = { ["id"] = 84021, ["name"] = "Machine Without Cogs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 84021 }, ["description"] = "Diagnosis: This machine's movement is impaired. We must get it moving again. I'm going to need some replacement parts. The gears must keep grinding.", ["objectivesText"] = "Bring an Overclocked Gear-A-Rang Launcher to Speaker Jurlax for parts. Progress: Did you bring the parts we need?", ["rewardItems"] = { 219299, 219301, 219306, 221765, 226683 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
