[84022] = { ["id"] = 84022, ["name"] = "Uniting Severed Threads", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "You have done well to ally Anub'azal and Nizrek to our cause. It is time that we solidify this triumverate relationship between us all. We will conference via shadecasters. Activate them when you're ready to begin.", ["objectivesText"] = "Join forces with the Weaver, the General, and the Vizier to forge the Severed Threads. Progress: I wonder how our three potent personalities will work together. Only time will tell, I suppose.", ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84023] = { ["id"] = 84023, ["name"] = "Orienting Ourselves", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 84023 }, ["description"] = "The machine moves without intent. Let us guide it toward purpose. Deliver direction unto this device.", ["objectivesText"] = "Bring a Synergistic Brewterializer to Speaker Jurlax for parts. Progress: Do you bear spatial omniscience?", ["rewardItems"] = { 219299, 219301, 219306, 221765, 226683, 237502 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
