[84024] = { ["id"] = 84024, ["name"] = "Clutching Control", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 84024 }, ["description"] = "The machine breathes without life. We must provide ours. Find a conduit for the will of the divine.", ["objectivesText"] = "Bring a Burin of the Candle King to Speaker Jurlax for parts. Progress: Do you wield a tool of influence?", ["rewardItems"] = { 219299, 219301, 219306, 221765, 226683, 237502 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2QuestHubAreaPoiID"] = 7911, ["questType"] = "standard", ["flags"] = {  },
