[84084] = { ["id"] = 84084, ["name"] = "Just a Pinch", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84084 }, ["description"] = "Dust is the foundation of the art of enchantment. Where novice enchanters turn up their noses at such a common material, a master understands its versatility. Bring me Storm Dust . No matter our expertise, we must always return to the fundamentals.", ["objectivesText"] = "Collect 20 Storm Dust and deliver it to Nagad in Dornogal . Progress: Have you collected the requisite dust?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 219946, 219949, 227667 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 40, ["questType"] = "profession", ["flags"] = {  },
},
[84085] = { ["id"] = 84085, ["name"] = "The Power of Potential", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84085 }, ["description"] = "As enchanters, we do not merely trade in runes or wands. Our true commodity is potential. We take the power of possibility and infuse it into tangible forms. For this, Gleaming Shards are essential. I require several to continue my work.", ["objectivesText"] = "Collect 10 Gleaming Shards and deliver them to Nagad in Dornogal . Progress: Where dust offers versatility, shards confer potential.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 219949, 227667 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 40, ["questType"] = "profession", ["flags"] = {  },
},
[84086] = { ["id"] = 84086, ["name"] = "A Rare Necessity", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84086 }, ["description"] = "Occasionally, we are called upon to provide our greatest and most powerful boons. For these, I require a Refulgent Crystal . True, such crystals are rare, but necessary for us to reach the heights of our art. Worry not, it will not be squandered.", ["objectivesText"] = "Collect 1 Refulgent Crystal and deliver it to Nagad in Dornogal . Progress: Once in hand, I will ensure it is put to worthwhile purpose.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 219952, 227667 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219085, ["x"] = 0.526, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 40, ["questType"] = "profession", ["flags"] = {  },
},
[84121] = { ["id"] = 84121, ["name"] = "A Little Insurance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "There are too many Darkfuse guardin' this place for us to sneak around them. We're gonna have to thin 'em out the old fashioned way. Take out as many Darkfuse as you can. Me and Gazlowe will do some reconnaissance.", ["objectivesText"] = "Slay 10 Darkfuse on the Kaja'Coast. Progress: I don't need those goons breathin' down our necks while we're working things out here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 227937, ["x"] = 0.222, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228132, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84122] = { ["id"] = 84122, ["name"] = "Cut the Cameras", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Gallywix ain't an idiot. He's got those surveillance birds keepin' an eye on this entire area. We're gonna need to bring 'em offline if we wanna keep a low profile--and by that, I mean smash 'em to itty bitty pieces. If you need help grabbin' them outta the air, use this auto-grappler. Oh, and scoop some of their parts up for me when you're done. I've got an idea.", ["objectivesText"] = "Collect 6 Handfuls of B.I.R.D. Parts from Surveillance B.I.R.D.s on the Kaja'Coast. Progress: I'm not sure why they're watchin' a mine this closely, but we need to make sure they got less eyes on it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226823, 226824 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225645, ["x"] = 0.222, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84127] = { ["id"] = 84127, ["name"] = "Blacksmithing Services Requested", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84127 }, ["description"] = "Greetings, <class>. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. If you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. Come speak with me once you've completed your designs, and may the wind guide your hands and heart.", ["objectivesText"] = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium. Progress: Come speak with me once you've completed your designs, and may the wind guide your hands and heart.", ["rewardXP"] = 9245, ["rewardItems"] = { 198606, 228774, 245345, 263455 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 228177, ["x"] = 0.592, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 228177, ["x"] = 0.592, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2DetailThemeID"] = 33, ["questType"] = "profession",
