[84140] = { ["id"] = 84140, ["name"] = "Can-Do Caddy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "So, my \"company\" was subcontracted to provide services for the golf course here. Only, it turns out the materials we used in our patented, explosive-proof grass has drawn a swarm of coursehares . Which is inconvenient 'cause they're the only type of rodents that can eat the grass. I need a can-do caddy I can sub-subcontract out the elimination of this threat to my business. So tell me, can you?", ["objectivesText"] = "Eliminate 9 Coursehares .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84141] = { ["id"] = 84141, ["name"] = "Scam Cans", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "Look, I run a clean business here... when I'm paid to. But, I've gotta swathe of cheatin' no gooders tryin' to plant scam cans in the holes. The things cause the balls of cheaters to get drawn into 'em, cheapenin' the game. Can't have that. Get out there, find the scam cans , and get them gone.", ["objectivesText"] = "Extract 4 Scam Cans . Progress: Yeah, gotta watch out for them explodin' balls. They make for a great sport but hazard pay is a real thing.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84142] = { ["id"] = 84142, ["name"] = "The Hole Deal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "Okay, well now that's settled, how about you get a free go, eh? Here at... < Ripsnoodle pauses to look at notes he digs out of his pocket.> Emerald Hills Golf Course, we pride ourselves on everyone gettin' a hole-in-one! Especially since our boomballs explode after the first swing. So make 'em count. Go take a few balls out and give the course a whack.", ["objectivesText"] = "Sink 4 Boomballs into the four golf holes. Progress: The other day I saw this warlock trying to have their imp nudge a ball into the hole. Man that imp was NOT happy when it got resummoned after the explosion. The things people sell their soul over...", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232742, 232749, 232751, 232760 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84143] = { ["id"] = 84143, ["name"] = "Lost and Busy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84143 }, ["series"] = { 84144, 84363, 84393 }, ["description"] = "Thank the Light, an adventurer! Please, you must help me. Event coordination is a harrowing profession in the best of circumstances. I am drowning in crises! There was a small tuskarr child in need of assistance, but I have my hands full here. I last saw her headed to Leeroy's Chicken.", ["objectivesText"] = "Find Maru near Leeroy's Chicken.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
