[84144] = { ["id"] = 84144, ["name"] = "Tat Big Meanie", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84144 }, ["series"] = { 84143, 84363, 84393 }, ["description"] = "Tat big meanie stole my brovver's sleufing fingy! We need to find who it was and make them give it back! I fink it was lost past da potty over there. Here, my unco has this old bird idol that can look for clues! You can borrow it 'cause you look helpy.", ["objectivesText"] = "Use the Idol of Ohn'ahra to search for clues near the outhouses. Progress: Did you find any clues? We gotta find tat meanie!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 225252, 227363, 227364, 227443 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84214] = { ["id"] = 84214, ["name"] = "The Job", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["series"] = { 84215 }, ["description"] = "Want money? Good at smashing stuff? Not afraid of a little morally grey wealth acquisition? Well then Entrepreneur Inc. has a gig for you! Come on down to our headquarters in the Heap and speak with Skedgit Cinderbangs for more details.", ["objectivesText"] = "Speak with Skedgit Cinderbangs in The Heap.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 25784, 25785, 32865, 32866, 32867, 32868, 33457, 33458, 33459, 33460, 33461, 33462, 35844, 35846, 35848, 59044, 59045, 59046, 59096, 59097, 59098, 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355, 118075, 118076, 118077, 118078, 131452, 131512, 208128, 208129, 225947, 233289, 233298, 237812 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
