[84215] = { ["id"] = 84215, ["name"] = "The Crew", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["series"] = { 84214 }, ["description"] = "You are hired! Okay, this heist I got planned is gonna make us a lot of money, but requires a crew and a bunch of planning. I'll take care of the planning, you get the crew. We need Goldmine. Outside of Venture Co., he's one of the fastest drivers out there. Because he's outside of Venture Co., he can't be traced back to me. We also need a face that no bruiser can say no to. We need Handsome Crog . Oh, and I need my cousin Ripsnoodle . He's not the best mage, but he's family... and my boss.", ["objectivesText"] = "Gather the crew. Progress: Okay, I know some of them may not come willingly. So, we got to tell them we're gonna get lotsa money outta this heist. Like... lots of money. Because there is. Lotsa of money. I swear.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 59086, 59087, 59088, 59089, 61484, 61495, 61500, 128658, 131445, 155052, 155058, 155063, 155066, 155071, 155073, 155077, 155080, 204378 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84216] = { ["id"] = 84216, ["name"] = "The Play", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "I'm gonna go over the details of the plan. However, here is the too-long-didn't-listen version: We meet in front of the Airship Station in Bilgewater's district. Handsome Crog helps get us past the guards to the airship supply balloon there. We steal that balloon and use it to board the airship over the arena where the safe with all that loot is. Ready?", ["objectivesText"] = "Steal an Airship Supply Balloon.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 56649, 56650, 56651, 56664, 56665, 56666, 131302, 131534, 156958, 166846, 166970, 166971, 189544, 190189, 190343, 190344, 190345, 190348, 190349, 190351, 190352, 190353, 190355, 190356, 190358, 190359, 190360, 190363, 190364, 190366, 190367, 190368, 190371, 190372, 190605, 190633, 190634, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451, 211279, 235502, 237812, 246697 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228333, ["x"] = 0.51, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84217] = { ["id"] = 84217, ["name"] = "The Highst", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "Okay, we got this. Me, you, and loudmouth here are going to hop this service balloon and get up to that airship over the arena. That is where they are keeping the loot. Once we get aboard, fighting space will be tight. I got us some uniforms so we'll look like people who work there but try not to start anything. Ready?", ["objectivesText"] = "Reach the Safe.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228333, ["x"] = 0.51, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228341, ["x"] = 0.615, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84218] = { ["id"] = 84218, ["name"] = "The Getaway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "Okay... um... I \"may\" have lied about the loot. You can be mad at me all you want but we need to get away now. Get in the car! We have to gun it!", ["objectivesText"] = "Escape in the Getaway Car.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232734, 232735 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228341, ["x"] = 0.615, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
