[84220] = { ["id"] = 84220, ["name"] = "Passage to the Ringing Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84220 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 228304, ["x"] = 0.376, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 228304, ["x"] = 0.376, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
