[84221] = { ["id"] = 84221, ["name"] = "Paperwork Makes the Mine Go Under", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Name is Marty. Marty Zoomcart . Marty Zoomcart , public defender, and agent assigned to the Gallagio's case for State of Undermine . What a mouthful... Just call me Marty. So the deed holder, Rosebud Gallywix, is dead? And no one knows whodunnit. And some nobody, you, has the deed? Frankly, it's a common occurrence. Plenty of precedent. Just no time... Here's the skinny: if we don't attach some new legal owners to the deed, it's getting put up on the auction house like a pair of decade-old pants.", ["objectivesText"] = "Establish a plan to keep the Gallagio out of the auction house. Progress: I don't usually like to get wrapped up in big business. But the Gallagio, you know, it's an important establishment for the people of Undermine .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232764, 232765 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84222] = { ["id"] = 84222, ["name"] = "Secure the Perimeter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "A veritable menagerie of dangerous creatures have attacked us since we set up our encampment. While my troops can manage most threats, some of the more powerful creatures may require your expertise. Scour the island and eliminate any powerful entities that might jeopardize our operations here.", ["objectivesText"] = "Eliminate 2 rare enemies on the Siren Isle . Progress: How goes the hunt? Is our encampment safe for now?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84223] = { ["id"] = 84223, ["name"] = "Survivor's Guilt", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "We have all suffered from Xal'atath's deeds, some more than others. I am glad to be alive, even if I now feel as old as I look. <Khadgar tries to laugh but coughs instead. He waves off your worry.> Don't worry about me. But Aethas... I've heard he went back to Dalaran's crash site. And that he hasn't slept or eaten since we arrived. He wants my help, but I haven't been able to bring myself to visit the crash site. Will you go in my stead?", ["objectivesText"] = "Find Aethas Sunreaver in the Tranquil Strand.", ["rewardGold"] = 30300, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84224] = { ["id"] = 84224, ["name"] = "To Delves!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 81595, 81596, 83500, 84224 }, ["description"] = "There's more tae do in delves, <name>! Meet me in Dornogal. There's loads to discuss!", ["objectivesText"] = "Meet Brann Bronzebeard within Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 224784, 229129, 229354, 229371, 232049, 232371, 235502, 239118, 244865, 250116, 254677, 268490 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5633, ["name"] = "Delves - Season 1", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84225] = { ["id"] = 84225, ["name"] = "Eggstinction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "We should really get outta here, but... Do you see those eggs over there? If those monsters hatch them all, this place will be swarming with crabs when the storm clears. Ugh, there's just too many to destroy by hand. We're gonna need some help! Suzie's got a lot of helpful items back at the camp... or maybe my broiler will work? I dunno, champ. Grab somethin' to get rid of those eggs!", ["objectivesText"] = "Eliminate 12 Egg Tenders and 12 Spawning Clutches. Progress: Did you get rid of the eggs?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231937, ["x"] = 0.635, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227814, ["x"] = 0.691, ["y"] = 0.475 }, { ["mapID"] = 2369, ["npcID"] = 231937, ["x"] = 0.635, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 11, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84236] = { ["id"] = 84236, ["name"] = "The Great Detective", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84236 }, ["series"] = { 84237 }, ["description"] = "Adventurer, thank the Light you are here. We have a missing guest. There was a detective who was investigating the case, but I have not heard back. Could you please check in with him?", ["objectivesText"] = "Speak with Detective Jones.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84237] = { ["id"] = 84237, ["name"] = "The \"Great\" Detective", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84237 }, ["series"] = { 84236 }, ["description"] = "The missing guest? Yes, some Herrkrop fellow. Not to worry, I've already solved the case. He probably just got lost. Relax, <class>. Enjoy the festivities! Our missing guest will show up soon enough. If you don't believe me, go... I don't know... solve it yourself. Interrogate someone or other.", ["objectivesText"] = "Solve the mystery of Herrkrop's disappearance. Progress: Have you any luck in finding our missing guest?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206696, 207730, 208092, 227551 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.6265, ["y"] = 0.5125 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84241] = { ["id"] = 84241, ["name"] = "Shoreline Stand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "This storm will not drive me from my sacred duty. This cave must be defended at all costs! This new crystal may still be shrouded in mystery, but we will never understand its secrets or its relation to Beledar if we allow it to fall into the grasp of these wretches who crawl from the ocean's abyss. Stand with me, <name>. Together, we shall defend this shoreline to our final breath.", ["objectivesText"] = "Eliminate 15 Brinebound Wraith and Tide-Champion Korval . Progress: Is the crystal safe?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232297, ["x"] = 0.4364, ["y"] = 0.2404 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232297, ["x"] = 0.4364, ["y"] = 0.2404 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.4364, ["y"] = 0.2404 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84242] = { ["id"] = 84242, ["name"] = "Diving into the Heaps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Our first marks are the dynamite duo of gaming: Kayjay and Fantastic Davey. Been a few years since I was hustling macaroons in the electro-billiards halls. I wasn't bad, but those two cleaned the house out whenever they showed. They don't just win games either. They make them! Real artist-types, you know? But with great gaming, comes great debt. And it's usually to Venture Co. Meet me at the Heaps. If Rosebud's death means they're outta work, I'd bet money Venture scooped 'em up again.", ["objectivesText"] = "Meet Marty Zoomcart at Venturewood in The Heaps.", ["rewardGold"] = 147500, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226277, ["x"] = 0.5145, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84244] = { ["id"] = 84244, ["name"] = "Blackwater Beach Blast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You've done good work with Jojo. Real good. I'll stick around, seal the deal, then meet you over at Blackwater Marina for the final signature. Had my radio turned to WGOB 101.1 FM while dropping off the fifteen landfill-scented individuals earlier. DJ B. B. Rev announced there would be a battle of the bands at the marina today. Wouldn't you know it, Rosebud's Chief Executive of Entertainment is playing! The band you're looking for is the Cellar Gnomes.", ["objectivesText"] = "Meet Marty Zoomcart at Blackwater Marina.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231812, ["x"] = 0.368, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84246] = { ["id"] = 84246, ["name"] = "Witnessing Brilliance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 84246 }, ["description"] = "The time has finally come and the moment could not be more exhilarating. It's time to get to work. Join me outside, let's observe the fruits of our labor.", ["objectivesText"] = "Witness Siesbarg's Ascension.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84248] = { ["id"] = 84248, ["name"] = "A Ritual of Runes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "I went to investigate a cave nearby, and I came across some Bloodwake vrykul that were conjuring something... something that activated my threat mitigation protocols. I calculate that if they complete their ritual, it would be disastrous for the island. <name>, please assess the cave and stop their ritual before something terrible occurs!", ["objectivesText"] = "Destroy 5 Summoning Runes and eliminate Inhyldir the Cursed . Progress: Did you disrupt the ritual?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 233139, ["x"] = 0.515, ["y"] = 0.483 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 233139, ["x"] = 0.515, ["y"] = 0.483 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84249] = { ["id"] = 84249, ["name"] = "A Vat in the Pan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Our next mark is Jojo Gobdre, in the Vatworks. She was a big time chef. The real deal. And running cuisine at the Gallagio woulda meant franchise opportunities. Is there a reason she'd want Rosebud dead? Either way, we need a lead on where she's cooking these days. Luckily, I got an ol' pal who should have info. He's a little bit of a big shot for Steamwheedle, but we should be able to find him on his rooftop hideaway. We'll meet there. Come hungry.", ["objectivesText"] = "Meet Marty Zoomcart in The Vatworks.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226932, ["x"] = 0.328, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.5645, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 11, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84252] = { ["id"] = 84252, ["name"] = "Peak Precision", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Flying? It ain't for me. Sally Boltwrench wanted me to activate a bunch of survey machines to monitor the wind currents, but it's too rough up there and the heights give me the heebie jeebies. An' I get sick every time I try. Use the Go-Pack to activate the machines for me. I'll owe ya one!", ["objectivesText"] = "Activate 6 Survey Machines using the Experimental Go-Pack to help reach them. Progress: Did you switch those machines on?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230728, 230795 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232255, ["x"] = 0.422667, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227814, ["x"] = 0.691, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84254] = { ["id"] = 84254, ["name"] = "Meet and Greet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84254 }, ["series"] = { 82672 }, ["description"] = "Greetings, salutations, and happy anniversary! I am Yllana , the conductor of this symphony of celebration. I trust you are itching for fun and entertainment? Well do not fret, for there is much to do and plenty of time to do it. I've marked your map with the locations of my gleeful greeters who will tell you all about the activities in store for you. Once you've talked to them, return to me for a gift that will maximize your merriment. After all, what's a celebration without presents?", ["objectivesText"] = "Talk to the activity greeters. Progress: It's easy to get distracted. Have you spoken with the activity greeters I told you about?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84260] = { ["id"] = 84260, ["name"] = "Crafting to Order", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84260 }, ["description"] = "Hello, greetings, and welcome to the Crafter's Enclave. According to Market Reeve Vokgret, we are now operating with the Artisan's Consortium to accommodate the needs of both the earthen and the outlanders. Please speak to Ardran or Pordaz to view and place crafting orders.", ["objectivesText"] = "Talk to Ardran in the Crafter's Enclave. Progress: Have you talked to Ardran?", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["rewardItems"] = { 210796, 210799, 210802, 210805, 210808, 210814, 210930, 210933, 210936, 212664, 212667, 213611, 218336, 218337, 219150, 219946, 219949, 224828, 227890, 228338, 228916, 228917, 228919, 228931, 228932, 228933 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84274] = { ["id"] = 84274, ["name"] = "Crafting Orders: Blacksmithing", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84274 }, ["description"] = "So you are a blacksmith? You should have mentioned that earlier! Let me send you to Darean , a blacksmith of great renown, who has her shop within the Forgegrounds. I will mark it on your map. Darean has her very own Blacksmith's table", ["objectivesText"] = "Find Darean in the Forgegrounds and use her blacksmith's table . Progress: Please make use of my blacksmith's table if you need it.", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223644, ["x"] = 0.492, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
