[84287] = { ["id"] = 84287, ["name"] = "Crafting Orders: Inscription", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84287 }, ["description"] = "So you are an inscriber? I know one of the best inscribers in Dornogal . You should look for Brrigan on the southern edge of the Forgegrounds. Brrigan", ["objectivesText"] = "Find Brrigan in the Forgegrounds and use her drafting table. Progress: You are more than welcome to use my drafting table. Inscription is a rather new technique for us. There is much we can learn from your work.", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219090, ["x"] = 0.486, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
