[84288] = { ["id"] = 84288, ["name"] = "Crafting Orders: Alchemy", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84288 }, ["description"] = "So you are an alchemist? I see. You should visit Tarig . She's an alchemist like you. Tarig", ["objectivesText"] = "Find Tarig in the Forgegrounds and use her alchemist's lab bench . Progress: I would never miss an opportunity to share my expertise--or my lab bench!", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219092, ["x"] = 0.472, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84296] = { ["id"] = 84296, ["name"] = "The Trail's Gone Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84296 }, ["series"] = { 84278 }, ["description"] = "I've tracked the scent of Scrapes as far as here, but this cold air smothers our lead. I found a couple scraps of notes. Nothing useful yet, but he seems to have left a paper trail in his hurry. Look for clues that may indicate where our villain's lair is hidden. I will mark what I found on your map. Take Spirit's whistle . Call upon us when you are in need of assistance.", ["objectivesText"] = "Find Scrapes' hideout. Progress: How goes the hunt?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208092, 227664, 227665, 227671, 227672 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226952, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84298] = { ["id"] = 84298, ["name"] = "HELP WANTED: Kaja'Curiosity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<This listing is new, posted by the Bilgewater Cartel.> Do you like kaja'mite? Are ya ready to get your intellectual fix under some tropical sun? Want to develop cutting-edge tools that will only explode when we tell them to? Hop on a rocket drill to the Kaja'Coast! No prior experience required. Combat capabilities extremely welcome. Contractors are liable for their own safety. Compensation and working hours negotiable on-site. Please seek Jazz Mokkitz on the Kaja'Coast for more information.", ["objectivesText"] = "Speak with Jazz Mokkitz on the Kaja'Coast. Progress: Research takes guts, sure, but I would like to keep mine intact.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["startItems"] = { 227702 }, ["questType"] = "standard", ["flags"] = {  },
},
[84299] = { ["id"] = 84299, ["name"] = "Pirate Plunder", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "We got a good thing here, but these pirates are bad for business! They're stealin' all the special gems, an' they even made off with our Kaja'Cola stash ! Get rid of these pirate losers and recover any of the stuff they took from us!", ["objectivesText"] = "Bilge Rat forces disrupted Progress: Ya better be tellin' me them pirates is all gone!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 227453, 227670 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 12, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84300] = { ["id"] = 84300, ["name"] = "Refine, Repair, Repeat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<Jazz holds up a well-polished crystal of kaja'mite.> Most materials aren't ready to use straight outta the ground--kaja'mite included. I've got a few refined crystals to tinker with, but I'll need more. I rigged up some refiners on the slope, but halfway through the cycle elementals started beatin' on 'em pretty hard. Could you see if you could get 'em goin' again? You look like you could handle those angry rocks, and my wife likes it when I come home without injuries.", ["objectivesText"] = "Repair 6 broken Kaja'mite Refiners on the Kaja Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84301] = { ["id"] = 84301, ["name"] = "Mineral Madness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "With all these elementals wreakin' havoc, it's impossible to work out here! How are we supposed to gather raw material when they're swingin' at us with the stuff? <Jazz stops, eyes lighting up.> <name>, those elementals ARE our raw material. Smashin' 'em up is our best bet--though, you'll have to do that for me. Now, keep it movin'! Time is money, and I ain't one to waste perfectly good research funding.", ["objectivesText"] = "Clear out aggressive Kaja'mite elementals and collect 12 Raw Kaja'mite Chunks from them. Progress: Who knew this place was so elementally active? No wonder the Darkfuse needed all hands on deck out here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 227708 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84302] = { ["id"] = 84302, ["name"] = "Creative Iteration", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "Alright, <name>, time for this to get serious. You got the crystals, and I've got our parts to work with! Kaja'mite is good for containin' volatile energy. I think we can do better than Darkfuse weaponry, but first, we need a proof of concept. I've got this old, glitchy, junk shrink ray. The kaja'mite should stabilize it. If it does, we've got a potential breakthrough! I need an extra set of hands to tinker on this thing. Just follow my instructions and you'll stay in one piece. Probably.", ["objectivesText"] = "Help Jazz tinker with his shrink ray and kaja'mite.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84303] = { ["id"] = 84303, ["name"] = "Experimental Application", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<Jazz shoves the shrink ray into your hands.> Only thing left to do is test the prototype, <name>. Try using it on the elementals! If it can work on those, it'll work on anything, probably. Don't expect the effects to last, though. It's only a first iteration! And keep contained to the mines. Just in case we need to bury any problems. Oh, don't give me that look. I built this originally to make spiders easier for my wife to handle. I promise, there's at least ONE functional failsafe.", ["objectivesText"] = "Test the Kaja'Containment Device on 8 Kaja'mite Crawlers in the Lucky Break Mines.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228948 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84304] = { ["id"] = 84304, ["name"] = "A Gem-Splitting Headache", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "Hey, <name>, I'm not usually one for revenge, but I've got an idea. That big guy who tossed us around ran up this way. I'll bet you good money it's in the mines somewhere, and I bet we could get a giant sample off its body. That'd set me up real nice for future tinkering. Besides, taking it out means it won't come back, and I'd like to finish this gig intact. I've got bills to pay, and kids to feed! Try the shrink ray on that hunk o' rock. Show it who's boss! For science, of course.", ["objectivesText"] = "Use the prototype to weaken & kill the Raging Kaja'mite Gemsplitter . Progress: Good to see you in one piece. How'd it go?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 228549, 228948, 232762, 232763 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 862, ["db2PoiMapID"] = 1642, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
