[84336] = { ["id"] = 84336, ["name"] = "Spot the Difference", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84336 }, ["description"] = "Look, I'm the real detective. You believe me, right? I know--ask me anything. The good people here will be able to corroborate my story and we'll prove that I'm me.", ["objectivesText"] = "Solve the case of the shapeshifting demon. Progress: This is preposterous...", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 207730 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 }, { ["mapID"] = 71, ["npcID"] = 228661, ["x"] = 0.61, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.6265, ["y"] = 0.5125 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84352] = { ["id"] = 84352, ["name"] = "No More Walkin' Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84352, 86618, 87581 }, ["description"] = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at the Caddy Shack and see if she'll lend you some wheels.", ["objectivesText"] = "Meet Nanny Talullah on the third floor at the Caddy Shack.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225531, ["x"] = 0.426, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5772, ["name"] = "Shipping? Handled.", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
