[84363] = { ["id"] = 84363, ["name"] = "Tweasure Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84363 }, ["series"] = { 84143, 84144, 84393 }, ["description"] = "I know! We could use da stick to look for tweasures! You and Enzo go check da other ruins. Find somefing really cool! I'll meet you back at da parties.", ["objectivesText"] = "Use the Torch of Pyrreth to search for treasure around the ruins of Tanaris. Progress: Did you find any tweasure?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 227775, 227777, 227785, 227790 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229062, ["x"] = 0.362, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
