[84365] = { ["id"] = 84365, ["name"] = "Something on the Horizon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84365 }, ["series"] = { 79197, 79333, 84367 }, ["description"] = "Brann's scouts have reported sightings of reinforcements approaching the shores of Khaz Algar. He's put out the call for adventurers to join him in Dornogal.", ["objectivesText"] = "Speak to Brann Bronzebeard in Dornogal.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
