[84367] = { ["id"] = 84367, ["name"] = "A Time to Come Together", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84367 }, ["series"] = { 79197, 79333, 84365 }, ["description"] = "We ought tae be getting a whole fleet o' reinforcements soon. Just in time, I hear Alleria and Anduin are back in Dornogal. If I know Moira, she'll already be workin' with 'em tae figure out our next move. She knows how tae lead like a gryphon knows how tae fly. Best go find her before she comes looking for ye.", ["objectivesText"] = "Speak to Moira Thaurissan in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84370] = { ["id"] = 84370, ["name"] = "The Key to Success", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84370 }, ["description"] = "<A Cipher Key? Elise Starseeker might know what to do with this.>", ["objectivesText"] = "Bring the Archaic Cipher Key to Elise Starseeker in Dornogal. Progress: This map makes no sense... Champion! Good tidings I hope?", ["rewardGold"] = 234000, ["rewardXP"] = 4760, ["rewardItems"] = { 131744, 227794, 245589 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 228605, ["x"] = 0.48, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["startItems"] = { 227794 }, ["questType"] = "standard",
