[84371] = { ["id"] = 84371, ["name"] = "Lorewalking: The Blade and the High Priest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Xal'atath, the Harbinger of Void, is a cunning and dangerous foe. She has been careful to make her presence known only to a precious few. We first learned of her during the Legion's third invasion of Azeroth, but whispers say she has been around since long, long before that. This is a story of power, darkness, and deceit. Join me and I will tell you the tale of Xal'atath's mysterious past.", ["objectivesText"] = "Follow Cho's guidance to learn the story of Xal'alath's past.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 229361, 242386, 244888, 245567, 245631 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84376] = { ["id"] = 84376, ["name"] = "Property Devalued", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 84378 }, ["description"] = "<You come across a wanted poster that has been nailed on top of a for rent sign .> WANTED: Seeking able-bodied adventurer to work as security for local apartment complex. Must be capable of not dying. REWARD: Free room and board in exchange for services rendered. Interested parties should inquire upstairs at the nearby Barrelbottom Apartments for further details.", ["objectivesText"] = "Visit Barrelbottom Apartments and inquire about a room to rent. Progress: That Moz is driving me crazy! Maybe you can talk some sense into him.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84378] = { ["id"] = 84378, ["name"] = "Renter's Insurance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 84376 }, ["description"] = "It's bad enough that the old skinflint landlord is letting this place slowly fall apart, but now we got even bigger problems. Recently, those would-be gangsters up the road, the Underriders, went from petty theft and noise complaints to being a heavily armed menace. They've started trashing the place, and even attackin' us directly! What's worse, anyone who can't afford to move out are evicted for the damage those thugs caused instead. You keep us safe, you can crash here free of charge.", ["objectivesText"] = "Kill 12 Underrider biker gang members. Progress: I can't keep up with all these repairs. Someone needs to do something about those bikers!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84379] = { ["id"] = 84379, ["name"] = "Tenant Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["description"] = "<Gabi waves you over urgently. The small goblin wrings her hands together nervously trying to find the words to explain her concern.> Some goblins aren't moving out--they're being kidnapped. I know it. My friends wouldn't have moved. They wouldn't. <Gabi looks up at you imploringly with misty eyes.> Please help, <class>. Please?", ["objectivesText"] = "Rescue 8 Captured Tenants.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228860, ["x"] = 0.394667, ["y"] = 0.684667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.684667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84380] = { ["id"] = 84380, ["name"] = "Weapons Cash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["description"] = "<Inside the weapons crate you find a crumpled note written to the Underriders.> Good to see you're putting your new toys to good use. These little squatters are leaving in droves thanks to you guys! Keep up the good work and there's more where this came from. Just try not to burn the whole place down. Can't rent out an empty lot, haha! Signed, M.B.B.", ["objectivesText"] = "Destroy Underrider equipment throughout the compound. Progress: Find something?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229392 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84381] = { ["id"] = 84381, ["name"] = "Renegotiations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 86408 }, ["description"] = "That settles it! I think we both know who's responsible for this mess. It's that bastard landlord, Moz Barrelbottom ! Soon as the Underriders were dealt with, he sent his goon Jarvis on a rampage. Looks like if he can't scare us out, he's going to force us out! <Keara spits on the ground in disgust.> He won't scare us so easily. You're pretty tough, <name>. Moz's office is just across the street. Go show him he's messin' with the wrong goblins!", ["objectivesText"] = "Defeat Jarvis Bonebreaker and collect the Barrelbottom Deed from Moz Barrelbottom in his third floor office across the street. Progress: We'll be fine here. You just go deal with Moz!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 229419, 235146, 235147, 235148, 235149 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84392] = { ["id"] = 84392, ["name"] = "Hungry in Hollow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 84392 }, ["series"] = { 82843 }, ["description"] = "Hey. You looking for a great meal? Willing to wade through the mud to get it? Go see Dolena . She'll sort you out. Don't bother trying to convince her to leave that hollow, though. Believe me--we've all tried. Why someone would leave the safety of the light for that... She seems to do alright, though.", ["objectivesText"] = "Seek out Dolena in Growling Hollow", ["rewardGold"] = 30300, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 222683, ["x"] = 0.489333, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.489333, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["flags"] = {  },
