[84430] = { ["id"] = 84430, ["name"] = "Crystal Crusade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "I swore my life to protect Beledar... and now a new star sings to us from the sea. I know not what this means for the Arathi, but I do know that letting these foul creatures of the deep snatch up pieces of it is likely to lead to ill. Kill them with extreme prejudice and recover any pieces of the crystal in their possession.", ["objectivesText"] = "Recover 10 Crystal Fragments and 30 Crystal Chunks from the Naga forces. Progress: Have you recovered the Crystal Fragments ?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228780, 228787 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84432] = { ["id"] = 84432, ["name"] = "Longship Landing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "These Bloodwake vrykul have no regard for us or our research. Even when we tried to share our discoveries with them, we were attacked! They do not care that we mean the isle no harm--they want us to leave. But we cannot leave now. There is so much more to discover! Someone must show them that we're not going to go just yet and that they should leave us alone. We need to show them we will fight back.", ["objectivesText"] = "Eliminate 15 Bloodwake Vrykul. Progress: Did you convince them to leave us alone yet?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228096, ["x"] = 0.6975, ["y"] = 0.4345 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228096, ["x"] = 0.6975, ["y"] = 0.4345 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6975, ["y"] = 0.4345 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
