[84439] = { ["id"] = 84439, ["name"] = "Kaja'Conclusions", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "You've really helped me out here, <name>, but I need one more teeny tiny favor from you. <Jazz hands over an envelope stuffed to the brim with schematics and paper reports.> Could ya get this to my contract agent, Kory Hoxx ? He'll get it to HQ. You'll probably catch him in the Incontinental Hotel, putting up more gig sheets.", ["objectivesText"] = "Deliver Jazz's Report to Kory Hoxx in the Incontinental Hotel. Progress: Can't ya see I'm a little busy here? Recruitment's hard work, ya know!", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 228215 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229136, ["x"] = 0.425, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862, 2346 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84442] = { ["id"] = 84442, ["name"] = "Invitation to the Spirit Festival", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 25 }, ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 84442, 84451, 84453, 84454, 84455, 84456, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Greetings, $p. It's been too long since I've returned to Shen-zin Su. I miss him... and I miss everyone that calls him home as well. Would you like to attend the Spirit Festival? Li Li asked for you specifically. I seem to remember she fought with her father during one year's festival. However, he's the one who extended the invitation to her this time. Perhaps he just wants to see her return home. Ji will be coming along too! Join us!", ["objectivesText"] = "Meet Aysa Cloudsinger in Stormwind near the hot air balloon.", ["rewardGold"] = 31900, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 229260, ["x"] = 0.683333, ["y"] = 0.164667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.164667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard",
},
[84444] = { ["id"] = 84444, ["name"] = "Invitation to the Spirit Festival", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 84444, 84452, 84453, 84454, 84455, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Hey, $p. It's been a while since I've been back home, to Shen-zin Su. Remember that old turtle? Still wandering the Great Sea... Li Li asked me to pass along an invitation to the Spirit Festival. It's funny, I remember Li Li and her father had a huge fight about it one year. But guess who the original invite's from? Her father! I guess they get along better these days. Or maybe he just wants her to come home. Who knows? Aysa's coming along too. Will you join us?", ["objectivesText"] = "Meet Ji Firepaw in Orgrimmar by the hot air balloon.", ["rewardGold"] = 32800, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 229266, ["x"] = 0.702, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 85, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 1, ["flags"] = 1 } }, ["questType"] = "standard",
},
[84446] = { ["id"] = 84446, ["name"] = "Renown of Khaz Algar", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84446 }, ["series"] = { 82449 }, ["description"] = "There is still much we still need tae do to aid Khaz Algar. But I dunnae know much about this land past the realms of earthen. I'll have to refer ye to Faerin Lothar tae see what Hallowfall may need. Talk to her an' see if she needs any help. Ye already are acquainted, aren't ye?", ["objectivesText"] = "Speak with Faerin Lothar in Dornogal.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84451] = { ["id"] = 84451, ["name"] = "The Wanderers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 84442, 84451, 84453, 84454, 84455, 84456, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "$p! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub! I suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us. <Li Li smiles--half anxious, half something else.> Let's enjoy this together.", ["objectivesText"] = "Ride the hot air balloon to the Wandering Isle.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 229257, ["x"] = 0.682, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229339, ["x"] = 0.505, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 84, 2366 }, ["zone"] = { 1519 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84452] = { ["id"] = 84452, ["name"] = "The Wanderers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 84444, 84452, 84453, 84454, 84455, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "$p! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub! I suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us. <Li Li smiles--half anxious, half something else.> Let's enjoy this together.", ["objectivesText"] = "Ride the hot air balloon to the Wandering Isle.", ["rewardGold"] = 28900, ["rewardXP"] = 850, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 229338, ["x"] = 0.704, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229339, ["x"] = 0.505, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 85, 2366 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84453] = { ["id"] = 84453, ["name"] = "To Dai-Lo Farmstead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "My brother Chon Po has been trying to rally everyone. He sent out handwritten invitations to each village. Can you believe that? He's a brewmaster--he should've sent brew! Dai-Lo Farmstead was like a second home to us. Chon Po and I spent half our childhood there, helping with the harvests. It's where we made our very first drinks. Let's give the Dai-Lo villagers a big hit of nostalgia, and something new--as a teaser for what's to come at the festival.", ["objectivesText"] = "Journey to Dai-Lo Farmstead in the Wandering Isle.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229347, ["x"] = 0.505, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229357, ["x"] = 0.696, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84454] = { ["id"] = 84454, ["name"] = "Tide of Virmen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "I was hoping for a heartier welcome when we arrived. Unfortunately, many of the villagers are occupied in the farmland. The harvest is in full swing, and so are the virmen. We've fought these pests all my life. I don't know how they keep coming! Chon Po and I are busy setting up the drink tasting. Can you take care of the problems in the field?", ["objectivesText"] = "Take back The Rows by killing virmen, harvesting produce, and helping farmers. Progress: The Rows sound a little busy!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 229004 }, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229357, ["x"] = 0.696, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229357, ["x"] = 0.696, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84455] = { ["id"] = 84455, ["name"] = "Big Bertha", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "I love Chen's idea to entice the villagers with a brew tasting. I'm surprised I didn't think of it first! My friends were hoping to take a large portion of the harvest to the festival. But Big Bertha is missing! We need her if we ever hope to haul back all the food and drink in time. The villagers say she suddenly broke from her cart and disappeared underground. I'm worried. She may be large, but she has a soft heart. Can you go find her?", ["objectivesText"] = "Find and save Big Bertha in The Rows.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229358, ["x"] = 0.698, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229358, ["x"] = 0.698, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84456] = { ["id"] = 84456, ["name"] = "To Morning Breeze", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84451, 84453, 84454, 84455, 84456, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody has shown up. That's very strange. They're usually the ones most excited about the Spirit Festival. They'll use any excuse to make and set off their fireworks! Something must have happened. Let's go see.", ["objectivesText"] = "Journey to Morning Breeze Village in the Wandering Isle.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229349, ["x"] = 0.505, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229380, ["x"] = 0.301, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84457] = { ["id"] = 84457, ["name"] = "To Morning Breeze", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84444, 84452, 84453, 84454, 84455, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody showed up. That's odd. They're usually the ones most excited about the Spirit Festival. Any excuse to make and set off their fireworks! Something must be up. Let's find out.", ["objectivesText"] = "Journey to Morning Breeze Village in The Wandering Isle.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229348, ["x"] = 0.504, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229381, ["x"] = 0.274667, ["y"] = 0.388667 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84458] = { ["id"] = 84458, ["name"] = "Devil's in the Details", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Let's investigate the village for signs of mischief. I don't believe that the fireworks were simply misplaced. Shisai is a watchful pandaren and this is his big contribution to the festival. The theft must have happened recently. Someone must have seen something.", ["objectivesText"] = "Search for 3 clues about the missing fireworks in Morning Breeze Village.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229380, ["x"] = 0.301, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 230417, ["x"] = 0.302545, ["y"] = 0.415636 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.301, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 10, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84459] = { ["id"] = 84459, ["name"] = "Scamps Ain't It!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Shisai said the fireworks were in a barrel... <Ji paws at his face.> And... he likely put them in the wrong barrel. Amidst the festival's extensive preparation, it'd be a miracle if none of the goods were crossed. Well then, let's search the barrels! It won't take long.", ["objectivesText"] = "Search 8 Wooden Barrels in Morning Breeze Village. Progress: There sure are a lot of barrels...", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 234621, 234622, 234623, 234625 }, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229381, ["x"] = 0.274667, ["y"] = 0.388667 }, { ["mapID"] = 2366, ["npcID"] = 230864, ["x"] = 0.287, ["y"] = 0.411 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 230864, ["x"] = 0.287, ["y"] = 0.411 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.274667, ["y"] = 0.388667 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 11, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84460] = { ["id"] = 84460, ["name"] = "Red Hand or Herring?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Every clue points at the hozen stealing the fireworks! It is as Ji said. They've done it before--they'll do it again. Let us confront them right now.", ["objectivesText"] = "Confront Huk Huk , the hozen chieftain, in Fe-Feng Village. Progress: It can only be the hozen who have done it!", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 230417, ["x"] = 0.302545, ["y"] = 0.415636 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 231114, ["x"] = 0.236667, ["y"] = 0.327333 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.302545, ["y"] = 0.415636 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 12, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84461] = { ["id"] = 84461, ["name"] = "It's Not a Spirit Festival Without Spirits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "<The crane bears a letter. It's from Li Li.> Something's wrong at the Temple of Five Dawns. I need your help. Please come as soon as you can!", ["objectivesText"] = "Meet Li Li Stormstout in the Temple of Five Dawns.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229535, ["x"] = 0.5072, ["y"] = 0.5388 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229412, ["x"] = 0.515333, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.5072, ["y"] = 0.5388 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84462] = { ["id"] = 84462, ["name"] = "Patterns in Static", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "I can't find any of the spirits in the temple. How are we going to have a Spirit Festival with no spirits? Today is a celebration for all four of the elemental spirits, but perhaps they also think today is just another day. We need to find them and tell them otherwise! Look, is this the wind spirit's trail? Maybe it will lead us to Dafeng ... who can lead us to the others.", ["objectivesText"] = "Collect 30 Remnants of Wind and use their power to find Dafeng in the Temple of Five Dawns. Progress: < Dafeng floats, waiting for something.>", ["rewardGold"] = 84900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229412, ["x"] = 0.515333, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229407, ["x"] = 0.515, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84463] = { ["id"] = 84463, ["name"] = "Codependency", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Ah, $p! Are you and Li Li back for the festival? My heart warms to see your return. Not all is well today, though. The spirits seem restless and have scattered. Dafeng and I have been looking for them everywhere. Well, I found Shu and Wuguo. Unfortunately, I found them... together. They got into a fight, and do you know what happens when you mix water and earth? A mud monster, that's what! We must break them up. Fortunately, that's something I know plenty about.", ["objectivesText"] = "Free Shu and Wuguo by defeating the Mud Amalgam in Pei-Wu Forest. Progress: Did you and Jojo find the rest of the spirits? Dafeng led me here... but I'm not sure why yet.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229271, ["x"] = 0.508, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229413, ["x"] = 0.3968, ["y"] = 0.5956 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84464] = { ["id"] = 84464, ["name"] = "Lost My Spark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Dafeng led me here, but then he flew away. I think he senses Huo, the spirit of fire, nearby. Why are all the spirits in such a state today? The festival is for them, after all. I was anxious about returning home, but didn't know why. The spirits have always reflected the truth about the isle and its pandaren. If they're agitated, something must be wrong... or something has to change. <Li Li sighs and shakes her head.> For now, we need to find Huo, and quickly. This steam trail must be his.", ["objectivesText"] = "Follow the trail of steam to find Huo, the Ancient Spirit of Fire. Progress: We need to find Huo and help him!", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229413, ["x"] = 0.3968, ["y"] = 0.5956 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229413, ["x"] = 0.3968, ["y"] = 0.5956 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.3968, ["y"] = 0.5956 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 16, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84465] = { ["id"] = 84465, ["name"] = "Of Water and Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Mr. Crane told me about your success in the other villages. Now that we've found the spirits, we can begin the festivities. But before we go, $p... will you come with me to the Wood of Staves? I'd love your help gathering flowers while we're there. I hear the woods are still crawling with scamps. It's to see my... family. I'd like to pay them a visit, before the festival. Just for a moment. It's been too long.", ["objectivesText"] = "Gather 10 Blue Floristars and slay 10 Thornbranch Scamps in the Wood of Staves. Progress: This place brings back so many memories.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 235715 }, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229413, ["x"] = 0.3968, ["y"] = 0.5956 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229465, ["x"] = 0.202, ["y"] = 0.517333 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.3968, ["y"] = 0.5956 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 17, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84466] = { ["id"] = 84466, ["name"] = "Thousands of Years Ago...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "The world is changing as we speak. We've been through so much. But it's like time skips this isle. Everything is exactly as I remembered... is that a good thing, $p? Is it even possible? Even the ancients grow older. Shen-zin Su must be looking for something more, after all this time. Perhaps the spirits don't want this to just be another year. Anyway, we should head back to Wu-song Village before they start the festival without us. Let's not keep everyone waiting.", ["objectivesText"] = "Return to Wu-Song Village to begin the Spirit Festival.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229465, ["x"] = 0.202, ["y"] = 0.517333 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 231916, ["x"] = 0.525, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.517333 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 18, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84467] = { ["id"] = 84467, ["name"] = "This Was Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "<name>! I cannot believe my eyes--Shen-zin Su, the Wandering Isle? Here? And his return to the shores of his birth coincided with the annual Spirit Festival? This cannot be a coincidence. You must have restored some sense of purpose and peace to him--and within everyone here as well. I have much to explore here. But first, we must celebrate this reunion! My dear friends!", ["objectivesText"] = "Celebrate the Spirit Festival in Wu-Song Village. Progress: I never thought I would witness Shen-zin Su's return to Pandaria in my lifetime.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 235818 }, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229476, ["x"] = 0.524, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229476, ["x"] = 0.524, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 19, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84468] = { ["id"] = 84468, ["name"] = "Brew You One Better", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Ready for the brew tasting? We've caught the attention of a small crowd already. I've got something that will send their heads spinning--ingredients they've never even heard of before, and impeccable technique... <With a flourish, Chen places a ribbon of cucumber on a drink.>", ["objectivesText"] = "Distribute Chen and Chon's homebrews to the villagers. Progress: <Chen quietly observes the villagers' reactions.>", ["rewardGold"] = 157900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229357, ["x"] = 0.696, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 229357, ["x"] = 0.696, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["db2PoiUiMapID"] = 2366, ["db2PoiMapID"] = 2794, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84469] = { ["id"] = 84469, ["name"] = "Battle Pet Bingo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84469 }, ["series"] = { 84506 }, ["description"] = "Well, hi there! The grand master pet tamers from Pandaria have posted a challenge to find certain battle pets on this fancy-lookin' bingo card . All we have to do is find the pet that goes to the riddle and note it down on our bingo cards , but I'm having a hard time with the last two. It's quite easy to spot the normal pets, but these bingo cards require us to find special versions of the creatures. Hmm... They didn't say anything in the rules about getting outside help. Care to help a friend out?", ["objectivesText"] = "Find the battle pets based on the riddles. Progress: Have you any luck in finding the battle pets?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 228328, 231907 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 228276, ["x"] = 0.622, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228276, ["x"] = 0.622, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84470] = { ["id"] = 84470, ["name"] = "Dirt-Caked Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84470 }, ["description"] = "<Though unearthed and dusted off, this crate still smells of death. Regardless, Alyx would likely appreciate the supplies returned.>", ["objectivesText"] = "Return the Dirt-Caked Celebration Crate to Alyx . Progress: Yes?", ["rewardItems"] = { 228321, 228322 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 228322 }, ["questType"] = "standard", ["flags"] = {  },
