[84485] = { ["id"] = 84485, ["name"] = "Renowned with the Tazaveshi Brokers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "emissary" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 84485 }, ["description"] = "Well hey there! We want to thank you for all your help. How about you meet me in Loamm, so we get you something nice? Keep up the good work!", ["objectivesText"] = "Speak with Mimuup in Loamm.", ["rewardItems"] = { 204712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
