[84489] = { ["id"] = 84489, ["name"] = "Shopping Squee!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84489 }, ["description"] = "Now that you have an idea of some of the main attractions, let's talk shopping. The main pavilion here contains just a few of places where you can look for amazing new purchases. Do a loop and talk to the shopkeeps to see what they have to offer. Once you are done, come back and let me know if anything caught your fancy. Ta-ta!", ["objectivesText"] = "Talk to the shopkeeps. Progress: Don't be shy, you're allowed to browse. Go ahead and have a look at the wares for sale and then come back when you're done.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84490] = { ["id"] = 84490, ["name"] = "The Great Vault", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82651, 84490 }, ["description"] = "Many of Dornogal's systems have been dormant for millennia and are now back online. One that you might find useful, <race>, is the Great Vault. Once, this cache of armor and weapons would have supported the earthen in their Oathsworn duty to protect Dornogal. Now it is extended to you with the expectation that you use what you find there to aid others along your quest. The Vault is housed here in Dornogal within the Council's Treasury. The Councilward has granted you full access to its contents.", ["objectivesText"] = "Obtain a piece of loot from the Great Vault. Progress: The vault is yours to peruse, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228378 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 229336, ["x"] = 0.518, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 229336, ["x"] = 0.518, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5709, ["name"] = "Important Quests", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84506] = { ["id"] = 84506, ["name"] = "Pet Pursuit", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84506 }, ["series"] = { 84469 }, ["description"] = "Hello, adventurer! I spotted a group of battle pet tamers who were going on about a bingo game. Jepetto Joybuzz was among them and seemed to be in some distress over his progress. Why don't you see if he could use some help?", ["objectivesText"] = "Find Jepetto Joybuzz near the pet playground.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228276, ["x"] = 0.622, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4063 }, ["questType"] = "standard", ["flags"] = {  },
