[84583] = { ["id"] = 84583, ["name"] = "A Hozen On My Back", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84583 }, ["series"] = { 84595 }, ["description"] = "Hello, <name>. I don't suppose I could trouble you again? A strange couple has been causing trouble near the edge of the petting area. Perhaps you could convince the hozen to stop shouting at our guests.", ["objectivesText"] = "Confront the boisterous hozen.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208092 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229749, ["x"] = 0.618, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4063 }, ["questType"] = "standard", ["flags"] = {  },
