[84588] = { ["id"] = 84588, ["name"] = "Operation Toy Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84588 }, ["series"] = { 84563 }, ["description"] = "Nooo! A sneaky thief has taken some of my friends' toys! You're a good sleufer now, right? Can you halp my friend Yennu find his stolen toy? You'll find him on the Dragon Isles.", ["objectivesText"] = "Find the missing toys. Progress: Did you find da toys?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 161451, 228791, 228795, 229164, 229351, 229908, 229990 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
