[84595] = { ["id"] = 84595, ["name"] = "The Case of the Fur-Getting Wikket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84595 }, ["series"] = { 84583 }, ["description"] = "Riko has had enough of these blikkety tik-digglers! All Kiryn wants is to be a furry-haver, and these mankers won't give any! Kiryn says Riko needs to stop jabberings. Says taking their furries is \"stealing.\" You a helpful wikket? Find Kiryn a furry friend! Better take notes so wikket don't get stuck.", ["objectivesText"] = "Find a companion pet for Riko and Kiryn. Progress: If wikket can't find a furry, Riko will have to be a stickypaw.", ["rewardGold"] = 17450, ["rewardXP"] = 1415, ["rewardItems"] = { 191393, 208092, 228740, 228750, 228755, 231907 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229749, ["x"] = 0.618, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229749, ["x"] = 0.618, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84616] = { ["id"] = 84616, ["name"] = "Celebrate Good Fun!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84616 }, ["description"] = "Welcome to the Bronze Celebration! We invite you to enjoy our myriad of events. You might choose to mirror your pet and run around our playground. You could participate in one of our big events like Fashion Frenzy or Mount Mania. A different event begins every 15 minutes. Or you might fancy yourself a challenge. If so seek out Chromie as she cleans up her Codex to prepare for her tours. Any event will do, as long as you are having fun!", ["objectivesText"] = "Participate in activities around the celebration and tasks put forward by those visiting. Progress: Are you enjoying our fine celebration?", ["rewardGold"] = 29500, ["rewardXP"] = 175, ["rewardItems"] = { 127696, 224157 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard",
},
[84619] = { ["id"] = 84619, ["name"] = "Ooker Dooker Literature Club", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84619 }, ["description"] = "The hozen in the Bilge Rat crew are master scavengers. For years, they've been visiting this island, snatching up anything that might be of value. Among their spoils are many research materials that could help unlock the history of this place. Infiltrate their camp, board their ships, and recover whatever books, scrolls, and documents you can find.", ["objectivesText"] = "Acquire various writing from the Bilge Rat ships and landing area. Progress: Did you find anything worth reading?", ["rewardXP"] = 11765, ["rewardItems"] = { 231786, 231788, 231802, 231809, 231812, 231813 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84621] = { ["id"] = 84621, ["name"] = "Squire's Spurs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "You come to Campalot to pledge fealty? Become Knight of the Brown Table? Not have look of tenderfoot, but even bravest knight start as squire. Earn spurs. Learn humility. Prove you have learned it in same way. See what can do to help around castle. Might be good example to other squires, too.", ["objectivesText"] = "Help out around Campalot. Progress: Hmm, think missed spot.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218864, ["x"] = 0.668, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218864, ["x"] = 0.668, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
