[84627] = { ["id"] = 84627, ["name"] = "Three Heads of the Deep", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "The reach of these creatures is truly frightening! I have encountered them countless times in the Imperial waters. I know their strategies well, and I have a plan to deal with them. My scouts have pinpointed the location of three of their leaders. Eliminate them, and we'll seize the advantage.", ["objectivesText"] = "Eliminate Warlord Thresh , Extractor Silsai, and Nereu of the Silent Wave Progress: Have you eliminated their leaders?", ["rewardGold"] = 309800, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84638] = { ["id"] = 84638, ["name"] = "Trouble in the Highlands", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Both Geya'rah and Danath have received word of unrest in the Arathi Highlands--civil unrest in Stromgarde, and raids on Mag'har and Stromic outposts. Danath and Geya'rah are returning to their homes, Stromgarde and Hammerfall, to defuse tensions. I asked to accompany them. I have long wanted to reconnect myself and my people to the Arathi. I also want to learn more about the Horde. Geya'rah was willing, but... Danath took some convincing. Though, I may have implied you were joining me...", ["objectivesText"] = "Travel to the Arathi Highlands via the portal in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84639] = { ["id"] = 84639, ["name"] = "Torches and Tar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "We've been attacked before. But this time... <Walker shudders.> This was different. They didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs. I don't know what they're going to do with it, but... I can guess. They're going to burn something down. You need to stop them before they do another homestead harm!", ["objectivesText"] = "Retrieve 10 Stolen Torches from Defias bandits and 10 Barrels of Tar from Newstead Farm. Progress: I hope whatever they're planning doesn't involve my neighbors. Or Stromgarde!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229094, 229095 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84640] = { ["id"] = 84640, ["name"] = "Emblematic of Things to Come", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["series"] = { 84641 }, ["description"] = "<This Defias bandit was carrying a badge with an unfamiliar emblem . The emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red. Perhaps Danath can identify it.>", ["objectivesText"] = "Bring the Unfamiliar Emblem to Danath Trollbane at Newstead Farm. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["rewardItems"] = { 228963 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["startItems"] = { 228963 }, ["questType"] = "standard", ["flags"] = {  },
},
[84641] = { ["id"] = 84641, ["name"] = "Ill Tidings", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["series"] = { 84640 }, ["description"] = "A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands... Stromgarde was right to send a missive asking for my return. What is going on here? I placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.", ["objectivesText"] = "Meet Danath Trollbane at the gates of Stromgarde Keep.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["rewardItems"] = { 197846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84643] = { ["id"] = 84643, ["name"] = "Curfew Kerfuffle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order. Marran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it. As my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.", ["objectivesText"] = "Deal with 15 Marran Supporters in Stromgarde. Progress: I understand that curfews are unpopular, but we really need one right now.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84645] = { ["id"] = 84645, ["name"] = "Deputy Delivery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks. Nials was too busy, so I took it upon myself to write official requests for aid. Most are simple and straightforward--writs for supplies and such for the Stromic army. The desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot. As my deputies, would you enforce my requests for aid?", ["objectivesText"] = "Deliver Brewston's request writs to people in Stromgarde. Progress: I know some won't be happy with what we're requesting of them, but it's what's best for Stromgarde and its people.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84649] = { ["id"] = 84649, ["name"] = "Marran Trollbane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "I am Colonel Veronica Nials , and I am in command of Stromgarde in Lord Trollbane's absence. I'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. Her actions during his absence led him to imprison her when he returned. That said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.", ["objectivesText"] = "Observe the meeting between Faerin Lothar and Marran Trollbane in the barracks of Stromgarde Keep.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84650] = { ["id"] = 84650, ["name"] = "Finding Refuge at Refuge Pointe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here. He may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there. You might catch up with him there.", ["objectivesText"] = "Look for Danath at Refuge Pointe in the Arathi Highlands . Progress: It's good to see humans and orcs banding together to help one another. If only the Arathi here could have seen what I did at Khaz Algar.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235345 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84651] = { ["id"] = 84651, ["name"] = "A Familiar Face", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources. Now they are better coordinated. As if they are working together as a group. That's bad news for everyone. But rivals don't come together without a strong leader. And without them, they will fall. If you're willing, find the leader of this attack on Refuge Pointe and eliminate them.", ["objectivesText"] = "Defeat the leader of the attack on Refuge Pointe. Progress: Go. I will protect these people until your return.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84652] = { ["id"] = 84652, ["name"] = "Supply Run", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. Hammerfall does what it can to help, but we too fight in Khaz Algar. We've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources. But there may be a way to help more people. Vikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.", ["objectivesText"] = "Collect 4 Supply Crates from Refuge Pointe.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 194123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84653] = { ["id"] = 84653, ["name"] = "DEPRECATED", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84653 }, ["description"] = "<You find another one of the strange rings. This time from a Scarlet Crusade member.> <You should talk to Faerin about it. This is getting suspicious.>", ["objectivesText"] = "Bring the Scarlet Ring to Faerin in the Arathi Highlands .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 94219, 128823, 128868, 209353, 228964 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 228964 }, ["questType"] = "standard", ["flags"] = {  },
},
[84656] = { ["id"] = 84656, ["name"] = "Onward to Hammerfall", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84651, 84652, 84656, 84657, 84658, 84659, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 85529, 87299, 91039 }, ["description"] = "First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. Different groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. Also, Joseph is directly involved. This all seems connected... and it leads back to Marran. Danath needs to know what's going on. If he's not here, he should already be at Hammerfall. We should head there as soon as possible.", ["objectivesText"] = "Meet Faerin Lothar at Hammerfall in the Arathi Highlands .", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84657] = { ["id"] = 84657, ["name"] = "Return to Stromgarde", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance. We need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search! Come, <name>. There's no time to waste!", ["objectivesText"] = "Return to Stromgarde and enlist Colonel Nials's aid in finding Danath.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 23, ["flags"] = 1 }, { ["id"] = 5947, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84658] = { ["id"] = 84658, ["name"] = "Finding Family", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Where's my mama? My papa? Ellie ? <Maggie looks around with tears in her eyes.> I was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here. I don't know where Mama and Papa and Ellie are. Can you find them for us? Clarabelle is starting to get worried... <Maggie sniffles.>", ["objectivesText"] = "Discover the fates of Marshall Wiltshire, Sharon Wiltshire, and Ellie at Newstead Farm. Progress: Ellie must be so scared!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230000 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84659] = { ["id"] = 84659, ["name"] = "The Search for Faerin", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building. Go find her. Hopefully, she's still alive... And see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere. The more information we have, the more we can use against them when we fight back.", ["objectivesText"] = "Search the structures in Stromgarde for Faerin and information on the Red Dawn. Progress: Have you found Faerin?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 24, ["flags"] = 1 }, { ["id"] = 5947, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84664] = { ["id"] = 84664, ["name"] = "Making the Underworld Go Round", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 84664 }, ["description"] = "Hey there, 'Overcrawler.' You're lookin' more than a little out of your element there. You get run over by an airship or something? Whatever. Doesn't matter. Take it from one outsider to another, if you're going to survive down here you're gonna need to learn the rules of the road. Gold's all well and good where you came from, but down here you're gonna need Kej, and lots of it. Now here. Consider this a token of good will from Lady Pedipalps up there. Go get yourself something nice.", ["objectivesText"] = "Spend Kej at one of the vendors in the Weaver's Lair. Progress: What, you allergic to retail therapy or something? Get out there and live a little!", ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84667] = { ["id"] = 84667, ["name"] = "The G.O.L.E.M. of Progress", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84667, 84672, 84673, 84674, 84675 }, ["description"] = "The citizens of Undermine cry out for help! They need protection! They need joy! They need to get by! As an inventor, I've spent my life building somethin' that'll solve our people's problems, and it's just about ready for a test run. I'm calling it my Goblin Optimal Livability Enhancement Machine, or G.O.L.E.M. for short! Find some problems and take it out for a spin- and take my son with you! Pitz doesn't have an inventor's bone in his body, but certainly he can yak it up with the neighbors.", ["objectivesText"] = "Tour the Vatworks with the G.O.L.E.M. and solve problems for Gart Pocketz, \"Cranky\" Nan, and the children of Undermine . Progress: Pops is really over the moon about this G.O.L.E.M. thing. I hope it works out for him.", ["rewardGold"] = 309800, ["rewardItems"] = { 235532, 235533 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 230554, ["x"] = 0.274667, ["y"] = 0.623333 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231517, ["x"] = 0.371333, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.274667, ["y"] = 0.623333 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5741, ["name"] = "The G.O.L.E.M. of Progress", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84672] = { ["id"] = 84672, ["name"] = "Garbage Day", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84667, 84672, 84673, 84674, 84675 }, ["description"] = "My old man's got all these crazy ideas about helping the world... I dunno. It's all a bit over my head, but I guess that's why I was never the inventor he wanted me to be. Still, I've got some thoughts on how to solve problems around here. Like those dang rodents getting litter all over the streets! It might not revitalize the spirit of the community or whatever, but I bet people would be happier if we cleaned up the streets.", ["objectivesText"] = "Collect 12 pieces of litter and use the G.O.L.E.M.'s incinerator function to dispose of them. Progress: Toxic fumes? Nah, that's just what Undermine smells like!", ["rewardGold"] = 309800, ["rewardItems"] = { 49040, 229805, 229824, 229825, 233202 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 230555, ["x"] = 0.275, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231517, ["x"] = 0.371333, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5741, ["name"] = "The G.O.L.E.M. of Progress", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84673] = { ["id"] = 84673, ["name"] = "World's Okayest Inventor", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84667, 84672, 84673, 84674, 84675 }, ["description"] = "I'm... not the inventor my old man is. Or much of an inventor at all, really. My masterwork is over by the wall there, but to be honest, there's a lot of work that still needs to be done to get it to do... anything. But this! This could be my big chance to prove to Pops that I've got what it takes to make him proud! All we need to do is actually, uh, figure out how to repair this thing. How hard could it be?", ["objectivesText"] = "Help Pitz repair the G.O.L.E.M. Progress: Is it... working?", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231517, ["x"] = 0.371333, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231517, ["x"] = 0.371333, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.371333, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5741, ["name"] = "The G.O.L.E.M. of Progress", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84674] = { ["id"] = 84674, ["name"] = "The G.O.L.E.M. Goes Berserk!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84667, 84672, 84673, 84674, 84675 }, ["description"] = "The G.O.L.E.M.'s gone berserk! Haywire! Bonkers! I gotta go chase it down--who knows what kinda trouble an invention that powerful could cause! Plus, imagine how mad my old man would be if we lost it! I hate to ask you to clean up my messes, but someone's gotta hang back and get everything in order again. Could you do that?", ["objectivesText"] = "Calm the chaos caused by the G.O.L.E.M. Progress: Pitz! Has anyone seen Pitz?", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231517, ["x"] = 0.371333, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232180, ["x"] = 0.396, ["y"] = 0.612667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.371333, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5741, ["name"] = "The G.O.L.E.M. of Progress", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84675] = { ["id"] = 84675, ["name"] = "Showdown in the Attic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84667, 84672, 84673, 84674, 84675 }, ["description"] = "I've been so blind! Everything's falling apart! The neighborhood is worse off than ever, and the G.O.L.E.M.'s to blame! And my boy, my dear Pitz... He ran into this building to try and stop the contraption. I was so hard on him, and now I might never see him again... You gotta find him. And stop that thing once and for all.", ["objectivesText"] = "Rescue Pitz and destroy the G.O.L.E.M. Progress: My hubris... that's the first thing they tell you in inventor school! Why didn't I listen!", ["rewardGold"] = 309800, ["rewardItems"] = { 230731, 233202, 260700 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 232180, ["x"] = 0.396, ["y"] = 0.612667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232180, ["x"] = 0.396, ["y"] = 0.612667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.612667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5741, ["name"] = "The G.O.L.E.M. of Progress", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84680] = { ["id"] = 84680, ["name"] = "Rock 'n Stone Revival", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "The attacking vrykul harness salt and brine elementals, turning them against their foes. To counter their assault, we can harness them as well. Use this Rock Reviver to unleash the elementals residing within nearby stones, transforming them into powerful allies. With their help, we can defeat this vrykul threat.", ["objectivesText"] = "8 Restless Pebbles or Stones revived, 8 Bloodbrine horrors and the Bloodbrine Monstrosity defeated. Progress: Have you stopped the vrykul and their elemental thralls?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228988 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228096, ["x"] = 0.6975, ["y"] = 0.4345 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228096, ["x"] = 0.6975, ["y"] = 0.4345 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6975, ["y"] = 0.4345 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84682] = { ["id"] = 84682, ["name"] = "Of Pacts and Patrons", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 84682 }, ["description"] = "The Severed Threads is ready for you and your allies. You will be a lit torch to Ansurek's webs. The General, the Vizier, and, myself, the Weaver, each have differing methods of combating our foes... and different benefits of aiding our accomplices. You may prefer to prioritize one, or perhaps to dabble with all three instead. Meet with our representatives, and inform yourself on our varying practices. Then you may forge your first Pact. Don't worry, little morsel, no choice is ever permanent.", ["objectivesText"] = "Speak with the representatives of the Severed Threads, then forge your first Pact. Progress: Have you considered your options?", ["rewardXP"] = 14705, ["rewardItems"] = { 223276, 223278, 223279 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questType"] = "standard", ["flags"] = {  },
},
[84683] = { ["id"] = 84683, ["name"] = "Into the Gutter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "What're you doing here? Sabotagin'? I can understand that. Things are way out of hand. But if we explode this pipe here, it'll get even worse. Black Blood everywhere. Maybe together we could come up with somethin' real to do. Meet me in Gutterville. We'll talk more, away from these awful slimes!", ["objectivesText"] = "Meet Pamsy in Gutterville.", ["rewardGold"] = 28900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225591, ["x"] = 0.695, ["y"] = 0.841 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225772, ["x"] = 0.7088, ["y"] = 0.8652 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.841 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84684] = { ["id"] = 84684, ["name"] = "Ratts' Race", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84684 }, ["description"] = "I saw a vulpera acting very suspicious. She seemed... on edge. I think I saw a knife at her side and a look of dark magic in her eyes. She noticed me staring and immediately fled. Is she a wanted criminal? She... dropped this. Here.", ["objectivesText"] = "Track down Ratts. Progress: <Ratts seems to have dropped this gem in her haste.>", ["rewardXP"] = 1770, ["rewardItems"] = { 44124, 116812, 127394, 136898, 168123, 208092, 228934, 228935, 228936, 228937, 228938, 228941 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 230042, ["x"] = 0.55, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84693] = { ["id"] = 84693, ["name"] = "Weaver's Lair Profession Table", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 84693 }, ["description"] = "Present this token to Ak'itaz in the Weaver's Lair to have your own personal profession table constructed.", ["objectivesText"] = "Speak with Ak'itaz in the Weaver's Lair. Provided item:", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["rewardItems"] = { 228946 }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 230202, ["x"] = 0.566, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["startItems"] = { 228946 }, ["questType"] = "standard", ["flags"] = {  },
