[84700] = { ["id"] = 84700, ["name"] = "Pacts Below", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84700 }, ["description"] = "This weave-rat carries a note upon its body. It's addressed to you, from the Widow Arak'nai . \"Dearest morsel, Myself and the other members of our Severed Threads triumvirate request your presence. Azj-Kahet", ["objectivesText"] = "Go to the Widow Arak'nai in the Weaver's Lair.", ["rewardGold"] = 30300, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 230098, ["x"] = 0.461, ["y"] = 0.497 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84701] = { ["id"] = 84701, ["name"] = "The Speaker", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84701 }, ["description"] = "So there is someone else who has experienced something close to what I experienced. Yet it is not the same. I must speak with him.", ["objectivesText"] = "Speak to Magni in Dornogal .", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["rewardItems"] = { 169903, 237812 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 227499, ["x"] = 0.422, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 227503, ["x"] = 0.355, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84704] = { ["id"] = 84704, ["name"] = "A Different Point of View", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "Danath is not here. Faerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. I will dispatch outriders immediately to search for him. While we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them. Distribute the crates directly to them. I'm sure they will be grateful for the food inside.", ["objectivesText"] = "Place 4 Supply Crates next to Arathi Refugees taking shelter in Hammerfall.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84705] = { ["id"] = 84705, ["name"] = "Withering the Witherbark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "The Witherbark have always been an annoyance since I have been here. But now? Something has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame. Eitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. But we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders! Make them think twice about that.", ["objectivesText"] = "Slay 15 Witherbark trolls at Witherbark Village.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84706] = { ["id"] = 84706, ["name"] = "Crime Family", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. But he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks. He has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.", ["objectivesText"] = "Save Crestor, Holt, and Perry from the Witherbark trolls in Witherbark Village. Progress: You'd better move quickly. Witherbark don't keep prisoners for long.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84707] = { ["id"] = 84707, ["name"] = "To See a Troll", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. I have told him we would go and give her the news. She's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. I can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde. Let's go. We can look for Danath while we're out there.", ["objectivesText"] = "Meet Overlord Geya'rah at Go'Shek Farm.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84708] = { ["id"] = 84708, ["name"] = "The Syndicate Strikes Back", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended! Let's go <name>. We must defend our home!", ["objectivesText"] = "Meet Overlord Geya'rah at Hammerfall.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84709] = { ["id"] = 84709, ["name"] = "Hammerfall Down", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "< Eitrigg growls in frustration.> I was such a fool! I should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall. And were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides... But now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. Those spies have had enough of my open hand. Now they'll suffer my fists!", ["objectivesText"] = "Eliminate Syndicate soldiers and save trapped civilians in Hammerfall. Progress: The Syndicate... I haven't seen them in this number in many years.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84710] = { ["id"] = 84710, ["name"] = "Once Bitten Twice Shy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84651, 84652, 84656, 84657, 84658, 84659, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 85529, 87299, 91039 }, ["description"] = "I caught a glimpse of who was leading the attack. It looks like Joseph the Enlightened may be less full of hot air than we thought he was. Is he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.", ["objectivesText"] = "Defeat Joseph the Enlightened in Hammerfall. Progress: I fully expect him to run away again like the coward he is.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84711] = { ["id"] = 84711, ["name"] = "Danath's Disappearance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "My outriders discovered a destroyed caravan on the road. Around it were the bodies of Stromic soldiers. It could be Danath's escort. Or it could be another hapless group. Either way, we must investigate. Let us hope Danath is not among the dead.", ["objectivesText"] = "Meet Overlord Geya'rah at the Arathi Highlands crossroads.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84712] = { ["id"] = 84712, ["name"] = "False Flag", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently. If Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable. <Geya'rah grimaces.> We must search for Danath among the dead and find out what happened here. Leave no stone left unturned.", ["objectivesText"] = "Investigate the area for clues as to Danath's disappearance.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84713] = { ["id"] = 84713, ["name"] = "Fallen Fortress", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "If Danath's kidnappers want to keep him from prying eyes, Ar'gorok is the perfect place. It's been abandoned for years, but its buildings still stand. All the \"Red Dawn\" could be there and no one would be the wiser. We must find Danath quickly, $p. Hammerfall is vulnerable and tensions are high. A missing leader is just the excuse Marran needs to start a war.", ["objectivesText"] = "Meet Eitrigg at Ar'gorok.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 26, ["flags"] = 1 }, { ["id"] = 5948, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84714] = { ["id"] = 84714, ["name"] = "From Ironforge With Love", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner. And I'm sure they've brought their spoils with them. It may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands . See if they are carrying anything with them.", ["objectivesText"] = "Collect 20 Stolen Ironforge Supplies from Red Dawn troops within Ar'gorok. Progress: Who knows what we will find. What they've stolen could have come from here in the Arathi Highlands , or as far as the Horde or Alliance capitals.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235996 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 28, ["flags"] = 1 }, { ["id"] = 5948, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84715] = { ["id"] = 84715, ["name"] = "The Search for Danath", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "Using Ar'gorok as a base was clever. Very clever. It looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here. Search the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. Let's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.", ["objectivesText"] = "Search the structures in Ar'gorok for Danath and information on the Red Dawn. Progress: Danath is here but we need a key to open the door!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 27, ["flags"] = 1 }, { ["id"] = 5948, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84716] = { ["id"] = 84716, ["name"] = "Returning to Stromgarde", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde. My kidnapping was just the start. Colonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup! Marran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\" <Danath's face is red with fury, but his eyes water with tears.> We must gather our allies... and confront these traitors!", ["objectivesText"] = "Meet your allies at Stromgarde Keep.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 29, ["flags"] = 1 }, { ["id"] = 5948, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84717] = { ["id"] = 84717, ["name"] = "Rise of the Red Dawn", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84651, 84652, 84656, 84657, 84658, 84659, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 85529, 87299, 91039 }, ["description"] = "Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed. But after seeing Joseph the Enlightened 's handiwork first hand... Despite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down. He's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.", ["objectivesText"] = "Defeat Joseph the Enlightened and help Danath and Eitrigg .", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardItems"] = { 239135, 239136 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84719] = { ["id"] = 84719, ["name"] = "The Expedition Awaits", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "Greetings, <name>! Are you here to answer the Siren Isle 's call to adventure? Recently, a goblin salvage team discovered an isle with a strange \"singing crystal\" at its center. Like the goblins, the Arathi of Hallowfall have taken a keen interest in this crystal--as have we. We've been preparing an expedition to the isle! Most of the expedition has gone ahead, but the goblins last vessel is set to leave momentarily. If you hurry, you can catch them before they leave and join us!", ["objectivesText"] = "Meet Skaggit by the East Gate of Dornogal.", ["rewardGold"] = 30900, ["rewardItems"] = { 228411, 228640 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 232132, ["x"] = 0.418, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 230235, ["x"] = 0.732, ["y"] = 0.06 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["db2QuestHubAreaPoiID"] = 7898, ["questType"] = "standard", ["flags"] = {  },
},
[84720] = { ["id"] = 84720, ["name"] = "To the Siren Isle!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "The Siren Isle is a myst'ry. A potentially profitable one. My crew thought they hit it big when they found a deserted island with some strange, singin' crystal... Turns out, everyone in Dornogal is interested in unclaimed \"strange singin' crystals.\" Both the Arathi and earthen scrambled quick an' were off before we could even charter a zeppelin! Fortunately for us, Ricket and crew have gone ahead to set up. We're the last to depart, an' I'm itchin' to go. What're we waitin' on?", ["objectivesText"] = "Speak with Skaggit to journey to the Siren Isle .", ["rewardGold"] = 154900, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 230235, ["x"] = 0.732, ["y"] = 0.06 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230238, ["x"] = 0.6965, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.06 }, ["mapCandidates"] = { ["npc"] = { 2339, 2369 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84721] = { ["id"] = 84721, ["name"] = "To Scan a Crystal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "In order to understand the \"singing crystal\" at the heart of the island, we will need some special machinery. We have forged a device to scan its exposed facets, but the crystal's energies are far too complex to read. It has a highly unusual energy signature. The goblins and Arathi seem keen to contribute, so let us proceed with their help. Take my toolbox and retrieve the prototype and the components the Arathi and goblins have prepared.", ["objectivesText"] = "Assist Bargus by collecting the earthen prototype , the Arathi's focus and the goblin's power source. Progress: Normally, our technology is quite capable when it comes to crystals and the energies found within them. But the energies found here are anomalous and don't synchronize with our technology...", ["rewardGold"] = 309800, ["rewardItems"] = { 230770, 230771, 230773, 230851 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84722] = { ["id"] = 84722, ["name"] = "Facet-nating Signals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "Intriguing! These radiant remnants from the Arathi seemed to have given our device the necessary focus it needed. All that remains is to attune it properly to its size. In order to attune to the signal, we'll need to set up some pylons around the site. There is testing to initiate, <name>. Follow me if you would like to assist me.", ["objectivesText"] = "Meet Bargus by the Crystal and help him set up the pylons. Progress: Once the pylons are operational, I should be able to triangulate the signal.", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231140, ["x"] = 0.4815, ["y"] = 0.4415 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84723] = { ["id"] = 84723, ["name"] = "Buried Secrets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15827, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "These ruins are... quite old. Well, old by most outlanders' standards. Which begs the question: was finding this chamber the unfriendly outlanders' directive, or was it finding the tablet? One clue is that my readings suggest energy is flowing through the tablet as a conduit rather than originating from it. Shall we take a closer look? Perhaps investigation will yield some answers--and the source of the energy readings.", ["objectivesText"] = "Investigate the ruins and find the source of the signal.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230271, ["x"] = 0.497333, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.497333, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 15827 } }, ["db2PoiUiMapID"] = 2375, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84724] = { ["id"] = 84724, ["name"] = "The Radiant Vault", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15827, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "This vault... this crystal... Who made this place? Who lived here? And who is this \"Cyrce\" we keep seeing mentioned on the tablets? When we set off to learn about the crystal, I did not anticipate discovering the remnants of an ancient civilization far beneath the earth. < Bargus ruffles his wiry moustache before glancing at you.> This bears closer examination, don't you think?", ["objectivesText"] = "Investigate the Crystal Shrine. Progress: It would seem we've made quite the discovery...", ["rewardItems"] = { 229001, 229002 }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230351, ["x"] = 0.711, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 15827 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84725] = { ["id"] = 84725, ["name"] = "The Circlet Calls", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "< Angorla peers at you from over her spectacles with excitement.> Can you hear it, <name>? This small, humble citrine is calling out to the circlet... just as the Siren Crystal called out to you and to all of us. I am uncertain what will happen when you reunify them... but there's only one way to find out. Place the circlet upon your finger and socket the citrine into the setting.", ["objectivesText"] = "Equip Cyrce's Circlet and socket the Windsinger's Runed Citrine into the Singing Wind Socket. Then, remove the Windsinger's Runed Citrine from the socket. Progress: Have you placed the citrine into the circlet, <name>?", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711333, ["y"] = 0.441333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84726] = { ["id"] = 84726, ["name"] = "Uncovered Mysteries", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "< Angorla takes your hand in hers and examines the crystal-embedded circlet closely.> Can you feel the energy humming through it, <name>? The circlet feels... awake. Perhaps more secrets lie around the isle, waiting for you to uncover them. Dawn encouraged us to explore and learn about this isle, but I've got my work cut out for me here. Why don't you see what other secrets you can find?", ["objectivesText"] = "Uncover hidden secrets around the Siren Isle . Progress: What have you found? Another treasure, perhaps?", ["rewardGold"] = 619600, ["rewardItems"] = { 229365, 232860, 232861, 232862 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711333, ["y"] = 0.441333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84727] = { ["id"] = 84727, ["name"] = "The Second Signal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "An unexpected development. The energy signature appears to have a secondary source--and it is just north of here. Curiosity activated. Judging from the estimated size of the crystal, I theorize it might be a secondary exposed facet. Further investigation is required. Follow me.", ["objectivesText"] = "Follow Bargus north.", ["rewardGold"] = 154900, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231140, ["x"] = 0.4815, ["y"] = 0.4415 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 233501, ["x"] = 0.435, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.4815, ["y"] = 0.4415 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84728] = { ["id"] = 84728, ["name"] = "Reforged Anew", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "The cracked citrine you found seems to be a perfect fit for one of the sockets found in the ring, yet... <As Angorla sockets the shard into the ring, the citrine wiggles loose and pops out.> The ring appears to be rejecting the piece. If we can repair the citrine and stabilize the energy within the shard, perhaps the ring will accept it? Since you've been so helpful with Bargus, care to lend another hand?", ["objectivesText"] = "Help Angorla repair the Citrine. Progress: A fractured citrine is hardly an obstacle!", ["rewardGold"] = 232300, ["rewardItems"] = { 228640 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711333, ["y"] = 0.441333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84730] = { ["id"] = 84730, ["name"] = "An Armored Charge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["requiredRaces"] = { 3, 34, 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84730 }, ["description"] = "The inorganic material of this island is peculiar. The effects of salt water and years of storm erosion have enriched the minerals of this place. And enriched minerals are exactly the type of material an Ordinant seeks to infuse into new armaments. Bring me a considerable amount of storm-flecked debris from the isle's myriad of creatures. I would like to see if they are suitable for my craft.", ["objectivesText"] = "Collect 50 storm-flecked debris . Debris can be looted from creatures across the Siren Isle . Progress: Have you found any storm-flecked debris ? It should be somewhat plentiful here if you're willing to look.", ["rewardItems"] = { 234455 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84735] = { ["id"] = 84735, ["name"] = "Truth of the Dark Irons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84735 }, ["description"] = "Few know the truth of the Dark Iron clan. Even fewer have seen it for themselves. The Timewalkers have agreed to take us back. They will send us to the time when our clan lost its emperor. And in doing so, I hope I can show you everything that came from that defeat. The good. The bad... Will you see the truth for yourself?", ["objectivesText"] = "Defeat Emperor Dagran Thaurissan in the Return to Blackrock Depths raid. Progress: I will guide you along your path. Though the end of it... I don't know if I can bear to witness that again, champion.", ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84740] = { ["id"] = 84740, ["name"] = "Bridge to Nowhere", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84741, 84915 }, ["description"] = "Are you heading to the dunes? I'm looking for my sister, Shahata. I don't know if she's alive, but I have to find her. The only place I can think to start the search is our village. K'aresh is nothing like I remember. I need landmarks--anything I can recognize to navigate by. Take this echo surveyor . It will reveal traces of the past--hopefully enough for me to orient us.", ["objectivesText"] = "Use the Echo Surveyor to help Om'fennad find his way.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 229423 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.7008, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84741] = { ["id"] = 84741, ["name"] = "Signs in the Sands", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84740, 84915 }, ["description"] = "Things are starting to feel familiar. I think I know the way back to my village. I should tell you... I'm not just looking for my sister. Our mother died when I was studying in the cities. Shahata buried her under her favorite tree, but I wasn't there. I swore I would come home to conduct the funeral rites, but I didn't make it in time. I have left my oath unfulfilled for far too long. I owe it to mother to at least try now. Come--let's search the village.", ["objectivesText"] = "Follow Om'fennad to his village. Progress: This can't be it! There must be something left.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.7008, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84755] = { ["id"] = 84755, ["name"] = "The Final Toy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84755 }, ["series"] = { 84756 }, ["description"] = "Maru discovered that one of her toys is now missing! Could this be related to the other missing toys that you previously helped her friends with?", ["objectivesText"] = "Speak with Maru .", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 229164, 229196 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84756] = { ["id"] = 84756, ["name"] = "The Toy Thief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84756 }, ["series"] = { 84755 }, ["description"] = "My toy! It's been stolen! We have to figure out da culprit before they take more toys!", ["objectivesText"] = "Discover the toy thief. Progress: Did you find my toy?", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 229196, 229350, 229358, 229990, 229992, 232364 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84759] = { ["id"] = 84759, ["name"] = "Ill-met in Starlight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["description"] = "I used to practice what I would say when I saw my brother again. Then I stopped believing I would... He's been away all this time, and now he comes to ask for heirlooms? I dug our mother's grave beside her favorite tree. Alone. He should have come back then, I don't have time to help him ease his conscience now. If you two are so set on talking, at least have the sense not to do it in the open. Come to my camp--we'll speak there.", ["objectivesText"] = "Meet Shahata at her camp.", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230789, ["x"] = 0.606, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84760] = { ["id"] = 84760, ["name"] = "A Friendly Warning", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["description"] = "Before the Devouring, the Sufaadi were priests. There were customs of courtesy and charity. Those were erased with the rest of K'aresh . If the Wastelanders think I won't retaliate, they'll never stop targeting me. I think you understand the value of a show of force. Kill their leaders--let it be a warning for the others.", ["objectivesText"] = "Slay Soulbinder Sabeel and Duelist Xaheen . Progress: Hard to believe they were once priests.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84761] = { ["id"] = 84761, ["name"] = "Toil and Trespass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["description"] = "Fennad picked a poor time to ask for my help. I'm leaving as soon as I recover my supplies from the Sufaadi. I was passing through when they attacked, and they could have killed me if Ruya hadn't carried me off. I followed them back to Sufaad, but there are too many for me to deal with. If you help me recover my supplies, I'll see what I can do to help Fennad.", ["objectivesText"] = "Recover Shahata 's stolen supplies. Progress: Hopefully they haven't used everything up.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237038 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84762] = { ["id"] = 84762, ["name"] = "We Are Our Words", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["description"] = "I had a necklace that our mother beaded. The Sufaadi took it when they robbed me. Things from old K'aresh are rare. If the Sufaadi haven't traded it, it'll be with their other valuables. I was planning to leave it behind. Sentimentality isn't worth risking your life, but you kept your word--which is more than I can say for my brother. Help me recover the necklace and it's yours.", ["objectivesText"] = "Help Shahata recover her mother's necklace. Progress: What happened? Where's Fennad?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 23846, 34423, 34424, 177665, 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 180933, 181368, 181377, 181464, 181511, 181569, 181571, 181575, 181576, 181577, 181580, 181589, 181591, 181596, 181604, 181605, 181608, 181610, 181627, 181628, 181630, 181631, 181632, 181633, 181634, 181635, 181636, 181637, 181702, 181703, 181704, 181738, 181745, 181845, 182128, 182187, 182203, 182344, 182385, 182466, 182485, 182494, 182503, 182512, 182621, 182622, 182675, 183044, 183402, 183468, 183479, 183481, 183504, 183744, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184843, 185717, 237127, 237812 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
