[84765] = { ["id"] = 84765, ["name"] = "Of Bonds and Boughs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84820 }, ["description"] = "All that time in Tazavesh, all I could think about was coming home. Now it's only brought more grief. Even if the surveyor wasn't damaged, I still have nothing to trace back to our mother's grave. < Om'fennad glances around the cave.> See these markings? This was a shrine to the Exchange. I guess it's a fitting place to finally say goodbye. Would you be willing to help one last time? Nothing dangerous--just light some incense .", ["objectivesText"] = "Help Om'fennad and Shahata honor their mother.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245713, 245714, 245715, 245716 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.7008, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
