[84776] = { ["id"] = 84776, ["name"] = "A Call to Delves", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84776 }, ["description"] = "There are many treasures to be found in the delves around our land. Perhaps some could be of use to you.", ["objectivesText"] = "Complete 5 Delves in Khaz Algar. Progress: Beware of whatever lurks in these delves.", ["rewardItems"] = { 229129, 250116 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard",
