[84779] = { ["id"] = 84779, ["name"] = "Lorewalking: The Blade's Gambit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. Xal'atath took advantage of the many forces at play in the war in a gambit to restore her power...", ["objectivesText"] = "Listen to Lorewalker Cho to learn the story of Xal'alath during the Fourth War.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 164911, 242386, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84781] = { ["id"] = 84781, ["name"] = "Master of Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 6757, ["storyline"] = { 84781 }, ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 142223, 161081, 198622, 205162, 228967, 228995, 228996 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
