[84782] = { ["id"] = 84782, ["name"] = "Lorewalking: The Blade's Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Many years ago, a stone tablet from Stormsong Valley made its way into my library. It took years to break the cipher and translate the fragments of runes etched into it. I will tell you what we have pieced together. A tale of yet more treachery...", ["objectivesText"] = "Listen to Cho to learn the story of Xal'alath in Ny'alotha.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2381, ["db2PoiMapID"] = 2801, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84784] = { ["id"] = 84784, ["name"] = "Lorewalking: The Blade's Nemeses", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive. You know what to do.", ["objectivesText"] = "Activate the 3 Ritual Obelisks to summon Yogg-Saron , C'Thun , and Y'Shaarj . Progress: Do not waste Lord N'Zoth's time.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 244888, 245567, 245631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2383, ["db2PoiUiMapID"] = 2383, ["db2PoiMapID"] = 2801, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
