[84855] = { ["id"] = 84855, ["name"] = "Dead Silence", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["series"] = { 85032, 85961, 93979 }, ["description"] = "Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence. I had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida , Lo'shah , and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.", ["objectivesText"] = "Find the scouts at Overlook Zo'Shuul.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237861, 237873, 237878, 237892 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230806, ["x"] = 0.482, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234106, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84856] = { ["id"] = 84856, ["name"] = "Where the Void Gathers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["series"] = { 86495 }, ["description"] = "With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much. You will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. Talk to me when you are ready. Time is of the essence.", ["objectivesText"] = "Search Shadow Point in Untethered Space with Xal'atath 's help. Progress: We will need more than one Reshii Ribbon if we want to reach Dimensius with a force capable of stopping his emergence.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233946, ["x"] = 0.482, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233946, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84857] = { ["id"] = 84857, ["name"] = "Eco-Dome: Primus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "Xal'atath is correct. We need more than my one Reshii Ribbon to get a force to Dimensius. There is an eco-dome south of here. The founder of the Trust is there, overseeing its operation. She acquired the domes from the Consortium. She claims they will be the key to restoring K'aresh . I am skeptical anything will be safe now that Dimensius stirs. She was a member of the Ravel and possesses a Reshii Ribbon. Surely she would lend it to us.", ["objectivesText"] = "Meet Locus-Walker at Eco-Dome: Primus.", ["rewardGold"] = 73700, ["rewardXP"] = 2940, ["rewardItems"] = { 237863, 237868, 237876, 237884 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234106, ["x"] = 0.482, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230811, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84858] = { ["id"] = 84858, ["name"] = "System Restart", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["description"] = "My Reshii Ribbon is all that is keeping this dome and its systems from collapsing. This eco-dome took too much of my fortune to build just for the Shadowguard to destroy it. They have sabotaged many of our control consoles, risking a complete ecological collapse. Find Engineer Om'loof and help him restart our environmental support system while I monitor the rest of the facility.", ["objectivesText"] = "Help Engineer Om'loof in Eco-Dome: Primus. Progress: This eco-dome will fail if the environmental support system stops. We must stabilize it!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233068 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84859] = { ["id"] = 84859, ["name"] = "Damage Report 101", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["description"] = "Just like Engineer Om'loof, I have hired more well-regarded, highly trained, expensive management consultants from cartel Om. Two of them have not reported in. Are they dead, or just distracted again? Find botanist Om'nittar and shield technician Om'door . Get their damage reports. I need to know if the attack caused any lasting damage to my dome.", ["objectivesText"] = "Find botanist Om'nittar and shield technician Om'door and bring their reports to Ve'nari . Progress: I hire the best. I am sure Om'nittar and Om'door have the information I need.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233187, 233189 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84860] = { ["id"] = 84860, ["name"] = "Eco-Stabilizing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["description"] = "The Shadowguard attack caused chaos and disarray in this dome. Several control consoles have powered down, and my consultants are stretched thin reviving their assigned biomes and systems. This is where you come in, <name>. It's an easy, but critical job. Find the disabled consoles and make sure they restart.", ["objectivesText"] = "Activate the disabled control consoles in Eco-Dome: Primus. Progress: Are all the consoles operational? No? Go switch them on!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232517, 233326 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84861] = { ["id"] = 84861, ["name"] = "This Is Our Dome!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["description"] = "We may have driven the saboteurs out of the dome and repaired its systems, but that doesn't mean the Shadowguard is done with my domes. They're still hiding at the perimeter, trying to find a way to harvest the vast amounts of expensive energy needed to power the eco-dome. I need you to fight them off. Then maybe this attack will truly end.", ["objectivesText"] = "Kill 7 Shadowguard around Eco-Dome: Primus. Progress: Did you get them all? Or are there still Shadowguard hiding around the perimeter, damaging my dome?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237862, 237867, 237874, 237882 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84862] = { ["id"] = 84862, ["name"] = "Void Alliance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "We can't have you patrolling the perimeter of this dome, like the city watch fighting attackers in perpetuity. We need a permanent solution so we can continue with our noble quest. Take these crystals. They've been attuned to the eco-dome's defense magics. Just place them near strategic parts of the perimeter to strengthen the magical defenses. What? This time it's no trick. If this dome explodes, I'll never get to destroy Dimensius.", ["objectivesText"] = "Place 4 Xal'atath defenses around Eco-Dome: Primus. Progress: Have you placed the crystals I gave you? Ve'nari won't give up her ribbon until her dome is secure.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228911 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230825, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230825, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84863] = { ["id"] = 84863, ["name"] = "Counter Measures", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "I cannot relinquish my Reshii Ribbon just yet, <name>. Not while the Shadowguard assaults my eco-dome from their camp in Serrated Peaks. Take the fight to them! If you decimate their forces, they will stop this assault. Bring Locus-Walker's apprentice, Alleria. She looks like she knows how to handle herself in a fight. She also keeps staring daggers at the Harbinger, and I don't have time to play peacemaker between those two.", ["objectivesText"] = "Kill 12 Shadowguard forces in Serrated Peaks. Progress: The Shadowguard are still attacking. Did you decimate their numbers yet?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230814, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84864] = { ["id"] = 84864, ["name"] = "Her Dark Side", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "An ethereal army runs on its energy siphons. Interrupt the flow of energy by destroying their siphon tower, and the army will pull back. It's one of their weaknesses as minions. Normally I wouldn't share the secrets of their defeat, but they betrayed me and will forever live with the consequences. The siphon has a control console that can be overloaded to collapse the system. It will be shielded by a void barrier. Alleria can remove it for you.", ["objectivesText"] = "Destroy the Ethereal Siphon in Serrated Peaks. Progress: Now the Shadowguard will have to retreat.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 106175, 107307, 107312, 107317, 237812 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230825, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84865] = { ["id"] = 84865, ["name"] = "Divide and Conquer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "Of all the assets on the field of battle, the troops are the most expendable. I've sent enough to their destruction to know this as a fact. If we are to safeguard this dome for Ve'nari and get her Reshii Ribbon, we should destroy their cannons. Those cannons are easily worth the lives of all of their soldiers. Destroy them and their commanders will sound the retreat. Most field commanders would never admit this as it's bad for morale, but you seem like the type that can handle uncomfortable truths.", ["objectivesText"] = "Destroy 3 Shadowguard Cannons in Serrated Peaks. Progress: Taking out these cannons will force the Shadowguard's retreat. I would not listen to Xal'atath 's ideas on ethics of command, though.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233222 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230825, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84866] = { ["id"] = 84866, ["name"] = "To Purchase Safety", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "I need to focus on the mission. Regardless of my doubts about our companions, the Shadowguard are a scourge. We should slay their Shadow-Captain so they cannot easily return to Eco-Dome: Primus. Ve'nari would lend her Reshii Ribbon to our cause, and we would discover if my trust in Locus-Walker was well placed. I will not let my doubts stay my bow on the battlefield, <name>. You can trust me to hunt these followers of Dimensius.", ["objectivesText"] = "Kill Shadow-Captain Lakheesh .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 238386 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 237705, ["x"] = 0.542, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84867] = { ["id"] = 84867, ["name"] = "Stalking Stalkers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "I've planted the seed, yet Soul-Scribe still hesitates. Her daughter Narathe is more receptive. She might be able to give us the nudge that's needed to win the Wastelanders over. Daughters are useful. Go with Narathe . Win over their tribe. I will stay here and continue to work on Soul-Scribe 's will.", ["objectivesText"] = "Find a way to sway the Wastelanders. Progress: I will do what my oaths dictate, but I am not convinced that your plan is the way to go.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237859, 237865, 237871, 237880 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230658, ["x"] = 0.63, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230292, ["x"] = 0.63, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84868] = { ["id"] = 84868, ["name"] = "A Whiff of Help", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84868 }, ["description"] = "You seem quite equipped for solving secrets now! As much as I expect Maru would want to come with you, she's far too young. Fortunately, we Tuskarr have an incense that lets our souls communicate across long distances. I keep a stock of it on me if you need. As a friend of Maru , I will only charge you for the cost of materials.", ["objectivesText"] = "Purchase and use a Spiritual Incense from Benatauk . Progress: Have you tried the incense?", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 229351 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226766, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226766, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84869] = { ["id"] = 84869, ["name"] = "Hunting on Glass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "Violent scavengers of the Void have been drawn to Dimensius's aura to feast upon the scraps he will leave behind. This presents a problem for our Wastelander friends. Scavenging is their job. They could handle these beasts--I would not be seeking to ally with them if they couldn't. But why not give them a gift, and show them you are their equal--no, their superior in combat?", ["objectivesText"] = "Kill 4 Void Terrors and 8 Unreal Observers . Progress: Dimensius's power grows and the Wastelanders are feeling the pinch. Let us ease the pressure for them a bit.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84876] = { ["id"] = 84876, ["name"] = "The Oasis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "Soul-Scribe would fight for us, even die for our cause. Yet she still denies us her Reshii Ribbon. She sees it as a tool of the Ravel, and her oaths are getting in the way of our mission. If she could feel the presence of the Worldsoul K'aresh once again, she would give anything to protect him--even the ribbon. The Oasis is the Trust's eco-dome that has a stable biome. The perfect place to commune with a Worldsoul, if one still exists.", ["objectivesText"] = "Meet Xal'atath at the Oasis eco-dome. Progress: Our research here is essential to the future of K'aresh . That we have stabilized this area means that we can replicate this feat in other domes--perhaps even heal the shattered remains of K'aresh .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 56840, 56841, 56842, 56843 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230658, ["x"] = 0.63, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84879] = { ["id"] = 84879, ["name"] = "Restoring Hope", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "This dome is a reasonable facsimile of K'aresh . We will find no better place for Soul-Scribe to hear the Worldsoul's song. And yet, as Dimensius grows in power, even the Oasis succumbs to the Void. I can feel the rifts tearing open. Their energies will disrupt this delicate ritual. Unfortunately they'll need to be closed so Soul-Scribe can be convinced.", ["objectivesText"] = "Cleanse the eco-dome of invasive elements. Progress: The Void creeps further and further into K'aresh every day. Dimensius's power grows ever stronger.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237864, 237869, 237877, 237885 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230738, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230738, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84882] = { ["id"] = 84882, ["name"] = "Deck Dismay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84882 }, ["description"] = "Gather up the cards that got scattered around the area and I will be forever grateful!", ["objectivesText"] = "Collect the missing cards. Progress: How's it going? Have you found all my missing cards?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 229199, 229207, 229208, 229210, 229211, 229212, 229213, 229216, 229219, 229225, 231907 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 230838, ["x"] = 0.638, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84883] = { ["id"] = 84883, ["name"] = "K'aresh That Was", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "The Tabiqa has not been attempted for thousands of years. It was clear that the Devouring War destroyed K'aresh . And yet, looking at this dome... they have recreated so much that I thought lost forever--fresh water, clean air, even the zaranit flowers I thought extinct. Does the Harbinger speak the truth? No. I didn't break my oath and abandon the Worldsoul. K'aresh is gone.", ["objectivesText"] = "Gather materials for the ritual. Progress: Did you find the components for the Tabiqa ritual? Do they even still exist?", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 229363, 230938 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230739, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230739, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84885] = { ["id"] = 84885, ["name"] = "Working for G.E.T.A.", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84885, 84891, 84892, 84893 }, ["description"] = "Attention: Protect the Citizens of Undermine AND get paid! Profit-seeking bounty hunters encouraged to check in at the local G.E.T.A. office for more information.", ["objectivesText"] = "Inquire at the local G.E.T.A. office in the Vatworks Progress: Do you need something, <name>? I don't have time for idle chit-chat.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5686, ["name"] = "G.E.T.A.", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[84891] = { ["id"] = 84891, ["name"] = "G.E.T.A. The Radioactive Rat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84885, 84891, 84892, 84893 }, ["description"] = "We got a report here of some big, radioactive rat that was chased into a nearby sewer. Not only is it highly aggressive, it's terrible for the environment. Hey, don't look at me like that. Us Underminers care about that stuff even if the big cartels don't. I put the location of the sewer entrance on your map. Hopefully, one of these lunks will get off their butts and join you there.", ["objectivesText"] = "Defeat the Radioactive Rat Progress: Once you're finished, come back here, and I'll make sure you're adequately compensated.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233066 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5686, ["name"] = "G.E.T.A.", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84892] = { ["id"] = 84892, ["name"] = "G.E.T.A. The Crocodilian", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84885, 84891, 84892, 84893 }, ["description"] = "Did you know that crocodiles can grow indefinitely? Well, the owner of this crocodile didn't. And when it got too big, it was released. Normally these crocodiles make their way out of the Undermine . But this one decided it liked the taste of goblins and stayed. If you're up for it, the people of Undermine could use someone brave to face it. Are you game?", ["objectivesText"] = "Defeat the Crocodilian Progress: Who's afraid of a big ol' croc, you say?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233113 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5686, ["name"] = "G.E.T.A.", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84893] = { ["id"] = 84893, ["name"] = "G.E.T.A. The Captain", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84885, 84891, 84892, 84893 }, ["description"] = "This is a unique one. Some cave skippers got into the Undermine sewers and are starting to populate, causing all sorts of problems. It looks like an especially big one is organizing them somehow. We've taken to calling him \" the Captain .\" Make sure his reign of finned, eye-bulging terror ends today.", ["objectivesText"] = "Defeat the Captain Progress: Be careful, <name>. From what we can tell, The Captain doesn't work alone.", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 232771, 232775, 232779, 232787, 233114 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228393, ["x"] = 0.33, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5686, ["name"] = "G.E.T.A.", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
