[84896] = { ["id"] = 84896, ["name"] = "The Next Dimension", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "By the Songs of K'aresh , I will join you to face the Shadowguard and Dimensius in battle. Let those that would prey on Untamed K'aresh fear his followers! My scouts have tracked your comrades setting a foothold in Shadowguard territory. They will need our assistance. K'aresh lives! Our cause is just! Our oaths are unbroken!", ["objectivesText"] = "Meet with Soul-Scribe in Shan'dorah on K'aresh .", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["rewardItems"] = { 231769 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230786, ["x"] = 0.744, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230818, ["x"] = 0.602, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84897] = { ["id"] = 84897, ["name"] = "The Calm Before We Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "Narathe is right. We are fortunate that void elves have experience battling the Shadowguard. The wastes of K'aresh are merciless, and the battle to come will be as well. I hope they are prepared for a brutal fight. These will not be the scattered scouts they are used to fighting on Telogrus. You should ensure they are ready for the battle to come.", ["objectivesText"] = "Check in with Alleria and the void elves at Shan'dorah on K'aresh . Progress: We have spent a long time preparing for this moment. I will not let it slip.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 197649, 197650, 197651, 197652 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230818, ["x"] = 0.602, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231443, ["x"] = 0.606, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84898] = { ["id"] = 84898, ["name"] = "The Sands of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "My people have fought across every inch of the ruins of our world. We gave our oath to King Salhadaar and he rewarded us by sending the Shadowguard to hunt us down. Salhadaar is long dead, but we knew the Shadowguard would return. In the long years that followed, we secreted caches of weapons so we would always be able to raise a blade in defiance.", ["objectivesText"] = "Collect 3 Weapons Caches from the nearby sands of the Shatter Gorge on K'aresh . Progress: Have you gathered all of the weapons caches in the sand?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233192, 233193, 233194, 237136 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231443, ["x"] = 0.606, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231446, ["x"] = 0.552, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84899] = { ["id"] = 84899, ["name"] = "Shadowguard Diffusion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "With or without Xal'atath, the Shadowguard have long been a thorn in my side. It would be wise to take out as many as we can on this rock. I still do not trust her, but we must focus on the enemy we can defeat right now. Do not relent, <name>. If you see any Shadowguard, cut them down. A battle against them today saves us a battle against them tomorrow.", ["objectivesText"] = "Defeat Shadowguard in the sands of the Shatter Gorge surrounding Shan'dorah on K'aresh . Progress: We still have many to defeat before we can progress.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 238390 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230817, ["x"] = 0.606, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231444, ["x"] = 0.55, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84900] = { ["id"] = 84900, ["name"] = "Like a Knife Through Aether", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "Very good, my champion. You are a swift and sharp blade of destruction. We will put all that power to use now. We will slaughter the Shadowguard that seek to raise Dimensius, and the machines created to feed his insatiable hunger. The Shadowguard must have a Reshii Ribbon among their spoils. As we destroy their garrisons, look for this final ribbon. It is our way forward to kill a Void Lord.", ["objectivesText"] = "Stop the Shadowguard ethereals at Shadow Point: Darkmend in K'aresh . Progress: A few more of these and we might even have a chance. Do not relent, <name>. You are capable of this and so much more.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233333 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231445, ["x"] = 0.55, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231476, ["x"] = 0.486, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84902] = { ["id"] = 84902, ["name"] = "Adverse Instantiation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "Turning into beings of energy was a choice we made when we had no other option. In the time since then, we have become reliant on consuming energy to survive. The Shadowguard are feeding that power to Dimensius. His hunger is infinite, and he will drain the energy from K'aresh to fuel his re-emergence. We must destroy this machinery that feeds him, <name>.", ["objectivesText"] = "Disable 6 Shadowguard Power Pylons in Shadow Point on K'aresh . Progress: Are they all dealt with?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231487, ["x"] = 0.485, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231492, ["x"] = 0.482, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84903] = { ["id"] = 84903, ["name"] = "Until the Sands Bleed Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "I have fought Shadowguard on Eredath, Telogrus, and now on K'aresh . They are a thorn that should be plucked from the cosmos. That they should follow the very monster that threatened their world proves they are a scourge. Though, perhaps I am no better, fighting alongside Xal'atath. I will grapple with that contradiction later. For now, I intend for us to put an end to them, <name>.", ["objectivesText"] = "Kill Shadowguard in Shadow Point on K'aresh . Progress: Spare no remorse for their kind. They would do far worse.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237934, 237935 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231488, ["x"] = 0.485, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231493, ["x"] = 0.482, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84904] = { ["id"] = 84904, ["name"] = "And We Will Answer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "This is unthinkable. Heretical! The Shadowguard have captured my warriors and are converting them into new troops for Dimensius--forcing an oath to serve the All-Devouring as the Void fills their being. Free them, <name>. We cannot let this last any longer. I will send Narathe to aid you in this fight. She knows how to untether the souls of oath-breakers.", ["objectivesText"] = "Rescue Captured Wastelanders in Shadow Point on K'aresh . Progress: Once an ethereal embraces the shadow, they are lost forever.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233334 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231486, ["x"] = 0.486, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231491, ["x"] = 0.482, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84905] = { ["id"] = 84905, ["name"] = "To Walk Among Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "We must continue disabling or destroying these buildings. I am loathe to destroy the technology of my people, but when used for such dire purpose, there is no choice! From here on out, hold nothing back. Let us raze the works of the Shadowguard.", ["objectivesText"] = "Help Locus-Walker disable Shadow Point: Torment at Shadow Point on K'aresh .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231492, ["x"] = 0.482, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231506, ["x"] = 0.482, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84906] = { ["id"] = 84906, ["name"] = "Nexus Regicide", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84896, 84897, 84898, 84899, 84900, 84902, 84903, 84904, 84905, 84906, 85037 }, ["description"] = "Now is the time, <name>. We must not hesitate. They will send their strongest to defend this last manaforge. We will find Nexus-Prince Azir there and we will end him before we take this battle to Dimensius. Xal'atath or no Xal'atath, we have what we need to do this. Just one final kill. Let us not dally. Make haste.", ["objectivesText"] = "Defeat the leader of the Shadowguard in Shadow Point: Apotheosis on K'aresh .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 237936, 237937, 237938, 237939 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231505, ["x"] = 0.482, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231521, ["x"] = 0.442, ["y"] = 0.182 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84908] = { ["id"] = 84908, ["name"] = "Stormrider's Honors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84908 }, ["series"] = { 83024, 83025 }, ["description"] = "<A golden missive finds its way to you.> Champion, though you are no Stormrider, you may yet be worthy of the Stormrider's armor. Find Stormrider Bruelda if you wish to claim this honor.", ["objectivesText"] = "Speak with Stormrider Bruelda in Dornogal.", ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 225347, ["x"] = 0.352, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84909] = { ["id"] = 84909, ["name"] = "Ghostly Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84909 }, ["description"] = "<The crate emits a ghostly glow, and you can't help but feel the presence of mysterious spirits. Alyx would appreciate the supplies returned.>", ["objectivesText"] = "Return the Ghostly Celebration Crate to Alyx . Progress: Yes?", ["rewardItems"] = { 181163, 229367 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 229367 }, ["questType"] = "standard", ["flags"] = {  },
