[84910] = { ["id"] = 84910, ["name"] = "The Tabiqa", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "My followers long for the days when they were oracles. They yearn to hear the Song of K'aresh . I am a realist. The evil of the Ravel, of Dimensius--they have destroyed the beauty that was our Worldsoul. But you have gathered the items for the Tabiqa. So I will attempt it. When I hear the void of K'aresh 's absence, there will be consequences.", ["objectivesText"] = "Help Soul-Scribe with the ritual. Progress: It has been too long since we were this close to K'aresh . It is but an echo of what once was, but the memories that it brings back...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 238037, 238039, 238040, 238041 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230739, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230787, ["x"] = 0.744, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84912] = { ["id"] = 84912, ["name"] = "The Show Must Go On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 84912 }, ["series"] = { 84985 }, ["description"] = "Thank you for coming! We've had a bit of a mishap with the script and various stage props. They've all gone missing! It seems as though a prankster has decided to make a mockery of our productions and scattered several needed items throughout the area. At least the prankster was somewhat considerate and left us some clues as to where we can find the missing items. Do you think you can solve the riddles? And please, do not carry any open flames or shine any bright lights while in our theater.", ["objectivesText"] = "Help Dapperdew at the Amphitheater in Ardenweald. Progress: Use the play list to find the missing items in the area.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 229383, 229384, 229385, 229387, 231907 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171743, ["x"] = 0.415, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171743, ["x"] = 0.415, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
