[84915] = { ["id"] = 84915, ["name"] = "Clearing the Dunes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84740, 84741 }, ["description"] = "The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm. Now it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.", ["objectivesText"] = "Slay 8 dune creatures. Progress: Is it safe yet?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.7008, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84923] = { ["id"] = 84923, ["name"] = "A Bird's Tale", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84923 }, ["series"] = { 84924 }, ["description"] = "I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.", ["objectivesText"] = "Find Reshad near the stage.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 229411 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4063 }, ["questType"] = "standard", ["flags"] = {  },
