[84924] = { ["id"] = 84924, ["name"] = "A Bird's Tail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84924 }, ["series"] = { 84923 }, ["description"] = "I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it? I will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story. You can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.", ["objectivesText"] = "Learn about Percy's adventures by finding his feathers. Progress: Have you discovered Percy's tale?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 207730, 229408, 229409, 229410, 229411, 229958, 231907 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[84925] = { ["id"] = 84925, ["name"] = "Rallying All Rapscallions!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84925 }, ["description"] = "Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha", ["objectivesText"] = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .", ["rewardItems"] = { 229390, 229401, 230287 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219215, ["x"] = 0.555, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["startItems"] = { 229401 }, ["questType"] = "standard", ["flags"] = {  },
},
