[84932] = { ["id"] = 84932, ["name"] = "A Legacy of Destruction", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84932 }, ["series"] = { 84933 }, ["description"] = "Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos. Could you go talk to him and see if you can sort out the issue?", ["objectivesText"] = "Find the dragon whelpling at the pet playground.", ["rewardGold"] = 33100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231029, ["x"] = 0.618, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4063 }, ["questType"] = "standard", ["flags"] = {  },
