[84933] = { ["id"] = 84933, ["name"] = "From Ashes to Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84933 }, ["series"] = { 84932 }, ["description"] = "I will become the great and powerful Deathwing! Cower before my strength! You there! Do you wish to join me, the next Deathwing, on an epic adventure?", ["objectivesText"] = "Show Voidfire the destruction of Deathwing. Progress: I want to get followers to do my bidding! Like a cult!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 134022, 231292, 231907 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231029, ["x"] = 0.618, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
