[84956] = { ["id"] = 84956, ["name"] = "A Shadowy Invitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "$p, I've received word from my mentor, Locus-Walker . He warns of a Shadowguard plot that requires our aid. I wonder if he has finally tracked down Xal'atath. Come to the Foundation Hall in Dornogal. We must speak immediately.", ["objectivesText"] = "Meet Locus-Walker at the Foundation Hall in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 235499 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 233603, ["x"] = 0.409333, ["y"] = 0.243333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84957] = { ["id"] = 84957, ["name"] = "Return to the Veiled Market", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh . The Trust is in desperate need of one of your skills, <name>. The Shadowguard assaults our city and threatens the work of the eco-dome project. Please accompany me.", ["objectivesText"] = "Accompany Locus-Walker and Alleria to Tazavesh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 233603, ["x"] = 0.409333, ["y"] = 0.243333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 233706, ["x"] = 0.595333, ["y"] = 0.833333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.409333, ["y"] = 0.243333 }, ["mapCandidates"] = { ["npc"] = { 2339, 2472 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84958] = { ["id"] = 84958, ["name"] = "Beasts Unbound", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "I am Ta'ka , supplier of rare creatures destined to repopulate my homeland. At least, I was until some of them escaped their translocation cages! This cannot stand! These creatures are vital. If you could assist me with capturing them, I'd be quite appreciative. Engage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.", ["objectivesText"] = "Defeat escaped creatures in Tazavesh to return them to Ta'ka . Progress: Have you finished capturing the escaped beasts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230954, ["x"] = 0.568, ["y"] = 0.733 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230954, ["x"] = 0.568, ["y"] = 0.733 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.733 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84959] = { ["id"] = 84959, ["name"] = "Lost Lines of Defense", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed. These barrier projectors are essential for securing the wild places on K'aresh , and even the city of Tazavesh. Our efforts are in jeopardy! Please, if you can find any of my shipments it would help us get our efforts back on track.", ["objectivesText"] = "Collect 8 Stolen Barrier Projectors for Ba'ver . Progress: Have you located my barrier projectors?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235366, 237875, 237883, 237887, 237888 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230955, ["x"] = 0.532, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230955, ["x"] = 0.532, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84960] = { ["id"] = 84960, ["name"] = "The Darkness Among Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Alleria, <name>... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us. Come, let's seek them out and drag them into the light before they strike.", ["objectivesText"] = "Investigate the Void Presence and locate the culprits behind the many troubles in Tazavesh. Progress: We need to find the hidden Shadowguard, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 237890, 237893 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 233706, ["x"] = 0.595333, ["y"] = 0.833333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.595333, ["y"] = 0.833333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84961] = { ["id"] = 84961, ["name"] = "Barriers to Entry", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming. Move swiftly, <name>. This may be our only chance to stop the Shadowguard from flooding in.", ["objectivesText"] = "Place 8 Barrier Projectors around Tazavesh. Progress: Did you place the barrier projectors ? We need to slow down the invasion. Quickly!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234596, ["x"] = 0.54, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
