[84963] = { ["id"] = 84963, ["name"] = "Sealing the Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["series"] = { 84965 }, ["description"] = "No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them. Wait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. Please, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!", ["objectivesText"] = "Collect 5 Saturated Entropic Cores from Shadowguard within Tazavesh. Progress: Got those cores that Om'en wanted?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233199, 238056, 238262 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234601, ["x"] = 0.54, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84964] = { ["id"] = 84964, ["name"] = "Heroes Among Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "<name>! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! We need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.", ["objectivesText"] = "Rescue 8 Tazavesh Civilians . Progress: The people are still out there, <name>!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 269973 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234602, ["x"] = 0.493333, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84965] = { ["id"] = 84965, ["name"] = "Core Contributions", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["series"] = { 84963 }, ["description"] = "The entropic cores we collected will be crucial in our defense. Use the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders. Time is of the essence, <name>. The fate of Tazavesh rests in your hands.", ["objectivesText"] = "Activate 5 Market Guardians scattered around Tazavesh. Progress: Any of the guardians we activate should help stabilize the situation.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15781 } }, ["mapID"] = 2371, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
