[84967] = { ["id"] = 84967, ["name"] = "The Shadowguard Shattered", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "The commander of the Shadowguard, Shadowlord Al'zar , has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out. I must depend on you, <name>. Venture forth and eliminate Shadowlord Al'zar . His demise will cripple the Shadowguard's assault on Tazavesh. The fate of the city rests on your shoulders.", ["objectivesText"] = "Kill Shadowlord Al'zar in Tazavesh. Progress: Go. We will come as soon as we can.", ["rewardGold"] = 567400, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234620, ["x"] = 0.395333, ["y"] = 0.698333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234620, ["x"] = 0.395333, ["y"] = 0.698333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.698333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
