[84972] = { ["id"] = 84972, ["name"] = "Chipping the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "Greetings. I am Driruj . I think you could help with a project of mine. The nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all! Bring me back some samples of the void glass so I can assess their worth to future buyers.", ["objectivesText"] = "Collect 6 Void Glass Samples from the Clefts of Unreality. Progress: I am preparing to move off world before what's left of K'aresh crumbles away. There are many potential uses, and therefore potential markets, for this newly created void glass. Potential equals profit, and profit means I can make a new life on a less volatile world.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229892 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84973] = { ["id"] = 84973, ["name"] = "Of Motes and Husks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device. While you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.", ["objectivesText"] = "Collect 4 Dune Wyrm essences and 6 Krolusk shells. Progress: Anything can be turned into profit, if you have the right market. It's all about knowing your buyers and finding that which they most desire. I still think the void glass will be the most lucrative for me, but it needs to be able to hold together more solidly.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229900, 229901 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84974] = { ["id"] = 84974, ["name"] = "Shards of Hope", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "I still believe void-infused glass is my ticket out of here. The problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse. I have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...", ["objectivesText"] = "Collect 20 Void Shards. Progress: There are many potential uses, and therefore potential markets, for newly created void glass. If we can get this right, I should be set up comfortably in a new home by week's end! If you hold the device while standing in the void surges, the energy from the motes should help create more stable fragments.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229959, 236411 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[84985] = { ["id"] = 84985, ["name"] = "Not Ready on Set", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84985 }, ["series"] = { 84912 }, ["description"] = "Oh <name>, I am glad to see you again. My superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations! Now I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems. Would you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.", ["objectivesText"] = "Find Dapperdew in Ardenweald.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171743, ["x"] = 0.415, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 1565 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4018, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
