[84996] = { ["id"] = 84996, ["name"] = "Vereesa's Tale", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 84997, 92405 }, ["description"] = "We came here so Vereesa could get closer to the source of her visions. Unfortunately, it has only made them stronger, not clearer. But this is her story. She should be the one to tell it.", ["objectivesText"] = "Hear Vereesa Windrunner 's tale.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 231039, ["x"] = 0.285, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 233252, ["x"] = 0.265, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
