[85001] = { ["id"] = 85001, ["name"] = "Blessings Be Upon You", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 85002, 85011, 85151, 85155, 85804 }, ["description"] = "These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid! Champion, I am certain that you and I can do this if we work together.", ["objectivesText"] = "Help Arator to rescue 8 Dalaran Custodians from the clutches of the Twilight's Blade. Progress: These poor souls are imperiled through no fault of their own!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85002] = { ["id"] = 85002, ["name"] = "Off to Tazavesh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 85001, 85011, 85151, 85155, 85804 }, ["description"] = "It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her. Last I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh. Lucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.", ["objectivesText"] = "Regroup with Arator in Tazavesh, the Veiled Market, on K'aresh.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 231266, ["x"] = 0.602, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2248, 2472 }, ["zone"] = { 14717 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85003] = { ["id"] = 85003, ["name"] = "Restoring Operational Efficiency", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing. Tazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.", ["objectivesText"] = "Help the brokers of Tazavesh by assisting with their issues.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.578857, ["y"] = 0.776286 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85005] = { ["id"] = 85005, ["name"] = "A Radiant Call", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 85005 }, ["description"] = "I have an urgent missive for $p from Mylton Wyldbraun , second in command of the Flame's Radiance! Hallowfall requires what strength we can muster and the Flame's Radiance seeks volunteers to join the fight against the remaining Sureki forces. Please report to Wyldbraun without delay.", ["objectivesText"] = "Meet Mylton Wyldbraun at the Flame's Radiance camp in Hallowfall .", ["rewardItems"] = { 233288 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 242126, ["x"] = 0.46, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["db2DetailThemeID"] = 62, ["questType"] = "standard", ["flags"] = {  },
},
[85006] = { ["id"] = 85006, ["name"] = "Those We Have Lost", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85006 }, ["description"] = "Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular. I have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.", ["objectivesText"] = "Collect Flickering Essence . Progress: How did the collecting go?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229969 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85007] = { ["id"] = 85007, ["name"] = "Extended Reach", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85007 }, ["description"] = "I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types. They have probably sat out there long enough for an initial reading. Could you go gather that info for me?", ["objectivesText"] = "Gather readings from the Broker Pylons. Progress: Hopefully the devices were easy to find?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85008] = { ["id"] = 85008, ["name"] = "Machinations of Memory", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85008 }, ["description"] = "Well, the readings aren't anything to be concerned about... So we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?", ["objectivesText"] = "Interact with the console. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85009] = { ["id"] = 85009, ["name"] = "Those We Have Yet to Save", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85009 }, ["description"] = "The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species. I wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.", ["objectivesText"] = "Recharge 6 Flickering Ephemera . Progress: Have you finished our experiment?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230730, 245705, 245706 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85011] = { ["id"] = 85011, ["name"] = "Where in K'aresh is Alleria Windrunner?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85001, 85002, 85151, 85155, 85804 }, ["description"] = "While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard. I managed to get a lead on a few traders who might have crossed paths with my mother recently. We should go before her trail runs cold.", ["objectivesText"] = "Discover the location of Alleria Windrunner by asking around Tazavesh, the Veiled Market. Progress: <Umbric looks at you with curiosity.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231266, ["x"] = 0.602, ["y"] = 0.915 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234263, ["x"] = 0.5145, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85018] = { ["id"] = 85018, ["name"] = "Packets of Promises", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. Will you meet me outside? I have one last thing I would ask of you.", ["objectivesText"] = "Talk to Driruj . Progress: Driruj is a fool! He's likely to burn through his wrappings with his hot-headedness. He'll be back.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 229905, 245721, 245722, 245723, 245724 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231161, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85019] = { ["id"] = 85019, ["name"] = "An Outcast's Request", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "I felt it. Something happened in that dome. Something--no... someone... My friend, I do not know your name or where you came from, but this is it! It has to be! The ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.", ["objectivesText"] = "Retrieve Outcast Hizfran 's belongings from North Sufaad. Progress: Once I have my belongings, I will be able to walk the path of the old ways. It is time to retake my true oath.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229893, 229895, 229902 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85020] = { ["id"] = 85020, ["name"] = "The Blood of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other. On the day of the Devouring of K'aresh , a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end. Please collect deposits from sand striders or veins and bring them to me.", ["objectivesText"] = "Collect 20 Blood of K'aresh deposits . Progress: Although the Blood of K'aresh may not have existed prior to the Devouring like other minerals, it came from within our world and thus should still be usable for the process.", ["rewardGold"] = 292100, ["rewardXP"] = 11765, ["rewardItems"] = { 229970 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85021] = { ["id"] = 85021, ["name"] = "Cleansing the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "Now that you have brought me all that I need, the ritual of return can begin. You see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches. While grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.", ["objectivesText"] = "Help Outcast Hizfran with the ritual of return. Progress: Almost there, stranger... <name>. That is your name, is it not?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231699, ["x"] = 0.778, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85022] = { ["id"] = 85022, ["name"] = "Priest of the Old Ways", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "<name>, I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there. I have a final request for you. Go find these creatures and slay them. Then, I will be able to reassume the mantle of priest.", ["objectivesText"] = "Slay 3 void manifestations. Progress: One step, <name>. One last step.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245707, 245708, 245709, 245710 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231699, ["x"] = 0.778, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231774, ["x"] = 0.778, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85024] = { ["id"] = 85024, ["name"] = "Toy Trouble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85024 }, ["series"] = { 85025 }, ["description"] = "Adventurer, Maru is once again in need of your aid. She has an urgent matter that she would like to discuss with you.", ["objectivesText"] = "Speak with Maru .", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2PoiUiMapID"] = 71, ["db2PoiMapID"] = 1, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
