[85025] = { ["id"] = 85025, ["name"] = "Operation Toy Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85025 }, ["series"] = { 85024 }, ["description"] = "A sneaky thief has taken some of my friends' toys! You're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.", ["objectivesText"] = "Find the missing toys.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 228791, 228795, 229908, 229991 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[85026] = { ["id"] = 85026, ["name"] = "Where Legends are Made", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 84423, 84424, 85026 }, ["series"] = { 84424 }, ["description"] = "There's so much to catch you up on <name>! Where do you want to start?", ["objectivesText"] = "Select a Timewalking Campaign from Chromie . Progress: Oooh, that one is my favorite!", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 85, ["db2PoiMapID"] = 1, ["questLines"] = { { ["id"] = 5676, ["name"] = "Adventure Awaits", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
