[85027] = { ["id"] = 85027, ["name"] = "Lorewalking: The Protectorate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries. So! Who are these strangers? What do we know of their history? We must piece it together, it seems. But our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.", ["objectivesText"] = "Follow Cho's guidance to learn about the ethereals.", ["rewardGold"] = 1024800, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85028] = { ["id"] = 85028, ["name"] = "Lorewalking: The Brokers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 10565, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers. They share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade. Yet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.", ["objectivesText"] = "Follow Cho's guidance to learn about the brokers.", ["rewardGold"] = 1024800, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10565 } }, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85029] = { ["id"] = 85029, ["name"] = "Lorewalking: Locus-Walker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. Not just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power. But there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.", ["objectivesText"] = "Follow Cho's guidance to learn about void ethereals.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["mapID"] = 2393, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85032] = { ["id"] = 85032, ["name"] = "What Is Left of Home", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["series"] = { 84855, 85961, 93979 }, ["description"] = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", ["objectivesText"] = "Speak to citizens of Tazavesh and members of the Trust. Progress: There will be a day when K'aresh is restored.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231128, ["x"] = 0.376, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85035] = { ["id"] = 85035, ["name"] = "Locus-Walker, Telogrus Ranger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. I have been sent with an object for you to deliver to Locus-Walker . He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there. There is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?", ["objectivesText"] = "Deliver Ve'nari's device to Locus-Walker in Telogrus Rift. Progress: Why have the Shadowguard come here, of all places?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 231831 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 234111, ["x"] = 0.64, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 971, ["db2PoiMapID"] = 1865, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85036] = { ["id"] = 85036, ["name"] = "Veni Vidi Ve'nari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "A broker sent you with this device? And they were sent to you by Ve'nari? This does not bode well.", ["objectivesText"] = "Witness the conversation with Locus-Walker . Progress: I have much to think about, my friend--and much to add to my studies!", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["rewardItems"] = { 242386, 244843, 245567 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9415 } }, ["db2PoiUiMapID"] = 2393, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85037] = { ["id"] = 85037, ["name"] = "That's a Wrap", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius? < Xal'atath chuckles.> Very well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.", ["objectivesText"] = "Speak to Xal'atath to assemble the Reshii Ribbons . Progress: What is Xal'atath 's game here? She had ample opportunity to trick us.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231520, ["x"] = 0.442, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231522, ["x"] = 0.428, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85039] = { ["id"] = 85039, ["name"] = "Compromised Containment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked. If you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.", ["objectivesText"] = "Kill Arcane Creatures and seal the Unstable Artifact . Progress: Have you completed your assignment?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237891, 237894 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231564, ["x"] = 0.565, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 231564, ["x"] = 0.565, ["y"] = 0.7255 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
