[85051] = { ["id"] = 85051, ["name"] = "Beach Comber", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "There's a peculiar mechanical gnome scouring the beach nearby for valuable scrap metals. I am concerned for his safety but also intrigued. I just wonder what he's trying to find! Maybe he would be willing to share anything he finds in exchange for your assistance... Could you aid him in recovering any valuable items?", ["objectivesText"] = "Assist Kerchunk in his search for 24 Salvageable Scrap Progress: Have you found any Salvageable Scrap ? I'm looking for all I can find.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229967 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231783, ["x"] = 0.416, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231783, ["x"] = 0.416, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85052] = { ["id"] = 85052, ["name"] = "A Lucrative Opportunity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Most fortuitous greetings, offworlder! I have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh! It just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit. It would bring good fortune to my endeavor to have your help with this. Can I count on you, <race>?", ["objectivesText"] = "Seek out Cartel Boss Xy'eolm in Tazavesh on K'aresh .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231674, ["x"] = 0.48, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
},
[85053] = { ["id"] = 85053, ["name"] = "Obtaining Permits", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "There is a difference between securing a permit and securing permission to sell in Tazavesh. Xy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission. Not everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.", ["objectivesText"] = "Obtain permission for Vaultkeeper Xy'vez in Tazavesh. Progress: Have you done what I asked?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85054] = { ["id"] = 85054, ["name"] = "Articles of Acquisition", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand? You may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop. This venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.", ["objectivesText"] = "Return to Vaultkeeper Xy'vez in the market of Tazavesh on K'aresh . Progress: Do we have good news, offworlder?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 244847 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85055] = { ["id"] = 85055, ["name"] = "Expired Goods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always. Thus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. You and I, <name>, are selling opportunities to purchase what remains. Blind of course. Help me prepare.", ["objectivesText"] = "Help Vaultkeeper Xy'vez prepare the void storage vaults for sale in Tazavesh on K'aresh . Progress: Always so much to prepare before a first sale.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 1604, 11122, 22589, 22726, 50818, 185824, 190005, 190006, 190007, 190008, 245725, 245726, 245727, 245728 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85059] = { ["id"] = 85059, ["name"] = "A Piece of the Action", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85059 }, ["description"] = "Game on table look like fun. But Skaggit no want Jack to play. Maybe you can? Sneak in and put a bet down. We see who wins!", ["objectivesText"] = "Contribute to an event on the Siren Isle Command Map. Progress: Did you put down a bet?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85060] = { ["id"] = 85060, ["name"] = "Pirate Foods and Superstitions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85060 }, ["series"] = { 85047 }, ["description"] = "Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage. We've tried to make out his scribbles, but alas, we only managed to make the ink run. Me matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!", ["objectivesText"] = "Help the Booty Bay Buccaneers figure out how to recreate Cooktholomew's lucky feast. Progress: Cooktholomew and I have spun many a yarn talking about words and language. He was a lot deeper than most folk around here gave him credit for.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 229968, 231263 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231413, ["x"] = 0.608, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 105637, ["x"] = 0.4152, ["y"] = 0.704533 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 71, 210 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
