[85075] = { ["id"] = 85075, ["name"] = "To Stormsong", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 87340 }, ["description"] = "We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. Bring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.", ["objectivesText"] = "Travel to Stormsong Valley in Kul Tiras to get some bees for Ve'nari . Progress: Where did you come from?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 167744, 169614, 202046, 230030 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 942, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85076] = { ["id"] = 85076, ["name"] = "Don't Bee Crazy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "Something is agitating the bees, and I suspect it's these honey-crazed maulers ! Take some down and see if it helps. Even if it doesn't, you're doing the world a favor. They are completely out of control!", ["objectivesText"] = "Slay 10 maulers in the Highland Flats and Mildenhall Meadery. Progress: The poor bees...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85077] = { ["id"] = 85077, ["name"] = "Sticky Fingers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down. It looks like their honey is being stolen. Try to take some honey back from those honey... blob... things? Can't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!", ["objectivesText"] = "Collect 7 Honey Globules at the Mildenhall Meadery. Progress: Did you get the honey?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230053 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85078] = { ["id"] = 85078, ["name"] = "Bee in the Bonnet", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "While you were out, I scouted some of the smaller bee hives . They all look like they've suffered damage. We should investigate them. Maybe that's the cause of their aggression?", ["objectivesText"] = "Investigate 4 Bee Hives . Progress: What could have driven something to destroy so many hives?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85079] = { ["id"] = 85079, ["name"] = "Such a Sleebee-head", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "We need to deal with the hive guardians one way or another if we are going to investigate this place. I do hope we don't have to kill them.", ["objectivesText"] = "Tranquillize or slay 5 Hive Guardians . Progress: We should keep as many bees alive as possible.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230210 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85080] = { ["id"] = 85080, ["name"] = "An Un-Bee-lievable Solution", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85081, 85082, 85249 }, ["description"] = "If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. Do you have any ideas? Perhaps that friend of yours has something? If you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.", ["objectivesText"] = "Collect the Anima Vacuum and use it to vacuum up 15 Honey Bees. Progress: Have you rescued the bees?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229424 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85081] = { ["id"] = 85081, ["name"] = "Beehemian Rhapsody", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85080, 85082, 85249 }, ["description"] = "We need a way to lure out the queen so we can take her away from here. Oh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. You said you were after bees? I think she'd be a great fit.", ["objectivesText"] = "Place the Honey Pot and use it to lure out and rescue the Queen Bee. Progress: If we can get her to safety, and bring some of her hive, they can rebuild.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230549 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["db2PoiUiMapID"] = 942, ["db2PoiMapID"] = 1643, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85082] = { ["id"] = 85082, ["name"] = "To K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85080, 85081, 85249 }, ["description"] = "We've secured the queen and apparently sent some bees to K'aresh. So... How do we get there?", ["objectivesText"] = "Return to the Oasis on K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
