[85083] = { ["id"] = 85083, ["name"] = "Photogra-Bee", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85084, 85257 }, ["description"] = "The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here. We should document it. It's not science if you don't write it down. You'll find them mostly around the plants.", ["objectivesText"] = "Document 10 Honey Bees. Progress: Have you documented the bees?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230729 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
