[85109] = { ["id"] = 85109, ["name"] = "Renowned with the K'aresh Trust", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85109 }, ["description"] = "Traveler, your aid to K'aresh will never be forgotten. You have our deepest gratitude. As a token of our appreciation, we have prepared a gift for you. Seek out Om'sirik in Tazavesh. He will see that it reaches your hands.", ["objectivesText"] = "Speak with Om'sirik in Tazavesh.", ["rewardItems"] = { 230032 }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 235252, ["x"] = 0.406, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2659, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
