[85151] = { ["id"] = 85151, ["name"] = "In Her Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85001, 85002, 85011, 85155, 85804 }, ["description"] = "The two of you fell into the trap I set for Shadowlord Vesheen . I need to know what his orders are from Salhadaar and what he knows about Xal'atath's plans. Now, the three of us are going to sneak into this camp and see what we can discover. We're not here to fight--just some reconnaissance. I don't want him to know that I'm after him.", ["objectivesText"] = "Sneak with Alleria through the camp at the Fracture of Laacuna to uncover clues about Shadowlord Vesheen . Progress: I keep retracing my steps and all I've uncovered are whispers that Xal'atath has a force amassing somewhere out in the void. I have further suspicions, but there's more to uncover.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 21404, 21405, 21406, 25933, 25934, 25935, 32446, 43857, 43912, 43945, 43980, 49888, 54985, 54986, 58217, 66247, 90858, 90859, 90860, 90861, 90862, 93386, 94219, 114723, 114724, 114725, 114726, 128827, 130222, 147474, 152711, 211279, 237812 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231987, ["x"] = 0.552, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231987, ["x"] = 0.552, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85155] = { ["id"] = 85155, ["name"] = "Do You Have a Spare?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85001, 85002, 85011, 85151, 85804 }, ["description"] = "Now that we know where Vesheen is, I need a cage to put him in so I can get my answers. And I know just the person who will provide us with one. Ve'nari . You'll find her in the eco-dome called the Oasis. It's on the island off to the east. Do what you must and don't take no for an answer, <name>.", ["objectivesText"] = "Travel to the Oasis and convince Ve'nari to provide you with a cage.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231987, ["x"] = 0.552, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85174] = { ["id"] = 85174, ["name"] = "Get Out There", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "You all saw what Gallywix can do. These weapons, this Black Blood--we have to cut him off at the source. Revilgaz, you've gotta kill their shipments coming out of your HQ. And Grimla, Venture Co. has to be involved for Nikki the Fixer to be so well-armed. Split up. <name>, I want you with me. I've got a newsman, Dirk, you'll want to talk to in Tailgate Park. We'll need hearts and minds to take back this city. I'll be there soon.", ["objectivesText"] = "Speak with Dirk Greasedealer in Tailgate Park.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225523, ["x"] = 0.398, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226660, ["x"] = 0.485, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85184] = { ["id"] = 85184, ["name"] = "Repossession is Nine-Tenths of the Law", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85185, 85186, 85196, 85212, 85213, 85214 }, ["description"] = "A cage you say? Of course, I have one. But, it's not free. I'll need something in return. Several somethings. I believe the saying in your world is, \"You scratch my back, I'll scratch yours.\" To my point, there are Wastelanders occupying the nearby ruins. They are illegally hoarding relics of historic importance which belong to all the K'areshi. I want you to repossess them. Take my portation tags to make it all easier. However else would you carry so many? Your backpack isn't that big.", ["objectivesText"] = "Use Ve'nari 's portation tags to repossess 10 Ancestral K'areshi Relics.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85185] = { ["id"] = 85185, ["name"] = "Those As Well", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85186, 85196, 85212, 85213, 85214 }, ["description"] = "There are any number of stolen smaller, but still significant artifacts in the ruins at North Sufaad. While you're out there, I see no reason why you should not also retrieve them for me. I'm certain I can make the transaction worth your time. I trust this isn't beneath you... so long as the payment is sufficient.", ["objectivesText"] = "Recover 6 Lesser K'areshi Artifacts from Wastelanders at North Sufaad. Progress: These lesser artifacts can also be of great importance. To the K'areshi people, of course.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232618 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85186] = { ["id"] = 85186, ["name"] = "A Cage for Alleria", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85185, 85196, 85212, 85213, 85214 }, ["description"] = "I do so love a bit of intrigue. Please hurry back and let me know how everything plays out with this new Shadowguard lieutenant. Actually, I might just come pay you a visit. I'm sure Alleria will get all the answers she's after this time...", ["objectivesText"] = "Deliver Ve'nari's Package to Alleria at Shan'dorah. Progress: Do you have the cage? I hope Ve'nari didn't make you jump through too many hoops. Nothing's for free with her. Nothing.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232623 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232110, ["x"] = 0.608, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85189] = { ["id"] = 85189, ["name"] = "Our Day in Court", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Another series of miscellaneous and legally questionable tasks done well, <name>! You should really consider going into this line of work full time... whatever line of work this is exactly. I'll grab the Gnomes's signatures, and meet you back at my office. Normally I'd be willing to give you a ride, but I've got a personal errand to run first. You'll see.", ["objectivesText"] = "Meet Marty Zoomcart at his office in Hovel Hill.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227018, ["x"] = 0.386, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.3975 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85190] = { ["id"] = 85190, ["name"] = "Settled Dust", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["series"] = { 87321 }, ["description"] = "I'm surprised Shaw showed up in person. I thought he'd send an agent or somethin', but... maybe I should start expectin' better of people. I made sure Renzik got looked after. Got the respect he deserves. This chest took me a long time to make. A lot of tiny tools. I'm not used to detail work like that, but I got it done pretty good. I'm sure he could still pick the lock like nothin', but... <Gazlowe smiles sadly.> Let's get him sent back home to Stormwind, yeah?", ["objectivesText"] = "Speak to Gazlowe to return Renzik's ashes to Mathias Shaw.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 232822, ["x"] = 0.425, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 234783, ["x"] = 0.3, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 52, 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 52, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[85191] = { ["id"] = 85191, ["name"] = "Cut After Cut", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 40, ["mapID"] = 52, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "Renzik was one of my finest agents--but more than that, he was a friend. He wasn't an agent of the Stormwind crown begrudgingly fulfilling a mission in Undermine . He worked for Stormwind, but he loved Undermine . His people were his home. Not us. Help me gather up some of Renzik's things he left here. They should go back to Undermine , along with him.", ["objectivesText"] = "Collect Renzik's belongings around the Westfall Lighthouse. Progress: Renzik never opened up all the way, but I saw what I needed to through the cracks.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233655, 233656, 233657, 235629, 237267 }, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 234783, ["x"] = 0.3, ["y"] = 0.86 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 234783, ["x"] = 0.3, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 40 } }, ["db2PoiUiMapID"] = 52, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85192] = { ["id"] = 85192, ["name"] = "Coming Home", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 40, ["mapID"] = 52, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "Renzik would want his ashes returned to Undermine . I know that for certain, and I would like to do my friend one last favor by seeing it done. I'm sure he'll like it far more than being stuffed under a marble slab in the Stormwind cemetery, far away from his people. Let's go, <name>.", ["objectivesText"] = "Meet Gazlowe and Mathias Shaw on the upper stairs of the Scrapshop in Undermine . Progress: Knowin' he always thought of Undermine as a home... That's somethin'. I could've learned a lot more from him.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 234783, ["x"] = 0.3, ["y"] = 0.86 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 234801, ["x"] = 0.392, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 52, 2346 }, ["zone"] = { 40 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85195] = { ["id"] = 85195, ["name"] = "Pirate Gastronomy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 85195 }, ["series"] = { 85208 }, ["description"] = "Here are Cooktholomew's notes deciphered. Even though this still looks strange, I am positive I deciphered it correctly. I was able to work out how much of everything you need, but it looks like he had his own names for different ingredients, so... good luck!", ["objectivesText"] = "Use Rosa's Boonful Banquet translation notes to search for the ingredients. Progress: Don't ya worry. We're a patient bunch, we are.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 2452, 4402, 6359, 6522, 27439, 33823, 41800, 41813, 46874, 51559, 74846, 160711, 229968, 231263 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 105637, ["x"] = 0.4152, ["y"] = 0.704533 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231413, ["x"] = 0.608, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.4152, ["y"] = 0.704533 }, ["mapCandidates"] = { ["npc"] = { 71, 210 }, ["zone"] = { 5287 } }, ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 230235 }, ["questType"] = "standard", ["flags"] = {  },
},
[85196] = { ["id"] = 85196, ["name"] = "Tag, You're It", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85185, 85186, 85212, 85213, 85214 }, ["description"] = "Vesheen is up in the Khiyed Ruins to the north. The fool thinks he's so clever, but he's about to find out who he is dealing with. Wear him down and then place Ve'nari's tag on him. It will teleport him into the cage here. I'll stay here to make sure the cage works. Hurry, <name>, before he realizes we're on to him!", ["objectivesText"] = "Weaken Shadowlord Vesheen and then place Ve'nari's Portation Tag on him to teleport him into Alleria's cage. Progress: He's going to tell me everything. Too much is riding on this for half measures.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232110, ["x"] = 0.608, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233885, ["x"] = 0.608, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85208] = { ["id"] = 85208, ["name"] = "A Pirate Missive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85208 }, ["series"] = { 85195 }, ["description"] = "There you are, <name>. Someone named Scowling Rosa wants to see you in Booty Bay.", ["objectivesText"] = "Pick up the notes from Scowling Rosa in Booty Bay.", ["rewardGold"] = 26210, ["rewardXP"] = 175, ["rewardItems"] = { 2452, 4402, 6522, 27439, 33823, 41813, 74846, 160711 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 105637, ["x"] = 0.4152, ["y"] = 0.704533 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 210 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard", ["flags"] = {  },
},
[85212] = { ["id"] = 85212, ["name"] = "A Void Test of Wills", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85185, 85186, 85196, 85213, 85214 }, ["description"] = "This will be dangerous. I intend to use the Void to break his will and extract what I can from his mind. <name>, stand ready to assist. First, we'll set up some ritual devices. Then, listen for my instructions. One false move could mean our doom.", ["objectivesText"] = "Assist Alleria in her void contest to break Shadowlord Vesheen 's will. Progress: It seems our war against the Void is never-ending.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233885, ["x"] = 0.608, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233980, ["x"] = 0.608, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85213] = { ["id"] = 85213, ["name"] = "Off to Tazavesh, Again", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85185, 85186, 85196, 85212, 85214 }, ["description"] = "Now that we've helped my mother, it's time to continue on. < Arator seems choked up at the idea of leaving his mother again so soon.> Ve'nari helped us before. I know it's dangerous, but maybe she can get us into the Maw to find Sylvanas?", ["objectivesText"] = "Work with Arator and Ve'nari to decide how best to proceed. Progress: Well, hello there. Again.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 242715 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233980, ["x"] = 0.608, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232124, ["x"] = 0.605, ["y"] = 0.926 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85214] = { ["id"] = 85214, ["name"] = "Here Goes Something", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85184, 85185, 85186, 85196, 85212, 85213 }, ["description"] = "Getting you into the Maw to visit his auntie, Sylvanas, can be done... but at no small risk to Arator . Under no circumstance should he linger there. However, that is your business. I am in the business of keeping my slates clean, and this is something I can do for you. The engine of Tazavesh can power a gateway and allow the two of you to break into that dreadful place.", ["objectivesText"] = "Use the power of the city to open a gateway to the Maw.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232124, ["x"] = 0.605, ["y"] = 0.926 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.926 }, ["mapCandidates"] = { ["npc"] = { 1543, 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 1543, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85229] = { ["id"] = 85229, ["name"] = "Rallying All Rapscallions!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 85229 }, ["description"] = "Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha", ["objectivesText"] = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .", ["rewardItems"] = { 229390, 230284, 230287 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219215, ["x"] = 0.555, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["startItems"] = { 230284 }, ["questType"] = "standard", ["flags"] = {  },
},
[85238] = { ["id"] = 85238, ["name"] = "Stranger on the Steps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["description"] = "Please! We have to stop the Naakroans. Three of us were sent by cartel Om to install a research machine. It was only meant to help study extinct plants. At first, the Wastelanders were polite, even curious--until we tried to leave. They forced us to modify the machine. Om'musa refused and they killed him. Om'baladh and I obeyed. We should have refused as well. Once we finished, the Wastelanders let their guards down. Om'baladh said to run, so I did. He was right behind me. Please--find him.", ["objectivesText"] = "Find Om'baladh . Progress: Oh, my friends. What have we done?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85239] = { ["id"] = 85239, ["name"] = "A New Devouring", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["description"] = "This isn't a temple anymore--it's an abattoir. They tear souls from captives to power their rituals. Right now, they're pouring stolen energy into our machine. I think I know why. With the modifications we made, overloading the device with arcane energy will create a massive feedback loop. It'll disrupt our technomancy across K'aresh . The eco-domes will fail. Tazavesh will be defenseless. We'll be just another feast for the Naakroans. If you can disrupt their rituals, it will buy us time.", ["objectivesText"] = "Disrupt the Naakroan rituals. Progress: Stop the rituals. End the suffering of their captives.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85240] = { ["id"] = 85240, ["name"] = "Only Hunger Remains", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["description"] = "They think Xal'atath has returned for them--that their worship will be rewarded. They'll consume everything to prove their devotion to her. We came here for peace--to rebuild our shattered home. We have to protect the future, $p. It's all we have left. These Wastelanders are massing to raid the eco-domes. If they manage to bring down the shields, they'll pick them clean. Don't give them that chance.", ["objectivesText"] = "Slay Naakroan Wastelanders. Progress: We won't let them take what we've built.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85241] = { ["id"] = 85241, ["name"] = "A Once-Proud Priest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["series"] = { 86193 }, ["description"] = "Their leader conducts the last ritual site. Issam the Unraveler ... I saw him live up to that name. If he uses our echo machine against us, he and his followers will tear through everything. We'll all be offerings to their absent \"god.\" Slay him and end his ritual. We can't allow a second Devouring.", ["objectivesText"] = "Slay Issam the Unraveler . Progress: Killing him should stop the ritual. It has to.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85242] = { ["id"] = 85242, ["name"] = "Seasonal Refresher", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 85242, 85243, 85244 }, ["description"] = "We're back tae uncovering more things within delves! Let's get ye up to speed on new items we've found first. Then I've got some concerning information tae talk about.", ["objectivesText"] = "Learn about Season 2 of Delves from the Delver's Documents, then purchase supplies from Reno Jackson and Sir Finley Mrrgglton.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5698, ["name"] = "Delves - Season 2", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85243] = { ["id"] = 85243, ["name"] = "I Want My Hat Back", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 85242, 85243, 85244 }, ["description"] = "Ye may have noticed a change in me fashion. Some goblin went and took me hat! And all the treasures we had collected so far! I'll tell ye how it all went down.", ["objectivesText"] = "Listen to Brann's story of how he lost his treasures and his hat.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229974 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5698, ["name"] = "Delves - Season 2", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
