[85244] = { ["id"] = 85244, ["name"] = "Defeating the Underpin", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15991, ["mapID"] = 2339, ["storyline"] = { 85242, 85243, 85244 }, ["description"] = "This blasted \"Underpin\" took me hat! Along with all the curios we collected. It's time tae get some vengeance. We got tae get stronger if we're going tae take him down. I know he's somewhere in Undermine when yer ready tae tackle him. I'll be right there with you!", ["objectivesText"] = "Increase your item level to challenge the Underpin in his tier 8 delve within Undermine.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 212170, 230727 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 15991 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5698, ["name"] = "Delves - Season 2", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
