[85252] = { ["id"] = 85252, ["name"] = "Lorewalking: Children of the Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15969, ["mapID"] = 84, ["storyline"] = { 48962, 49354, 49787, 53735, 53737, 53882, 54096, 85252, 85254 }, ["description"] = "The blood elves of the Eastern Kingdoms have only taken up that name in recent years. Once, they were known as highborne, or high elves--but no more. Would that it were a pleasant tale, but in truth the name reflects upon those who have fallen and lost their lives... an unthinkable number. The blood elves, or sin'dorei, will never forget that loss. Let us remember them as well.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 242386 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 234616, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 234616, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 15969 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85254] = { ["id"] = 85254, ["name"] = "Lorewalking: Children of the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15969, ["mapID"] = 84, ["storyline"] = { 48962, 49354, 49787, 53735, 53737, 53882, 54096, 85252, 85254 }, ["description"] = "The void elves... so strange. There is very little difference between a void elf and a blood elf, other than what they have chosen to wield. Yet to their former kin, they are anathema--no longer considered a blood elf at all, and no longer welcome in their former home. Let us explore how, and why, this came to be.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 242386 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 234616, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 234616, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 15969 } }, ["questLines"] = { { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85255] = { ["id"] = 85255, ["name"] = "Tranquila-Bee", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85256, 85258, 85259, 85260, 85261, 85262 }, ["description"] = "I think we should start prepping to move the bees into the Oasis. I'd like to tag them so we can monitor the hive. Bees don't tend to stand still for long. We'll need to tranquilize and tag them. I tagged the queen. Would you tag the honey bees?", ["objectivesText"] = "Tranquilize and tag 10 bees in Eco-Dome: Primus in K'aresh.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230210 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85256] = { ["id"] = 85256, ["name"] = "Botany, Finally", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85258, 85259, 85260, 85261, 85262 }, ["description"] = "The bees are doing well and have no negative interactions with the local fauna. But what about the flora? I have some cuttings of plants from the Oasis. Would you gather some cuttings from this dome so I can compare them?", ["objectivesText"] = "Collect 10 K'aresh Flora Cuttings . Progress: I'm terribly excited to work on plants again. It's been quite a while now. Get it? Bee-n?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230809 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85257] = { ["id"] = 85257, ["name"] = "Primus Buzzness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85083, 85084 }, ["description"] = "Alright. Let's get these bees into Eco-Dome: Primus for the next round of tests!", ["objectivesText"] = "Meet Botanist Alaenra in Eco-Dome: Primus.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85258] = { ["id"] = 85258, ["name"] = "Oh Honey Honey", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85256, 85259, 85260, 85261, 85262 }, ["description"] = "The hive has settled in quite well. I'd like to do a quick honey check though. The pollen in these plants is quite different, and it should change the honey quite a bit. We need to make sure it's working for the hive. It should be fine based on the experiments in the earlier domes. Best to check though, right?", ["objectivesText"] = "Collect 8 Honeycombs and then pet the Queen Bee in the Oasis. Progress: Have you collected the honeycomb ?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 124640, 152668, 162286, 211279, 230907 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85259] = { ["id"] = 85259, ["name"] = "Waggle Dance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85256, 85258, 85260, 85261, 85262 }, ["description"] = "Alaenra requested that I pass on a message. \"Hey, Om'talad . I'm going to dance for the bees so they know where the new flowers are. Can you ask <name> to do the same?\" Odd, but please feel free to... frolic.", ["objectivesText"] = "Dance for the bees in the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85260] = { ["id"] = 85260, ["name"] = "Hiving a Hard Day", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85256, 85258, 85259, 85261, 85262 }, ["description"] = "I just spotted a few bees flop to the ground. I think they've overworked themselves trying to get at the new plants. They'll be fine. They're just tired. Could you help me pick them up and bring them back to the hive?", ["objectivesText"] = "Pick up 10 Overworked Honey Bees and return them to the hive. Progress: Poor bees! Handle them carefully.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 124640 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
