[85261] = { ["id"] = 85261, ["name"] = "Bee Roll", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85256, 85258, 85259, 85260, 85262 }, ["description"] = "Ah, there you are. It's time for documentation! We need to keep track of how the bees are doing in the Oasis. I've filled out the paperwork already. Perhaps you could get me some photos of the bees in action?", ["objectivesText"] = "Document 10 Honey Bees and the Queen Bee . Progress: Have you gotten some good shots?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 231163 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85262] = { ["id"] = 85262, ["name"] = "The Royal Procession", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85255, 85256, 85258, 85259, 85260, 85261 }, ["description"] = "Hmm, your photos make me think the hive is ready to swarm! This is the ultimate goal of any hive--birth a new queen and create a new hive. It does mean our queen needs to move to a new location, but there is plenty of eco-dome to go around, right? Can you help her find a new location?", ["objectivesText"] = "Help the Queen Bee find a new hive location. Progress: Have you gotten the old queen settled in?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
