[85394] = { ["id"] = 85394, ["name"] = "An Eye for Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85383, 85384, 85394 }, ["description"] = "If we were to consider the silver lining here, it is that we now know our concoction works. Just not on whom we wished. I do not suppose you have it in you to defeat this empowered version of the creature? It is only our reputations and the future of Tazavesh at stake. Another chance to prove you truly are as mighty as they say.", ["objectivesText"] = "Defeat Bakishroth the Empowered and save Tazavesh! Progress: Is it done, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245733, 245734, 245735, 245736 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5699, ["name"] = "That Tazavesh Taste", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
