[85409] = { ["id"] = 85409, ["name"] = "Snitches Get Stitches", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "I thought we could talk here in Gutterville, but it feels tense. They're all Venture Company, but I don't recognize a lot of 'em. Word is, Gallywix sent down a bunch of workers who are sympathetic to him so they could spy on us. Clear out some of these turncoats. If any of them report to Overseer Gozzic that we're working against the pipeline, he'll go after my people.", ["objectivesText"] = "Remove the Venture turncoat spies in Gutterville. Progress: The spies are everywhere, I tell ya.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232353, 232394, 232396, 232398 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225772, ["x"] = 0.7088, ["y"] = 0.8652 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225772, ["x"] = 0.7088, ["y"] = 0.8652 }, { ["mapID"] = 2214, ["npcID"] = 232491, ["x"] = 0.722, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.7088, ["y"] = 0.8652 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
