[85410] = { ["id"] = 85410, ["name"] = "Undermine's Long Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "These engineers have been through a lot. Let's make sure they're good. Maybe they can shed some light on Undermine.", ["objectivesText"] = "Speak with Pamsy's engineers. Progress: There's a lot of information to chew on.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.703333, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
