[85429] = { ["id"] = 85429, ["name"] = "Overwhelm Them", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "There's an audit coming up. My employer, Xy Imports, will be audited. Again. <Xy'nell visibly shakes, ducking his head.> I need this audit to go badly. It must be worse than the last. Can you help me? We have a shipment of small devourers that would cause a lot of trouble if they were to escape or go missing. Break open their crates. Business needs to be overwhelmed just like last time.", ["objectivesText"] = "Break 8 Xy Imports Crates on the docks in Tazavesh.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
},
[85430] = { ["id"] = 85430, ["name"] = "Mandatory Time Off", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "If my colleagues knew of my plan, they would be in danger of discharging their oaths as good employees. Besides that, they are far too excellent at their jobs. Take these. They're devices of my own creation. When placed near my colleagues, it will create an illusion of them working. They will be able to step away and rest. And the business will be under even more pressure without them.", ["objectivesText"] = "Place 7 Illusion Devices . Progress: I had to become good at illusions for this job. It was the only way to make it tolerable. Maybe now I can use those skills to help others for once.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
},
[85431] = { ["id"] = 85431, ["name"] = "Drain Their Resources", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "We've made good progress, but we need more disorganization. I've redirected a particularly large shipment of anima in the form of a devourer. Kill it and bring its anima core to me. The anima itself is not important--rather, the fact that it can be stolen. My boss will have more to answer for in the audit when his books are in disarray.", ["objectivesText"] = "Collect Overflowing Anima Core from Respleth the Hungerer outside Tazavesh. Progress: The Xy Imports associates transporting this anima are expecting a--ah--broker of sorts to relieve them of their charge. They will give you no trouble.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232609 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85432] = { ["id"] = 85432, ["name"] = "Confuse Their Contacts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "When our imports are delayed or lost, the most direct impact is on Tazavesh businesses. Take this illusion pin. It will make you appear as a Xy Imports employee. Tell the businesses their shipments are delayed indefinitely. My boss cannot ignore downstream pressure forever.", ["objectivesText"] = "Speak with market vendors in Tazavesh. Progress: This is not the first time the market vendors have dealt with my boss's failings. I only hope it is the last.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232644 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85433] = { ["id"] = 85433, ["name"] = "Eyes on Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "I can hear Coordinator Xy'thir raging about the slide in business already. <Xy'nell shifts uncomfortably and ducks his head.> We're ready. Go to Port Authority Zo'rau . Tell them you represent an invested party and that the audit should be moved up. And there's one more thing I need you to do. Speak with me before you go.", ["objectivesText"] = "Speak with Port Authority Zo'rau in Tazavesh. Progress: This is more important than I can say, <name>. But I cannot break my oath. Deliver the pin to Zo'rau.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 22829, 22832, 38760, 38761, 38762, 53416, 53448, 65278, 65298, 65317, 66887, 66889, 66890, 71083, 130219, 130220, 130222, 131333, 133998, 143536, 153069, 153071, 153219, 153226, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 190454, 190456, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 195204, 195205, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 211279, 217242, 217243, 225571, 228445, 228446, 228447, 228448, 232639, 232740, 232748, 232750, 232761, 232772, 232777, 232780, 232785, 237812, 239125, 250769 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
