[85434] = { ["id"] = 85434, ["name"] = "On a Technicality", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "It's time. I cannot tell you what to expect, $p. I only hope this is the last day I must keep such a dreadful oath. <Xy'nell shakes his head.> Let us hurry. Port Authority Zo'rau has already begun questioning Coordinator Xy'thir .", ["objectivesText"] = "Confront Coordinator Xy'thir in Tazavesh. Progress: <Xy'nell is silent before Coordinator Xy'thir .>", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245717, 245718, 245719, 245720 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 233942, ["x"] = 0.515, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85438] = { ["id"] = 85438, ["name"] = "Or Else", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "Am I glad I found you, <name>! My boss, Kraz Torquewrench, sent me to find you, and he don't take no for an answer, yanno? I thought I was gonna have to cash out and move futher underground, but here you are! Anyway, the boss's little girl is getting married, and he told me he wanted you, specifically, to help him \"finalize\" some \"details,\" with her intended and who's attendin'--if you get my meanin'.", ["objectivesText"] = "Speak with Kraz Torquewrench in Hovel Hill.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 52908, 52954, 131830, 237812 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233235, ["x"] = 0.44, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[85444] = { ["id"] = 85444, ["name"] = "Found Family", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "This crew trusted me. They're my family. We gotta see if any of them survived. I have other engineers who ain't here. They must have fled into the field. Razi , Keets , and Glizza are out there. Find 'em. Bring 'em home.", ["objectivesText"] = "Rescue Pamsy 's last engineers from the Writhing Fields. Progress: Don't leave those engineers out there to die.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228214, ["x"] = 0.705, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
