[85449] = { ["id"] = 85449, ["name"] = "Phase Shift", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "As soon as the ethereals attacked, phase resonance tore open rifts throughout the area. The rifts are gone, but the ethereals can return while the resonance remains. That is how they call more soldiers and communicate with their commanders. We need to destroy that resonance. It may earn us the ire of whoever is behind this attack, but I gladly invite them to stop us.", ["objectivesText"] = "Destroy 4 Phase Resonance in the Vatworks. Progress: We need to destroy that resonance if we are to stop this attack.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.294667, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
