[85451] = { ["id"] = 85451, ["name"] = "The Burning of Hammerfall", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "The Syndicate has put Hammerfall to torch! And the cowards are using pyromancers to feed the flames. But we can save our huts if we get to them quickly. Fight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!", ["objectivesText"] = "Use the Hammerfall Horn at each main structure in Hammerfall to summon a shaman and put out the flames.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 231766 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
