[85553] = { ["id"] = 85553, ["name"] = "Side Gig: Feeling Crabby", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 2346, ["storyline"] = { 85553 }, ["description"] = "Food's a critical resource for any crew that dares to sail the sea. So is gunpowder. Let's kill two crabs with one stone and get our hands on some of those bombshells out on the Kaja'Coast. Just don't get yourself blown up while you do it, yeah?", ["objectivesText"] = "Collect 15 Powdery Crab Meat from bombshell crabs on the Kaja'Coast. Progress: We'll need time to separate the powder from the crab, so get 'em here quick!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233483, 235339, 245653 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questType"] = "standard", ["flags"] = {  },
},
[85554] = { ["id"] = 85554, ["name"] = "Side Gig: It's Always Sunny Side Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Pterrordax eggs have been all the rage lately in the Undermine . And what good would the Blackwater name be if we couldn't import high-demand luxury goods? If you're interested in makin' some gold, head over to the Kaja'Coast and collect some for us. Oh, and make sure you don't take too many. Consumers these days love when we can label our goods \"ethical.\"", ["objectivesText"] = "Collect 8 Pterrordax Eggs on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232486, 232883, 233478, 233482, 234218, 235508, 245653 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 41, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85562] = { ["id"] = 85562, ["name"] = "Tougher Than We Thought", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Hah! I've never been feeling better! Now, we seize back what rightfully belongs to Blackwater, <name>. They've turned our prized headquarters into a smuggler's cove for that foul sludge. There are too many crates of Black Blood to deal with right now, but they can't move their cargo without fresh bodies. Let's cut them down.", ["objectivesText"] = "Reclaim the Port Authority from Darkfuse forces. Progress: There's blood to spill!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226372 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85570] = { ["id"] = 85570, ["name"] = "The Tattered Journal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15827, ["mapID"] = 2369, ["storyline"] = { 85570 }, ["description"] = "<The journal almost falls apart in your hands as you leaf through it. What few pages that remain are filled with an erratic scrawling script. Perhaps Stellin Verasa would be interested in this journal back in camp.>", ["objectivesText"] = "Take the journal to Stellin Verasa back in the Siren Isle camp. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232643, 233027 }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 15827 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85571] = { ["id"] = 85571, ["name"] = "Scattered To The Winds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85571 }, ["description"] = "My goodness! This journal is missing many of its pages! <Stellin flips through the journal, careful to not let any loose pages fall out.> This journal doesn't look very old... and it seems to be of human origin? Could this be the key to discovering what happened to the humans that came here? What a mystery! But less of a mystery if we could find the missing pages... Would you keep an eye out for them while you're out in the field?", ["objectivesText"] = "Collect 5 Journal pages around the isle. Progress: Have you found any more pages from the journal?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232643, 233027, 233831, 235543, 235544, 235545, 235546, 235547 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85572] = { ["id"] = 85572, ["name"] = "A Group Effort", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85572 }, ["description"] = "This is, um, quite the mess you've handed me. All these pages... what order do they go in? Aha! This journal seems to have belonged to a Kul Tiran that came here... <Stellin looks up, her eyes shining with excitement.> ...and it might hold the key to learning about their time on the isle. But the pages are hard to read... perhaps we should ask around to see if anyone can read them? Here, take a few pages. I'll keep trying to decipher the base journal while you go to camp and ask around.", ["objectivesText"] = "Ask Alta, Skitter, and Ricket if they can read the journal. Progress: <Stellin adjusts her glasses with a grimace.> This... seems like the author's signature. Had... is that a \"d\" or an \"l\" Had... do.. k--oh! Haddock? Or maybe that's an \"'e.\"", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233027 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85573] = { ["id"] = 85573, ["name"] = "Laid To Rest At Last", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85573 }, ["description"] = "<Stellin listens as you explain what you've learned and nods gravely.> This poor fellow was part of a crew that sailed here aboard a ship called the Maiden's Whisper. They were almost wiped out by a storm, but then even the survivors disappeared! He was the last one and... didn't make it either in the end. Perhaps we can put his memory to rest? I spotted a graveyard out behind the Kul Tiran's base... perhaps setting the journal there amongst his crew's graves will bring his memory some peace.", ["objectivesText"] = "Bring the Tattered Kul Tiran Journal to the graveyard behind the Kul Tiran base in the Abandoned Mines. Progress: <name>, did you find the graveyard?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232694, 233027 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85574] = { ["id"] = 85574, ["name"] = "Hazy Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85574 }, ["description"] = "<This crate phases in and out of existence with dark, necromantic energy. Regardless, Alyx would likely appreciate the supplies returned.>", ["objectivesText"] = "Return the Hazy Celebration Crate to Alyx . Progress: Yes?", ["rewardItems"] = { 232263 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 2339, ["npcID"] = 234262, ["x"] = 0.505, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 2339 }, ["zone"] = { 440 } }, ["db2QuestSortName"] = "Nightborne", ["db2LabelIDs"] = { 4061, 4063 }, ["startItems"] = { 232263 }, ["questType"] = "standard", ["flags"] = {  },
},
[85589] = { ["id"] = 85589, ["name"] = "Ruffled Pages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Many of the wyvern on this isle have crafted their nests from folios, scrolls, and documents they scavenge from the isle's ruins. Because of this, their nests may hold the clues we need to understand the full history of this place. Our scouts have secured grappling holds for you to climb to their nests, but use any means you like to recover the paper the wyverns have used as nesting material. Our knowledge of the isle's history depends on it!", ["objectivesText"] = "Collect 15 Nesting Papers from the wyvern nests around the island. Progress: I really want to see what's on the papers the wyvern have taken!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232361 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85648] = { ["id"] = 85648, ["name"] = "Delver's Call: Earthcrawl Mines", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 85648 }, ["description"] = "HELP WANTED Troubles continue within Earthcrawl Mines. Fine pay to whoever can handle it.", ["objectivesText"] = "Complete the Earthcrawl Mines delve on any difficulty. Progress: Are you the one who grabbed the task for Earthcrawl Mines?", ["rewardGold"] = 295000, ["rewardXP"] = 9515, ["rewardItems"] = { 232371 }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
