[85649] = { ["id"] = 85649, ["name"] = "Delver's Call: The Waterworks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15002, ["mapID"] = 2214, ["storyline"] = { 85649 }, ["description"] = "NOTICE The Waterworks have become unstable. Request aid in addressing issues.", ["objectivesText"] = "Complete the Waterworks delve on any difficulty.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 232371 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 15002 } }, ["questType"] = "standard", ["flags"] = {  },
