[85653] = { ["id"] = 85653, ["name"] = "Dipping a Toe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85653 }, ["description"] = "That ring of yours has caused quite a stir, hasn't it? And the history behind it... vrykul? Someone named Cyrce? I know you and Bargus unlocked more of the ring's potential by scouting the isle but... perhaps you should turn your attention to the sea? Take your ring into the water and see what happens. Bring whatever you find back to me. I'm a bit of a novice, but I might be able to piece whatever you find back together.", ["objectivesText"] = "Look for more citrines in the waters surrounding Siren Isle . Progress: Kobyss would give anyone thalassophobia. You're a brave soul looking for gems in that water.", ["rewardItems"] = { 229365, 232860, 232861, 232862 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.413333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questType"] = "standard", ["flags"] = {  },
},
[85654] = { ["id"] = 85654, ["name"] = "Juicing Up and Storming Out", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85654 }, ["description"] = "Well, look. If it ain't <name>, the talk of the camp. <Didi grabs your hand and looks closely at your ring.> That ring on ya finger sure is peculiar, ya sure ya don't want a different one? <Didi looks up at you and winks.> I'm just yankin' ya chain, let's see what we can do with it! Ya get me enough of that magic metal lookin' stuff we've been finding, and I'll see about gettin' you suited up in the Pummeler over there. Your ring oughta give it the juice it needs to really wreak some havoc!", ["objectivesText"] = "Acquire enough Flame-Blessed Iron to test out the N.U.K.U.L.A.R Target Painter and TR-06 Pummeler . Progress: Ya got around to finding some of that iron an' wreakin' some havoc out there?", ["rewardItems"] = { 229365 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questType"] = "standard", ["flags"] = {  },
},
[85655] = { ["id"] = 85655, ["name"] = "Unleashing Her Power", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85655 }, ["description"] = "This ring that you and Bargus found has taken you all over the isle learning its history and finding its treasures. The ring has aided you in your exploration--and in battle. But, we have never truly pushed the ring to find its limitations. Perhaps some formal testing is in order. Perhaps we can unveil more of its potential if we invite a bit of danger. Go now and test the ring against any worthy opponents you can find. Come back to me with your observations.", ["objectivesText"] = "Equip Cyrce's Circlet and fight creatures on the Siren Isle to trigger its hidden ability while in combat. Progress: Have you engaged in combat testing with the ring? What were your findings?", ["rewardItems"] = { 88375, 199830, 229365 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711333, ["y"] = 0.441333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questType"] = "standard", ["flags"] = {  },
},
[85656] = { ["id"] = 85656, ["name"] = "The Singing Bandit Catcher", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85656 }, ["description"] = "Seems you've gotten the hang of that ring, eh? Maybe you can put it to good use for me. Our supplies here--especially our gold and flame-blessed iron --have been disappearing! <Tanmar leans in to whisper.> Normally I wouldn't suggest this--the Arathi are a trustworthy lot--but the number of incidents is building. and I'm wondering if there's a thief among us. See if you can find 'em. They being pretty brazen. I'm sure you can catch 'em in the act somewhere!", ["objectivesText"] = "Catch three thieves. Progress: Keep your hand on your pockets. There are thieves everywhere, it seems like.", ["rewardItems"] = { 229365, 232860, 232861, 232862 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.413333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questType"] = "standard", ["flags"] = {  },
},
[85657] = { ["id"] = 85657, ["name"] = "Cyrce Would Be So Proud", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85657 }, ["description"] = "It ain't no secret the winds here are terrible. But! I don't think we've given that ring there a fair chance at fightin' 'em. I mean, that thing can let ya swim like a fish, make tornadoes outta nothin', and even shock the invisibility off of magical boxes! Surely it's got somethin' to say about a lil' nasty weather, right? Take my balloon up and see if you can keep it stable usin' that ring of yours. Maybe we can find the trick for stayin' in the sky!", ["objectivesText"] = "Fly in the Skypiercer to see if Cyrce's Circlet can protect you from the high winds. Progress: If that ring could help us outta storms, that'd be amazin'!", ["rewardItems"] = { 229365, 235041 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["db2PoiUiMapID"] = 2369, ["db2PoiMapID"] = 2127, ["questType"] = "standard", ["flags"] = {  },
},
