[85724] = { ["id"] = 85724, ["name"] = "Repel the Invaders", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "A big lunk of a hobgoblin, Skeez, took over the docks around the time that Gallywix had me thrown in the brig. He moved his Darkfuse in, and a lot of my Blackwater lads went missing. Captain took that personal, and so do I. Skeez thinks Gallywix will keep him safe. Let's kill him.", ["objectivesText"] = "Kill Dockmaster Skeez . Progress: Still in one piece, eh?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226372, 232486 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
