[85730] = { ["id"] = 85730, ["name"] = "Salvaging What's Left", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "The loss of an eco-dome is unimaginable. The death of Om'bera... <The broker's shoulders rise and fall in what looks like a sigh, though no breath is heard.> I cannot leave without retrieving the research crates! Her work must live on, even if she cannot. Om'bera's manifest says that there were at least five crates full of research and resources.", ["objectivesText"] = "Return 5 Stolen Research Crates to Om'resh . Progress: I don't understand the Wastelanders. I thought they were once oracles of Untamed K'aresh . Nature worshipers. Why do they steal from our domes and prevent the Trust's mission?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232876, 237858, 237870, 237879, 237886 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230294, ["x"] = 0.71, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230603, ["x"] = 0.684, ["y"] = 0.529 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
