[85871] = { ["id"] = 85871, ["name"] = "Lorewalking: The Blade's Forces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Xal'atath brings with her an army of shadows and tricks. They are nothing to our evolved forms! You have been chosen--blessed with power by N'Zoth to serve as his champion. Go now and destroy them!", ["objectivesText"] = "Defeat Xal'atath's forces.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 244888, 245567, 245631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2383, ["db2PoiUiMapID"] = 2383, ["db2PoiMapID"] = 2801, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
