[85875] = { ["id"] = 85875, ["name"] = "Ascent of the Lich King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "<Icecrown lies before you. Waiting. Frostmourne bids you... ... ascend.>", ["objectivesText"] = "Banish your memories. Progress: Arthas... my son.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 233811, ["x"] = 0.522, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["db2PoiUiMapID"] = 118, ["db2PoiMapID"] = 571, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
