[85876] = { ["id"] = 85876, ["name"] = "Reading the Runes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85876 }, ["description"] = "My curiosity is still not terminated, <name>. I would like to know more about these vrykul and why they came to this land. < Bargus 's wiry brows knit together and his mustache bristles as he thinks.> The tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. Perhaps there are additional tablets we missed? I have my ordained duties here, but please examine them and report back to me.", ["objectivesText"] = "Examine various Rune-Carved Tablets within the Forgotten Tomb.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85878] = { ["id"] = 85878, ["name"] = "O' Thanagor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 4820, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "You are the Lich King. The whole of Azeroth is arrayed against you. Show them what it means to be king.", ["objectivesText"] = "Defeat the usurpers atop Icecrown Citadel.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 4820 } }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
