[85879] = { ["id"] = 85879, ["name"] = "Reduce, Reuse, Resell", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85869, 85879, 86775 }, ["description"] = "The guys over at S.C.R.A.P. could use some extra hands this week. You want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you. But if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.", ["objectivesText"] = "Complete 3 S.C.R.A.P. jobs in Undermine . Progress: What d'you need, instructions? Big trash piles. Shovel. Get at it.", ["rewardItems"] = { 234741, 236682 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 }, { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 }, { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5900, ["name"] = "Undermine Repeatables", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard",
