[85884] = { ["id"] = 85884, ["name"] = "Lorewalking: The Prince Who Would Be King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown. Before he pulled that cursed sword from the depths of Frostmourne Cavern. We must talk about the prince who was promised the world, and the people who championed his cause. We must start in Lordaeron, many years ago, on a day of pomp and circumstance.", ["objectivesText"] = "Hear the story of Prince Arthas Menethil.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85885] = { ["id"] = 85885, ["name"] = "Lorewalking: No King Rules Forever", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart? Perhaps the undying servitude of his people? Just as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born. Where do we draw the line between man and monster?", ["objectivesText"] = "Listen to the story of the Lich King.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 242386, 244858, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
