[85941] = { ["id"] = 85941, ["name"] = "Attitude Adjustment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "I'm not a violent gal by nature, but there are a lot of Darkfuse out there. They're already hassling the locals and they won't like you guys asking questions. You wanna keep your friends safe? You wanna put the locals in better spirits? It'd probably be best if there were a whole lot less Darkfuse. If you catch my meaning.", ["objectivesText"] = "Kill 12 Darkfuse at Tailgate Park. Progress: My meaning was, go kill a bunch of Darkfuse so they don't kill your friends. Can't a gal be subtle?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85944] = { ["id"] = 85944, ["name"] = "Side Gig: Blood Type", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Darkfuse was up to all sorts of questionable research out in the Ringing Deeps and, well, everywhere, really. Anyway, they had to write some of it down. Nab whatever notes you can find and bring them back to me. Don't look at me like that. It's not intellectual dishonesty, it's industrial espionage!", ["objectivesText"] = "Collect 8 Darkfuse Research Notes in the Writhing Fields. Progress: Got the goods?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232863, 233451, 233483, 233484, 233485, 233533, 233534, 233536, 233538, 233539, 233540, 233541, 235359, 236096 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 44, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85945] = { ["id"] = 85945, ["name"] = "Side Gig: Blood-B-Gone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Do you have any idea how hard it is to get dried blood stains out of your laundry? Well, you might, I guess. Steamwheedle's finest are working on a new detergent specifically formulated to deal with this pressing issue! And while the blood fields in the Ringing Deeps might be bad for the environment, and you, they're the perfect place to field test our latest formulations. Just give the blood slimes out there a quick hose down and let us know what happens.", ["objectivesText"] = "Test Blood-B-Gone on 8 blood slimes in the Writhing Fields. Progress: We've got a market to corner here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232897, 233448, 233453, 233456, 233461, 233464, 233469, 233472, 233477, 233480, 233529 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 45, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
