[85947] = { ["id"] = 85947, ["name"] = "An Original Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 85947 }, ["description"] = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: You're not givin' up, are ya?", ["rewardGold"] = 1168400, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["db2LabelIDs"] = { 4063 }, ["questType"] = "standard",
},
[85948] = { ["id"] = 85948, ["name"] = "A Burning Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 85948 }, ["description"] = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1123600, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard",
},
[85949] = { ["id"] = 85949, ["name"] = "A Frozen Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4395, ["storyline"] = { 85949 }, ["description"] = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1353200, ["rewardItems"] = { 232877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard",
},
