[85960] = { ["id"] = 85960, ["name"] = "Side Gig: Lost in the Sauce", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Some of the workers forced by the Darkfuse to work the blood fields never made it home. We've got reports that they might be lost in whatever the \"Unseeming\" is. Apparently it's got something to do with the big blood puddles? Sounds like a job for someone more expendable--I mean experienced, than me.", ["objectivesText"] = "Rescue 8 Lost Goblins from the Unseeming in the Writhing Fields.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233453, 233461, 233469, 233477, 233480, 233484, 236096, 245653 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231063, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231063, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 46, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85961] = { ["id"] = 85961, ["name"] = "Moving the Pawns", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["series"] = { 84855, 85032, 93979 }, ["description"] = "There is a small island to the northwest of here, called Overlook Zo'Shuul. My scouts have been searching for a way into Manaforge Omega, where we must stop the return of the All-Devouring. If we are fortunate, the scouts have already found a safe pathway inside.", ["objectivesText"] = "Meet Locus-Walker at Overlook Zo'Shuul.", ["rewardGold"] = 147500, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230806, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[85962] = { ["id"] = 85962, ["name"] = "Side Gig: Unseemly Reagents", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "There's all sorts of weirdness going on in the Ringing Deeps thanks to all that Black Blood still lying around. And where there's madness and mutation, there's opportunity! Get out there and see what sort of horrific but potentially lucrative reagents you can scrape up.", ["objectivesText"] = "Collect 10 Unseemly Growths in the Writhing Fields. Progress: Try not to go crazy until after delivery, ok?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 124640, 232486, 232907, 235363, 235373, 235467 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 47, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86151] = { ["id"] = 86151, ["name"] = "Faceless Mask of the Burned Bridge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 86151 }, ["description"] = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", ["objectivesText"] = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Burned Bridge on the altar.", ["rewardItems"] = { 232917 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 232917 }, ["questType"] = "standard", ["flags"] = {  },
},
[86152] = { ["id"] = 86152, ["name"] = "Faceless Mask of the Daredevil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 86152 }, ["description"] = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", ["objectivesText"] = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Daredevil on the altar.", ["rewardItems"] = { 232918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 232918 }, ["questType"] = "standard", ["flags"] = {  },
},
[86153] = { ["id"] = 86153, ["name"] = "Faceless Mask of the Dark Imagination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 86153 }, ["description"] = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", ["objectivesText"] = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Dark Imagination on the altar.", ["rewardItems"] = { 174080, 174081, 232919 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 232919 }, ["questType"] = "standard", ["flags"] = {  },
},
[86154] = { ["id"] = 86154, ["name"] = "Faceless Mask of the Pained", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 86154 }, ["description"] = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", ["objectivesText"] = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Pained on the altar.", ["rewardItems"] = { 232920 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 232920 }, ["questType"] = "standard", ["flags"] = {  },
},
[86155] = { ["id"] = 86155, ["name"] = "Faceless Mask of the Long Night", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 86155 }, ["description"] = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", ["objectivesText"] = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Long Night on the altar.", ["rewardItems"] = { 232921 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 232921 }, ["questType"] = "standard", ["flags"] = {  },
},
[86156] = { ["id"] = 86156, ["name"] = "Getting Involved", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86156 }, ["description"] = "You. Do that again. Could be good stuff we ain't seen yet. Get those caves open an' see what's in there!", ["objectivesText"] = "Contribute 10 times to events on the Siren Isle Command Map and complete one event by slaying the target. Progress: Did you check out the cave? No? Get goin' then!", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
