[86177] = { ["id"] = 86177, ["name"] = "Side Gig: The Tides Provide", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "You look like the type who ain't shy to get your hands dirty. Up for a little treasure hunting? Word has it that a ship exploded not far off the Kaja'Coast. Go to shore and see what the tide's brought in. \"Finders keepers\" is one of the foundational tenets of goblin society, after all.", ["objectivesText"] = "Collect 5 Shiny Treasures along the Kaja'Coast. Progress: Gotta bring your own shovel. I never supply nothin', that's a liability waitin' to happen.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233453, 233461, 233469, 233477, 233480, 233484, 233527, 233537, 235346 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 49, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86178] = { ["id"] = 86178, ["name"] = "Side Gig: Cleanin' the Coast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "It's time for the Venture Company to earn a lil' good faith. We're lookin' to hire some efficient workers like yourself to clean up the Kaja'Coast. Could you help us kill some of the kaja'mentals that have gone... well, mental out there? We'll toss some competitive compensation your way.", ["objectivesText"] = "Kill 10 Agitated Kaja'mentals on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232485, 233478, 233480, 233533, 233534, 233536, 233538, 233539, 233540, 233541, 233542, 234217, 245653 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 50, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86179] = { ["id"] = 86179, ["name"] = "Side Gig: Lucky Break's Big Break", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "You know the Lucky Break Mines over on the Kaja'Coast? Settin' those up was kind of a rush job. Darkfuse didn't exactly give Venture a whole lotta time to reinforce the place. Long story short, there's a good chance the mines might collapse if we don't fix 'em up. That wouldn't be good news for anyone, especially not my wallet. Could you head over and rig up some support beams in the mines? That should do the trick for now.", ["objectivesText"] = "Place 6 Support Beams in the Lucky Break Mines on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232486, 233481, 233482, 233483, 233484, 235373, 235467, 236096 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 51, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86180] = { ["id"] = 86180, ["name"] = "Side Gig: Infested Waters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "So, my workers were supposed to be loadin' up some kaja'mite over in Zuldazar, but apparently the transport got upended and a shark swallowed the whole crate. I tried submittin' an insurance claim, but they ain't buyin' it. So we got no choice but to get that kaja'mite back ourselves. Down for a little shark huntin'?", ["objectivesText"] = "Retrieve the Swallowed Kaja'mite from the Kaja' Carrying Razormaw on the Kaja'Coast. Progress: You think the shark might end up bein' able to talk? I kinda want a talkin' shark.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232486, 232883, 233450, 233452, 233453, 233458, 233461, 233466, 233468, 233469, 233474, 233477, 233481, 233485, 233530, 235508, 236096, 236773 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 48, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86182] = { ["id"] = 86182, ["name"] = "Ghost Buster", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86183, 86184 }, ["description"] = "I have been working on the Oasis console and I believe I am ready for the next step. It will involve destruction, so naturally I thought of you. I need you to use a phase conduit to shift into the Untethered Space of K'aresh and retrieve the essence of the ghostly slatebacks. I will explain more when you return.", ["objectivesText"] = "Collect 10 Slateback Essence in the Untethered Space of K'aresh. Progress: Well? Have you succeeded?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229395 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86183] = { ["id"] = 86183, ["name"] = "The Power of Gods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86182, 86184 }, ["description"] = "Today, we create life. Assuming my calculations are correct--which they are--we can use the essence you gathered along with the data we have collected to create new slatebacks.", ["objectivesText"] = "Help Ve'nari use her machine to create life in the Oasis. Progress: Has the experiment succeeded?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86184] = { ["id"] = 86184, ["name"] = "Diminishing Returns", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86182, 86183 }, ["description"] = "The machine has its uses, but the slatebacks must start breeding so they can sustain themselves. Thus far, they have shown no inclination to do so. Take this device and use it to collect the slatebacks for testing. Om'talad will review the data.", ["objectivesText"] = "Shrink and collect 10 Slateback Roamers . Progress: Have you brought in the slatebacks as requested?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232432 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86185] = { ["id"] = 86185, ["name"] = "Running Free", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "Been talkin' to Ve'nari and Om'talad--trying to help the slatebacks get together. Apparently slatebacks used to display virility by engaging in races. Challenge the slateback alpha to a race. At worst, you'll both get some exercise. At best, it will increase the likelihood of a successful pairing.", ["objectivesText"] = "Race the Slateback Alpha . Progress: How's the race going?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86186] = { ["id"] = 86186, ["name"] = "The Super Sniffer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "It appears the slatebacks are not secreting the correct pheromones, resulting in them not breeding. We believe this is a side effect of the stasis. The technology was never tested for such an extreme length of time. Until now. Hemet tells me there are creatures called niffen in Azeroth that have expertise in this research. Bring me one from Azj-Kahet. You can use my portal to quickly get there.", ["objectivesText"] = "Travel to Mmarl in Azj-Kahet in Khaz Algar and find a willing niffen to help in the Oasis. Progress: I'm smellin' opportunity all over you!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2255, 2371 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
