[86188] = { ["id"] = 86188, ["name"] = "More-shrooms", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "Poor Gharrli needs to be set up while I'm away. The mushrooms you get will help with that. Get eight of them for now. We'll worry about the last one later!", ["objectivesText"] = "Collect 8 Rak-ush Mushrooms from Rak-ush and the nearby area. Progress: Got them mushrooms?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233010 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
