[86189] = { ["id"] = 86189, ["name"] = "Fungal Invasion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86190, 86191 }, ["description"] = "I'm sending you somewhere a lil scary, but I'm sure you can handle anything that comes your way! Mind clearing up some of the creatures so it'll be easier for Gharrli to gets the ingredients in the future?", ["objectivesText"] = "Slay 10 monsters in Pillar-nest Vosh. Progress: Did ya get 'em?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
