[86190] = { ["id"] = 86190, ["name"] = "One Mushroom to Rule Them All", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86189, 86191 }, ["description"] = "We've been working on a new scent to delight the locals, but we have one more ingredient we need. It's a rare mushroom from Pillar-nest Vosh. Get that, and Gharrli can finish the fragrance while I'm away!", ["objectivesText"] = "Collect a Voshsroom from Pillar-nest Vosh. Progress: Did you get that mushroom?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233011 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2255, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86191] = { ["id"] = 86191, ["name"] = "Smell Ya Later", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86189, 86190 }, ["description"] = "Well. That's everything, I think. I'm ready for adventure!", ["objectivesText"] = "Meet Rhubarn and Ve'nari in the Oasis on K'aresh. Progress: This is a big sniff for me, <name>!", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255, 2371 }, ["zone"] = { 14752 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86192] = { ["id"] = 86192, ["name"] = "On a Bed of Bones They Lie", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86194, 86195 }, ["description"] = "I was talking to Om'talad over there. Apparently, slatebacks used to gather bones for birthing nests, which is kinda funny on account of them being herbivores! Normally they get bones from dead animals, but we don't have any in the eco-domes. Can you gather some bones from creatures outside the Oasis for me? They'd appreciate it, and so would I!", ["objectivesText"] = "Collect 8 Creature Bones from around K'aresh and place them in a pile in the Oasis. Progress: Have you built the nests as requested?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233016 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86193] = { ["id"] = 86193, ["name"] = "Life for Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["series"] = { 85241 }, ["description"] = "We're too late! The ritual is self-sustaining. It'll draw in more power until it overloads the machine. Tazavesh, the eco-domes--nothing will be safe if the failure cascades. If we remove the infusers, the energy should dissipate before it can cause any harm. It's too powerful though. It will tear you apart if you try to get close, and I'm not strong enough to do it alone... Unbind me. I'll wrap you in my energy. That should be enough to let you get close to the machine.", ["objectivesText"] = "Stop the machine.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245737, 245738 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233503, ["x"] = 0.595, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86194] = { ["id"] = 86194, ["name"] = "The Scent of Love", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86192, 86195 }, ["description"] = "I was out and about checking on these slatebacks of yours, and your broker friends are wrong! The slatebacks are giving off the smell of love, but it's just not strong enough to overpower all this dry air on K'aresh. Not yet anyway! I whipped up a batch of pheromones that should fix them right up! Take this sprayer and douse the slatebacks. That'll get things started!", ["objectivesText"] = "Douse 12 Slateback Roamers in pheromones. Progress: Have you got them smellin' better?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233195 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86195] = { ["id"] = 86195, ["name"] = "Slateback Soccer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86192, 86194 }, ["description"] = "Oh my. I never thought I would see the day. A newly born slateback! I have been running standard non-invasive medical tests. However, I also need a test of its coordination. I have been noticing it chasing this ball around. Perhaps you could throw it and observe the results?", ["objectivesText"] = "Catch a ball 10 times while playing with your Slateback Cub. Progress: Has the cub responded to the ball?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 229420 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86196] = { ["id"] = 86196, ["name"] = "Give Me Fuel", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Thank you for coming, <name>. There are many dangers we face when attempting to terraform K'aresh , not the least of which is attracting creatures that see the domes as convenient energy sources. Eco-Dome: Springhost is plagued with them. I have a plan to remedy this, but I could use your help preparing.", ["objectivesText"] = "Gather Firebud Pollen for Om'vek. Progress: Have you gathered enough pollen for me?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233009, 237812 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86200] = { ["id"] = 86200, ["name"] = "Give Me Fire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Now we need to process this firebud pollen into fuel. And with this fuel, the downfall of these pests will be assured.", ["objectivesText"] = "Process the Firebud Pollen into fuel. Progress: Just place the firebud pollen into the containers on the console, and we'll get it refined into something we can use.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86201] = { ["id"] = 86201, ["name"] = "Watch Me Make These Bugs Expire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Now that we've processed this firebud pollen, we can bring some flame to bear against our pests in Eco-Dome: Springhost.", ["objectivesText"] = "Use the flamethrower to force the glutted creepers off of the dome, then destroy them. Progress: Have you cleansed the eco-dome with the flame I've provided?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233028, 245711, 245712 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
