[86203] = { ["id"] = 86203, ["name"] = "Operation: Floodgate", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86203 }, ["description"] = "My sources report that Darkfuse forces have infiltrated the Waterworks down in the Ringing Deeps. They have seized the power generators there and are rerouting the electricity somewhere else. We do not know their directive, but I am not keen to find out. Dismantle their operation and I will see that you are adequately rewarded.", ["objectivesText"] = "Biergoth wants you to confront Geezle Gigazap within Operation: Floodgate. Progress: Have you ended the operation?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
[86204] = { ["id"] = 86204, ["name"] = "Liberation of Undermine: The House Loses", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "Gallywix has been a stain on Undermine since he forgot where he came from. Gallywix's always been steppin' on the little guy--greed and always looking for the \"next best thing\" is just makin' him step even harder. Seeking power just for its own sake? Forget that! The power lies with the people. Let's bring Gallywix some swift justice, <name>.", ["objectivesText"] = "Defeat Chrome King Gallywix in the Liberation of Undermine .", ["rewardGold"] = 18588000, ["rewardXP"] = 20380, ["rewardItems"] = { 230936, 236954 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233482, ["x"] = 0.435, ["y"] = 0.509 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 238006, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.509 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "raid", ["flags"] = {  },
},
[86261] = { ["id"] = 86261, ["name"] = "Homeward Bound to Safer Shores", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86261 }, ["description"] = "<Upon seeing you walk into camp this dirty, matted dog perks up. His tail wags when he sees the familiar face of the person who found his favorite toy. The faded tag around its neck reads: \"The Duke.\" He seems to have been here since the Kul Tirans disappeared and has somehow survived the isle's many perils. \"The Duke\" looks at you longingly and nuzzles your hand, seeking affection.>", ["objectivesText"] = "Pet the goodest boy. Progress: <The dog looks at you with hope gleaming in its old eyes.>", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 233027, 233056 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 234357, ["x"] = 0.6832, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 234357, ["x"] = 0.6832, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6832, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86271] = { ["id"] = 86271, ["name"] = "Sanity's Rest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["series"] = { 86272 }, ["description"] = "Looks like another one down the hatch, huh? I'm tellin' ya, these Black Blood dig sites are chewin' up workers faster than I can hire 'em! Every day, one of my guys goes down with the shakes, sproutin' nonsense about seein' tentacles in the dirt... Take 'em to see my guy, Stitchoaf , in the cave over there. He's brewin' up some kinda \"cure.\" See if he can't help this poor guy out.", ["objectivesText"] = "Carry the Incapacitated Worker inside the cave in the Ringing Deeps . Progress: I'm already short. I mean, short-handed!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86272] = { ["id"] = 86272, ["name"] = "Counteracting the Black Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["series"] = { 86271 }, ["description"] = "Black Blood? Nasty stuff. Glad I got this mask here. Nobody should be workin' in that mess. It gets inside ya, messes with ya head. Some folks get dizzy, seein' things that ain't there. Some even sproutin' strange scales. Makes me itch thinkin' about it. An' there ain't no cure. Best we can do is ease the pain an' maybe help the symptoms a bit. I got a \"cure\" brewin'. It's just soup, but they don't know that. It's almost \"done,\" but it could use some flavor.", ["objectivesText"] = "Help Stitchoaf ease the goblin's symptoms in the Ringing Deeps . Progress: I got the pot simmerin'. All it needs is a few finishing touches.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.968 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86273] = { ["id"] = 86273, ["name"] = "Visit to the Shop", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "That's all we can do for now. But if you really wanna help us fix all this, you ought to talk to our local engineer--uh, Tricksy... or maybe Trixxy. She's got her workshop set up further down in the cave, and Benny's got her tinkerin' away day and night on some kind of... \"permanent solution.\" Odd, but she's sharp as a blade. If anyone's got a chance at makin' people safe down here, it's her.", ["objectivesText"] = "Find Trixxie Boltcrank 's workshop further in the depths of Sanity's Rest in the Ringing Deeps .", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.968 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86274] = { ["id"] = 86274, ["name"] = "Automation Solution", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "As you have probably figured out, Black Blood exposure is bad for your health. And that's a problem for our operation. We can't keep replacin' our workers. It's expensive, and it ain't ethical. So! What's the solution? Replacin' our workers with my fully-automated bots. These beauties don't get affected by Black Blood exposure. They just dig and haul--precision, efficiency, an' no more sick workers! I just need more scrap to patch 'em up. You in?", ["objectivesText"] = "Collect metal scrap lying around the cave in the Ringing Deeps . Progress: Time is... you know what it is.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233015 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86275] = { ["id"] = 86275, ["name"] = "Bug Exterminator Needed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "Well, if ya really wanna help... We're safe in this cave from the Black Blood--or we were until it was crawlin' with nasty bloodfeasters . The ugly little creeps always had a taste for blood--but now they're gonzo for Black Blood! I got a hunch they're spreadin' Black Blood poisonin' when they bite us. I can't work like this. Each time I see one in a scrap pile, I wanna scream. They're gross, an' I don't wanna get bit an' start seein' things. Stomp 'em flat so we can keep safe an' keep workin'!", ["objectivesText"] = "Kill Bloodfeasters inside the cave in the Ringing Deeps . Progress: <Humming a catchy tune.> Ahh! Oh, I thought you were another bloodfeaster .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86276] = { ["id"] = 86276, ["name"] = "Out in the Fields", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "If Trixxie has those bots ready, then all we gotta do is mark where they needa work. Head out, fire a flare, and deploy those tin cans--an' see if they actually, yanno, work. Watch for glitchy servos, smokin' coolant vents... You know the drill. If they start doin' their work? Great. If not, well... I might be callin' some workers back in to clean up.", ["objectivesText"] = "Deploy goblin bots in the Writhing Fields in the Ringing Deeps . Progress: The longer it takes us to deploy those bots, the longer my workers gotta be in that Black Blood sludge. And the longer I have to pay 'em!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86277] = { ["id"] = 86277, ["name"] = "\"Worm\" Food No More", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "We've got the bots workin' the fields, but there are still flesh-an'-blood workers out there. They need to be able to get back here safely, an' they can't do that with a giant, slobberin' \"worm\" doggin' their steps 'cause it's got a taste for goblin meat. So, here's the job: I don't want that thing scared off, I want it gone. Go out there, track down that overgrown \"earthworm\", and make sure it dies. Don't hold back--I want guts everywhere. Payback for all the goblins it's had for lunch.", ["objectivesText"] = "Kill the Maddened Eyestalk in the Writhing Fields in the Ringing Deeps .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235619, 235620, 235621, 235622 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86297] = { ["id"] = 86297, ["name"] = "Morale Reflects Leadership", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Undermine swallows everything that's good. Now it got Laslo. We need to find who's in charge now and figure out how to keep 'em safe. I think I know where to start askin'.", ["objectivesText"] = "Find the goblin in charge of the Bilgewater Cartel in Undermine . Progress: This ain't no place for good goblins.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229223, ["x"] = 0.455, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229223, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
