[86348] = { ["id"] = 86348, ["name"] = "Fox Bane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "You have done well with the slatebacks. Will you do as well with the thorntails? If we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.", ["objectivesText"] = "Collect 10 Thorntail Essences while Phase Diving in Untethered Space on K'aresh. Progress: Do you have the essences?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237896 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86349] = { ["id"] = 86349, ["name"] = "Lapbug Essence Hunter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["description"] = "Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate. Gather some of their astral essence. You can use a phase conduit to get into Untethered Space.", ["objectivesText"] = "Collect 10 Lapbug Essence in Untethered Space on K'aresh. Progress: How fare your efforts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229393 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86350] = { ["id"] = 86350, ["name"] = "Eau de Foxy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86351, 86362 }, ["description"] = "It's my favorite <race>! I've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me? Let Om'talad know when you're done--he was lookin' to do some testing too!", ["objectivesText"] = "Douse 8 Regal Thorntails in pheromones. Progress: Did you apply the pheromones?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233487 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86351] = { ["id"] = 86351, ["name"] = "Strike a Pose", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86350, 86362 }, ["description"] = "We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food. Can you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.", ["objectivesText"] = "Document 10 Regal Thorntails. Progress: Have you taken the photos?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233488 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
