[86352] = { ["id"] = 86352, ["name"] = "Hunting for a Good Author", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. Have you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. However, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.", ["objectivesText"] = "Look for Hemet Nesingwary in the Azure Span on the Dragon Isles.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2024, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86353] = { ["id"] = 86353, ["name"] = "Protecting the Young", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 84822, 86354 }, ["description"] = "These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. Let's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.", ["objectivesText"] = "Rescue 6 Tuskarr Children in the Brakenhide Brambles. Progress: We have to rescue those children! Who knows what the gnolls will do to them?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86355] = { ["id"] = 86355, ["name"] = "Using the Whole Animal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "K'aresh, eh? Sounds a bit like Netherstorm. I've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.", ["objectivesText"] = "Collect 20 Bruffalon Meat nearby in the Azure Span. Progress: Make sure you harvest the whole animal. It'll go faster.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234036, 234457 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86356] = { ["id"] = 86356, ["name"] = "Sustainable Harvesting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing. Can ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.", ["objectivesText"] = "Collect 12 Chopped Wood nearby in the Azure Span. Progress: Did ye get the wood?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 234452 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
