[86357] = { ["id"] = 86357, ["name"] = "Time for Noms", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86358, 86359 }, ["description"] = "The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time. Can ye put out some of the meat ye gathered for them?", ["objectivesText"] = "Place a Pile of Meat for the local ottuks just outside Iskaara. Progress: Have ye fed those ottuks yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
