[86358] = { ["id"] = 86358, ["name"] = "Any Old Excuse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86357, 86359 }, ["description"] = "This'll be the hardest task for ye yet. The ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. Hard work, but it has to be done.", ["objectivesText"] = "Pet 5 Ottuk Pups outside of Iskarra. Progress: What do you think of the wee li'l pups?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["db2PoiUiMapID"] = 2024, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["questType"] = "standard", ["flags"] = {  },
