[86360] = { ["id"] = 86360, ["name"] = "Fantastic Ms. Fox", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "The thorntails aren't hunting like they're supposed tae? Ve'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!", ["objectivesText"] = "Teach the Thorntail Matriarch to hunt Lapbug Skitterers 10 times. Progress: Is she hunting properly?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
