[86361] = { ["id"] = 86361, ["name"] = "Are You Kitting Me?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up. Please take this ball and have a kit chase it. For scientific purposes, of course.", ["objectivesText"] = "Catch a ball 10 times while playing with your Thorntail Kit. Progress: Has a kit been sufficiently trained?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 229420 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86362] = { ["id"] = 86362, ["name"] = "What Does the Fox Dream?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86350, 86351 }, ["description"] = "I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me. Use these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.", ["objectivesText"] = "Collect 5 Blood Samples. Progress: Have you gathered the samples we need?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233552 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86363] = { ["id"] = 86363, ["name"] = "The Better Part of Valorstones", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86363 }, ["description"] = "It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones . It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research. With new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.", ["objectivesText"] = "Collect 50 Valorstones while adventuring in Khaz Algar, Undermine, and K'aresh, then return to Cuzolth and upgrade a piece of Season 3 equipment. Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
},
[86364] = { ["id"] = 86364, ["name"] = "Crests from the Ether", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86364 }, ["description"] = "Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. That being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.", ["objectivesText"] = "Acquire 15 Weathered Ethereal Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal. Progress: If you're having a hard time finding Weathered Ethereal Crests, you can search for hidden treasures around Khaz Algar, Undermine, or K'aresh. There's no shortage of those treasures!", ["rewardGold"] = 292100, ["rewardXP"] = 11765, ["rewardItems"] = { 236953 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
},
[86365] = { ["id"] = 86365, ["name"] = "Crest Transmutation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86365 }, ["description"] = "My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers! If you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier. Let's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.", ["objectivesText"] = "Bring 15 Carved Ethereal Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Ethereal Crests. Progress: If you lose those Carved Ethereal Crests, you can find more from powerful creatures around K'aresh. I've heard there's quite a variety of them!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236953 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
},
