[86456] = { ["id"] = 86456, ["name"] = "An Elegy for a Silent World", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86456, 86457, 86458, 86820 }, ["series"] = { 86457, 86458 }, ["description"] = "<The crystal you are holding vibrates faintly in your hand. The energy it emits feels like it is holding your hand, trying to reach out and never let go--like it wants you to hold it, to bring it to safety. You can hear a faint song in the back of your mind--a song of fear, confusion, and longing for life. Maybe Ve'nari would know more about it?>", ["objectivesText"] = "Bring the Dimmed Crystal to Ve'nari in the Oasis. Progress: I am dealing with another crisis in my eco-domes, <name>. Make it quick or move aside.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234273 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5734, ["name"] = "The Light of K'aresh", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5734, ["questLineOrder"] = 5 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5734, ["questLineOrder"] = 5 } }, ["startItems"] = { 234273 }, ["questType"] = "standard", ["flags"] = {  },
},
[86457] = { ["id"] = 86457, ["name"] = "A Lullaby of Hope", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86456, 86457, 86458, 86820 }, ["series"] = { 86456, 86458 }, ["description"] = "<name>, do you know what this is? If I am right, this crystal is the essence of my world, K'aresh . I've spent much of my capital preserving some bit of K'aresh through the eco-dome project. But this... I do not wish to assume anything before verifying if it is true. Place down the shard, and let's see what we can find.", ["objectivesText"] = "Place the Dimmed Crystal. Progress: If this crystal is what I think it is, we have found a new hope of saving K'aresh .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5734, ["name"] = "The Light of K'aresh", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5734, ["questLineOrder"] = 5 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5734, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86458] = { ["id"] = 86458, ["name"] = "A Song for Our Future", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86456, 86457, 86458, 86820 }, ["series"] = { 86456, 86457 }, ["description"] = "There is a site, Eco-Dome: Al'dani, which I have kept hidden. It is built on the remains of one of our most sacred places with a powerful connection to K'aresh. It is the site of our greatest triumph of the project. This is the place where we can take the Worldsoul's essence so it can survive. This is also the eco-dome where Soul-Scribe and her Wastelanders are attacking. Clear the way for me one last time, <name>. For K'aresh to survive, we need both the dome and Soul-Scribe intact.", ["objectivesText"] = "Defeat Soul-Scribe within Eco-Dome: Al'dani. Progress: We must make Soul-Scribe see reason. We must prevent her oath to Salhadaar from dooming K'aresh.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2449, ["db2PoiMapID"] = 2830, ["questLines"] = { { ["id"] = 5734, ["name"] = "The Light of K'aresh", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5734, ["questLineOrder"] = 5 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5734, ["questLineOrder"] = 5 } }, ["questType"] = "dungeon", ["flags"] = {  },
},
