[86482] = { ["id"] = 86482, ["name"] = "A Lifeline", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86482 }, ["description"] = "<The snapdragon barely moves as you approach. It is clearly weak and seems much smaller than it should be. Perhaps Zexel Fingersnap has something for sale that could help get it back up on its feet?>", ["objectivesText"] = "Talk to Zexel Fingersnap. Progress: <The small snapdragon looks wearily at you with dull eyes.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 168970, 232466, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501, 234426 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235216, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235216, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
