[86495] = { ["id"] = 86495, ["name"] = "The Reshii Ribbon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["series"] = { 84856 }, ["description"] = "During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh. Xal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius. Alleria will not like this plan. You must convince her!", ["objectivesText"] = "Convince Alleria to let Xal'atath perform the ritual of transformation on you. Progress: Every moment spent debating or arguing is a moment closer to Dimensius emerging.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234106, ["x"] = 0.482, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233946, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86496] = { ["id"] = 86496, ["name"] = "An Ordered Design", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["requiredRaces"] = { 3, 34, 85 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86496 }, ["description"] = "< Bargus holds up a tiny splinter of golden crystal.> Much like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island. Unlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. But these tiny splinters are worth investigating. Bring me a sizable portion. For... experimental purposes.", ["objectivesText"] = "Collect 50 crystal-splintered rubble . The crystal-splintered rubble can only be looted from creatures on the Siren Isle during the Seafury Tempest. Progress: Have you found more splinters of the Siren Crystal? I think I may be able to create something useful with them.", ["rewardItems"] = { 234456 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86503] = { ["id"] = 86503, ["name"] = "Who are the Dastardly Duos?", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 86503 }, ["series"] = { 86491 }, ["description"] = "Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos . And because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there! Good luck! Maybe I'll see you on the other side.", ["objectivesText"] = "Beat the Dastardly Duos while finishing Vinnie's \"Dastardly\" tasks, then speak with Vinnie Sweets . Progress: Speak with Xyggie Marou , do my tasks, and beat those Dastardly Duos !", ["rewardGold"] = 34100, ["rewardXP"] = 17650, ["rewardItems"] = { 238259, 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86535] = { ["id"] = 86535, ["name"] = "Test Run", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86535 }, ["description"] = "Hey, you lookin' to make a few coins? We made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine 's jewelers can offer. I just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya. We'll say this constitutes a verbal waiver, yeah?", ["objectivesText"] = "Use the teleporter to travel from Undermine to Dornogal. Progress: Look at this teleporter. Ain't she gorgeous?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 211397 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 235402, ["x"] = 0.275, ["y"] = 0.541 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 235403, ["x"] = 0.524667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.541 }, ["mapCandidates"] = { ["npc"] = { 2339, 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questType"] = "standard", ["flags"] = {  },
},
