[86556] = { ["id"] = 86556, ["name"] = "A Shattered Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 86556 }, ["description"] = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard",
},
[86560] = { ["id"] = 86560, ["name"] = "A Shrouded Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 86560 }, ["description"] = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the shrouded star, and walk the paths it reveals.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard",
},
[86563] = { ["id"] = 86563, ["name"] = "A Savage Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7333, ["storyline"] = { 86563 }, ["description"] = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the brutal star and walk the paths it reveals.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7333 } }, ["questType"] = "standard",
},
[86564] = { ["id"] = 86564, ["name"] = "A Fel Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 86564 }, ["description"] = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the corrupting red star and walk the paths it reveals.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard",
},
[86575] = { ["id"] = 86575, ["name"] = "Rocket Roll", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out. While I finish up here, why don't you go tell Benny the good news? I'm sure he'll wanna deploy 'em right away!", ["objectivesText"] = "Return to Benny Gooserocket outside the cave in the Ringing Deeps .", ["rewardGold"] = 28090, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["db2PoiUiMapID"] = 2214, ["db2PoiMapID"] = 2601, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
