[86587] = { ["id"] = 86587, ["name"] = "To Maldraxxus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched. However, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.", ["objectivesText"] = "Travel to Maldraxxus in the Shadowlands to get some rays for Ve'nari . Progress: Greetings.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 176140, 181648, 181687, 181692, 181732, 181733 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 1536, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 1536, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
