[86588] = { ["id"] = 86588, ["name"] = "Ritualistic Murder", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86589, 86590, 86591, 86592, 86593, 86782 }, ["description"] = "The local ritualists are causing problems for the necrorays. Specifically, plague problems. If you kill them, it should lessen the issues for the necrorays.", ["objectivesText"] = "Slay 13 Morbid Ritualists .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["db2PoiUiMapID"] = 1536, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
