[86589] = { ["id"] = 86589, ["name"] = "A Plague a Day Keeps the Doctor Away", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86590, 86591, 86592, 86593, 86782 }, ["description"] = "The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job! Bring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.", ["objectivesText"] = "Collect 6 Plague Samples from dead Pestilential Necrorays. Progress: Do you have those samples for me?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234815 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["db2PoiUiMapID"] = 1536, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86590] = { ["id"] = 86590, ["name"] = "I Don't Even Work Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86591, 86592, 86593, 86782 }, ["description"] = "It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague. But now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!", ["objectivesText"] = "Gather 15 Rancor Essences . Progress: Well? Have you gathered the essences?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234944 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["db2PoiUiMapID"] = 1536, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86591] = { ["id"] = 86591, ["name"] = "A Poor Imitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86590, 86592, 86593, 86782 }, ["description"] = "This is Vorax's work. He was once my apprentice, just like you! He's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.", ["objectivesText"] = "Slay Grand Ritualist Vorax . Progress: Is the deed done?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["db2PoiUiMapID"] = 1536, ["db2PoiMapID"] = 2222, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
