[86594] = { ["id"] = 86594, ["name"] = "A Cultured Palette", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86595, 86783 }, ["description"] = "We're trying to figure out what these rays eat. I've gathered some options. Can ye put them out? I'll watch for responses.", ["objectivesText"] = "Place 3 Food Items. Progress: Feeding time. Get to it!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235370 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
