[86604] = { ["id"] = 86604, ["name"] = "Dubious Intent", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "The ooze that Hemet had you collect may be of use to us. Go and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.", ["objectivesText"] = "Collect 7 Necroray Gunk . Progress: Have you gathered the ooze?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235500, 235501 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["questType"] = "standard", ["flags"] = {  },
