[86934] = { ["id"] = 86934, ["name"] = "Trash to Profit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86934, 86935 }, ["description"] = "Ey! I heard you've been cleanin' up some of the trash around Undermine . Good on ya. Any interest in takin' that more literally? It's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation. Tell him I sent ya so I get my recruitment bonus!", ["objectivesText"] = "Talk to Carlo Greasegrind at Undermine Sanitation.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 237649, ["x"] = 0.428, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5776, ["name"] = "Trashy Business", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[86935] = { ["id"] = 86935, ["name"] = "On-the-Job Training", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86934, 86935 }, ["description"] = "If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\" We go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'. Find somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes. But I mean, it's trash shovelin', not rocket surgery.", ["objectivesText"] = "Check out Angelo Rustbin's wares inside Undermine Sanitation, then complete a S.C.R.A.P. job in Undermine . Progress: You might wanna invest in some eye protection. Or at least some really thick gloves. Maybe nose plugs.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.374667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5776, ["name"] = "Trashy Business", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[86936] = { ["id"] = 86936, ["name"] = "Warped Wood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 86936 }, ["description"] = "Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job. If you could clear out a few it would really help speed up our construction efforts.", ["objectivesText"] = "Kill 3 Rotting Treants", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[86937] = { ["id"] = 86937, ["name"] = "Healthy Home Certified", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 86937 }, ["description"] = "We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources. Do us a favor and get rid of him? As always, see my assistant for payment.", ["objectivesText"] = "Kill the Xarn Felhoof", ["rewardGold"] = 468000, ["rewardXP"] = 11895, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
