[86960] = { ["id"] = 86960, ["name"] = "The Key to Good Health", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 86960 }, ["description"] = "I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?", ["objectivesText"] = "Find a key to open the chest and retrieve the antidote.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 235708, 235714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
