[87000] = { ["id"] = 87000, ["name"] = "No Wood Left Behind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 87000 }, ["description"] = "When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.", ["objectivesText"] = "Collect 8 wood logs.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[87001] = { ["id"] = 87001, ["name"] = "Warrant: Shatterpulse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87001 }, ["series"] = { 90124 }, ["description"] = "The horrifying monstrosity known as Shatterpulse lies hidden in a stasis cell at Shadowpoint. It is not kept as a prisoner, but as a weapon to be unleashed upon us when we are least prepared. Create a key to open Shatterpulse's stasis cell revealing this threat to everyone.", ["objectivesText"] = "Collect a Calculation Container , Marking Matrix and some Void Fused Resin to create a key. Progress: Combine the items to form the Stasis Cell Key.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235866, 235913, 235982, 235983, 236353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2472, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["startItems"] = { 235983 }, ["questType"] = "standard", ["flags"] = {  },
},
[87008] = { ["id"] = 87008, ["name"] = "Ad-Hoc Wedding Planner", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "Eeey, now that was a wedding worth talkin' about! You did okay. Everything went right and the only hitch was the one my little girl got. So we're good. I know the bride an' groom wanna say their thanks so go chat with them.", ["objectivesText"] = "Speak with Neenee and Vrizek . Progress: Ain't it great to see those two crazy kids hitched?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245308 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87010] = { ["id"] = 87010, ["name"] = "Calculation Container", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87010 }, ["description"] = "A Calculation Container is no easy feat to construct. I have not made one recently, as thieves have stolen the data rods I need to complete the task. If you can recover the rods, I could create one. Be warned! The rods are quite heavy and will take some effort to return them. I have been known to drop them quite easily.", ["objectivesText"] = "5 Weighty Variable Rod delivered to Engineer Om'loof Progress: Have you found what we need?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235866 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
