[87284] = { ["id"] = 87284, ["name"] = "A Radiant Echo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87284 }, ["description"] = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", ["objectivesText"] = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 235896 }, ["questType"] = "standard", ["flags"] = {  },
},
[87285] = { ["id"] = 87285, ["name"] = "Marking Matrix", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87285 }, ["description"] = "A Marking Matrix must be attuned to the frequency of the void energies wielded by the Shadowguard. You must obtain samples of that energy. My containment Trap is designed to capture Shadowguard and allow you to extract the void markings tied to their corrupted energies. With those markings I can create a matrix to help attune your creation to work on void powered constructs.", ["objectivesText"] = "8 Void Markings extracted from Shadowguard enemies. Progress: Have you finished the work?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 187684, 235898, 235913 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
