[87289] = { ["id"] = 87289, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 10, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 87289 }, ["description"] = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the dracthyr folk would hurry up and bring the rest of the barrels down here. Some o' the dracthyr folk have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Kharanos? And try not to break 'em!", ["objectivesText"] = "Deliver barrels to Kharanos. Progress: Careful with the barrels! Ye shouldn't jostle a good ale.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["db2QuestSortName"] = "Epic", ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard",
},
[87290] = { ["id"] = 87290, ["name"] = "The Oasis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 87337 }, ["description"] = "Hello again, <name>. Ve'nari asked me to find you. She asked that you meet her in the Oasis. I shall join you shortly. I have some errands to run here first.", ["objectivesText"] = "Travel to the Oasis in K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 56840, 56841, 56842, 56843, 245611 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238212, ["x"] = 0.395, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238209, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
