[87291] = { ["id"] = 87291, ["name"] = "Salad Bar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87292 }, ["description"] = "Hemet, Om'talad, and I have been working together to see what we can do to help the lapbugs. It seems their original food source didn't make it through the collapse of K'aresh! Do you think you might be able to gather some prickleblooms and lustrous conkers, and put together a little platter for them?", ["objectivesText"] = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters . Progress: Have you fed the lapbugs?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235914 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87292] = { ["id"] = 87292, ["name"] = "Rooting for Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87291 }, ["description"] = "Our bees have been marvelous at cultivating the local flora. Some of the plants have seen almost explosive growth. However, the lapbugs have become entangled in their roots. I've been untangling them all morning. Would you lend a hand?", ["objectivesText"] = "Detangle 10 Stuck Lapbugs . Progress: Have you gotten those lapbugs untangled?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87293] = { ["id"] = 87293, ["name"] = "Shameless Hawking", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87294 }, ["description"] = "Lapbugs were once a highly sought after pet here on K'aresh. I suspect we could use them to attract interested parties in Tazavesh, increasing both support and donations for the Oasis. I would like you to test this theory.", ["objectivesText"] = "Gather support for the Oasis in Tazavesh. Progress: Yes? I am busy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
},
[87294] = { ["id"] = 87294, ["name"] = "A Truth Universally Acknowledged", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87293 }, ["description"] = "I have an idea, <name>. Everyone seems to love the lapbugs, so I have enlarged them, given them hats, and placed them in picturesque locations. Take this camera and take some photos with the lapbugs. If I am correct, this will go a long way toward increasing support for our efforts.", ["objectivesText"] = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats. Progress: Have you gotten those photos? Do make sure your charming face is in them as well.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 236406 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87297] = { ["id"] = 87297, ["name"] = "Cashing the Check", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "We got one more thing to set straight. Come on. Grimla's waitin' for us back in the hotel lobby.", ["objectivesText"] = "Speak to Grimla Fizzlecrank in the Incontinental Hotel. Progress: Heya, boss.", ["rewardGold"] = 28300, ["rewardXP"] = 1470, ["rewardItems"] = { 243321 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234801, ["x"] = 0.392, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 238002, ["x"] = 0.435, ["y"] = 0.511 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87298] = { ["id"] = 87298, ["name"] = "Void Fused Resin", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87298 }, ["description"] = "Void-Fused Resin isn't my usual craft, but there is a way I could make it for you. Void energies continue to seep through the cracks in our shields contaminating the plants in the domes. If we eliminate the contaminated plants, they may provide the ingredients needed to create the resin. Destroy Void-Tainted Growths and bring me any Void Granules you find.", ["objectivesText"] = "35 Void Granules collected. Progress: Hurry, you need to finish this task!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235918, 235982 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87299] = { ["id"] = 87299, ["name"] = "How Old Are These Things?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane. But when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies! Help us take out her goons and collect any evidence that shows what they really are!", ["objectivesText"] = "Collect 20 Articles of Proof from Red Dawn troops within Stromgarde. Progress: Some of this stuff must be at least twenty years old...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 7997, 23192, 231878, 231879, 231880, 231881, 231883, 231884 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2372, ["db2PoiUiMapID"] = 2372, ["db2PoiMapID"] = 2796, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 25, ["flags"] = 1 }, { ["id"] = 5947, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87301] = { ["id"] = 87301, ["name"] = "Untethered Battery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87301 }, ["description"] = "Untethered batteries are difficult to create, as they require elusive energies that leak from void storage cells into Untethered Space. However, I know of an individual capable of harvesting this energy. If they can extract and store the energy and return it to me, we will have the necessary components to construct a battery. Speak to Myi Koo and collect the energy, we can then create a battery.", ["objectivesText"] = "Meet with Myi Koo, enter untethered space and collect 10 Untethered Energy Samples. Progress: Have you collected the required energy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 239249 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
