[87321] = { ["id"] = 87321, ["name"] = "Things Left Undone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["series"] = { 85190 }, ["description"] = "Hey pal, I can't thank you enough for what you've done for me... and for Undermine . <Marin glances over at Sprinkle before looking back at you.> I know you've been busy since Renzik and Gazlowe brought you here, and you keep doing what we've asked of you. But there's one more thing that needs doing. Meet up with Gazlowe at the hotel. I'm sure he'd appreciate you being there to help.", ["objectivesText"] = "Meet with Monte Gazlowe in the Incontinental Hotel in Undermine .", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 238006, ["x"] = 0.275, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232822, ["x"] = 0.425, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87324] = { ["id"] = 87324, ["name"] = "Pile of Voidbane Gems", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87324 }, ["description"] = "Voidbane Gems are dangerous business! The Shadowguard hide the gems in Untethered Space. You need to go in and find them. Be warned though, others may be looking for those gems as well! I marked the location of the stashes for you, but there's other gems laying around too. Grab what you can, and you'll have yourself a nice big pile of gems when you're done.", ["objectivesText"] = "20 Voidbane Gems collected. Progress: Hurry, grab those gems before someone else does.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235917, 236407, 236632 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87327] = { ["id"] = 87327, ["name"] = "A Challenger's Resilience", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16395, ["mapID"] = 2112, ["storyline"] = { 87327 }, ["description"] = "Wow <name>, you've taken on some unbelievably scary dungeons AND lived to tell me about it! Come speak with me and I'll see about making your most challenging Keystones more Resilient.", ["objectivesText"] = "Meet with Lindormi to learn about Resilient Keystones . Progress: You have achieved much. Your deeds are Legendary.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197711, ["x"] = 0.531, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 197711, ["x"] = 0.531, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 16395 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest", ["questType"] = "standard",
},
[87328] = { ["id"] = 87328, ["name"] = "Truly Horrific to Behold", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "<name>, we have much to discuss. The new threat of the Void is one that puts us all at risk. But this is not our first time. There are clues in our past encounters. So is the case for the Black Blood. In the past, N'Zoth used it to induce visions. Perhaps we can figure out how to counter its effects by returning to these moments. Come, help me set up the portal.", ["objectivesText"] = "Speak with Soridormi to assist with setting up the portal. Progress: Are you ready to revisit these Horrific Visions?", ["rewardGold"] = 170800, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87329] = { ["id"] = 87329, ["name"] = "Into the Darkest Memories", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "Are you prepared? The path through the timeways has been opened to where we last entered the visions. Expect your sanity to be tested. You probably will not last long on this first attempt. The portal is ready for you, <name>. Journey forth.", ["objectivesText"] = "Interact with the Portal to Horrific Visions to rediscover the horrors of the Black Blood. Progress: We must build on our past knowledge. Did you find something new?", ["rewardGold"] = 619600, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87332] = { ["id"] = 87332, ["name"] = "A Collection of Variables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "My assistant Augermu has been monitoring you and the timeways while you were in the past. He has a way for you to replicate gaining some of the boons adventurers used the first time they faced these visions. Give him some of the displaced corrupted mementos you gleaned from your experience for further analysis.", ["objectivesText"] = "Speak to Augermu to ask about what you can do with the Displaced Corrupted Mementos.", ["rewardGold"] = 31500, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87335] = { ["id"] = 87335, ["name"] = "Echoing Lessons", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "We can use your displaced corrupted mementos to create Echoes of N'Zoth. I don't want to bore you with the details unless you want to hear. No? Oh well. < Augermu appears slightly disappointed.> The more echoes you have, the closer we can get you to a version of yourself that's more prepared for the visions. So, let's get started.", ["objectivesText"] = "Work with Augermu to create an Echo of N'Zoth and insert it into the Hourglass of Horrific Visions. Progress: Were you able to slot in the first Echo of N'Zoth?", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87336] = { ["id"] = 87336, ["name"] = "Remembering Again and Again", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "Now that we have the hourglass calibrated to you, you can re-enter Horrific Visions whenever you like. No need for keys when traveling back in time! That said, we do face one limitation. The hourglass is still fragile, and I must harden it week to week to support additional Echoes of N'Zoth. Who knew that memories of an Old God were so dangerous...? Well, you should report back to Soridormi and get back to it!", ["objectivesText"] = "Report back to Soridormi .", ["rewardGold"] = 31500, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87337] = { ["id"] = 87337, ["name"] = "Custodian Duties", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 87290 }, ["description"] = "Ve'nari is very busy. While both her and Om'talad are away, I will give you your orders. We have many creatures here in the Oasis. They make messes. Go clean them up.", ["objectivesText"] = "Clean up the Oasis in K'aresh. Progress: I apologize for that.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236416 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238209, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87338] = { ["id"] = 87338, ["name"] = "Day One Orientation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["description"] = "We've taken some of the native species we saved out of stasis. We will need to recreate their habitats. There are two primary species here, as well as this console to monitor species in the Oasis. I recommend acquainting yourself with these creatures before we begin.", ["objectivesText"] = "Introduce yourself to the animals of the Oasis, and check their status on the console in the Oasis. Progress: Have you familiarized yourself with the animals?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87339] = { ["id"] = 87339, ["name"] = "Ongoing Activities", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["description"] = "While you will be on assignments that befit your skill set, there are also additional tasks that need to be done in the Oasis on a regular basis. While these are typically done by the custodians, if you are in the area I would not say no to your assistance with them. Now, and in the future.", ["objectivesText"] = "Perform various activities in the Oasis in K'aresh. Progress: Have you been hard at work?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236641 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87340] = { ["id"] = 87340, ["name"] = "Junk Mail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 85075 }, ["description"] = "One final item before we begin--a special task suited to your unique capabilities. No, not killing. Flying. The Oasis requires donations. Donations come from advertising. Take these stacks of fliers and distribute them around Tazavesh.", ["objectivesText"] = "Fly through the rings above Tazavesh to distribute fliers. Progress: Have you distributed the fliers?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
