[87341] = { ["id"] = 87341, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 87341 }, ["description"] = "If it's ale you're looking for, we've got plenty to sample! Or at least we would if the Dracthyr folk would hurry up and bring the rest of the barrels down here. Some of the Dracthyr have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Razor Hill? And try not to break them.", ["objectivesText"] = "Deliver barrels to Razor Hill. Progress: Careful with the barrels! You shouldn't jostle a good ale.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 238221, ["x"] = 0.425, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 238221, ["x"] = 0.425, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard",
},
[87342] = { ["id"] = 87342, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 87342 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in the Isle of Dorn.", ["rewardGold"] = 84900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238236, ["x"] = 0.482, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questType"] = "standard", ["flags"] = {  },
