[87343] = { ["id"] = 87343, ["name"] = "Warrant: Hollowbane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87343 }, ["series"] = { 90123 }, ["description"] = "Shadowguard forces in Shadow Point have rallied around an enigmatic champion know as Hollowbane. Though the Hollowbane's existence is unconfirmed, we have located a travel portal supposedly used by the champion. Unlock the portal and expose Hollowbane so they may be confronted and eliminated.", ["objectivesText"] = "Combine an Umbral Facade , Energy Encapsulation and a Bag of Veilshards to create a portal key.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235917, 236688, 236957, 237354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2472, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questType"] = "standard", ["flags"] = {  },
