[87344] = { ["id"] = 87344, ["name"] = "A Key Threat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87344 }, ["description"] = "Tazavesh is a city rife with turmoil, beset by countless dangers. We could always use your help. Check our warrant board, and see if you have what it takes to eliminate our most wanted threats.", ["objectivesText"] = "Complete a warrant and eliminate the threat to our city. Progress: Have you completed a warrant.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.5755 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
