[87345] = { ["id"] = 87345, ["name"] = "Warrant: Xy'vox the Twisted", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87345 }, ["series"] = { 90122 }, ["description"] = "Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family. Unknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox. When the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities. Create a Refuge Dampener to reveal Xy'vox to all of Tazavesh.", ["objectivesText"] = "Collect a Tazavesh Facade , Ethereal Seal and a Zo'kita Fruit .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236753, 236762, 236781, 236783, 236858, 237485, 245255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2371, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questType"] = "standard", ["flags"] = {  },
},
