[87358] = { ["id"] = 87358, ["name"] = "Umbral Facade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87358 }, ["description"] = "The trick to creating a perfect Facade is to scan live Shadowguard with a nifty little device I will provide you. This device will allow you copy the very unique essence that is the core of their being, and store it for our use. You can locate shadowguard in both regular and untethered space. Regardless of how you find them, they won't take kindly to your presence, and they certainly won't want to be scanned.", ["objectivesText"] = "18 Shadowguard Essence scanned Progress: Did you finish those scans?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236679, 236688 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87363] = { ["id"] = 87363, ["name"] = "Tazavesh Facade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87363 }, ["description"] = "To create the perfect Tazavesh facade , you must scan live Shadowguard around Tazavesh with a device I will provide you. This device will mark the targets, allowing you to copy the unique essence that is the core of their being and store it for our use. This is dangerous business, as you will have to approach them directly and see if they're willing to be scanned!", ["objectivesText"] = "15 Shadowguard Essence scanned. Progress: Did you finish those scans?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236762, 236766 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238387, ["x"] = 0.468, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238387, ["x"] = 0.468, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
