[87374] = { ["id"] = 87374, ["name"] = "C.H.E.T.T.ing In", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87374 }, ["description"] = "<You notice your bags feeling slightly heavier just as you catch a glimpse of a shadow moving away from you. A quick search uncovers a card you don't recognize. One side has, simply, \"C.H.E.T.T.!\". The other is a condensed map of The Undermine with directions to The Incontinental's second floor.>", ["objectivesText"] = "Speak to C.H.E.T.T. on the second floor of The Incontinental to learn about C.H.E.T.T. Lists.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[87376] = { ["id"] = 87376, ["name"] = "Ethereal Seal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87376 }, ["description"] = "An Ethereal Seal grants unrestricted access and control over Ethereal assets without raising suspicion. Acquiring an authentic seal can be quite difficult. It is far easier to forge one using discarded cyphers instead. If you're not afraid to get your hands dirty, you can find discarded writs in the trash piles outside of town. Bring those to me, and I can create a seal for you.", ["objectivesText"] = "Collect 12 Discarded Shadow Writs . Progress: Did your find the Shadow Seals?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235499, 236753, 236781, 236783 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87380] = { ["id"] = 87380, ["name"] = "Zo'kita Fruit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87380 }, ["description"] = "You can have the fruit, but only if you do me a favor first. Something is watching us. You can't see it, but the smell of the fruit draws it to us. Hidden monsters lurking just beyond our sight. Gain access to the Untethered Space, hunt these creatures down, and bring me their hides. I want proof that these creatures actually exist!", ["objectivesText"] = "8 Untethered Hide collected Progress: Did you see them? Did you cut them to pieces?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236858, 236859, 236962 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87404] = { ["id"] = 87404, ["name"] = "Energy Encapsulation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87404 }, ["description"] = "You need an Energy Encapsulation ? You must be planning to activate a portal or teleporter with it! I can construct what you require with ease, provided you supply the necessary energy. Visit the Harvesters nearby. They let us collect what we need, as long as we help keep the wyrms off the harvesters.", ["objectivesText"] = "10 Energy collected from Power Harvesters and Crackling Wyrms . Progress: Do you have the required energy?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235051, 236937 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87405] = { ["id"] = 87405, ["name"] = "Warrant: Grubber", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87405 }, ["series"] = { 90126 }, ["description"] = "A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber. Tragically, we lost deputy Zo'wie when he went out to investigate. The creature pulled him under the sand. Devise a method to lure the worm into revealing itself, so it may be eliminated once and for all.", ["objectivesText"] = "Collect a Basket of Zo'kita Fruit , a Dozen Veilshards and some Flavorful Scraps .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236962, 236966, 236967, 237352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
},
[87406] = { ["id"] = 87406, ["name"] = "Inoperative Mega-Mecha Gorilla", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87406 }, ["description"] = "<Despite your best efforts, the machine remains silent. Maybe a local expert could get it working.>", ["objectivesText"] = "Take the Inoperative Mega-Mecha Gorilla to Ditty Fuzeboy for repairs. Provided item:", ["rewardItems"] = { 232843, 234427, 234430, 234431, 234432, 234433, 234741, 236961 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 236411, ["x"] = 0.354, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["startItems"] = { 236961 }, ["questType"] = "standard", ["flags"] = {  },
