[87408] = { ["id"] = 87408, ["name"] = "Being Spiritual", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87409 }, ["description"] = "We have perfected creating existing creatures, but I would like to go one step further. I would like to try this process with a creature that did not survive the Devouring. This world once had a creature called a k'arroc. Locate its essence and gather it for me.", ["objectivesText"] = "Collect 15 Flyer Essence in Untethered Space on K'aresh. Progress: Have you gathered the essences I needed?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229396 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
