[87409] = { ["id"] = 87409, ["name"] = "From Death, Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87408 }, ["description"] = "We have only to let the machine do its work now. I will let you do the honors. If it fails, I will place the blame on you... ... I jest, my friend. Mostly.", ["objectivesText"] = "Help Ve'nari use her machine to create life in the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87410] = { ["id"] = 87410, ["name"] = "Percussive Negotiation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87411 }, ["description"] = "The k'arrocs are big and they're going to need tae stretch their wings sooner or later. Let's plan for it, eh? The Shadowguard have all sorts of void shielding going on. I bet you could get parts from them using your usual method of negotiatin' with enemies. Take the parts to Ve'nari when you're done.", ["objectivesText"] = "Collect 12 Void Shielding Parts in the Umbral Garrison. Progress: Did you get the parts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237010 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87411] = { ["id"] = 87411, ["name"] = "Making Stuff to Look Tough", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87410 }, ["description"] = "I suppose we can construct the void shield Hemet imagined, but these parts are not ideal. Meet me outside the Oasis to the east and we shall see if we can craft a workable solution.", ["objectivesText"] = "Assist Ve'nari in crafting a Void Shield outside the Oasis. Progress: Come now. Let us begin building.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237021 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87412] = { ["id"] = 87412, ["name"] = "K'arrocing Photos", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["description"] = "We must keep our documentation updated. That means I require your services once more. Take this camera and gather more photos of the k'arrocs. You'll find them on the rocks around the area.", ["objectivesText"] = "Document 7 Domineering K'arrocs. Progress: Have you taken the photos I requested?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237012 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87413] = { ["id"] = 87413, ["name"] = "Bird Bath", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["description"] = "<name>--just the person I needed! The k'arrocs are gettin' so dirty that it's covering up their natural smell. There's not enough water here for them to bathe! Take this anima vacuum . It'll take that dirt straight off 'em, but you're gonna have to stick to the ones on the ground. Try looking on top of the rocks to the north!", ["objectivesText"] = "Wash 7 Domineering K'arrocs. Progress: Have you cleaned up those dirty birdies?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237013 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87414] = { ["id"] = 87414, ["name"] = "Medical Maneuvers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87415 }, ["description"] = "It would be good to get a solid medical checkup on the k'arrocs. Would you shrink them down and bring them to me?", ["objectivesText"] = "Shrink and collect 8 Domineering K'arrocs. Progress: Have you gathered the k'arrocs I asked for?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237030, 238913 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87415] = { ["id"] = 87415, ["name"] = "The Skies of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87414 }, ["description"] = "The shielding device you helped with has been tested. It is ready for its first flight, if you will forgive the turn of phrase. Speak with Om'torid . They have a course picked out for you and the k'arroc to soar along.", ["objectivesText"] = "Test out the shield device by taking a k'arroc for a flight outside of the Oasis. Progress: How did the shield hold up?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["questType"] = "standard", ["flags"] = {  },
