[87417] = { ["id"] = 87417, ["name"] = "Worldsoul: Dungeons", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The enemies of Khaz Algar rise up, unified in the suffering they inflict on those who do not believe in their causes. <Faerin pauses, then takes a quick glance at the table in front of her before returning her gaze to you.> Show these people the light, <name>. If they cannot see the error of their ways, please show them a merciful conclusion to their beliefs.", ["objectivesText"] = "Complete any Seasonal Dungeon at Normal difficulty or higher. Progress: How goes the mission?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224701, 224784, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 13, ["flags"] = 0 } }, ["questType"] = "standard",
