[87419] = { ["id"] = 87419, ["name"] = "Worldsoul: Delves", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "These lands house many deep crevices, leaving shadows where our enemies believe they are safe. Explore these hidden places and leave our enemies no sanctuary.", ["objectivesText"] = "Complete a War Within Delve at any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 229354, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 15, ["flags"] = 0 } }, ["questType"] = "standard",
},
[87420] = { ["id"] = 87420, ["name"] = "Basket of Zo'kita Fruit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87420 }, ["description"] = "You need more Zo'kita Fruit than I'd ever dare to keep around here! Just one Zo'kita fruit is enough to drive my brother out of the market, and you're asking for a whole basket? Bold move, my friend! Visit Eco-dome: Primus, I secretly grow them there, hidden out of sight. Use my picking gear to locate them and take as many as you need.", ["objectivesText"] = "Collect 8 Freshly Picked Zo'kita Fruit. Progress: Did you get enough?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236962, 236972, 237009 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87422] = { ["id"] = 87422, ["name"] = "Worldsoul: Undermine World Quests", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Undermine may be a place I do not understand, but they too are in need of aid. Our conflicts inflame their situation, it would do good to help them move forward. Go there and help them. See what you can do to bring these... cartels closer together, and to us.", ["objectivesText"] = "Complete World Quests in Undermine.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 50, ["flags"] = 0 } }, ["questType"] = "standard",
},
[87423] = { ["id"] = 87423, ["name"] = "Worldsoul: Undermine Explorer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Undermine is held together by an intricate design of innovation, hard work, allegiance, and it seems like the sheer will of the goblins. Rather than cower in their sunless cave, the goblins have built a city that thrives on motion and activity. We can learn much from that. After not seeing new faces for years, they bring a new light to our lands. Go help them in whatever ways seem fitting.", ["objectivesText"] = "Complete various activities in Undermine.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 232523, 239118 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 43, ["flags"] = 0 } }, ["questType"] = "standard",
},
[87424] = { ["id"] = 87424, ["name"] = "Worldsoul: World Bosses", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Hallowfall is not the only land beset by enemies. Great monsters threaten our allies. Wherever the shadows of our war have fallen, savage beasts and cunning fiends rise up. They murder Arathi, earthen, and the others who stand with us. Innocent farmers to great warriors. I know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", ["objectivesText"] = "Defeat all available World Bosses in The War Within. Progress: I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 239118, 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 39, ["flags"] = 0 } }, ["questType"] = "standard",
},
[87425] = { ["id"] = 87425, ["name"] = "Large Sticky Voidmass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87425 }, ["description"] = "Ah, yes, I've seen what you are describing! The sap from the corrupted plants is tainted with void energy. Collect several samples of the sap as you can, and I will combine it to make a Large Sticky Mass.", ["objectivesText"] = "Collect 5 Corrupted Sap . Progress: Have you found the sap?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236964, 237019 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
