[87426] = { ["id"] = 87426, ["name"] = "Flavorful Scraps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87426 }, ["description"] = "Plenty of profit to be made scavenging these sands, but watch out for the monster. It's hungry, I've seen it drag scavengers under the sands! You can trick it, I fed it once. Tossed it some scraps. You need the tastiest garbage to lure it out. Collect what you can and I will help sort it to find the most flavorful scraps .", ["objectivesText"] = "Collect 24 Discarded Scraps Progress: Did you find anything tasty?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236766, 236966, 237022 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238591, ["x"] = 0.685, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238591, ["x"] = 0.685, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87475] = { ["id"] = 87475, ["name"] = "Sureki Incursion: Hold the Wall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87475 }, ["description"] = "Flames! Those chitinous vermin are relentless! We've received reports from Auralia Steelstrike that a small force of nerubians are harassing the outer perimeter of the city. Regroup with our allies on the outskirts of Mereldar and join the fight!", ["objectivesText"] = "Assist the Flame's Radiance in pushing back the Sureki outside Mereldar. Progress: We must hold the line against these Sureki. Push them back!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241344, ["x"] = 0.405, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
},
[87477] = { ["id"] = 87477, ["name"] = "Sureki Incursion: Southern Swarm", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87477 }, ["description"] = "The Sureki aren't known to give up their assaults so easily. Reports from our southern holdings have warned of a swarm stirring along the mountain range. I don't know whether they plan to hit Tenir's Ascent or Beledar's Bounty, but we cannot wait for them to make the first move. Join our allies and intercept the swarm!", ["objectivesText"] = "Assist the Flame's Radiance in pushing back the Sureki swarm in southern Hallowfall . Progress: The nerubians have brought every foul, multi-limbed horror from the depths in this swarm! We cannot allow our holdings to fall!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241340, ["x"] = 0.52, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
},
[87480] = { ["id"] = 87480, ["name"] = "Sureki Incursion: The Eastern Assault", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87480 }, ["description"] = "There's no time to rest, <name>! Our earthen allies in eastern Hallowfall have spotted a Sureki battalion preparing to attack Dunelle's Kindness--they must be targeting the Dawntower! Flame's Radiance reinforcements are securing the town and Lothar's Landing as we speak. Head east and lend what aid you can!", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki's eastern assault. Progress: We will hold this position. Go, help Dunelle's Kindness below!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241093, ["x"] = 0.764, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
},
[87496] = { ["id"] = 87496, ["name"] = "Benefit Packages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87496 }, ["description"] = "Times are rough, so the cartels have been tryin' out this new business strategy called \"employee retention.\" Never heard of it before, but it sounds fancy. Anyway, I'm pretty sure it means givin' employees the privilege of buyin' stuff from the company stores after you work for 'em long enough. Go check out what the cartels got for sale. See if anything catches your eye before you start workin'.", ["objectivesText"] = "Visit each cartel's quartermaster in Undermine . Progress: You can find the sellers at each cartel's headquarters.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231049, ["x"] = 0.428, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231049, ["x"] = 0.428, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["flags"] = {  },
},
