[87546] = { ["id"] = 87546, ["name"] = "Warrant: Purple Peat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 87546 }, ["series"] = { 90125 }, ["description"] = "In restoring the eco domes, much of the contaminated plant life was removed, allowing the soil to heal. However, one corrupted lasher escaped our notice. Nicknamed \"Purple Peat\" by the dome technicians, it continues to spread its roots and seeds into Eco-Dome: Primus. The plant hides safely in an old stasis cell outside the dome. Construct a device to remove the protective cell and expose the plant so it can be eliminated.", ["objectivesText"] = "Combine a Large Sticky Voidmass , Energy Encapsulation and a Untethered Battery create a create a key to unlock the stasis sphere.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236937, 236964, 237485, 239249, 239276, 245255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2472, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questType"] = "standard", ["flags"] = {  },
