[87547] = { ["id"] = 87547, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared. You're strong enough now that you should choose a combat specialization. This will unlock a new array of abilities for you to face the dangers within the Dragon Isles. Go ahead and choose your combat specialization.", ["objectivesText"] = "Choose your combat specialization. Progress: Having trouble? You can find your combat specialization beside your spellbook.", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["db2PoiUiMapID"] = 2022, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 57, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
