[87548] = { ["id"] = 87548, ["name"] = "A Dozen Veilshards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87548 }, ["description"] = "Yes I know of Veilshards, a highly prized treasure, often the target of thieves! But rest assured, the upstanding citizen Om'sto , would not be involved in such crimes. To find Veilshards you need only look to the rats of this city, they are the craftiest of thieves! Follow a Thieving Scurrier to its nest, and you're bound to uncover a gem among it's stolen hoard. Bring back what you find, and we'll bundle them into a neat dozen for you.", ["objectivesText"] = "Collect 12 Stolen Veilshards Progress: Did follow the rats?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237266, 237352 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[87551] = { ["id"] = 87551, ["name"] = "Week 3: Spread the Word", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87551 }, ["description"] = "Hey, you wanna help out the organization? you know, spread the word? Next time you're in a match, throw your Dastardly Banner down in the arena. Show support! But be careful -- your opponents might take offense and come straight after you...", ["objectivesText"] = "Place your Dastardly Banner during a match, then win the match. Progress: Don't forget to use your banner inside the area. Your opponents will hate it, but the fans will love it!", ["rewardGold"] = 30900, ["rewardItems"] = { 239007, 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
