[87552] = { ["id"] = 87552, ["name"] = "Week 4: They've Heard of You", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87552 }, ["description"] = "You're making a name for yourself, <race>. You keep the victories coming and I'll keep the tickets selling.", ["objectivesText"] = "Win a Dastardly Duos match, then speak with Vinnie Sweets .", ["rewardGold"] = 16980, ["rewardItems"] = { 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
