[87554] = { ["id"] = 87554, ["name"] = "Week 6: It's the Finale!", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87554 }, ["description"] = "This is it, the end of the event. Let's go out with a roar! Put on one last good show and we can count our money together!", ["objectivesText"] = "Win a Dastardly Duos match, then speak with Vinnie Sweets .", ["rewardGold"] = 16980, ["rewardItems"] = { 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
