[87555] = { ["id"] = 87555, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "Before you head off, you'll want to get yourself a Hearthstone . This little stone will return you to the inn where you last bound it to. It's not much of an \"inn\", but the explorer's have a tent set up. Test out that new mount of yours and ride over to Happy Hal. He'll get you sorted out with a Hearthstone .", ["objectivesText"] = "Ride your mount, then speak with Happy Hal to get a Hearthstone bound to the Wild Coast. Progress: Happy Hal nearby can get you set up with a Hearthstone .", ["rewardGold"] = 200, ["rewardXP"] = 505, ["rewardItems"] = { 6948 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["db2PoiUiMapID"] = 2022, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 68, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
