[87562] = { ["id"] = 87562, ["name"] = "Aiding the Dragon Isles", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span. Toddy Whiskers of the Dragonscale Expedition could use your help. Safe travels, <name>. I look forward to our next meeting!", ["objectivesText"] = "Meet Toddy Whiskers to begin your adventure in the Dragon Isles.", ["rewardXP"] = 505, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189022, ["x"] = 0.82, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 69, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
