[87581] = { ["id"] = 87581, ["name"] = "No More Walkin' Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84352, 86618, 87581 }, ["description"] = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at Shipping and Handling and see if she'll lend you some wheels.", ["objectivesText"] = "Meet Nanny Talullah on the third floor at Shipping and Handling.", ["rewardGold"] = 29500, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 238946, ["x"] = 0.432, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5772, ["name"] = "Shipping? Handled.", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
