[87582] = { ["id"] = 87582, ["name"] = "Delves: Site of Madness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87582 }, ["description"] = "Hey, pal. Some real weird stuff has been happening south of Gutterville. Some of my friends have gone missing, and their family's worried about them. How about you take that can-do attitude of yours down there and see if you can figure out what happened? <Paks scratches his chin before looking back at you.> I'm sure there will be some compensation to make it up to you too. Trust me.", ["objectivesText"] = "Complete the Excavation Site 9 delve on any difficulty. Progress: Yo, did you figure out what happened down there?", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["db2QuestInfoID"] = 288, ["db2QuestInfoName"] = "Delve", ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
},
[87583] = { ["id"] = 87583, ["name"] = "Delves: The Sluice Contains the Juice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87583 }, ["description"] = "Buddy, pal, <class>. Some Darkfuse have taken root down in the sewers here in Undermine. They're shaking down hard-working goblins for cash, stealing their lunches, and sometimes even destroying their flamingo lawn ornaments! Those Darkfuse suffer from a real lack of decorum, let me tell you. I know you'll do the right thing and help us out, especially after such a tearjerker of a story.", ["objectivesText"] = "Complete the Sidestreet Sluice delve on any difficulty.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["db2QuestInfoID"] = 288, ["db2QuestInfoName"] = "Delve", ["db2QuestHubAreaPoiID"] = 8189, ["questType"] = "standard", ["flags"] = {  },
