[87588] = { ["id"] = 87588, ["name"] = "Bash that Trash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["storyline"] = { 83323, 84788, 84791, 85715, 85717, 85732, 85733, 85758, 85759, 85769, 85771, 85773, 85797, 85826, 85854, 85861, 85874, 85888, 85946, 86311, 86313, 86314, 86315, 86317, 86318, 86319, 86320, 86321, 86410, 86412, 86418, 87569, 87588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["db2Objectives"] = { { ["text"] = "Arrived at The Heaps", ["amount"] = 0, ["type"] = 19, ["objectID"] = 36624, ["orderIndex"] = 0 }, { ["text"] = "Trash Compacted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Trash Compacted", ["amount"] = 10, ["type"] = 0, ["objectID"] = 239236, ["orderIndex"] = 2 } }, ["objectivesText"] = "Arrived at The Heaps Trash Compacted Trash Compacted", ["mapID"] = 2346, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5643, ["name"] = "FF Task List", ["orderIndex"] = 17, ["flags"] = 0 } }, ["activities"] = { ["scenarios"] = { { ["id"] = 2941, ["name"] = "Shipping & Handling", ["areaID"] = 0 } } }, ["db2LabelIDs"] = { 4101 }, ["questType"] = "scenario", ["flags"] = {  },
