[87597] = { ["id"] = 87597, ["name"] = "A Bag of Veilshards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 87597 }, ["description"] = "I myself could sell you Veilshards, but my own supply has been stolen. The vermin of this city will not hesitate to steal them when my back is turned. Follow any Thieving Scurrier to its nest, and you are sure to locate some stolen shards. To assist you, I will provide a device capable of tracking the thieving vermin. Recover enough Veilshards to satisfy both our needs.", ["objectivesText"] = "Collect 18 Om'sto's Veilshards Progress: Did you locate the veilshards?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237266, 237353, 237354, 237356 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88652] = { ["id"] = 88652, ["name"] = "Faceless Mask of the Nemesis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 88652 }, ["description"] = "There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.", ["objectivesText"] = "Return the Faceless Mask of the Nemesis to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Nemesis on the altar.", ["rewardItems"] = { 237434 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["startItems"] = { 237434 }, ["questType"] = "standard", ["flags"] = {  },
},
[88655] = { ["id"] = 88655, ["name"] = "Outbound for Outland", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["description"] = "Snakes! Why'd it have to be snakes? Ve'nari says they used to have snake-like things on K'aresh before the Devouring. None of 'em survived. They still got worms, but that's nae what we're after. I know just the place--my ol' stomping grounds in Nagrand on Outland. Let's use this infernal contraption of a portal to get there.", ["objectivesText"] = "Regroup with Hemet Nesingwary at the Nesingwary Safari in Nagrand on Outland.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 107, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 107, ["db2PoiMapID"] = 530, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88656] = { ["id"] = 88656, ["name"] = "Comfort Stones", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88657, 88658, 88660, 88661, 88662 }, ["description"] = "Right then. We're gonna need tae collect things tae make the snakes comfortable on K'aresh. Let's get 'em some bedding. Some of the most important things are rocks! Snakes can sun themselves atop a rock or hide under it. Those nearby earth elementals were always a pain in our side. See if you can get some rocks from 'em.", ["objectivesText"] = "Collect 20 Smooth Stones from Tortured Earth Spirits, Enraged Crushers, or Shattered Rumblers. Progress: It's nice to be helpin' these critters rather than hunting 'em. The angry elementals don't count!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237572 }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["db2PoiUiMapID"] = 107, ["db2PoiMapID"] = 530, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88657] = { ["id"] = 88657, ["name"] = "Zangarmoss", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3521, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88658, 88660, 88661, 88662 }, ["description"] = "Next up, we'll be needin' some moss for their beds. Sorry to say, but we need to go into the slimy marsh for 'em. The naga control that place. It grows on their mushroom trees. They're also fond o' munching on it or something foul. Fastest way to Zangarmarsh is through the pass to the north. If it were me, I'd look around the Darkcrest Shore.", ["objectivesText"] = "Collect 15 Marsh Moss in Zangarmarsh. Progress: How much you got? It's one o' the last things we need before we head back to K'aresh.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237757 }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3521 } }, ["db2PoiUiMapID"] = 107, ["db2PoiMapID"] = 530, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88658] = { ["id"] = 88658, ["name"] = "Sneks and Things", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88660, 88661, 88662 }, ["description"] = "O' course, we also need some snakes. That's the whole point o' why we came out here in the first place. You can find the small ones we want down in the Telaari Basin to the south. Just rustle their dens an' they'll come slitherin' out. That's where the plants they like grow. Speaking of which, make sure to get some o' them fragrant plants while you're at it. Ye might not know this, but snakes have a keen sense o' smell.", ["objectivesText"] = "Collect 10 Nagrand Snakes and 20 Fragrant Dreaming Glory . Progress: How many do you have? I canna tell. Your pack always looks so full.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237601, 237604 }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["db2PoiUiMapID"] = 107, ["db2PoiMapID"] = 530, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88659] = { ["id"] = 88659, ["name"] = "More Cozy Beds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We need all sorts o' replacements for things--stones and moss for the beds, and more o' them stinky flowers. Remember, ye can get the stone from the earth elementals in Nagrand. The flowers are down in the Telaari Basin there in Nagrand as well. An' the moss is over at the Darkcrest Shore in Zangarmarsh. It'll be a good excuse for me tae go see the gang again. Meet ye on the other side o' the portal.", ["objectivesText"] = "Collect 10 Fragrant Dreaming Glory , 10 Marsh Moss , and 10 Smooth Stones in Nagrand and Zangarmarsh on Outland. Progress: Have ye got it all?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237572, 237604, 237757 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 24, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88660] = { ["id"] = 88660, ["name"] = "Snakes on a Plane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88661, 88662 }, ["description"] = "Last, but certainly not least, we need to get those two snakes off o' me plane! I dunno how long snakes normally live, but it seems like those two have been there forever. And they always look at me funny if I come near. Maybe you could go get 'em?", ["objectivesText"] = "Gather the two snakes off of the crashed plane at the Nesingwary Safari. Progress: You got 'em?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["db2PoiUiMapID"] = 107, ["db2PoiMapID"] = 530, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88661] = { ["id"] = 88661, ["name"] = "To the Atrium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88660, 88662 }, ["description"] = "We got what we're after. Time to head back. Before we can introduce the snakes to the ecology in the Oasis, we need to test 'em out. There are a few o' these place they call eco-domes where that's done on K'aresh. Ve'nari's portal will take us to one called the Atrium. I wish I could fly me plane there instead.", ["objectivesText"] = "Regroup with Hemet Nesingwary at the Atrium on K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107, 2371 }, ["zone"] = { 3518 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88662] = { ["id"] = 88662, ["name"] = "What's in a Name?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88660, 88661 }, ["description"] = "Though they clearly don't like me, I think the two snakes from me crashed plane have taken a liking to you. Ye want to name 'em?", ["objectivesText"] = "Name the female and male snake . Progress: What have ye decided on?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 52921, 52938, 52941, 52966, 52970, 52972, 84105, 131844, 131846, 211279 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88663] = { ["id"] = 88663, ["name"] = "Scales and Measures", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88664, 88665 }, ["description"] = "Now to get some vital statistics. Ve'nari and her people have all sorts o' contraptions for doing things around here. This li'l robot is gonna use the thing the snakes are on to take some measurements. Just speak with it when you're ready. I can get readings for the rest o' the snakes while you're off doing other things.", ["objectivesText"] = "Speak with the Data Collection Drone to complete a data analysis of the named snakes. Progress: Let me know what that thing figures out an' we'll move on to other things. We gotta do some stuff before we can head back to the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88664] = { ["id"] = 88664, ["name"] = "Nagrandification", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88663, 88665 }, ["description"] = "Remember all those stinky plants ye gathered up in Nagrand? Would ye mind replanting 'em? We don't have to plant 'em all right now. Just enough to test and ensure they'll take to the soil of K'aresh. We'll be needin' a lot more plants than this eventually.", ["objectivesText"] = "Plant 6 Fragrant Dreaming Glory. Progress: I'm gonna have to make certain to stay upwind o' those \"fragrant\" plants.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88665] = { ["id"] = 88665, ["name"] = "Follow Your Tongue", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88663, 88664 }, ["description"] = "Now it's time to move north into Eco-Dome: Primus. That's a mouthful. Take one o' the remaining stinky flowers an' lead the snakes there.", ["objectivesText"] = "Lead the Nagrand Snakes to Eco-Dome: Primus.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
