[88666] = { ["id"] = 88666, ["name"] = "Mossy Beds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88667, 88668 }, ["description"] = "I've put together the rocks an' the moss that ye collected in Nagrand. Now it's time to see if the snakes like 'em. I spread 'em out around the eco-dome so you could test 'em out for differences. While you're doing that, I'll make preparations for getting 'em all to the Oasis.", ["objectivesText"] = "Test 8 Mossy Snake Beds.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88667] = { ["id"] = 88667, ["name"] = "Water Snakes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88666, 88668 }, ["description"] = "Oh no! Some o' the snakes are having trouble adapting. They aren't drinkin' as much as they should an' are dehydrated. Quick, <name>. Take this waterin' can and give 'em a good dousing.", ["objectivesText"] = "Use Hemet's Waterin' Can to water 10 Parched Snakes .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237898 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88668] = { ["id"] = 88668, ["name"] = "Ophidian Portation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88666, 88667 }, ["description"] = "Our tests are successful! Time to move to the Oasis. Ve'nari gave me these \"portation\" devices to quickly get the snakes o'er there. Why don't you take care o' Ember and Indigo, and I'll take care o' the rest? They've been giving me the side-eye ever since I moved 'em here.", ["objectivesText"] = "Use Ve'nari's Portation Tags on the two named snakes to transport them to the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88669] = { ["id"] = 88669, ["name"] = "Nesting Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88670, 88671, 88672 }, ["description"] = "We need to set up a nice home for these two, especially since Ember's expectin'. I took a look around an' spotted a shady place under a tree not far from here. There's all sorts o' things to make 'em comfortable an' safe. Use Ve'nari's portation tags again to summon in everything ye need.", ["objectivesText"] = "Set up a home for the two named snakes. Progress: How'd it go? Did they like their new place?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88670] = { ["id"] = 88670, ["name"] = "Soothing Serpents", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88671, 88672 }, ["description"] = "Most o' the snakes did not like Ve'nari's teleport. Others were cloned by Om'talad, an' they don't like that either. They're clearly agitated an' I'm afraid they're gonna hurt themselves. I've got this flute. Don't ask. I can't even play the darned thing. Would ye take it out there an' soothe the snakes with some calming melodies?", ["objectivesText"] = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes . Progress: I'm certain you're much better at playin' that thing than me.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238216 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88671] = { ["id"] = 88671, ["name"] = "Eggstra Eggs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88670, 88672 }, ["description"] = "I've been talkin' with the others about food for the snakes, an' we think we have a solution. The k'arrocs have been prospering a wee bit too much for the ecology o' the Oasis. If ye get some o' their eggs, that should be enough for now so we can feed the snakes.", ["objectivesText"] = "Collect 6 K'arroc Eggs . Progress: How goes the egg pilferin'?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238242 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88672] = { ["id"] = 88672, ["name"] = "Snakelets!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88670, 88671 }, ["description"] = "Speaking o' eggs--I checked, an' Ember has laid her clutch. It's almost time to hatch us some babies! Meet me back at the nest an' we can welcome our first snakelets to K'aresh.", ["objectivesText"] = "Help with hatching the snakelets. Progress: What an excitin' time.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["questType"] = "standard", ["flags"] = {  },
},
[88711] = { ["id"] = 88711, ["name"] = "Radiant Incursion: Toxins and Pheromones", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 88711 }, ["description"] = "Our allies in Azj-Kahet have identified a strategic location to strike at the Sureki. According to reports, our enemies are gathering toxins to fuel their war machines. Let's take this opportunity to cut off their supplies, and perhaps better our own understanding of their alchemy.", ["objectivesText"] = "Aid the Flame's Radiance in disrupting the Sureki forces in the Untamed Valley. Progress: Nerubian toxins are volatile, even for our most skill healers and medics.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 140192, 239546, 240215 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 242591, ["x"] = 0.66, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
