[88916] = { ["id"] = 88916, ["name"] = "Radiant Incursion: Sureki's End", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 88916 }, ["description"] = "Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them! The Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet . Be warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. Should you require aid, our Sacredites in the field should be equipped with potions to assist you.", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki forces at Arathi's End. Progress: We must not let them gather strength. Now is the time to strike!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 241100, ["x"] = 0.606, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
},
[88945] = { ["id"] = 88945, ["name"] = "Radiant Incursion: Rak-Zakaz", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 88945 }, ["description"] = "The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now. According to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults. Regroup with our forces at Faerin's Advance and cut off their reinforcements!", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki forces at Rak-Zakaz. Progress: By disrupting operations at Rak-Zakaz, we cut off their reinforcements and discourage any sympathizers to their cause.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 241100, ["x"] = 0.606, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["db2LabelIDs"] = { 4885 }, ["questType"] = "standard",
},
