[89348] = { ["id"] = 89348, ["name"] = "Let There Bee Love", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "All right. I'll get these bees over to the Oasis and meet you there.", ["objectivesText"] = "Meet Botanist Alaenra at the Oasis.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942, 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
