[89380] = { ["id"] = 89380, ["name"] = "Another World", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["series"] = { 89343, 89344, 89345 }, ["description"] = "I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable. The Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh , energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you. Meet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.", ["objectivesText"] = "Find Shad'anis at Overlook Zo'Shuul on K'aresh .", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241601, ["x"] = 0.748, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
