[89404] = { ["id"] = 89404, ["name"] = "Time Crisis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "You don't remember me? Hmmm, shifting through time can sometimes have that side-effect. Good thing I love introductions. Let me catch you up to speed on what we're doing here.", ["objectivesText"] = "Talk to Moratari and then find Khadgar. Progress: Khadgar needs your help.", ["rewardGold"] = 28090, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89405] = { ["id"] = 89405, ["name"] = "Mean Streets of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "The rest of the Council and I are currently barricaded in the Chamber of the Guardian working on a solution. In the meantime, we could use your help by taking some of the Legion's attention off us so we have time to think. Once you've bought us enough time to properly assess the situation, join me in the Chamber of the Guardian so we can turn this situation around and put the Legion on the defensive.", ["objectivesText"] = "Purge demons from Dalaran. Progress: Dalaran could use a few less demons.", ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89406] = { ["id"] = 89406, ["name"] = "Seal and Protect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "The citizens of Dalaran have sequestered themselves behind magical barriers that will keep the Legion at bay, for now. However, the power of the barriers is not infinite. Take my Reinforcing Ring and reinforce the barriers in order to keep our people safe. That will free me up to investigate the source of this Legion invasion. Once you're done, keep culling the Legion's numbers. I'll contact you once I've discovered more.", ["objectivesText"] = "Reinforce 5 magical barriers . Progress: Reinforcing the magical barriers should hold the Legion at bay until Khadgar can get this situation sorted out.", ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89407] = { ["id"] = 89407, ["name"] = "Thrift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "If we're going to help Khadgar, Dalaran, and our experiment, we're going to need to get you an artifact. Luckily I have a plan to accomplish just this. Dalaran is currently loaded with all manner of temporally important items--so called epoch objects. We'll gather up a few that won't be missed, blame their disappearance on the Legion, and then use them to get you that artifact. Here, I've made a shopping list.", ["objectivesText"] = "Recover the Dusty Stone Tablet , Bent and Battered Blade , and the Curious Curio for Momentus . Progress: These objects are loaded with epoch significance.", ["rewardGold"] = 309800, ["rewardXP"] = 1770, ["rewardItems"] = { 237812, 243601, 243604, 243607 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89408] = { ["id"] = 89408, ["name"] = "Threadbare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "To get you an artifact we'll need some temporal energy. Normally we use infinite cloaks woven from temporal threads, but those threads are frayed in this timeline. So instead I need you to gather those frayed temporal threads from around Dalaran. You can find them popping into and out of existence here and there. They look like radiant golden orbs of power, you can't miss them. Once you have enough of them bring them back to me.", ["objectivesText"] = "Collect Frayed Temporal Threads from the streets of Dalaran. Progress: With this source of power Momentus should have what he needs to help you get an artifact.", ["rewardGold"] = 341600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89411] = { ["id"] = 89411, ["name"] = "Scavenger Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Momentus may be expert what makes things, but Erus be expert what break things! < Erus energetically punches his fist into his palm to accentuate the word \"break\".> Go. Kill demons. Take their armor scraps. Then we get to scrapping! I love scrapping.", ["objectivesText"] = "Loot Legion Armor Scraps from the demons around Dalaran. Progress: One demon's trash is an infinite dragon's bronze.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812, 241211 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89412] = { ["id"] = 89412, ["name"] = "Get Plenty of Exorcise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Khadgar is close to divining the source of the Legion presence here, but there is no guarantee that he will if the Legion's plans proceed unchallenged. The fate of Dalaran is not yet decided. All he needs is a little more time. You can buy him that time by halting the Legion's efforts here in the city. Seek out Legion Portals and seal them. That should slow the arrival of more demons entering the city.", ["objectivesText"] = "Seal Legion Portals around Dalaran.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 628, ["db2PoiUiMapID"] = 628, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89413] = { ["id"] = 89413, ["name"] = "Obliterate, Then Iterate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Artifact is not what catches eye of Erus . No. You have demon armor scraps. Now, you might think to yourself, 'but Erus , demon armor scraps are junk', and you might be right. But Erus sees demon scraps and he does not see junk, he sees bronze . bronze hidden in the junk. Listen closely, Erus will teach you how to use the Unraveling Sands. You put junk in sands, sands unravels it, and then you get bronze from the ashes. Try using the Unraveling Sands and then toss in the Legion armor scraps .", ["objectivesText"] = "Use the Unraveling Sands ability to summon the Unraveling Sands, then place the Legion Armor Scraps in the sands to scrap it into Bronze . Progress: Happy scrapping!", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 217174, 237812, 251901 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89414] = { ["id"] = 89414, ["name"] = "Not A Memento Too Soon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Everything is unfolding splendidly, <name>. With your artifact in hand, you should have no issues assisting Khadgar in driving the Legion fully from Dalaran. According to Moratari's calculations, he should have discovered the source of the Legion invasion. Return to the Chamber of the Guardian when you are ready and learn what he has discovered.", ["objectivesText"] = "Talk to Khadgar in the Chamber of the Guardian.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89415] = { ["id"] = 89415, ["name"] = "Storm the Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Fel Lord Nezmet managed to slip through our teleportation spell and open cracks within our wards. Left unopposed, Nezmet will widen those cracks until the wards fail and the full might of the Legion is brought down upon us. We have a chance now, to finish him before he finishes us. Cut off their head and the rest of the Legion will wither and die. Head to the Violet Citadel with all haste. There is not a moment to lose.", ["objectivesText"] = "Kill Fel Lord Nezmet . Progress: With Nezmet dead, Dalaran is saved.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89416] = { ["id"] = 89416, ["name"] = "Eternal Gratitude", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Well, look at you. Saving Dalaran. You're starting to resemble your legend already. < Moratari glances about to make sure you are indeed alone before continuing.> We have somewhere to be and people to meet. I'm opening a portal to the Infinite Bazaar. < Moratari considers the name for a moment.> It's a place where we're safe to congregate out in the open without interfering with the timeline. Just step through when you're ready.", ["objectivesText"] = "Step through the portal and meet Eternus and the infinite dragonflight.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89417] = { ["id"] = 89417, ["name"] = "Infinite Meetings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "There, Dalaran is back to how it should be. I'm sure you have many questions, <name>. Who are we? What are we doing here? Why are you here? The simple answer is this: We are the Infinite, we are searching through time for answers to questions larger than any of us, and we need your help to do it. I think you will come to understand this answer more if you meet the rest of our flight. Moratari, if you would make the introductions?", ["objectivesText"] = "Tour the Infinite Bazaar. Progress: As their name would suggest, the infinite dragonflight is certainly not lacking in numbers.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 6948, 237812, 250316, 254320 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[89418] = { ["id"] = 89418, ["name"] = "A Fixed Point in Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "By now, the Legion will have been fully purged from Dalaran and events will begin unfolding. Events that require your presence, <name>. Moratari will take you back to Krasus' Landing. There your legend will continue to grow. I see great potential in you, <name>. No matter which timeline you're from.", ["objectivesText"] = "Talk to Moratari and return to Krasus' Landing.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812, 246937 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
