[89450] = { ["id"] = 89450, ["name"] = "Create a Neighborhood", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 89450 }, ["description"] = "You know what they say: it takes a neighborhood! Do they not say that? Well, they should. Gather signatures from like-minded settlers and found your own neighborhood!", ["objectivesText"] = "Gather charter signatures from players, then create your new neighborhood! Use the Neighborhood Charter quest item to open your charter.", ["rewardItems"] = { 239098 }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 }, { ["mapID"] = 85, ["npcID"] = 254688, ["x"] = 0.584, ["y"] = 0.895 }, { ["mapID"] = 84, ["npcID"] = 256078, ["x"] = 0.474, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard", ["flags"] = {  },
