[89490] = { ["id"] = 89490, ["name"] = "Warrant: Arcana-Monger So'zer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 89490 }, ["series"] = { 90127 }, ["description"] = "Arcana-Monger So'zer is responsible for a spree of thefts throughout Tazavesh that have resulted in the loss of magic relics, wands, and several crates of highly toxic Zo'kita fruit. Informants suggest that So'zer may be compelled to reveal himself if presented with a highly prized arcane relic. Create an item tempting enough to trick this criminal into revealing themselves.", ["objectivesText"] = "Combine an Arcane Runed Sigil with a Charged Crystal and a Smuggler's Mark to create an Arcane Lure to reveal So'zer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239314, 239484, 239564, 239607 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2472, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questType"] = "standard", ["flags"] = {  },
