[89501] = { ["id"] = 89501, ["name"] = "Charged Crystal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89501 }, ["description"] = "An arcane charged crystal is not an item you will find in K'aresh , but there is a way we can make one! A small helper I know can help you harvest and store arcane energy . If you return that energy and an uncharged crystal to me, we can make a charged crystal . Gain Myi Koo's assistance, then travel through the ethereal portal to the Azure Vaults. Collect the energy and crystal.", ["objectivesText"] = "Meet with Myi Koo, enter the Archival Assault delve, and collect 6 Arcane Energy Samples and an Uncharged Crystal . Progress: Have you collected the crystal and the required energy?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239446, 239607 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
