[89502] = { ["id"] = 89502, ["name"] = "Worldsoul: Nightfall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The remaining Sureki are rampaging around Hallowfall and Azj-Kahet, but we believe they are gathering forces west of the Veneration Grounds so that they can strike Mereldar directly! Please join Flame's Radiance in their defense and put down this Sureki threat!", ["objectivesText"] = "Complete the Nightfall scenario.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2339, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 53, ["flags"] = 0 } }, ["questType"] = "standard",
