[89505] = { ["id"] = 89505, ["name"] = "Smuggler's Mark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 89505 }, ["description"] = "An upstanding citizen such as Om'sto, would not have such an illegal item like a Smuggler's Mark . If I did acquire one...I would be inclined to give it to someone that I owe a debt to. If you did me a favor, and then I would be in your debt. Travel to North Sufaad, and fill my pack with items I lost there. You do this, and I may have what you need.", ["objectivesText"] = "Find enough lost items in North Sufaad to fill Om'sto's pack. Progress: Have you recovered all my items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239484, 239495, 239497, 239500, 239501, 239510 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["flags"] = {  },
