[89514] = { ["id"] = 89514, ["name"] = "Worldsoul: Horrific Visions Revisited", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15942, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "This Black Blood that has corrupted the nerubians is nasty stough. I hear that it is not the first time that the Old Gods have used this blood. A new visitor to Dorgogal, Soridormi of the Bronze Dragons, has found a way for you to revisit this past event. Seek her out to relive these Horrific Visions and learn what you can. Keep your eyes open <name>. Any info you can learn will surely aid us today.", ["objectivesText"] = "Defeat 5 bosses inside Horrific Visions Revisited.", ["rewardGold"] = 683200, ["rewardXP"] = 17650, ["rewardItems"] = { 244865 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 15942 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 38, ["flags"] = 0 } }, ["questType"] = "standard",
