[89515] = { ["id"] = 89515, ["name"] = "Renowned with Flame's Radiance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 89515 }, ["description"] = "You continue to inspire us on the battlefield, <name>. Your heroic deeds have kept our people safe during these trying times, and we cannot thank you enough.", ["objectivesText"] = "Speak with Lars Bronsmaelt in Morgaen's Tears.", ["rewardItems"] = { 239489 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 240852, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2689, ["threshold"] = 7500 } } }, ["questType"] = "standard", ["flags"] = {  },
