[89561] = { ["id"] = 89561, ["name"] = "Wrapped Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["description"] = "Shad'anis has told me about you--a fleshling with the ability to travel to Untethered Space. How do you accomplish such a feat? Wait--let me deduce. It must be those wraps you wear as a cloak. They have been modified by a Reshii Ribbon. I have not seen such a thing since the Devouring War. Very nice. Classic. Do you want classic? Or do you want powerful? I can enhance your Reshii Wraps with modern technomancy techniques to better face the dangers of Untethered Space.", ["objectivesText"] = "Talk to Hashim about your Reshii Wraps. Progress: Enhancing the Reshii Wraps is paramount to your survival.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 21191, 21310 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241588, ["x"] = 0.502, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
