[90081] = { ["id"] = 90081, ["name"] = "Arcane Runed Sigil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90081 }, ["description"] = "An Arcane Runed Sigil is essential in proving an item's authenticity as a true masterpiece of Azure artisans. Of course, they can be affixed to any object, turning a flea market trinket into something that appears to be a priceless work of art. I could create something like that, and it might turn a great profit. If you travel to the Azure Vault and gather the parts I need, we can use them to craft a Sigil. Bring me enough parts for two, and I shall keep one as my fee for the service.", ["objectivesText"] = "Enter the Archival Assault delve and collect 24 Etched Fragments . Progress: Have you collected the parts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239564, 245740 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
