[90517] = { ["id"] = 90517, ["name"] = "My Part of the Deal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "The threat of the Shadowguard to Eco-Dome: Primus is over. My Reshii Ribbon is no longer needed to protect this asset. Take it. Use it wisely. Protect the greatest investment of all--our existence. Stay focused! The Harbinger has already driven off one member of your team. Once you get enough Reshii Ribbons, you still need to fight Dimensius. Find allies who will stand with us, in addition to artifacts.", ["objectivesText"] = "Take Ve'nari's Reshii Ribbon . Progress: The Reshii Ribbons are a means to get you and your allies to Dimensius. You will need at least two more if this plan is going to work.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 242538, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 242538, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90545] = { ["id"] = 90545, ["name"] = "A Reel Problem", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90545 }, ["description"] = "An essential component of the Oasis ecosystem is the aquatic life within our small lake. It appears that artificial organisms known as Hyrobites are in the lake. Originally introduced to remove toxins in the water, their continued presence threatens the equilibrium of the water. Please remove these mechanical fish immediately!", ["objectivesText"] = "Catch 7 Hydrobites around the Oasis. Progress: Did you catch those fish?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 241352 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard",
