[90659] = { ["id"] = 90659, ["name"] = "Something Borrowed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them. No one will be the wiser. All we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out. Let's start by selecting your specialization, that'll determine which artifact we'll be borrowing.", ["objectivesText"] = "Select your artifact weapon. Progress: Every artifacts needs a mighty hero to wield it.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
