[90663] = { ["id"] = 90663, ["name"] = "Stealing What is Ours", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead. A large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.", ["objectivesText"] = "Speak with Xy'dax and recover the Missing Imports . Progress: Have you recovered my missing items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242535, 242667, 242708, 242733 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2QuestHubAreaPoiID"] = 8385, ["questType"] = "standard", ["flags"] = {  },
