[90701] = { ["id"] = 90701, ["name"] = "Cowardly Cheery Bombs", ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 90701 }, ["description"] = "Goblins love bombs, I get that. But does EVERYTHING have to blow up? Do me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props. After you find the bomb, but before it \"blows up\"... smack it for me. Don't worry, they're cowards.", ["objectivesText"] = "Find a Cheery Bomb , hidden inside a Dastardly prop. Smack it before it blows up. Progress: Those cheery bombs are asking for it, <name>. Find one in a Dastardly Duos match and smack it!", ["rewardGold"] = 341600, ["rewardItems"] = { 237384, 237774 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234297, ["x"] = 0.526, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234297, ["x"] = 0.526, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90705] = { ["id"] = 90705, ["name"] = "Lorewalking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 90705 }, ["description"] = "Are you curious about your world's history? Would you like to learn more? Lorewalker Cho has been traveling and gathering stories of important events and figures across Azeroth and beyond. If you pay him a visit in your capital city, he will gladly share a tale of the past with you! Or perhaps more than one tale. He does very much enjoy conversation! Tell him Assistant Lali sent you.", ["objectivesText"] = "Find Lorewalker Cho in Silvermoon, Dornogal, Stormwind, or Orgrimmar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 242386, 244846, 244858, 244888, 245567, 245631 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 230246, ["x"] = 0.641, ["y"] = 0.163 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.641, ["y"] = 0.163 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard",
},
[90719] = { ["id"] = 90719, ["name"] = "Borrowing Corruption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90719 }, ["description"] = "Adventurer, I have made an amazing discovery. Analyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. I will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos .", ["objectivesText"] = "Find Black Blood Residue and Displaced Corrupted Mementos from the bosses of the Corrupted and Lost areas of the Horrific Visions. Progress: Were you successful?", ["rewardGold"] = 683200, ["rewardItems"] = { 238403, 238407, 238678, 239078, 239084, 239088, 239093 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90729] = { ["id"] = 90729, ["name"] = "Win-Win Situation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway! Xy'daz has been ripping people off for years. It's his turn to take a loss! Now, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", ["objectivesText"] = "Sell 6 Shadowtrade Overstock. Progress: Did you sell the items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242529, 242667, 242708, 242733 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90731] = { ["id"] = 90731, ["name"] = "Enhancing Corruption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90731 }, ["description"] = "Welcome back adventurer. I have made a new discovery but I need to test it out. Hidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate . This might be the key to increasing the power of the corruption effects... in a safe way. If you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", ["objectivesText"] = "Find Black Blood Coagulate and Displaced Corrupted Mementos from the bosses of the Lost areas of the Horrific Visions. Progress: Were you successful?", ["rewardGold"] = 683200, ["rewardItems"] = { 238405, 238680, 239080, 239086, 239090, 239095, 242648 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90747] = { ["id"] = 90747, ["name"] = "The Wrong Bluecephalus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "We may have gotten off on the wrong foot, but there's something you should know. That old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along. A rare bluecephalus, worth a fortune! You might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", ["objectivesText"] = "Speak with Ba'eth and others. Progress: Are you ready to help?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242667, 242708, 242733 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243291, ["x"] = 0.468, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90754] = { ["id"] = 90754, ["name"] = "Skyriding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "This land is more vast than I remember. However, a good scholar is always prepared. To cover more ground, you will need a winged mount and the skill to ride it swiftly. I recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him. Don't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", ["objectivesText"] = "Take Moratari 's portal to Lord Andestrasz . Progress: All things come with practice.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 194034 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 371, ["db2PoiMapID"] = 870, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard",
},
[90755] = { ["id"] = 90755, ["name"] = "Time Flies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 90755 }, ["description"] = "That should suffice for now. Remember the basics and you will improve in time. Speaking of time, you had best be on your way. The portal there will take you back to Moratari .", ["objectivesText"] = "Return to Moratari .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard",
},
[90770] = { ["id"] = 90770, ["name"] = "The Grift", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. Many more bargains to find in spots where treasures lie waiting. You know where to look? Go to dis special place and find treasures, I give the blue beast to you.", ["objectivesText"] = "Enter Untethered Space and recover the items Griftah requires. Progress: Did you find da treasures?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 723, 242371, 242667, 242708, 242733, 243049, 243050, 243053, 243054, 243055 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243915, ["x"] = 0.486, ["y"] = 0.414667 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243915, ["x"] = 0.486, ["y"] = 0.414667 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.414667 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90773] = { ["id"] = 90773, ["name"] = "Meat My Business", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Since I am helping you, I'm sure you won't mind returning the favor. I have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands? I've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", ["objectivesText"] = "Collect 12 Dustback Flank , 5 Siltwing Tail , and 5 Swoopwing Eggs . Progress: You've collect all the meat?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242667, 242708, 242733, 242794, 242796, 242797 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
