[90779] = { ["id"] = 90779, ["name"] = "Cracked Keystone", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 90779 }, ["description"] = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?", ["objectivesText"] = "Complete any dungeon on Mythic 2 or higher difficulty.", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 242919 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["flags"] = {  },
