[90869] = { ["id"] = 90869, ["name"] = "It's All in the Image", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\" We've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork. Oh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", ["objectivesText"] = "Speak to Sassy Hardwrench to select a \"marketing partner.\" Progress: C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.", ["rewardGold"] = 309800, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.76775 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["db2PoiUiMapID"] = 194, ["db2PoiMapID"] = 648, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 5, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90870] = { ["id"] = 90870, ["name"] = "Gathering the Grub", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90870 }, ["description"] = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans! So here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", ["objectivesText"] = "Collect Bags of Brewfest Ingredients and deposit them at the wagon. Progress: The feast won't come together without those ingredients!", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 62978, 62979, 62980, 62981, 64641, 243479 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["db2QuestSortName"] = "Epic", ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
},
[90879] = { ["id"] = 90879, ["name"] = "Brewmaster's Kitchen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90879 }, ["description"] = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd. We've got a short but sweet menu: Barley Soup, Pretzels , and of course a good ol' brew! Are ye ready to learn the ropes?", ["objectivesText"] = "Follow the steps to cook Brewfest food and a delicious Brew. Progress: Get cookin'!", ["rewardGold"] = 28600, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 244050, 244051, 244052, 244064 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["db2QuestSortName"] = "Epic", ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
},
[90880] = { ["id"] = 90880, ["name"] = "Serving with Style", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90880 }, ["description"] = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time. Ye'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile. Get out there and show 'em how it's done. Brewfest won't run without good service!", ["objectivesText"] = "Take the customer's order and serve the food to them. Progress: Remember to serve with a smile!", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["db2QuestSortName"] = "Epic", ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
