[90885] = { ["id"] = 90885, ["name"] = "My Beautiful Pumpkins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90885 }, ["description"] = "The kobolds and ogres appeared out of nowhere and kicked us out of the farm! I thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all. You have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them! You lead the way. I'll grab the pumpkins when you find them.", ["objectivesText"] = "Recover 4 Prized Pumpkins . Progress: Return to Thrall with Farmer Bruvk and his pumpkins", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 153741, 153742, 153796, 153797, 153802, 153803, 153817, 153818, 153862, 153863, 153908, 153909, 153927, 153928, 153948, 153949, 153995, 153996, 154011, 154012, 154114, 154115, 154745, 154746, 194533, 194534 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244729, ["x"] = 0.565, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["db2PoiUiMapID"] = 2451, ["db2PoiMapID"] = 2927, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6004, ["name"] = "12.0 Testing - RPE - Delete Me - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
