[90886] = { ["id"] = 90886, ["name"] = "Best Laid Plans of Kobolds and Ogres", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "The kobolds and ogres here seem to be carrying some sort of plan for their attack. I don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", ["objectivesText"] = "Collect 7 Poorly Written Plans . Progress: Did you recover the plans? They should be on most of the foes within the farm.", ["rewardGold"] = 31500, ["rewardXP"] = 175, ["rewardItems"] = { 153735, 153736, 153785, 153786, 153806, 153807, 153820, 153821, 153845, 153846, 153902, 153903, 153936, 153937, 153952, 153953, 154001, 154002, 154014, 154015, 154039, 154040, 154738, 154741, 194524, 194527, 243573 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["db2PoiUiMapID"] = 2451, ["db2PoiMapID"] = 2927, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
