[90896] = { ["id"] = 90896, ["name"] = "One Last Ogre", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "The head of the siege is still cowering within the former Horde encampment. He managed to hide from Jaina's spell behind several of his cohorts. You can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return. End this.", ["objectivesText"] = "Slay Ro'grok . Progress: Defeat Ro'grok and end this siege.", ["rewardGold"] = 625600, ["rewardXP"] = 1770, ["rewardItems"] = { 153737, 153744, 153787, 153789, 153808, 153810, 153822, 153825, 153842, 153847, 153855, 153904, 153911, 153938, 153941, 153954, 153956, 154003, 154006, 154016, 154041, 154048, 154735, 154737, 194528, 194530 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["db2PoiUiMapID"] = 2451, ["db2PoiMapID"] = 2927, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
