[90897] = { ["id"] = 90897, ["name"] = "Back to Stromgarde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90911 }, ["description"] = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. The same can't be said of other threats that are looming throughout Azeroth. Come. Let's return to Stromgarde to discuss matters further.", ["objectivesText"] = "Meet Jaina Proudmoore within Stromgarde Keep.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244667, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244714, ["x"] = 0.195, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["db2PoiUiMapID"] = 2451, ["db2PoiMapID"] = 2927, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90898] = { ["id"] = 90898, ["name"] = "Back to Hammerfall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90898, 90911 }, ["description"] = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two. That being said, more dangers lurk throughout Azeroth. I know you can be of help to some. Let us return to Hammerfall to see how they're recovering.", ["objectivesText"] = "Return to Hammerfall.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244715, ["x"] = 0.692, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["db2PoiUiMapID"] = 2451, ["db2PoiMapID"] = 2927, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90901] = { ["id"] = 90901, ["name"] = "As A Matter of Artifact", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 89404, 89405, 89406, 89407, 89408, 89409, 89411, 89412, 89413, 89414, 89415, 89416, 89417, 89418, 90659, 90901 }, ["description"] = "There's more to artifacts than meets the eye, <name>. Simply using an artifact allows its legend to grow, and as that legend grows, so too does its power. In order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable. Let's get started.", ["objectivesText"] = "Unlock artifacts traits using Infinite Power gained from looting Epoch Mementos from any enemy. Progress: Unlocking the full potential of your artifact will be key to understanding their impact on this timeline.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5899, ["name"] = "Legion: Infinitely Different", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5899, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
