[90938] = { ["id"] = 90938, ["name"] = "A Skip Through the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90938 }, ["description"] = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. Previously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps . My name is Hashim , and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", ["objectivesText"] = "Meet Hashim at Overlook Zo'Shuul.", ["rewardGold"] = 29200, ["rewardItems"] = { 235499, 238037, 238039, 238040, 238041 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241588, ["x"] = 0.502, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90968] = { ["id"] = 90968, ["name"] = "Titanic Rumblings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", ["objectivesText"] = "Seek out Dagran Thaurissan II at the Delver's Headquarters in Dornogal.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["rewardItems"] = { 242664, 245964, 245965, 245966 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 0, ["flags"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90969] = { ["id"] = 90969, ["name"] = "Titan Consoles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage. Confront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", ["objectivesText"] = "Seek out one of Dagran's Titan Consoles in an Overcharged Delve.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90970] = { ["id"] = 90970, ["name"] = "Titan Disc-Count", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15004, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. Make sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", ["objectivesText"] = "Secure Titan Disc Shards and dispatch Titan Constructs within the delve. Progress: Adventurer? Is that you?", ["rewardXP"] = 9515, ["rewardItems"] = { 244465 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15004 } }, ["mapID"] = 2346, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90971] = { ["id"] = 90971, ["name"] = "Overcharged Console", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. Use the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", ["objectivesText"] = "Restore a Titan Disc and then spend it to unlock one of the starting nodes in the Overcharged Console Tech Tree. Progress: Did it work?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 244466 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["mapID"] = 2346, ["db2PoiUiMapID"] = 2346, ["db2PoiMapID"] = 2706, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[90972] = { ["id"] = 90972, ["name"] = "A Common Cause", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "<name>! I heard you were here on K'aresh . Good. I need help. My apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights. To be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona. Leona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", ["objectivesText"] = "Speak to Adarus. Progress: Have you spoken to Adarus yet, <name>? It's clear that the Illidari's apotheosis has stripped them of their manners.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 247882 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard",
},
[90995] = { ["id"] = 90995, ["name"] = "The Future of The Fel Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 90995 }, ["description"] = "Oh wait! Of course, right when I send you off I remember the most important thing! The you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari. You will need to choose which of these diverging timelines to explore. What rings true to you?", ["objectivesText"] = "Choose your personal champion. Progress: Have you made a choice?", ["rewardGold"] = 22130, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questType"] = "standard", ["flags"] = {  },
},
[91009] = { ["id"] = 91009, ["name"] = "Durable Information Storage Container", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. Each of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", ["objectivesText"] = "Complete a Delve to charge the device. Progress: The overcharging is key.", ["rewardXP"] = 11765, ["rewardItems"] = { 242664, 245964, 245965, 245966 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91026] = { ["id"] = 91026, ["name"] = "Gathering an Upgrade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Hello? Hello? You're back! Perfect! I was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure. Return to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", ["objectivesText"] = "Complete any Delve. Progress: Were ye successful?", ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 5, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91030] = { ["id"] = 91030, ["name"] = "New Titan Directives", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly. But if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", ["objectivesText"] = "Complete any Delve. Progress: I can't wait to see the data!", ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 6, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91031] = { ["id"] = 91031, ["name"] = "Pushing it to the Limit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes. I do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", ["objectivesText"] = "Complete any Delve. Progress: I cannae wait to see if I was correct!", ["rewardGold"] = 936000, ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 7, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91033] = { ["id"] = 91033, ["name"] = "Monitoring 'Construct'ing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. We have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", ["objectivesText"] = "Complete an Overcharged Delve.", ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91035] = { ["id"] = 91035, ["name"] = "Construct De-Escalation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'... Head back into these overcharged areas and test out the charge on the constructs, then report back.", ["objectivesText"] = "Defeat 5 constructs and complete an Overcharged Delve.", ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 9, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
