[91038] = { ["id"] = 91038, ["name"] = "Hellhunters Wanted", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91038 }, ["description"] = "<A scorch-marked missive has been nailed to this wall.> HELL COMES FOR YOU! Now that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you. Please bring any shards you find IMMEDIATELY to us in Dornogal. And if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", ["objectivesText"] = "Bring the missive to Baranar in Dornogal.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245378, ["x"] = 0.53, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91039] = { ["id"] = 91039, ["name"] = "Faerin's Request", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84651, 84652, 84656, 84657, 84658, 84659, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 85529, 87299, 91039 }, ["description"] = "<name>, Geya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious. Can you come to Dornogal? I believe your presence can help the situation. Faerin", ["objectivesText"] = "Speak to Faerin Lothar in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
