[91044] = { ["id"] = 91044, ["name"] = "Hunger of the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us. He was strong. In a way, I think that worked against him. Meet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", ["objectivesText"] = "Reconvene with Magister Umbric and Leona back in Shan'dorah. Progress: I could feel the void energies roiling from here, <class>. What exactly happened?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245729, 245730, 245731, 245732 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.356667 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 8, ["flags"] = 0 } }, ["questType"] = "standard",
},
[91052] = { ["id"] = 91052, ["name"] = "Worldsoul: Overcharged Delves", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", ["objectivesText"] = "Complete an Overcharged War Within Delve at any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 14, ["flags"] = 0 } }, ["questType"] = "standard",
},
[91066] = { ["id"] = 91066, ["name"] = "Brewmaster's Kitchen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91066 }, ["description"] = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength. The menu's simple, but worthy: Barley Stew, Stone-baked Pretzels , and a strong brew to fuel the Horde! Are you prepared to learn?", ["objectivesText"] = "Follow the steps to cook Brewfest food and a delicious Brew. Progress: Start the fire and get to work!", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 246040, 246042, 246047, 246049 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
},
[91067] = { ["id"] = 91067, ["name"] = "Gathering the Grub", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91067 }, ["description"] = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub. Here's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", ["objectivesText"] = "Collect Bags of Brewfest Ingredients and deposit them at the wagon. Progress: The feast won't come together without those ingredients!", ["rewardGold"] = 22130, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 62978, 62979, 62980, 62981, 64641, 246044 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
},
[91068] = { ["id"] = 91068, ["name"] = "Serving with Style", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91068 }, ["description"] = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp. You'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration. Now get out there and show them what real service looks like! Brewfest don't run on empty mugs!", ["objectivesText"] = "Take the customer's order and serve the food to them. Progress: Remember to serve with a smile!", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["db2LabelIDs"] = { 2751 }, ["questType"] = "standard", ["flags"] = {  },
},
[91089] = { ["id"] = 91089, ["name"] = "Defeating Ky'veza", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 16539, ["mapID"] = 2339, ["storyline"] = { 91089, 91780, 91781, 91782 }, ["description"] = "So she's here to collect a bounty, eh? Did nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", ["objectivesText"] = "Increase your item level to challenge Ky'veza in her tier 8 delve on K'aresh.", ["rewardItems"] = { 212265, 212282, 219309, 219314, 219905, 222776, 244470 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 16539 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5973, ["name"] = "Delves - Season 3", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91093] = { ["id"] = 91093, ["name"] = "More Than Just a Phase", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 91093 }, ["description"] = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds. Aid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", ["objectivesText"] = "Complete activities while phase diving in Untethered Space on K'aresh. Progress: I dream of a day when we K'areshi can roam these lands freely and without fear.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 255676 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 }, { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.5755 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questType"] = "standard",
},
[91138] = { ["id"] = 91138, ["name"] = "I am the Creator and Destroyer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 91138, 91140 }, ["description"] = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless. Did you know, <class>, that to T'uure, the dark and the light were inseparable aspects of a greater truth? What creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", ["objectivesText"] = "Demonstrate your mastery over life and death.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245743, 250082 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5942, ["name"] = "The Legacy of T'uure", ["orderIndex"] = 1, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91140] = { ["id"] = 91140, ["name"] = "A Piece of the Past", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 91138, 91140 }, ["description"] = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths. Perhaps someone in Tazavesh will know more.>", ["objectivesText"] = "Show the fragment to Om'en in Tazavesh. Progress: What is this? Ah, I see now. You were right to come to me.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 59693, 59694, 59695, 59696, 59697, 59698, 245743 }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5942, ["name"] = "The Legacy of T'uure", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 245743 }, ["questType"] = "standard", ["flags"] = {  },
