[91314] = { ["id"] = 91314, ["name"] = "Untethered Potential", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91314, 91454 }, ["description"] = "<class>--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void. I need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. Go carefully.", ["objectivesText"] = "Collect 5 Phase-Altered essence in Untethered Space. Progress: Were you able to collect the Phase-Altered essence ?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 246244, 246589 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 246601, ["x"] = 0.598, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 246601, ["x"] = 0.598, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["db2PoiUiMapID"] = 2371, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 5953, ["name"] = "Untethered Potential", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
