[91459] = { ["id"] = 91459, ["name"] = "Manaforge Omega: A Walking Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91459 }, ["description"] = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming! There is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid", ["flags"] = {  },
