[91522] = { ["id"] = 91522, ["name"] = "Order from Chaos", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91522, 91728, 91729, 91730 }, ["description"] = "Thank you for coming to speak with me, $p. I know you are very busy these days. But it is that very demand on your time that I wish to speak with you about. With all you have accomplished of late, I feel that there is bound to be some valuable data to be gleaned from your experience. As a <class> without equal, I would like to ask you about your deeds of late. Can you spare a moment for Moratari ?", ["objectivesText"] = "Talk to Moratari and answer her questions. Progress: Once I record this data point you can return to your busy schedule.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5959, ["name"] = "Infinite Epilogues", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91525] = { ["id"] = 91525, ["name"] = "Head Hunting: Loom'ithar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91525 }, ["description"] = "Our intelligence describes a colossal beast within the Manaforge, responsible for producing the fabric that gives the Shadowguard their very form. Take it down and we'll hinder their ability to produce reinforcements. Oh, and Ba'choso says to bring some of the silk back with you - he may be able to fashion it into something useful.", ["objectivesText"] = "Defeat Loom'ithar within Manaforge Omega on any difficulty. Progress: Have you procured a sample?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245510 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245348, ["x"] = 0.42, ["y"] = 0.224 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.224 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid", ["flags"] = {  },
},
[91526] = { ["id"] = 91526, ["name"] = "Head Hunting: Forgeweaver Araz", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91526 }, ["description"] = "My friend, I hope your assault is going well. It's time for you to dispatch the Forgeweaver; using his mastery of technomancy he oversees both the Manaforge's production pipelines... as well as the ritual to return Dimensius to this plane. His workshop will be further in and heavily guarded, but cutting him down should stop their plans of resurrection for good.", ["objectivesText"] = "Defeat Forgeweaver Araz inside Manaforge Omega on any difficulty. Progress: Does the Forgeweaver yet live?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 249218 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid", ["flags"] = {  },
},
[91527] = { ["id"] = 91527, ["name"] = "Head Hunting: The Soul Hunters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91527 }, ["description"] = "Careful in the wastes, my friend. Scouts report that a trio of Demon Hunters are training south of the Manaforge - with one of them exhibiting power like we've never seen. You can avoid their path if you wish, but ignoring them could open you up to being flanked should they decide to engage. I recommend taking them out if you can, as well as providing us some samples of their newfound strength.", ["objectivesText"] = "Defeat The Soul Hunters within Manaforge Omega on any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 246492 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid", ["flags"] = {  },
},
