[91529] = { ["id"] = 91529, ["name"] = "Head Hunting: Nexus-King Salhadaar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91529 }, ["description"] = "The hour of Salhadaar's demise is upon us. While he may posture upon his Voidwing, he grows desperate at the feet of the All-Devouring. The army he commands is not enough for your might - strike him down.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 246727 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid", ["flags"] = {  },
