[91618] = { ["id"] = 91618, ["name"] = "A Few Things First", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 46083, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", ["objectivesText"] = "Obtain 1 Leystone Ore and a Suramarian Sapphire . Progress: I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 140328, 147768, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 627, ["db2PoiUiMapID"] = 627, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91619] = { ["id"] = 91619, ["name"] = "Blood of Sargeras", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 139, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras. We will need a plentiful quantity. Bring me whatever you can muster.", ["objectivesText"] = "Collect Blood of Sargeras.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["mapID"] = 24, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
