[91620] = { ["id"] = 91620, ["name"] = "Noggenfogger's Reasonable Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible. Marin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor. Of course, if you would rather, I can eliminate him.", ["objectivesText"] = "Collect Aethril.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["mapID"] = 626, ["db2PoiUiMapID"] = 626, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
