[91639] = { ["id"] = 91639, ["name"] = "Embrace Your Own Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 91639, 91721, 91722 }, ["description"] = "I will keep a close eye on your progress and watch your exploits with that artifact unfold with great interest. Once you have embraced the power of your own legend, I would like to hear your perspective on how important the artifact you wield has been on your journey.", ["objectivesText"] = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have embraced your own legend. Progress: We are on a journey of learning and discovery. Let us walk it together.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5968, ["name"] = "Infinite Power Hypothesis", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5968, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
