[91691] = { ["id"] = 91691, ["name"] = "The Vanishing of Iridikron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 91691, 91695 }, ["description"] = "As you traveled through Zaralek caverns, Chronormu and I confronted Iridikron and the Infinite Dragonflight. While we defeated the Infinite Dragonflight's champion, Chrono-Lord Deios, I fear Iridikron escaped. Allow me to show you what happened, for it gives us a clue of what must be done next.", ["objectivesText"] = "See Nozdormu 's vision of the conflict with Iridikron.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["db2PoiUiMapID"] = 2112, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 71, ["flags"] = 0 }, { ["id"] = 6214, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 }, { ["id"] = 346, ["title"] = "The Azure Span", ["questLineID"] = 6214, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91695] = { ["id"] = 91695, ["name"] = "Tracking Down Incarnates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 91691, 91695 }, ["description"] = "We must turn our attention to Fyrakk and Vyranoth with Iridikron seemingly vanished from our sight. Merithra and the Green Dragonflight have been pursuing him and have a lead. They've received the aid of Shandris Feathermoon in this task. She awaits you within Valdrakken. Shandris will need your help with what is to come.", ["objectivesText"] = "Find Shandris Feathermoon within Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 205067, ["x"] = 0.502, ["y"] = 0.533 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["db2PoiUiMapID"] = 2112, ["db2PoiMapID"] = 2444, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 70, ["flags"] = 0 }, { ["id"] = 6214, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 }, { ["id"] = 346, ["title"] = "The Azure Span", ["questLineID"] = 6214, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91721] = { ["id"] = 91721, ["name"] = "Surpass Your Own Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 91639, 91721, 91722 }, ["description"] = "While artifacts are key, we must not dismiss the power of the individuals who wield them. Continue in your fight against the Legion. Grow strong, stronger than you ever thought possible. Then we will compare the might of your legend against that of the artifact.", ["objectivesText"] = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have surpassed your own legend. Progress: The person wielding an artifact is of some importance. But how much? Which legend is the greater? Let us find out together.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5968, ["name"] = "Infinite Power Hypothesis", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5968, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91722] = { ["id"] = 91722, ["name"] = "Shape a New Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 91639, 91721, 91722 }, ["description"] = "It is clear now that the person is at least as important as the artifact they wield. Perhaps it is the quality of mortality that diminishes the importance of the individual through the lens of history. While an artifact is eternal, the people wielding them are fleeting. But no flame that burns brightly burns forever. I want you to burn as brightly as you can. Empower your artifact and carve a new legend into the world for all to see.", ["objectivesText"] = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have shaped a new legend. Progress: An artifact cannot empower itself. Its power grows only when its wielder performs great deeds with it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246813, 253343, 254267 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5968, ["name"] = "Infinite Power Hypothesis", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 303, ["title"] = "Legion: Remix", ["questLineID"] = 5968, ["questLineOrder"] = 1 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91728] = { ["id"] = 91728, ["name"] = "Suramar Liberated", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91522, 91728, 91729, 91730 }, ["description"] = "You have come a long way, $p. I never seem to tire of following your exploits. Even from afar, as a silent observer, I find myself absolutely invested in what you will do next. I do have one question though.", ["objectivesText"] = "Talk to Moratari and answer her question.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5959, ["name"] = "Infinite Epilogues", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91729] = { ["id"] = 91729, ["name"] = "Armies Gathered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91522, 91728, 91729, 91730 }, ["description"] = "The stakes have never been higher than now, $p. I would very much like to know what you are thinking right now.", ["objectivesText"] = "Talk to Moratari and answer her question.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5959, ["name"] = "Infinite Epilogues", ["orderIndex"] = 3, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91730] = { ["id"] = 91730, ["name"] = "Azeroth Saved", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91522, 91728, 91729, 91730 }, ["description"] = "$p. You have done it! Sargeras is gone and Azeroth is saved. I can only imagine what must be going through your mind at this moment. Let us remedy that. Allow me to record your thoughts and your words. Not as written by a historian who you never met, but by a friend who wished nothing more than to listen.", ["objectivesText"] = "Talk to Moratari and answer her question.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5959, ["name"] = "Infinite Epilogues", ["orderIndex"] = 4, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
[91757] = { ["id"] = 91757, ["name"] = "Until Our Next Hello", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91757 }, ["description"] = "Well, the moment is fast approaching now. < Moratari subtly nods in the direction of the raging temporal storm overhead.> You would think after so many goodbyes I would be better at this, but alas, I simply prefer hello over goodbye. I know a lot of people around here are going to miss you too. You should go say goodbye to them while there is still time.", ["objectivesText"] = "Say goodbye to the infinites at the Infinite Bazaar.", ["rewardGold"] = 262100, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["db2PoiUiMapID"] = 619, ["db2PoiMapID"] = 1220, ["questLines"] = { { ["id"] = 5972, ["name"] = "Last Goodbyes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
