[91782] = { ["id"] = 91782, ["name"] = "Repossessed!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91089, 91780, 91781, 91782 }, ["description"] = "I think ye may have guessed what my problem is by now, <name>. My clothes, my tools, my curios! Everything but my boots and hat, which I'm nae giving up again. All repossessed by some cartel thug who said I was delinquent on my void storage payments, if ye can believe it. Would ye be willing to help Ol' Brann out of this pickle? I'm sure if ye just explain that this is all some sort of mistake, they'll give back all my hard earned gear. Or at least me britches.", ["objectivesText"] = "Recover Brann's lost gear. Progress: Has it always been this breezy in Dornogal?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 238051, 248129 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5973, ["name"] = "Delves - Season 3", ["orderIndex"] = 2, ["flags"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
},
