[91821] = { ["id"] = 91821, ["name"] = "Out of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91821 }, ["description"] = "There you are, <name>. This timeline is collapsing! Presumably you have noticed the great rift tearing through reality above us. We don't have much time remaining before we must retreat from this timeline. To make matters worse, infernals from other timelines are starting to pour in. Send them back from when they came.", ["objectivesText"] = "Slay a Lost Legion Infernal on the Broken Isles.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 31510, 31512, 31516, 31521, 33226, 37208, 37271, 37393, 37402, 37425, 37484, 37543, 38212, 39348, 39402, 39438, 39508, 57438, 57439, 57440, 59711, 59712, 59713, 59714, 59715, 59716, 62860, 62861, 62862, 65344, 65347, 65350, 65353, 72880, 72881, 72882, 72883, 93724, 116394, 118937, 121490, 121492, 121494, 127853, 128949, 131453, 131665, 132954, 133315, 139506, 139770, 143607, 147467, 211279, 237812 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["flags"] = {  },
