[91843] = { ["id"] = 91843, ["name"] = "Recap: The Harbinger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 91843 }, ["description"] = "To understand the story of The War Within, one must first begin with the mysterious entity known as the Harbinger, and how the heroes of Azeroth uncovered the truth...", ["objectivesText"] = "Read along with the Tome of History and learn about the events which sparked The War Within. Progress: Xal'atath was a mysterious foe with ties to the Void. Her presence portended dire things for Azeroth...", ["ends"] = { { ["mapID"] = 85, ["npcID"] = 248948, ["x"] = 0.545, ["y"] = 0.567 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["db2PoiUiMapID"] = 2339, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 6007, ["name"] = "Catch Up: War Within: Wrapper 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6007, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
