[92405] = { ["id"] = 92405, ["name"] = "Meet Arator", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 84996, 84997 }, ["description"] = "Greetings, champion. I have an urgent message for you from Arator . He asks that you join him and his aunt Vereesa on Oztan Isle, off the coast to the west.", ["objectivesText"] = "Seek out Arator and Vereesa Windrunner on Oztan Isle off the Isle of Dorn coast.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 250839, ["x"] = 0.515, ["y"] = 0.4555 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 231039, ["x"] = 0.285, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.4555 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["db2PoiUiMapID"] = 2248, ["db2PoiMapID"] = 2552, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["questType"] = "standard", ["flags"] = {  },
