[92439] = { ["id"] = 92439, ["name"] = "Infinite Research: Combat Studies, Felrunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 92439 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of fighting the Legion with their own power, so focus on using demonic fel energy to slay your foes. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Twisted Crusade is your active artifact ability. Progress: Remember to pace yourself, the journey is just as important as the destination.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard",
},
[92440] = { ["id"] = 92440, ["name"] = "Infinite Research: Combat Studies, Stormrunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 92440 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the storm, so focus on fighting opponents by turning the tides quite literally. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Tempest Wrath is your active artifact ability. Progress: Remember to pace yourself, the journey is just as important as the destination.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard",
