[92441] = { ["id"] = 92441, ["name"] = "Infinite Research: Combat Studies, Magerunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 92441 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the arcane, so focus on fighting opponents with powerful magic. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Naran's Everdisc is your active artifact ability.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard",
