[92442] = { ["id"] = 92442, ["name"] = "Infinite Research: Combat Studies, Lightrunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 619, ["storyline"] = { 92442 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the Light, so focus on wielding holy justice to smite your enemies. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Vindicator's Judgment is your active artifact ability. Progress: Remember to pace yourself, the journey is just as important as the destination.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard",
},
[92572] = { ["id"] = 92572, ["name"] = "Furniture Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 92572 }, ["description"] = "Greetings! I see you are eyeing our fine furniture. My siblings and I were sent on a mission to find only the finest Decor in the land. Decor is more than furniture, you see. Crafting a truly great decoration requires attention to so many different details. Come, friend, let us go on that journey together! Starting today. Today, we find a crate. Not just a normal crate, one that is fantastic. A great crate. I hear they may sell them nearby, actually...", ["objectivesText"] = "Purchase a Storage Crate in Dornogal, Stormwind, or Orgimmar, and return to a Pawdo sibling. Progress: How is your day going? Is it fantastic?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 253173 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[92577] = { ["id"] = 92577, ["name"] = "Dreamy Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 92577 }, ["description"] = "A crate is nothing more than a box in the dark without lighting. Today, we go in search of the tiny suns that light our spaces. Not just any light will suffice. As you can clearly see from my chandelier, we have many lights of varying quality already. We seek a unique shape, a unique feel. The crafters of Bel'ameth in the Dragon Isles are well-known for their dream-inspired designs. Travel through the Dragon Isles and you will find them at the far end of the plains.", ["objectivesText"] = "Purchase a Filigree Moon Lamp in Bel'ameth in the Dragon Isles, then return to a Pawdo sibling in Dornogal, Stormwind, or Orgimmar. Progress: You never really know a cabinet until you've checked the hinges.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 202669, 245259 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[92578] = { ["id"] = 92578, ["name"] = "Draconic Decor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 92578 }, ["description"] = "The chandelier I showed you? You must think it so fancy. But here I am without the matching sconces! What room lighting can I create without matching sconces? It will be woefully incomplete! Head over to the Dragon Isles and see if you can find one from the vendors of Valdrakken.", ["objectivesText"] = "Purchase a Draconic Sconce in Valdrakken in the Dragon Isles, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 248116 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[92580] = { ["id"] = 92580, ["name"] = "Spare A Chair", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 92580 }, ["description"] = "We cannot enjoy our Decor designs without a place to enjoy them from. Behold, the chair. What better way to enjoy Decor than on Decor itself? I cannot imagine something more appropriate. Find me a chair to match this coil. The gearcrafters of Mechagon know the style.", ["objectivesText"] = "Purchase a Bolt Chair in Rustbolt in Mechagon, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 166846, 246487, 265822 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[92581] = { ["id"] = 92581, ["name"] = "Last Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 92581 }, ["description"] = "I have sat in the chair and looked at the lights, and yet I am still not satisfied. The Decor still does not strike the dramatic tone that we require. I must trouble you for another source of the light's rays. Travel to Suramar and speak to the crafters there. They are masters of the art of soft lighting.", ["objectivesText"] = "Purchase a Nightborne Lantern in Suramar in the Broken Isles, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 247915 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 252312, ["x"] = 0.561, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["flags"] = {  },
},
[92647] = { ["id"] = 92647, ["name"] = "A Shadowed Journey Through Time", ["faction"] = "both", ["categories"] = {  }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10565, ["storyline"] = { 92647 }, ["description"] = "Champion! The curiosities hidden within the Shadowlands are numerous, as are the dangers. I could use some assistance clearing a path, so to speak. There is much wealth to be gained should you choose to seek it.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard",
},
