[93979] = { ["id"] = 93979, ["name"] = "Lingering Memories", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["series"] = { 84855, 85032, 85961 }, ["description"] = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", ["objectivesText"] = "Meet Alleria and Locus-Walker at the docks.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231128, ["x"] = 0.376, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["db2PoiUiMapID"] = 2472, ["db2PoiMapID"] = 2738, ["questLines"] = { { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["questType"] = "standard", ["flags"] = {  },
},
