[94847] = { ["id"] = 94847, ["name"] = "Preparations Underway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 139, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 46083, 91618 }, ["description"] = "As you may or may not recall, I once helped young paladins obtain their first armored mount. It was a tedious task that involved months of obtaining materials and sending them all over Azeroth. Thankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord. In order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", ["objectivesText"] = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["mapID"] = 24, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[94850] = { ["id"] = 94850, ["name"] = "If You Build It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7875, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground. I will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. Here's the list of what you'll need.", ["objectivesText"] = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 29784, 29785, 29786, 30398, 33226, 63227, 63228, 63229, 144328, 156937, 157009, 157010, 158611, 158612, 158613, 158614, 160189, 160190, 160191, 160192, 167649, 178061, 183830, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["mapID"] = 717, ["db2PoiUiMapID"] = 717, ["db2PoiMapID"] = 1107, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["questType"] = "standard", ["flags"] = {  },
},
[94932] = { ["id"] = 94932, ["name"] = "Bindings of the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {  }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 94932 }, ["series"] = { 43558, 43560, 43796, 44093, 44094, 44095, 44096, 44097 }, ["description"] = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own. Return to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", ["objectivesText"] = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone. Progress: Yes, <race>?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139466, 139468, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["flags"] = {  },
